typedef long long int LL;

int main()
{
	LL N;
	in >> N;
	std::vector<LL>A(N);
	rep(i, N) in >> A[i];

	std::map<LL, LL>cnt;
	rep(i, N) ++cnt[A[i]];

	LL ans = 0;
	for (LL b = 31; b >= 0; --b)
	{
		LL num = (1LL << b);
		for (auto& p : cnt)
		{
			if (p.first > 0)
			{
				if (cnt.count(num - p.first) > 0)
				{
					if (num == p.first * 2)
					{
						ans += p.second / 2;
						p.second = 0;
					}
					else
					{
						LL res = std::min(p.second, cnt[num - p.first]);
						ans += res;
						p.second -= res; cnt[num - p.first] -= res;
					}
				}
			}
		}
	}

	out << ans << std::endl;
	return 0;
}

