template <typename T>
class FordFulkerson {
private:
	struct edge { int to; T cap; T rev; }; // 行き先、容量、逆辺
	vector<vector<edge>> G;
	vector<char> used;
public:
	const T INF = std::numeric_limits<T>::max();
	FordFulkerson(int V) {
		G.resize(V);
		used.resize(V);
	}
	void add_uni_edge(int from, int to, T cap) {
		// revには、逆辺の容量をすぐに得るためのインデックスを記録
		G[from].push_back(edge{ to, cap, SIZE(G[to]) });
		G[to].push_back(edge{ from, 0, SIZE(G[from]) - 1 });
	}
	// 未テスト
	void add_bi_edge(int v1, int v2, T cap) {
		add_uni_edge(v1, v2, cap);
		add_uni_edge(v2, v1, cap);
	}
	T max_flow(int s, int t) {
		T flow = 0;
		while (true) {
			fill(ALL(used), 0);
			T f = dfs(s, t, INF);
			if (f == 0) return flow;
			flow += f;
		}
	}
	void debug_print() {
		REP(from, SIZE(G)) {
			cout << "from " << from << ": " << endl;
			for (auto e : G[from]) {
				printf(" -> %d, capacity(%d), rev(%d)\n", e.to, e.cap, G[e.to][e.rev].cap);
			}
			cout << endl;
		}
	}
private:
	// vからtまでの最大流を返す
	// fは、頂点vの時点でわかっている可能な最大流の大きさ??
	T dfs(int v, int t, T f) {
		if (v == t) return f;
		used[v] = true;
		// v番目の頂点が持つ辺でループ
		REP(i, SIZE(G[v])) {
			edge &e = G[v][i];
			// まだ辺eに余裕がある場合
			if (!used[e.to] && e.cap > 0) {
				auto d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
};

int main(void)
{
	int N;
	cin >> N;
	vector<ll> As(N);
	map<int, int> A_count;
	REP(n, N) {
		ll a;
		cin >> a;
		As[n] = a;
		A_count[a]++;
	}

	vector<ll> targets;
	ll tmp = 2;
	while (1) {
		targets.pb(tmp);
		tmp *= 2;
		if (tmp > ll(1e9) * 2) break;
	}

	// 絶対マッチングしないものは候補から外す
	vector<ll> As2;
	map<ll, int> a_to_idx;
	int idx = 0;
	for (auto kv : A_count) {
		auto a = kv.first;
		bool ok = false;
		for (auto t : targets) {
			auto b = t - a;
			if (b <= 0) continue;
			if (A_count.count(b)) {
				ok = true;
				break;
			}
		}
		if (ok) {
			As2.push_back(a);
			a_to_idx[a] = idx;
			++idx;
		}
	}

	int V = SIZE(As2);
	FordFulkerson<int> ff(V * 2 + 2);
	int S = V * 2;
	int T = S + 1;
	REP(n, V) {
		auto a = As2[n];
		for (auto t : targets) {
			auto b = t - a;
			if (b <= 0) continue;
			if (a_to_idx.count(b)) {
				auto m = a_to_idx[b];
				if (n == m) {
					int pair_max = (A_count[a] / 2) * 2;
					if (pair_max > 0) {
						ff.add_uni_edge(n, V + n, pair_max);
					}
				}
				else {
					ff.add_uni_edge(n, V + m, min(A_count[a], A_count[b]));
				}
			}
		}
	}
	REP(n, V) {
		auto a = As2[n];
		ff.add_uni_edge(S, n, A_count[a]);
		ff.add_uni_edge(V + n, T, A_count[a]);
	}

	auto res = ff.max_flow(S, T);
	cout << res / 2 << endl;
	return 0;
}

