		ll here = 0;
		for(int i=0;i<=35;i++){
			ll st = 1LL<<i;
			if(st>it.F){
				ll rem = st - it.F;
				if(mp.count(rem)) here += mp[rem];
				if(rem == it.F) here--;
			}
		}
		choice[it.F] = here;
	}
	ll ans = 0;
	for(auto it:mp){
		while(it.S>0){
			ll ele = -1;
			ll count = 0;
			for(int i=0;i<=35;i++){
				ll st = 1LL<<i;
				if(st>it.F){
					ll rem = st - it.F;
					if(mp.count(rem) && ((ele == -1 && choice[rem]!=0) || count>choice[rem])){
						if(rem == it.F && it.S == 1) continue;
						ele = rem;
						count = choice[rem];
					}
				}
			}
			if(ele != -1){
				for(int i=0;i<=35;i++){
					ll st = 1LL<<i;
					if(st>it.F){
						ll rem = st - it.F;
						if(mp.count(rem)) choice[rem]--;
					}
				}
				for(int i=0;i<=35;i++){
					ll st = 1LL<<i;
					if(st>ele){
						ll rem = st - ele;
						if(mp.count(rem)) choice[rem]--;
					}
				}
				ans++;
				it.S--;
				if(it.F == ele) it.S--;
				else mp[ele]--;
			}
			else break;
		}
	}
	cout << ans << endl;
	return 0;
}

