long long mod = 1e9+7;
class Mint {
public:
  long long x;
  Mint(){}; // 引数なしでも定義できるように引数なしコンストラクタも用意しておく
  Mint(long long a){
    x = a%mod;
    while(x<0){
      x += mod;
    }
  };
  Mint& operator += (const Mint &a){
    x+=a.x;
    x%=mod;
    return *this;
  }
  Mint& operator -= (const Mint &a){
    x += (mod - a.x);
    x%=mod;
    return *this;
  }
  Mint& operator *= (const Mint &a){
    x*=a.x;
    x%=mod;
    return *this;
  }

  // a^n mod を計算する
  // Useaeg: Mint z = y.pow(y, n);
  Mint pow(Mint a, long long n) const {
    Mint y(1);
    Mint b(a);
    while (n > 0) {
      if (n & 1) y *= b;
      b *= b;
      n >>= 1;
    }
    return y;
  }

  // a^{-1} mod を計算する
  Mint modinv(const Mint &a) const {
    return pow(a, mod-2);
  }

  Mint& operator /= (const Mint &a) {
    x *= modinv(a).x;
    x %= mod;
    return *this;
  }

  Mint operator + (Mint &a) const {
    Mint y(*this);
    y += a;
    return y;
  }

  Mint operator - (Mint &a) const {
    Mint y(*this);
    y -= a;
    return y;
  }

  Mint operator * (Mint &a) const {
    Mint y(*this);
    y *= a;
    return y;
  }

  Mint operator / (Mint &a) const {
    Mint y(*this);
    y/=a;
    return y.x;
  }

  // nCk @mod を計算する
  Mint nCk(Mint &n, const long long k) const {
    Mint y = Mint(1);
    for (Mint i(0); (i.x)<k; i.x++){
      y *= (n-i);
      y /= i;
    }
    return y;
  }

  // nPk @mod を計算する
  Mint nPk(Mint &n, long long k) const {
    Mint y(1);
    for (Mint i(0); (i.x)<k; i.x++){
      y *= (n-i);
    }
    return y;
  }
};

int main(){
  std::vector<long long > power2;
  long long multiple = 1;
  while(multiple<1e16){
    power2.push_back(multiple);
    multiple *= 2;
  }
  int N;
  std::cin >> N;
  std::vector<long long > A(N);
  std::vector<bool > used(N+4, false);
  for (int i=0; i<N; i++){
    std::cin >> A[i];
  }
  std::sort(A.begin(), A.end());
  int index = N-1;
  int ans = 0;
  while(index>=0){
    if (used[index]){
      index--;
      continue;
    }
    used[index]=true;
    auto itr = std::upper_bound(power2.begin(), power2.end(), A[index]);
    long long target = *itr;
    long long need = target - A[index];
    //printf("index=%d, need=%d\n", index, need);
    auto itr2 = std::lower_bound(A.begin(), A.end(), need);
    while(itr2!=A.end() && *itr2==need){
      int i = itr2-A.begin();
      if (!used[i]) {
        ans++;
        used[i] = true;
        break;
      }
      itr2++;
    }
    index--;
  }
  std::cout << ans << std::endl;
  return 0;
}

