const int maxn=2e5+10;
int a[maxn],idx[maxn],idx_cnt,sum[maxn],ans=0;
int Begin[maxn],Next[maxn*30],to[maxn*30],e,vis[maxn];
inline void add_edge(int x,int y){
	to[++e]=y;
	Next[e]=Begin[x];
	Begin[x]=e;
}
void dfs(int x){
	int tot=0;
	vis[x]=1;
	for(int i=Begin[x];i;i=Next[i]) if(!vis[to[i]]){
		dfs(to[i]);
		tot+=sum[to[i]];
	}
	chkmin(tot,sum[x]);
	sum[x]-=tot,ans+=tot;
	REP(i,0,30) if(x==(1<<i)){
		ans+=sum[x]/2,sum[x]%=1;
		return;
	}
}
int main(){
	int n=read();
	REP(i,1,n){
		a[i]=read();
		idx[++idx_cnt]=a[i];
	}
	sort(idx+1,idx+idx_cnt+1);
	idx_cnt=unique(idx+1,idx+idx_cnt+1)-idx-1;
	REP(i,1,n) sum[lower_bound(idx+1,idx+idx_cnt+1,a[i])-idx]++;
	REP(i,1,idx_cnt) REP(j,0,30) if(i<=(1<<j)){
		int u=(1<<j)-idx[i];
		u=lower_bound(idx+1,idx+idx_cnt+1,u)-idx;
		if(idx[u]==(1<<j)-idx[i]) add_edge(i,u);
	}
	REP(i,1,idx_cnt) if(!vis[i]) dfs(i);
	printf("%d\n",ans);
	return 0;
}

