LL n,a[200010],ans;
bool vis[200010],ok;
vector <LL> pw;

LL FIND(LL lb,LL ub)
{
	while(lb<ub)
	{
		LL mid=(lb+ub+1)/2;
		if(vis[mid]) lb=mid+1;
		else ub=mid;
	}
	if(!vis[lb]) return lb;
	return (LL)(-1);
}

int main()
{
	pw.pb(1);
	repn(i,40) pw.pb(pw[i-1]*2LL);//,cout<<pw[i]<<endl;
	cin>>n;
	rep(i,n) cin>>a[i];
	sort(a,a+n);
	for(LL i=n-1;i>=0;i--)
	{
		if(vis[i]) continue;
		vis[i]=true;
		LL sum=pw[lower_bound(pw.begin(),pw.end(),a[i])-pw.begin()];
		if(sum==a[i]) sum=pw[lower_bound(pw.begin(),pw.end(),a[i]*2)-pw.begin()];
		LL targ=sum-a[i];
		LL pos=lower_bound(a,a+n,targ)-a,
		pos1=upper_bound(a,a+n,targ)-a;
		if(pos==n||a[pos]!=targ) continue;
		ok=false;
		LL j=FIND(pos,pos1-1);
		if(!ok) vis[i]=false;
		vis[j]=true;
		ans++;
	}
	cout<<ans<<endl;
	rt0;
}

