		ll res = 1;
		while ( res <= x ) res *= 2;
		return ( res );
	};

	ll cnt = 0;
	vector<bool> flg( N, false );
	rrep( i, N )
	{
		if ( flg[i] == false )
		{
			ll s = check( v[i] );
			auto it1 = lower_bound( ALL( v ), s - v[i] );
			auto it2 = upper_bound( ALL( v ), s - v[i] );
			if ( *it1 == s - v[i] )
			{
				while ( it1 != it2 )
				{
					auto d = distance( v.begin(), it1 );
					if ( flg[d] ) ++it1;
					else if ( i == d ) ++it1;
					else
					{
						++cnt;
						flg[i] = flg[d] = true;
						break;
					}
				}
			}
		}
	}

	cout << cnt << endl;

	return ( 0 );
}

