	for (int i = 0; i < n; ++i)
	{
		cin >> a[i];

		mapp[a[i]] += 1;
	}

	map<ll, ll> ind;

	for (int i = 0; i < n; ++i)
	{
		for (ll p = 0; p <= 30; ++p)
		{
			ll del = (1ll << p) - a[i];

			if (del < 0)
				continue;

			ind[a[i]] += mapp[del];

			if (a[i] == del)
				--ind[a[i]];
		}
	}

	vector<pair<ll, ll>> vec;
	for (int i = 0; i < n; ++i)
	{
		vec.push_back({ind[a[i]], a[i]});
	}

	sort(vec.begin(), vec.end());

	ll ans = 0;

	for (int i = 0; i < vec.size(); ++i)
	{
		ll val = vec[i].second;

		if (vec[i].first < 0)
			continue;

		ll minn = inf, res = -1;

		for (ll p = 0; p <= 30; ++p)
		{
			ll del = (1ll << p) - val;

			if (del < 0)
				continue;

			if (ind[del] - (val == del) < minn && ind[del] - (val == del) > 0 && mapp[del] > 0 && mapp[val] > 0)
			{
				minn = mapp[del];
				res = del;
			}
		}

		if (res != -1)
		{
			for (ll p = 0; p <= 30; ++p)
			{
				if ((1ll << p) - val >= 0 && (1ll << p) - val != val && mapp[(1ll << p) - val] > 0)
				{
					ind[(1ll << p) - val] -= 1;
					ind[val] -= 1;
				}

				if ((1ll << p) - res >= 0 && (1ll << p) - res != res && mapp[(1ll << p) - res] > 0)
				{
					ind[(1ll << p) - res] -= 1;
					ind[res] -= 1;
				}
			}

			mapp[res] -= 1;
			mapp[val] -= 1;

			ind[val] += 1;
			ind[res] += 1;
			ans += 1;
		}
	}


	cout << ans << endl;
	return 0;
}

