class NetworkFlow {
public:
	//引数：頂点数
	NetworkFlow(int size) {
		G.resize(size);
		used.resize(size);
	}

	//fromからtoへ向かう容量capの辺をグラフに追加する
	void add_edge(int from, int to, int cap) {
		Edge e1 = {to, cap, (int)G[to].size()};
		Edge e2 = {from, 0, (int)G[from].size() - 1};
		G[from].push_back(e1);
		G[to].push_back(e2);
	}

	//sからtへの最大流を求める
	int max_flow(int s, int t) {
		int flow = 0;
		while(true) {
			fill(used.begin(), used.end(), false);
			int f = dfs(s, t, INF);
			if(f == 0)return flow;
			flow += f;
		}
	}


private:
	//型と変数
	struct Edge { int to, cap, rev; };//辺を表す構造体（行き先、容量、逆辺）
	vector<vector<Edge>> G;   //グラフの隣接リスト表現
	vector<bool> used;//DFSで既に調べたかのフラグ

					  //関数
					  //増加パスをDFSで探す
	int dfs(int v, int t, int f) {
		if(v == t)return f;
		used[v] = true;
		REP(i, (int)G[v].size()) {
			Edge& e = G[v][i];
			if(!used[e.to] && e.cap > 0) {
				int d = dfs(e.to, t, min(f, e.cap));
				if(d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
};
using NF = NetworkFlow;

//二部マッチング：蟻本p195～
class BipartiteMatching: public NetworkFlow {
public:
	//引数：頂点数
	BipartiteMatching(int size):
		NetworkFlow(size + 2),
		start(size),
		end(size + 1)
	{}

	//二部グラフの左側にある頂点の登録
	void add_left(int id) {
		add_edge(start, id, 1);
	}

	//右側
	void add_right(int id) {
		add_edge(id, end, 1);
	}

	//左側と右側の頂点の間にある辺の登録
	void add_mid(int left, int right) {
		add_edge(left, right, 1);
	}

	//最大マッチングを求める
	int max_matching() {
		return max_flow(start, end);
	}




private:
	const int start, end;
};
