        }
        if(q[p[i]]==1) q.erase(p[i]);
        else q[p[i]]--;
        if(q[x-p[i]]==1) q.erase(x-p[i]);
        else q[x-p[i]]--;        
        ans++;
        break;
      }
      x*=2;
    }
  }

