int main()
{
    int N;
    cin >> N;
    vector<int> A(N);
    for( int i = 0; i < N; ++i ) cin >> A[i];


    map<int,int> mp;
    for( int i = 0; i < N; ++i ) ++mp[A[i]];

    sort( A.begin(), A.end(), greater<int>() );

    int ans = 0;
    for( int i = 0; i < N; ++i ){
        if( mp[A[i]] == 0 ) continue;
        // A[i] < tmp = 2^k なる tmp を求める
        long long tmp = 1;
        while( tmp <= A[i] ) tmp *= 2;
        if( A[i]*2 == tmp ){  // A[i] = tmp/2 = 2^{k-1} のとき
            if( mp[A[i]] >= 2 ){
                ++ans;
                mp[A[i]] -= 2;
            }
        }else{
            if( mp[tmp-A[i]] > 0 ){
                ++ans;
                --mp[A[i]];
                --mp[tmp-A[i]];
            }
        }
    }
    cout << ans << endl;

    return 0;
}

