    {
        while (j<n&&a[i]==a[j])    ++j;
        int f=__builtin_popcount(a[i]);
        if (f==1)
            ans+=(j-i)/2;
        if (f!=1||((j-i)&1))
            cnt[mp[a[i]]=++N]=j-i;
    }
    for (auto p:mp)
        for (int b=0;b<31;++b)
        {
            LL c=(1LL<<b)-p.first;
            if (p.first<=c)   continue;
            if (mp.count(c))
                join(p.second,mp[c]);
        }
}

