using namespace std;

set<unsigned> powers = {2};

unsigned count_pairs(multiset<unsigned>& S)
{
  uint64_t count = 0;

  while (S.size()>1) {
    auto x1 = S.begin();
    random_device rand;
    advance(x1,rand()%S.size());
    auto s1 = *x1;
    S.erase(s1);

    unsigned num_possible_options = 0;
    unsigned possible_option;
    for (unsigned power : powers ) {
      if (power < s1)
	continue;
      unsigned s2 = power - s1;
      if (S.find(s2)!=S.end()) {
	++num_possible_options;
	possible_option = s2;
      }
    }

    if (num_possible_options==1) {
      ++count;
      S.erase(possible_option);
    } else if (num_possible_options>1) {
      S.insert(s1);
    }
  }
  return count;
}

int main()
{
  int N;
  cin >> N;

  multiset<unsigned> odds, evens;

  for (int n=0; n<N; ++n) {
    unsigned a;
    cin >> a;
    if (a%2)
      odds.insert(a);
    else
      evens.insert(a);
  }

  while(true) {
    unsigned next = *powers.rbegin()*2;
    if (next > 2e9)
      break;
    powers.insert(next);
  }

  uint64_t count = 0;

  count += count_pairs(odds);
  count += count_pairs(evens);

  cout << count << endl;

  return 0;
}

