template<class Type>
Type solve(Type res = Type()){
    int N; cin >> N;
    vector<ll> A(N); for(auto& in:A) cin >> in;
    sort(A.begin(),A.end());
    map<ll,ll> mp; for(auto a:A) mp[a]++;
    for(int i = N-1;i>=0;i--){
        if(mp[A[i]]==0) continue;
        ll v = 1; while(v <= A[i]) v *= 2;
        ll r = v-A[i];
