// Dinic
int INF = 1000000000;
const int MAX_V = 400002;
struct edge { int to, cap, rev; };

vector<edge> G[MAX_V];
int level[MAX_V];
int iter[MAX_V];

void add_edge(int from, int to, int cap) {
   G[from].push_back((edge){to, cap, G[to].size()});
   G[to].push_back((edge){from, 0, G[from].size() - 1});
}

void bfs(int s) {
   memset(level, -1, sizeof(level));
   queue<int> que;
   level[s] = 0;
   que.push(s);
   while (!que.empty()) {
      int v = que.front(); que.pop();
      for (int i = 0; i < G[v].size(); i++) {
         edge &e = G[v][i];
         if (e.cap > 0 && level[e.to] < 0) {
            level[e.to] = level[v] + 1;
            que.push(e.to);
         }
      }
   }
}


int dfs(int v, int t, int f) {
   if (v == t) return f;
   for (int &i = iter[v]; i < G[v].size(); i++) {
      edge &e = G[v][i];
      if (e.cap > 0 && level[v] < level[e.to]) {
         int d = dfs(e.to, t, min(f, e.cap));
         if (d > 0) {
            e.cap -= d;
            G[e.to][e.rev].cap += d;
            return d;
         }
      }
   }
   return 0;
}

int max_flow(int s, int t) {
   int flow = 0;
   for (;;) {
      bfs(s);
      if (level[t] < 0) return flow;
      memset(iter, 0, sizeof(iter));
      int f;
      while ((f= dfs(s, t, INF)) > 0) {
         flow += f;
      }
   }
}

int calc(int N) {
   int i = 0;
   int ans;
   for (;;) {
      if (N >= pow(2, i) && N < pow(2, i + 1)) {
         ans = i;
         break;
      }
      i++;
   }
   return ans;
}

int main() {
   int N;
   cin >> N;
   ll A[N];
   map<ll, int> log, pos;
   for (int i = 0; i < N; i++) {
      cin >> A[i];
      log[A[i]]++;
      pos[A[i]] = i;
   }
   int s = 2 * N;
   int t = s + 1;
   for (int i = 0; i < N; i++) {
      add_edge(s, i, 1);
      add_edge(i + N, t, 1);
   }
   for (int i = 0; i < N; i++) {
      // cout << i << ": " << A[i] << endl;
      int k = calc(A[i]) + 1;
      ll amari = pow(2, k) - A[i];
      ll tmp;
      for (int j = k - 1; j <= 30; j++) {
         if (j == k - 1) tmp = amari;
         else tmp += pow(2, j);
         // cout << tmp << endl;
         if (log[tmp] > 0 && A[i] != tmp) {
            // cout << A[i] << " " << tmp << endl;
            add_edge(i, pos[tmp] + N, 1);
         }
      }
   }
   int ans = max_flow(s, t) / 2;
   for (int i = 0; i <= 30; i++) {
      int tmp = log[pow(2, i)];
      if (tmp > 1) ans += tmp / 2;
   }

   cout << ans << endl;
   return 0;
}

