        cin>>in;
        v[i]=in;
        canuse.insert(in);
    }
    ll t=0;
    sort(ALL(v),greater<>());
    while(!(v[0]>=pow(2,t)&&v[0]<pow(2,t+1))){
        t++;
    }
    rep(i,n){
        while(!(v[i]>=pow(2,t)&&v[i]<pow(2,t+1))){
            t--;
        }
        auto itr = canuse.find(pow(2,t+1)-v[i]);
        if(itr!=canuse.end()){
            if(v[i]%2==0){
                canuse.erase(itr);
                auto itr2 = canuse.find(v[i]);
                if(itr2 != canuse.end()){
                    canuse.erase(itr2);
                    ans++;
                }
            }else{
                canuse.erase(pow(2,t+1)-v[i]);
                canuse.erase(v[i]);
                ans++;
            }
        }
    }
    cout<<ans<<endl;
    return  0;
}

