		if (a[N - 1] + a[N - 2] < x) { continue; }
		for (int i = 0; i < N; ++i) {
			if (mp[a[i]] == 0) { continue; }

			ll y = x - a[i];
			if (y == a[i]) {
				if (mp[y] >= 2) {
					mp[y] -= 2;
					++res;
				}
			} else if (mp[y] > 0) {
				mp[a[i]] -= 1;
				mp[y] -= 1;
				++res;
			}
		}
		if (N - res*2 < 2) { break; }
	}

	cout << res << endl;

	return 0;
}

