        // 現在の数字よりも大きい２のべき乗を作成
        int search = (1UL << (bitPos + 1)) - x;
        // 自分自身は使用済みにする
        mp[x]--;
        if (mp[search] >= 1) {
            ans++;
            mp[search]--;
        }
    }
    cout << ans << endl;

