    ll pow2[32] = {1};
    for(int i = 1; i < 32; i++){
        pow2[i] = pow2[i-1]*2;
    }

    while(idx < B.size()){
        ll num = B[idx].first;
        if(B[idx].second == 0){
            idx++;
            continue;
        }
        bool found = false;
        int beki = (int) log2(num);
        ll aim = pow2[beki+1] - num;
        //cout << num << " " << aim << endl;
        //aimをBの中からにぶたん、あればfound = true
        int ng = -1, ok = B.size();
        int m = (ng+ok)/2;
        while(abs(ng-ok) > 1){
            if(B[m].first > aim) ng = m;
            else ok = m;
            m = (ng+ok)/2;
        }
        if(B[ok].first == aim && B[ok].second > 0) found = true;
        if(aim == num && B[ok].second <= 1) found = false;

        if(found){
            cnt++;
            B[idx].second -= 1;
            B[ok].second -= 1;
            if(B[idx].second == 0) idx++;
        }
        else idx++;
    }
    cout << cnt << endl;
    return 0;
}

