{
    vis[node]=1;
    c[col]++;
    for(int to:g[node]){
        if(!vis[to])
            dfs(to,col^1);
    }
}
void solve()
{   
    int n;
    cin>>n;
    for(int i=0;i<n;++i)
    {
        ll x;
        cin>>x; cnt[x].push_back(i);
    }
    for(ll res=2;res<=binpow(2,34);res*=2)
    {
        for(auto it:cnt)
        {
            if(cnt.count(res-it.first)){
                for(auto it1:cnt[it.first])
                    for(auto it2:cnt[res-it.first]){
                        if(it1==it2) continue;
                        g[it1].push_back(it2);
                    }
            }
        }
    }
    int ans=0;
    for(int i=0;i<n;++i){
        if(!vis[i])
        {
            dfs(i);
            ans+=min(c[0],c[1]);
            c[0]=0; c[1]=0;
        }
    }
    cout<<ans;

}   
