		int k = 0, tmp = a[i];
		while (tmp != 0) {
			tmp >>= 1;
			k++;
		}
		tmp = (1 << k) - a[i];
		eprintf("%d+%d=2^n\n", a[i], tmp);
		int ok = i, ng = n;
		while (ng - ok > 1) {
			int med = (ok + ng) / 2;
			if (a[med] >= tmp) ok = med;
			else ng = med;
		}
		if (a[ok] == tmp) {
			while(ok + 1 < n && a[ok + 1] == a[ok] && !used[ok + 1]) ok++;
			if (!used[ok]) {
				eprintf("(%lld,%d)\n", i, ok);
				ans++;
			}
			used[ok] = true;
		}
	}
	cout << ans << "\n";
	return 0;
}

