inline ll get_highest_one_bit(ll a)
{
	while ((a & (a - 1)) != 0)
	{
		a = a & (a - 1);
	}
	return a;
}

int solve() {
	ll N;
	cin >> N;

	vector<ll> as(N);
	REPD(i, 0, N) cin >> as[i];
	sort(as.begin(), as.end());

	ll res = 0;
	vector<bool> used(N, false);
	REPD(i, 0, N) {
		if (used[N - i - 1]) continue;
		used[N - i - 1] = true;
		ll a = as[N - i - 1];
		auto lower_iter = lower_bound(as.begin(), as.end(), get_highest_one_bit(a) * 2LL - a);
		auto upper_iter = upper_bound(as.begin(), as.end(), get_highest_one_bit(a) * 2LL - a);
		while(lower_iter != upper_iter) {
			auto idx = distance(as.begin(), lower_iter);
			if (!used[idx]) {
				used[idx] = true;
				++res;
				break;
			} 
			++lower_iter;
		}
	}

	RET(res);

	return 0;
}

