int bin_search(std::vector<long long>& A, long long x, int start) {
    int N = A.size();
    int L = start;
    int R = N;

    while (R - L > 1) {
        int M = (R + L) / 2;
        if (A[M] == x) return M;
        if (A[M] > x){
            L = M;
        }
        else {
            R = M;
        }

    }
    return -1;

}

