      if (used.find(j) != used.end()) {
        continue;
      }
      long c = b - a[j];
      if (c < 1) {
        break;
      }
      auto it = lower_bound(a, a + j, c);
      if (it == a + j) {
        continue;
      }
      while (it != a + j && *it == c) {
        if (used.find(j) == used.end() && used.find(it-a) == used.end()) {
          used.insert(j);
          used.insert(it - a);
          break;
        }
        ++it;
      }
    }
  }
  cout<<used.size()/2<<endl;
}

