    list<int> A;
    int tmp;
    for (int i = 0; i < N; ++i){
        cin >> tmp;
        A.push_back(tmp);
    }

    A.sort();

    int ans = 0;
    int a;

    while (A.size() > 0){
        a = A.back();
        A.pop_back();
        for (auto itr = A.begin(); itr != A.end();){
            if (check_pow_two(a + *itr)){
                ++ans;
                A.erase(itr);
                break;
            } else{
                ++itr;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

