	ListG(int s) : root(-1) {
		size = s;
		to = make_v<vector<int>>(size);
	}

	void setDirectedEdge(int f, int t) {
		to[f].push_back(t);
	}
	void setIndirectedEdge(int v1, int v2) {
		setDirectedEdge(v1, v2);
		setDirectedEdge(v2, v1);
	}

	void dfs(int x) {
		// do something
	}

	void makeTree(int r) {
		root = r;
		p = make_v<int>(size);
		p[root] = -1;
		depth = make_v<int>(size);
		mtdfs(root, 0);
		// count leaf node
		auto idxs = make_v<int>(size);
		iota(all(idxs), 0);
		leaf_idx = set<int>(all(idxs));
		FOR(i, 1, size)
			leaf_idx.erase(p[i]);
	}

	void makeEulerTour() {
		assert(root >= 0);
		et_begin = make_v<int>(size);
		et_end = make_v<int>(size);
		tmp_k = 0;
		etdfs(root, -1);
	}

	int size, root;
	vector<int> p; // parent for each node. parent of root = -1
	vector<int> depth; // for each node. depth of root node = 0
	vector<int> euler_tour;
	vector<int> et_begin, et_end;
	set<int> leaf_idx;

	int tmp_k;
private:	
	void mtdfs(int c, int d) {
		depth[c] = d;
		REP(i, to[c].size()) {
			int next = to[c][i];
			if (p[c] == next) continue;
			p[next] = c;
			mtdfs(next, d + 1);
		}
	}
	void etdfs(int vidx, int pidx) {
		et_begin[vidx] = tmp_k;
		euler_tour.push_back(vidx);
		tmp_k++;
		REP(i, to[vidx].size()) {
			if (to[vidx][i] != pidx) {
				etdfs(to[vidx][i], vidx);
				euler_tour.push_back(vidx);
				tmp_k++;
			}
		}
		et_end[vidx] = tmp_k;
	}
};

template <typename T>
class BinaryIndexedTree {
public:
	int size;
	vector<T> data;

	BinaryIndexedTree(int s, T initial_value = T(0)) {
		size = s;
		data = make_v<T>(size+1);
		fill_v(data, initial_value);
	}

	void add(int idx, T value) {
		while (idx <= size) {
			data[idx] += value;
			idx += idx & -idx;
		}
	}

	T sum(int idx) {
		T s = 0;
		while (idx > 0) {
			s += data[idx];
			idx -= idx & -idx;
		}
		return s;
	}
};

int mergecount(vector<int> &a) {
  int count = 0;
  int n = a.size();
  if (n > 1) {
    vector<int> b(a.begin(), a.begin() + n/2);
    vector<int> c(a.begin() + n/2, a.end());
    count += mergecount(b);
    count += mergecount(c);
    for (int i = 0, j = 0, k = 0; i < n; ++i)
      if (k == c.size())       a[i] = b[j++];
      else if (j == b.size())  a[i] = c[k++];
      else if (b[j] <= c[k])   a[i] = b[j++];
      else                   { a[i] = c[k++]; count += n/2 - j; }
  }
  return count;
}

