llong cnnnt(llong x){
	llong pw = 1, ans = 0;
	cnt[x]--;
	while(pw <= OO){
		if(x > pw) {
			pw *= 2;
			continue;
		}ans += cnt[pw - x];
		pw *= 2;
	}cnt[x]++;
	return ans;
}

