using namespace std;

struct edge { int to, rev; ll cap; };
vv<edge> g;
vi itr, level;

void add_edge(int from, int to, int cap) {
  g[from].push_back((edge){to, int(g[to].size()), cap});
  g[to].push_back((edge){from, int(g[from].size()-1), 0});
}

int n, m; // number of nodes, edges
vector<bool> used;
ll INF = 1e18;

void debug_g() {
  rep (i, n) {
    printf("u : %d\n", i);
    for (auto e : g[i]) {
      printf("%d %lld, ", e.to, e.cap);
    }
    printf("\n");
  }
}

void dinic_bfs(int s) {
  level.assign(n, -1);
  deque<int> q;
  level[s] = 0;
  q.push_back(s);
  while (!q.empty()) {
    int v = q.front();
    q.pop_front();
    for (edge& e : g[v]) {
      if (e.cap > 0 and level[e.to] < 0) {
        level[e.to] = level[v] + 1;
        q.push_back(e.to);
      }
    }
  }
}

ll dinic_dfs(int v, int t, ll f) {
  if (v == t) {
    return f;
  }
  int sz = g[v].size();
  FOR (i, itr[v], sz) {
    edge& e = g[v][i];
    if (level[v] >= level[e.to] or e.cap <= 0) { continue; }
    ll d = dinic_dfs(e.to, t, min(f, e.cap));
    if (d > 0) {
      e.cap -= d;
      g[e.to][e.rev].cap += d;
      return d;
    }
  }
  return 0;
}

ll dinic(int s, int t) {
  ll flow = 0;
  ll f;
  while (dinic_bfs(s), level[t] >= 0) {
    itr.assign(n, 0);
    while (true) {
      f = dinic_dfs(s, t, INF);
      if (f > 0) {
        flow += f;
      } else {
        break;
      }
    }
  }
  return flow;
}

