	for (auto p : count)
	{
		indexes[p.first] = ++index;
		data[index] = p.first;
	}
	std::vector<std::map<int, int>> edge(K + 2);
	for (std::uint32_t i = 1; i <= max + 1; i <<= 1)
	{
		for (int k : boost::irange(0, K))
		{
			auto d = data[k];
			if (d >= i)
			{
				continue;
			}
			if (i - d != d && indexes.count(i - d))
			{
				edge[k].emplace(indexes[i - d], std::min(count[d], count[i - d]));
			}
		}
	}
	std::vector<int> flag(K);
	for (int i : boost::irange<int>(0, K))
	{
