LL dfs(LL v, bool flag)
{
	if (vis[v]) return 0;
	vis[v] = true;
	LL res = 0;
	if (!flag) for (auto u : G[v]) res += dfs(u, flag);
	else
	{
		std::vector<std::pair<LL, LL>>cnt(G[v].size());
		LL sum = 0;
		rep(i, G[v].size())
		{
			auto temp = vis;
			cnt[i].first = dfs(G[v][i], false) + !vis[G[v][i]];
			vis = temp;
			cnt[i].second = dfs(G[v][i], true);
			sum += cnt[i].second;
		}
		rep(i, G[v].size())
		{
			LL temp = sum - cnt[i].second + cnt[i].first;
			res = std::max<LL>(res, temp);
		}
	}
	return res;
}

