struct UnionFind {
  vector<int> parent;
  UnionFind(int n) {
    parent.resize(n, -1);
  }
  int root(int x) {
    if (parent[x] == -1)
      return x;
    return parent[x] = root(parent[x]);
  }
  void unite(int x, int y) {
    if (root(x) == root(y))
      return;
    x = root(x); y = root(y);
    parent[x] = y;
    return;
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
};

int inv(int n) {
  stringstream ss;
  ss << bitset<32>(n);
  string s = ss.str(); // "00001001"
  all(reverse, s);
  while (s.back() == '0' && !s.empty()) s.pop_back();
  while (s.back() == '1' && !s.empty()) s.pop_back();

  int ans = 0, two = 1;
  for (const auto& e : s) {
    if (e == '0')
      ans += two;
    two *= 2;
  }
  return ans;
}
