  ll ans = 0;

  for(auto i = m.rbegin();i != m.rend();i++) {
    REP(j, 30) {
      ll tmp = (1<<j) - *i;
      if(*i != tmp && m.find(tmp) != m.end()) {
        ans++;
        m.erase(tmp);
        m.erase(*i);
      }
    }
  }

  cout << ans << endl;

}

