bool dfs(int v)
{
    used[v]=1;
    for(int u: G[v]) {
        int w=match[u];
        if (w<0 || (!used[w] && dfs(w))) {
            match[v]=u;
            match[u]=v;
            return true;
        }
    }
    return false;
}

int bipartite_mathing(int n)
{
    int res=0;
    memset(match, -1, sizeof(match));
    for(int v=0; v<n; ++v) if (match[v]<0) {
        memset(used, 0, sizeof(used));
        if (dfs(v)) ++res;
    }
    return res;
}

