int solve1(std::vector<int> a) {
  int ans = 0;
  std::sort(a.begin(), a.end());
  for(int k = 30; k >= 0; k--) {
    int n = (int) a.size();
    std::vector<bool> got(n, false);
    for(int l = 0, r = n - 1; l < n; l++) {
      if(got[l]) continue;
      while(r >= 0 && a[l] + a[r] > (1 << k)) r--;
      while(r >= 0 && got[r]) r--;
      if(l >= r) break;
      if(!got[l] && !got[r] && a[l] + a[r] == (1 << k)) {
        got[l] = got[r] = true;
        ans++;
      }
    }
    std::vector<int> b;
    for(int i = 0; i < n; i++) {
      if(!got[i]) b.push_back(a[i]);
    }
    a.swap(b);
  }
  return ans;
}

