int binaries(unsigned int n){
  unsigned int mask = 1;
  unsigned int nn = n;
  int count = 0;
  for(int i = 0; i < 32; i++){
    count += (nn&mask);
    //printf("n&mask : %u&%u\n", n, mask);
    //printf("count : %d\n", count);
    nn = nn >> 1;
  }
  return count;
}

