struct UnionFind {
  vector<int> parent;
  UnionFind(int n) {
    parent.resize(n, -1);
  }
  int root(int x) {
    if (parent[x] == -1)
      return x;
    return parent[x] = root(parent[x]);
  }
  void unite(int x, int y) {
    if (root(x) == root(y))
      return;
    x = root(x); y = root(y);
    parent[x] = y;
    return;
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
};

