	ll N;
	cin >> N;
	vector<ll> a(N);
	for (int i = 0; i < N; ++i) { cin >> a[i]; }
	sort(a.begin(), a.end());

	ll min_t = 0;
	ll max_t = 0;
	while (pow(2, max_t) <= a[N - 1]) {
		++max_t;
		if ((min_t == 0) && (pow(2, max_t) > a[0])) {
			min_t = max_t - 1;
		}
	}

	vector<vector<ll>> d(N);
	for (int i = 0; i < N; ++i) {
		for (ll t = min_t; t <= max_t; ++t) {
			if (pow(2, t) <= a[i]) { continue; }

			ll x = pow(2, t) - a[i];
			ll u = lower_bound(a.begin(), a.end(), x + 1) - a.begin();
			ll l = lower_bound(a.begin(), a.end(), x) - a.begin();
			if (a[l] != x) { continue; }
			for (ll j = l; j < u; ++j) {
				if (i == j) { continue; }
				d[i].emplace_back(j);
			}
		}
	}

	vector<P> cnt(N);
	for (int i = 0; i < N; ++i) {
		cnt[i] = P(d[i].size(), i);
	}
	sort(cnt.begin(), cnt.end());

	vector<ll> wl(N);
	for (int i = 0; i < N; ++i) {
		wl[cnt[i].second] = cnt[i].first;
	}

	vector<bool> used(N, false);
	ll res = 0;
	for (int i = 0; i < N; ++i) {
		if (cnt[i].first == 0) { continue; }
		if (used[cnt[i].second]) { continue; }

		int key = 0;
		int num = 1e8;
		for (int j = 0; j < d[cnt[i].second].size(); ++j) {
			if (used[d[cnt[i].second][j]]) { continue; }
			if (wl[d[cnt[i].second][j]] < num) {
				key = d[cnt[i].second][j];
				num = wl[d[cnt[i].second][j]];
			}
		}
		++res;
		used[cnt[i].second] = true;
		used[key] = true;
	}

	cout << res << endl;

	return 0;
}

