using namespace std;
vector<int> a;
vector<bool> us;
int fnd(int q){
    int n = a.size();
    int l = -1, r = n-1;
    while(r-l>1){
        int m = (r+l)/2;
        if(a[m]<q ||(a[m]==q && us[m])) l = m;
        else r = m;
    }
    if(a[l+1]!=q || us[l+1]) return -1;
    return l+1;
}
