    for(ll i = 1LL << 32; i; i >>= 1){
        for(int j = 0; j < n; ++j){
            if(i <= a[j])
                break;
            for(auto& xx : m[i - a[j]]){
                if(a[xx] == a[j])
                    continue;
                edges[j].push_back(xx);
            }
        }
    }
    vector<int> col(n, -1);

    function<void(int,int)> f = [&](int x, int c){
        for(auto& y : edges[x]){
            assert(col[y] != (c ^ 1));
            if(col[y] == -1){
                col[y] = c;
                f(y, c ^ 1);
            }
        }
    };

    REP(i,n){
        if(col[i] == -1){
            col[i] = 0;
            f(i, 1);
        }
    }
    VECCOUT(col);
    V c0, c1;
    REP(i,n){
        (col[i] ? c1 : c0).emplace_back(i);
    }
