    bitset<32> bs(a);
    if(bs.count()==1 && a_all.find(a)!=a_all.end()){
      a_all.erase(a);
      count++;
    }else{
      a_all.insert(a);
    }
  }

  for(auto a:a_all){
    bitset<32> bs(a);
    for(int i=0;i<32;i++){
      if(bs[i]){
        us[i].insert(a);
        us_vec[i].push_back(a);
        break;
      }
    }
  }

  for(int i=0;i<32;i++){
    for(auto v:us_vec[i]){
      if(us[i].find(v)==us[i].end()){
        continue;
      }

      bitset<40> bs_a(v);
