      bs_b[i]=true;
      for(int j=i+1;j<32;j++){
        bs_b[j]=!bs_a[j];
        bitset<40> bs_c(bs_a.to_ullong()+bs_b.to_ullong());
        if(bs_c.count()==1){
          if(us[i].find(bs_b.to_ulong())!=us[i].end()){
            auto it=us[i].find(v);
            assert(it!=us[i].end());
            us[i].erase(it);
            it=us[i].find(bs_b.to_ulong());
            assert(it!=us[i].end());
            us[i].erase(it);
            count++;
            break;
          }
        }
      }

    }
  }
