LL mi[100];
void solve(long long n, vector<long long> a)
{
    mi[0] = 1;
    for (int i = 1; i <= 32; ++i) {
        mi[i] = mi[i - 1] * 2;
    }
    sort(a.begin(), a.end());
    for (int i = 0; i < n; ++i) {
        if (mp.count(a[i]) == 0)
            mp[a[i]] = 1;
        else
            mp[a[i]]++;
    }
    reverse(a.begin(), a.end());
    int ans = 0;
    for (auto i : a) {
        if (mp[i] == 0)
            continue;
        int j;
        for (j = 0; j <= 32; ++j) {
            if (mi[j] >= i)
                break;
        }
        LL x = mi[j];
        if (x - i == i) {
            if (mp[i] > 1) {
                mp[i] -= 2;
                ans++;
            }
        } else if (mp.count(x - i) > 0 && mp[x - i] > 0) {
            mp[x - i]--;
            mp[i]--;
            ans++;
        }
    }
	cout<<ans<<endl;
}

