// utility
#define ALL(a) (a).begin(), (a).end()
#define EACH(i, a) for(auto &&i:(a))
#define FOR(i, a, b) for(int i=(a);i<(b);++i)
#define RFOR(i, a, b) for(int i=(b)-1;i>=0;--i)
#define REP(i, n) for(int i=0;i<(n);++i)
#define RREP(i, n) for(int i=(n)-1;i>=0;--i)


signed main() {
  INIT;
	VAR(int, n);
	map< int, int > mp;
	vector< int > a;
	REP(i, n) {
		VAR(int, j);
		a.push_back(j);
		mp[j]++;
	}

	sort(ALL(a));
	a.erase(unique(ALL(a)), a.end());

	int ans = 0;
	RREP(i, a.size()) {
		RREP(j, 31) {
			if (mp[a[i]] == 0) break;
			int target = (1 << j) - a[i];
			if (target == a[i]) {
				int tmp = mp[target] / 2;
				mp[target] -= tmp * 2;
				ans += tmp;
			} else {
				int tmp1 = mp[target];
				int tmp2 = mp[a[i]];
				mp[target] -= min(tmp1, tmp2);
				mp[a[i]] -= min(tmp1, tmp2);
				ans += min(tmp1, tmp2);
			}
		}
	}

	OUT(ans)BR;

  return 0;
}

