    auto ite = st.find(v[i]);
    st.erase(ite);

    int b = get2beki(v[i]) - v[i];
    auto it = st.find(b);

    if(*it == b) {
      ans++;
      st.erase(it);
    }
  }
  cout << ans << endl;

