bool operator <(Node x, Node y){
	if (x.v == y.v) return x.id < y.id;
	return x.v < y.v;
}

int main(){
	int n, num, ans, req;
	set <Node>::iterator it;
	scanf("%d",&n);
	for (int i = 1; i <= n; i++) scanf("%d",&a[i]);
