struct HopcroftKarp {
    int sizeL, sizeR;
    vector<vector<int> > list; // left to right

    // result
    vector<bool> seen, matched;
    vector<int> level, matching;

    // base
    HopcroftKarp(int l, int r) : sizeL(l), sizeR(r), list(l, vector<int>()) { }
    inline vector<int>& operator [] (int i) { return list[i]; }
    inline void addedge(int from, int to) { list[from].push_back(to); }
    inline friend ostream& operator << (ostream& s, const HopcroftKarp& G) {
        s << endl;
        for (int i = 0; i < G.list.size(); ++i) {
            s << i << " : ";
            for (int j = 0; j < G.list[i].size(); ++j) {
                s << G.list[i][j];
                if (j + 1 != G.list[i].size()) s << ", ";
            }
            s << endl;
        }
        return s;
    }

    // methods
    void hobfs() {
        queue<int> que;
        for (int left = 0; left < sizeL; ++left) {
            level[left] = -1;
            if (!matched[left]) {
                que.push(left);
                level[left] = 0;
            }
        }
        level[sizeL] = sizeL;
        while (!que.empty()) {
            int left = que.front();
            que.pop();
            for (int i = 0; i < list[left].size(); ++i) {
                int right = list[left][i];
                int next = matching[right];
                if (level[next] == -1) { //つまりmatched[next]=trueな時
                    level[next] = level[left] + 1;
                    que.push(next);
                }
            }
        }
    }
    bool hodfs(int left) {
        if (left == sizeL) return true;
        if (seen[left]) return false;
        seen[left] = true;
        for (int i = 0; i < list[left].size(); ++i) {
            int right = list[left][i];
            int next = matching[right];
            if (level[next] > level[left] && hodfs(next)) {
                matching[right] = left;
                return true;
            }
        }
        return false;
    }
    int solve() {
        seen.assign(sizeL, false);
        matched.assign(sizeL, false);
        level.assign(sizeL + 1, -1);
        matching.assign(sizeR, sizeL);
        int res = 0;
        while (true) {
            hobfs();
            seen.assign(sizeL, false);
            bool finished = true;
            for (int left = 0; left < sizeL; ++left) {
                if (!matched[left] && hodfs(left)) {
                    matched[left] = true;
                    ++res;
                    finished = false;
                }
            }
            if (finished) break;
        }
        return res;
    }
};



ll POW[32];

void init() {
    POW[0] = 1;
    for (int i = 1; i < 32 ; i++) {
        POW[i] = 2 * POW[i - 1];
    }
}

ll matching(vll &A) {
    int n = A.size();
    ll counter = 0;
    ll res = 0;
    vll B, C, D;

    rep(i, n) {
        if (A[i] == 1) {
            counter++;
        }
        else if (A[i] % 2 == 1) {
            if (A[i] % 4 == 1) C.pb(A[i]);
            else D.pb(A[i]);
        }
        else {
            B.pb(A[i] >> 1);
        }
    }

    res += counter / 2;
    res += matching(B);

    sort(all(D));
    int l = C.size(), r = D.size();

    if (l == 0 || r == 0) return res;

    HopcroftKarp hk(l, r);
    rep(i, l) {
        for (int t = 2; t < 32 ; t++) {
            auto itr = lower_bound(all(D), POW[t] - C[i]);
            if (itr != D.end()) {
                if (C[i] + *itr == POW[t]) {
                    int j = itr - D.begin();
                    hk.addedge(i, j);
                }
            }
        }
    }

    res += hk.solve();

    return res;
}



int main() {
    ll N;
    vll A(N);
    rep(i, N) cin >> A[i];

    init();
    ll ans = matching(A);

    cout << ans << endl;

}

