	for(int i=0; i<N; i++) cnt[A[i]]++;

	int n = cnt.size();
	map<ll, int> idx;
	int i=0;
	for(auto p: cnt) idx[p.first] = i++;
	FlowGraph flow(2*n+2);
	for(auto p: cnt){
		int i = idx[p.first];
		//debug(i, p.first);
		flow.add_edge(2*n, i, p.second);
		flow.add_edge(i+n, 2*n+1, p.second);
		for(int k=0; k<32; k++){
			ll b = (1ll<<k)-p.first;
			if(cnt.count(b)>0){
				int w;
				if(b==p.first){
					w = cnt[b]/2;
				} else {
					w = max(cnt[b], p.second);
				}

				flow.add_edge(i, idx[b]+n, w);
			}
		}
	}

	cout << flow.max_flow(2*n, 2*n+1)/2 << endl;

	return 0;
}

