#include <bits/stdc++.h>

int main()
{
	int n;
	scanf("%d", &n);
	std::vector<long long> a[32];
	for (int i = 0; i < n; i++)
	{
		long long tmp{};
		scanf("%lld", &tmp);
		int digit{};
		while (!(((long long)1 << digit) & tmp)) digit++;
		a[digit].push_back(tmp); 
	}
	int count{};
	for (int i = 0; i < 32; i++)
	{
		auto& v = a[i];
		std::vector<bool> used(v.size());
		std::sort(v.begin(), v.end(), std::greater<long long>());
		for (unsigned int j = 0; j < v.size(); j++)
		{
			if (used[j]) continue;
			used[j] = true;
			long long candidate{1 << i};

			for (int digit{i + 1}; ((long long)1 << digit) <= v[j]; digit++)
			{
				if (!((1 << digit) & v[j]))
					candidate += 1 << digit;
			}
			unsigned int left{j}, right{v.size() - 1};
			while (left + 1 < right)
			{
				auto mid{(left + right) / 2};
				if (v[mid] <= candidate) right = mid;
				else left = mid;
			}
			if (v[right] != candidate || used[right]) continue;
			used[right] = true;
			count++;
		}
	}
	printf("%d\n", count);

	return 0;
}

