bool solve() {
  int n;
  if (scanf("%d", &n) != 1) { return false; }

  vector <int> a(n);
  for (int i = 0; i < n; ++i) {
    scanf("%d", &a[i]);
  }
  sort(a.begin(), a.end());
  vector <pii> b;
  for (int i = 0; i < n; ++i) {
    if (b.empty() || b.back().first != a[i]) {
      b.push_back(pii(a[i], 0));
    }
    b.back().second += 1;
  }

  int res = 0;
  while (!b.empty()) {
    if (b.back().second == 0) {
      b.pop_back();
      continue;
    }
    int k = b.back().first;
    b.back().second--;

    int len = int(b.size());
    for (int pow = (1 << 30); pow > 0; pow >>= 1) {
      int index = lower_bound(b.begin(), b.end(), pii(pow - k, 1)) - b.begin();
      if (index < len && b[index].first == pow - k) {
        b[index].second--;
        res++;
        break;
      }
    }
  }
  printf("%d\n", res);

  return true;
}

int main() {
  while (solve());
  return 0;
}

