LL FIND(LL ubb,LL targ)
{
	LL lb=0,ub=ubb;
	while(lb<=ub)
	{
		LL mid=(lb+ub+1)/2;
		if(a[mid]==targ&& !vis[mid]) return mid;
		if(a[mid]>targ) ub=mid-1;
		else lb=mid+1;
	}
	return -1;
}

