	for (int i = (int)b.size() - 1; i >= 0; i--) {
		int x = b[i].first;
		for (int j = 30; j >= 0; j--) {
			if ((1 << j) <= x) break;
			if (b[i].second <= 0) break;
			int l = lower_bound(b.begin(), b.begin() + i + 1, make_pair((1 << j) - x, -1)) - b.begin();
