			if (l == i) {
				ans += b[i].second / 2;
				b[i].second %= 2;
			} else {
				int t = min(b[i].second, b[l].second);
				ans += t;
				b[i].second -= t;
				b[l].second -= t;
			}
		}
	}
	printf("%d\n", ans);
	return 0;
}

