  rep(i, n) {
    add_edge(s, i, 1);
    add_edge(n + i, t, 1);
  }

  rep(i, n) {
    rep(j, n) {
      if (a[i] < c[j] && b[i] < d[j]) {
        add_edge(i, j + n, 1);
      }
    }
  }
  cout << max_flow(s, t);

  return 0;
}

