int main() {
  int n;
  cin >> n;
  VEC<LL> a(n);
  REP(i, 0, n) cin >> a[i];
  sort(ALL(a));
  VEC<pair<LL, LL>> edge;
  for (LL nibeki = 1; nibeki <= 2 * LIM; nibeki *= 2) {
    auto iterator_begin = a.begin();
    REP(i, 0, n) {
      LL left = a[i];
      LL right = nibeki - a[i];
      if (right <= 0) {
        ++iterator_begin;
        continue;
      }
      auto next = iterator_begin+1;
      auto actual_p = lower_bound(next, a.end(), right);
      int j = distance(a.begin(), actual_p);
      LL actual = *actual_p;
      while (actual == right) {
        edge.push_back({i, j});
        //edge.push_back({j, i});
        ++actual_p;
        actual = *actual_p;
      }
      ++iterator_begin;
    }
  }
  //DUMP(edge);
