vector<ll> a;
bool isOK(int index, ll key)
{
  if (a[index] >= key)
    return true;
  else
    return false;
}
int binary_search(ll key)
{
  int ng = -1;
  int ok = (int)a.size();
  while (abs(ok - ng) > 1)
  {
    int mid = (ok + ng) / 2;
    if (isOK(mid, key))
      ok = mid;
    else
      ng = mid;
  }
  return ok;
}

ll repeatSquaring(ll n, ll p)
{
  if (p == 0)
    return 1;
  if (p % 2 == 0)
  {
    ll t = repeatSquaring(n, p / 2);
    return t * t;
  }
  return n * repeatSquaring(n, p - 1);
}

