long long n;
vector<long long> a;
map<long long, long long> mp;

long long solve();

int main() {
  cin >> n;
  for(long long i = 0; i < n; ++i) {
    long long x;
    cin >> x;
    a.push_back(x);
    ++mp[x];
  }
  sort(a.begin(), a.end(), greater<long long>());
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long ans = 0;
  for(int i = 0; i < n; ++i) {
    for(long long j = 32; j >= 0; --j) {
      long long now = (1LL << j);
      if(now <= a[i]) break;
      if(mp[now - a[i]] > 0) {
        if(a[i] == now - a[i] && mp[a[i]] == 1) continue;
        ++ans;
        --mp[a[i]];
        --mp[now - a[i]];
        break;
      }
    }
  }
  return ans;
}

