using namespace std;

#define MUCHO 9999999

ll n, m;
ll ns[400000];

struct coso {
	ll n;
	ll cant;
	ll cands;
};

set<pair<ll, ll>> pots;
map<ll, set<ll>> g;
map<ll, struct coso> cants;
set<pair<ll, ll>> cands;

int main() {
	IOS;
	cin >> n;
	m = n;
	forn (i) {
		cin >> ns[i];
		cants[ns[i]].n = ns[i];
		cants[ns[i]].cant++;
	}

	sort(ns, ns + n);
	fore (i, 0, n)
	fore (e, 1, 17) {
		int sum = 1 << e;
		ll* b = lower_bound(ns + i, ns + n, sum - ns[i]);
		if (b != ns + n && *b == sum - ns[i]) {
			//cerr << ns[i] << " + " << *b << " = " << sum << endl;
			pots.insert({ns[i], *b});
		}
	}

	for (auto v : pots) {
		//cerr << v.first << " -- " << v.second << endl;
		g[v.first].insert(v.second);
		g[v.second].insert(v.first);
		cants[v.first].cands += cants[v.second].cant;
		cants[v.second].cands += cants[v.first].cant;
	}

	for (const auto& c : cants)
		cands.emplace(c.second.cands, c.second.n);

	ll count = 0;
	for (auto n = cands.begin(); n != cands.end(); n = cands.begin()) {
		ll menos_cands = MUCHO;
		ll match = 0;
		for (auto v : g[n->second]) {
			if (cants[v].cands < menos_cands && cants[v].cands > 0
				&& ((v != n->second && cants[v].cant > 0)
					|| (v == n->second && cants[v].cant > 1)))
				menos_cands = cants[v].cands, match = v;
		}
		if (menos_cands == MUCHO) {
			cants.erase(n->second);
			cands.erase(n);
			continue;
		}
		//cerr << "Puedo usar " << match << " con " << n->second << endl;
		ll& ncant = cants[n->second].cant;
		ll& ncand = cants[n->second].cands;
		ll& mcant = cants[match].cant;
		ll& mcand = cants[match].cands;
		ll cmatches = min(ncant, mcant);
		if (match != n->second)
			cands.erase(make_pair(mcand, match));
		if (match == n->second)
			cmatches /= 2;
		ncant -= cmatches;
		mcant -= cmatches;
		ncand -= cmatches;
		mcand -= cmatches;
		if (match != n->second && ncant)
			cands.insert(make_pair(ncand, n->second));
		if (mcant)
			cands.insert(make_pair(mcand, match));
		cands.erase(n);
		count += cmatches;
	}
	cout << count << endl;
	return 0;
}

