			if(aa[v[i]]==1)aa.erase(v[i]);
			else aa[v[i]]--;
			if(aa[np(v[i])-v[i]]==1)aa.erase(np(v[i])-v[i]);
			else aa[np(v[i])-v[i]]--;
			tmp++;
		}
