int numdiv2(long long n)
{
    int ret = 0;
    while (n % 2 == 0) {
        n /= 2;
        ret++;
    }
    return ret;
}

bool is_powered2(long long n)
{
    while (n > 2) {
        if (n % 2 == 1) {
            return false;
        }
        n /= 2;
    }
    return n == 2;
}

int helper(std::vector<long long> ar)
{
    int max = -1;
    for (size_t i = 0; i < ar.size(); i++) {
        for (size_t j = i + 1; j < ar.size(); j++) {
            if (is_powered2(ar[i] + ar[j])) {
                auto cp = ar;
                cp.erase(cp.begin() + i);
                cp.erase(cp.begin() + j - 1);
                int ret = helper(cp);
                if (max < ret)
                    max = ret;
            }
        }
    }
    return max + 1;
}

int numpair2pow(const std::vector<long long>& ar)
{
    if (ar.size() == 0) {
        return 0;
    }
    int mindiv2 = 100;
    std::vector<long long> odds, evens;
    for (auto&& e : ar) {
        int d = numdiv2(e);
        if (mindiv2 > d)
            mindiv2 = d;
    }

    for (auto& e : ar) {
        auto d = (e >> mindiv2);
        if (d % 2 == 0) {
            evens.push_back(d);
        } else {
            odds.push_back(d);
        }
    }

    int sum = helper(odds);
    if (evens.size() == 1) {
        return sum;
    }

    sum += numpair2pow(evens);
    return sum;
}

