class bipartite_matching_fn_t {
public:
  bipartite_matching_fn_t(int N) : N_(N), G_(N) {
    match_ = new int [N_];
    used_ =  new bool[N_];
  };

  ~bipartite_matching_fn_t() {
    delete[] match_;
    delete[] used_;
  };

public:
  void add_edge(int u, int v) {
    assert(0 <= u && u < N_);
    assert(0 <= v && v < N_);

    G_[u].push_back(v);
    G_[v].push_back(u);
  };

private:
  bool dfs(int v) {
    used_[v] = true;

    for (int i = 0, size = G_[v].size(); i < size; i ++) {
      int u = G_[v][i], w = match_[u];

      if (w < 0 || (! used_[w] && dfs(w))) {
        match_[v] = u;
        match_[u] = v;

        return true;
      }
    }

    return false;
  };

public:
  int match() {
    int c = 0;

    memset(match_, -1, sizeof(int) * N_);

    for (int v = 0; v < N_; v ++) {
      if (match_[v] < 0) {
        memset(used_, 0, sizeof(bool) * N_);

        if (dfs(v))
          c ++;
      }
    }

    return c;
  };

private:
  int N_;

  std::vector<std::vector<int>> G_;

  int* match_;

  bool* used_;
};


int main(int argc, char** argv)
{
  std::cin.tie(0);
  std::ios_base::sync_with_stdio(0);

  int N, A[222222], c = 0;

  scanf("%d", &N);

  for (int i = 0; i < N; i ++)
    scanf("%d", A + i);

  std::sort(A, A + N);

  std::map<int, std::vector<int>> map;

  for (int i = 0; i < N; i ++)
    map[A[i]].push_back(i);

  bipartite_matching_fn_t fn(N);

  for (int i = 0; i < N; i ++) {
    for (int j = 1; j < 31; j ++) {
      long long s = 1LL << j;

      if (s > A[i]) {
        long long t = s - A[i];

        if (map.count(t))
          for (const auto& k : map[t])
            if (k > i)
              fn.add_edge(i, k);
      }
    }
  }

  printf("%d\n", fn.match());

  return 0;
}

