class BipartiteMatching: public NetworkFlow {
public:
	//引数：頂点数
	BipartiteMatching(int size):
		NetworkFlow(size + 2),
		start(size),
		end(size + 1)
	{}

	//二部グラフの左側にある頂点の登録
	void add_left(int id) {
		add_edge(start, id, 1);
	}

	//右側
	void add_right(int id) {
		add_edge(id, end, 1);
	}

	//左側と右側の頂点の間にある辺の登録
	void add_mid(int left, int right) {
		add_edge(left, right, 1);
	}

	//最大マッチングを求める
	int max_matching() {
		return max_flow(start, end);
	}




private:
	const int start, end;
};
