ll binary_matching(vector<ll> now)
{
	if(now.empty())return 0;
	BM bm(now.size());

	// 左右分割
	REP(i, now.size())
	{
		if(now[i] % 2 == 0)bm.add_left(i);
		else bm.add_right(i);
	}

	int lim=0;
	while(powi(2,lim)<now.back())lim++;

	// 結合探知
	ll res=0;
	REP(id, now.size())
	{
		REP(p, lim+2)
		{
			ll opp = powi(2, p) - now[id] - 1;
			if(opp<1)continue;

			auto itr = lower_bound(now.begin(), now.end(), opp);
			if(itr != now.end() && (*itr) == opp)
			{
				ll oppId = distance(now.begin(), itr);
				if(id == oppId)continue;
				if(now[id] % 2 == opp % 2)
				{
					exit(1);
				}
				if(now[id] == 0)bm.add_mid(id, oppId);
				else bm.add_mid(oppId, id);
			}
		}
	}
	res += bm.max_matching();

	REP(p, 35)
	{
		ll topic = powi(2,p);

		auto itrR = upper_bound(now.begin(),now.end(),topic);
		auto itrL = lower_bound(now.begin(),now.end(),topic);
		ll num = distance(itrL,itrR);
		res += num/2;
	}
	return res;
}

