    vector<pair<int,int>> vp2;
    for(int i=0; i<vp.size(); i++){
        if(__builtin_popcount(vp[i].first)==1){
            vp2.push_back({vp[i].first, vp[i].second/2});
            vp2.push_back({vp[i].first, vp[i].second/2+(vp[i].second%2)});
        }
        else{
