    int netsz=2*vp.size()+2;

    vector<vector<pair<int,int>>> net(netsz);

    for(int i=0; i<vp.size(); i++){
        net[0].push_back({i+1,vp[i].second});
        net[n2+i+1].push_back({netsz-1,vp[i].second});


        for(int j=0; j<=31; j++){
            int goal=(1<<j)-vp[i].first;
            pair<int,int> pg={goal,0};
            auto it=lower_bound(vp.begin(),vp.end(),pg);
            if(it==vp.end()) continue;
            int k=it-vp.begin();
            if(it->first==goal){
                if(goal==vp[i].first){
                    if(i==k){
                        net[i+1].push_back({n2+k+2,vp[i].second});
                    }
                    else{
                        net[i+1].push_back({n2+k+1,vp[i].second});
                    }
                }
                else if(__builtin_popcount(goal)==1){
                    net[i+1].push_back({n2+k+1,vp[i].second});
                    net[i+1].push_back({n2+k+2,vp[i].second});
                }
                else{
                    net[i+1].push_back({n2+k+1,vp[i].second});
                }

            }


        }


    }


    Dinic din(net);


    auto mf=din.maxflow();

    int ans=0;

    for(auto e:mf[0]){
        ans+=e->flow;
    }

    cout<<ans/2;


    return 0;
}

