int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    vector<ll> a(n);
    for (int i = 0; i < n; i++)
    {
        cin >> a[i];
    }
    sort(a.begin(), a.end());
    vector<vector<int>> g(n);
    vector<bool> check(n, false);
    vector<int> deg(n, 0);
    map<ll, vector<int>> mp;
    for (ll i = 0; i < n; i++)
    {
        for (ll j = 1; j <= 30; j++)
        {
            ll gt = (1LL << j) - a[i];
            if (gt <= 0)
                continue;
            if (mp.find(gt) == mp.end())
                continue;
            if (a[i] == gt)
            {
                check[i] = true;
                continue;
            }
            for (auto v : mp[gt])
            {
                g[i].push_back(v);
                g[v].push_back(i);
                deg[i]++;
                deg[v]++;
            }
        }
        mp[a[i]].push_back(i);
    }
    int res = 0;
    vector<bool> used(n, false);
    queue<int> q;
    for (int i = 0; i < n; i++)
    {
        if (deg[i] == 1)
            q.push(i);
    }
    while (!q.empty())
    {
        int v = q.front();
        q.pop();
        if(used[v]) continue;
        for(auto next:g[v]){
            if(used[next]) continue;
            res++;
            used[v] = true;
            used[next] = true;
            for(auto k:g[next]){
                deg[k]--;
                if(deg[k]==1) q.push(k);
            }
            break;
        }
    }
    for(int i=0;i<n;i++){
        if(used[i] || !check[i]) continue;
        for(auto v:mp[a[i]]){
            if(used[v]) continue;
            used[i] = true;
            used[v] = true;
            res++;
            break;
        }
    }
    cout << res << endl;
}

