map<ll, ll> h;
map<ll, bool> done;

int isBin(ll x) {
    return (x & (x - 1)) == 0;
}


int dfs(ll p, ll prev) {
    if (!h.count(p)) return 0;
    if (done[p]) return 0;
    done[p] = true;

    int ans = 0;
    for (int i = 0; i <= 30; i++) {
        ll nxt = (1ll << i) - p;
        if (nxt != p) ans += dfs(nxt, p);
    }
    while (prev != -1 && h[p] > 0 && h[prev] > 0) {
        h[p]--;
        h[prev]--;
        ans++;
    }

    while (h[p] >= 2 && isBin(p)) {
        h[p] -= 2;
        ans++;
    }

    return ans;
}

void solve(ll N, vector<ll> A) {
    for (int i = 0; i < N; i++) h[A[i]]++;
    int ans = 0;
    for (int i = 0; i < N; i++) {
        ans += dfs(A[i], -1);
    }
    cout << ans << endl;

}


