int lower(const vector<int> &a, int l, int r, int k) {
    l--; r++;
    while (r - l > 1) {
        int mid = (r + l) / 2;
        if (a[mid] <= k) {
            r = mid;
        }
        else {
            l = mid;
        }
    }
    return r;
}

int upper(const vector<int> &a, int l, int r, int k) {
    l--; r++;
    while (r - l > 1) {
        int mid = (r + l) / 2;
        if (a[mid] < k) {
            r = mid;
        }
        else {
            l = mid;
        }
    }
    return r;
}

