	return (1<<i+1)-x;
}
int ok(int x)
{
	int i;
	for(i=30;~i;--i)
		if(x&(1<<i))
			break;
	int tt=x^(1<<i);
	if(!tt) return 1;
	return 0;
}

void cc()
{
