int isBin(ll x) {
    return (x & (x - 1)) == 0;
}


int dfs(ll p, ll prev) {
    if (!h.count(p)) return 0;
    if (done[p]) return 0;
    done[p] = true;

    int ans = 0;
    for (int i = 0; i <= 30; i++) {
        ll nxt = (1ll << i) - p;
        if (nxt != p) ans += dfs(nxt, p);
    }
    while (prev != -1 && h[p] > 0 && h[prev] > 0) {
        h[p]--;
        h[prev]--;
        ans++;
    }

    while (h[p] >= 2 && isBin(p)) {
        h[p] -= 2;
        ans++;
    }

    return ans;
}


int func(vector<ll> A) {
    vector<int> dp((1 << A.size()), 0);

    int ans = 0;
    for (int i = 0; i < (1 << A.size()); i++) {
        for (int j = 0; j < A.size(); j++) {
            for (int k = 0; k < A.size(); k++) {
                if (j != k && !(i >> j & 1) && !(i >> k & 1) && isBin(A[j] + A[k])) {
                    ans = max(ans, dp[i | (1 << j) | (1 << k)] = max(dp[i] + 1, dp[(1 << j) | (1 << k)]));
                }
            }
        }
    }
    return ans;
}

