const int N = 2e5 + 10;

int n, a[N], b[N], c[N];
map<int,int> MP;

int cal(int n){
    int ret = 0;
    MP.clear();
    int s, x;
    bool flag = 0;
    for(int i=n-1; i>=0; i--){
        s = 1 << 30;
        flag = 0;
        while(s > c[i]){
            x = s - c[i];
            if(MP.count(x)){
                ret++;
                if(--MP[x] == 0){
                    MP.erase(x);
                }
                flag = 1;
                break;
            }
            s >>= 1;
        }
        if(!flag){
            MP[c[i]]++;
        }
    }
    return ret;
}

int solve(int *a, int n, int *b){
    if(n < 2)   return 0;
    int m = 0;
    int l = 0;
    for(int i=0; i<n; i++){
        if(a[i] & 1){
            c[l++] = a[i];
        } else {
            b[m++] = a[i] >> 1;
        }
    }

    return cal(l) + solve(b, m, a);
}

int main(){
    while(~scanf("%d", &n)){
        for(int i=0; i<n; i++){
            scanf("%d", a+i);
        }
        sort(a, a+n);
        printf("%d\n", solve(a, n, b));
    }
	return 0;
}

