		if (x % 2 == 1) {
			return 1;
		}
		x /= 2;
	}
	return 0;
}

int main() {
	int n;
	cin >> n;
	vector<llint>a(n);
	vector<int>b(n, 0);
	for (int i = 0;i < n;i++) {
		cin >> a[i];
	}
	sort(a.begin(), a.end());
	llint tmp;
	llint ans = 0;
	while (1 < a[n - 1]) {
		for (int i = 0;i < n;i++) {
			if (b[i] == 1) {
				continue;
			}
			if (a[i] % 2 == 1) {
				tmp = i;
				b[i] = 1;
				break;
			}
		}
		for (int i = tmp + 1;i < n;i++) {
			if (b[i] == 1) {
				continue;
			}
			if (a[i] % 2 == 1) {
				b[i] = 1;
				if (check(a[tmp] + a[i]) == 0) {
					ans++;
				}
			}
		}
		for (int i = 0;i < n;i++) {
			a[i] /= 2;
		}
	}
	cout << ans << endl;
	return 0;
}

