ll bits_msb(ll v) {
    for (unsigned int i = 1; i < sizeof(v) * 8; i <<= 1) {
        v = v | (v >> i);
    }
    return v ^ (v >> 1);
}

ll solve() {
    multiset<ll> s;
    for (int i = 0; i < N; i++) {
        s.insert(A[i]);
