const pll INIT = {INT_MAX,INT_MAX};
const pll NIL = {LLONG_MAX,LLONG_MAX};
struct SegTree {
    int N;
    pll init_v;
    vector<pll> node, lazy;

    SegTree(int _N):init_v(INIT) {
        N = 1;
        while (N < _N) N *= 2;
        node.resize(2 * N - 1, init_v);
        lazy.resize(2 * N - 1, NIL);
    }

    pll merge(pll l,pll r){
        return min(l,r);
    }
    void build(){
        for(ll k = N - 2; k >= 0; k--){
            node[k] = merge(node[2*k+1],node[2*k+2]);
        }
    }
    void direct_update(ll k,pll v){
        node[k+N-1] = v;
    }

    void lazy_evaluate(ll k) {
        if (lazy[k] == NIL) return;
        node[k] = lazy[k];
        if (k < N - 1) {
            lazy[2 * k + 1] = lazy[k];
            lazy[2 * k + 2] = lazy[k];
        }
        lazy[k] = NIL;
    }

    /* [a,b) 引数の範囲に注意!! s~tまでを更新→update(s,t+1,~) */
    pll update(ll a, ll b, pll x) { return update(a, b, 0, 0, N, x); }
    pll update(ll a, ll b, ll k, ll l, ll r, pll x) {
        if (r <= a || b <= l) {
            lazy_evaluate(k); // nodeの値を見るときは必ず遅延評価を更新する
            return node[k]; // updateでは全体の中の最小を見つける必要があるため, [l,r)外になっても値を参照
        }
        if (a <= l && r <= b) {
            lazy[k] = x;
            lazy_evaluate(k);
            return node[k];
        }
        else {
            lazy_evaluate(k);
            pll vl = update(a, b, 2 * k + 1, l, (l + r) / 2, x);
            pll vr = update(a, b, 2 * k + 2, (l + r) / 2, r, x);
            return node[k] = merge(vl, vr);
        }
    }

    /* [a,b) 引数の範囲に注意!! */
    pll query(ll a, ll b) { return query(a, b, 0, 0, N); }
    pll query(ll a, ll b, ll k, ll l, ll r) {
        if (r <= a || b <= l) return init_v;
        if (a <= l && r <= b) {
            lazy_evaluate(k);
            return node[k];
        }
        else {
            lazy_evaluate(k);
            pll vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
            pll vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
            return merge(vl, vr);
        }
    }
};

template<class Type>
Type solve(Type res = Type()){
    ll N; cin >> N;
    vector<ll> A(N); for(auto& in:A) cin >> in;

    vector<ll> tA = A;
    sort(tA.begin(),tA.end());
    tA.erase(unique(tA.begin(),tA.end()),tA.end());
    for(auto& a:A) a = lower_bound(tA.begin(), tA.end(), a) - tA.begin() + 1;

    SegTree ST((int)tA.size()+1);

    res = 0;
    for(int i = 0; i < tA.size()+1;i++) ST.direct_update(i, pll(0,-i));
    ST.build();

    for(int i = 1; i < N;i++){
        if(A[i-1] < A[i]){
            //ST.update(A[i-1],A[i],0);
        }
        if(A[i-1] == A[i]){
            pll v = ST.query(0,A[i-1]);
            if(v.first==res){
                res++;
                ST.update(A[i-1]-1,A[i-1],pll(res,-(A[i-1]-1)));
            }else{
                v.first++;
                ST.update(-v.second,-v.second+1,v);
            }
        }
        if(A[i-1] > A[i]){
            pll v = ST.query(0,A[i]);
            if(v.first==res){
                res++;
                ST.update(A[i]-1,A[i],pll(res,-(A[i]-1)));
            }else{
                v.first++;
                ST.update(-v.second,-v.second+1,v);
            }
        }
        //for(int j = 0; j < A[i];j++) cout << ST.query(j,j+1) << " "; cout << endl;
    }
    res+=1;
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    // solve(0);
    cout << fixed << setprecision(15) << solve<ll>() << endl;
    return 0;
}

