void solve2() {
  ll N;
  cin >> N;

  VL as(N);
  rep(i, N) cin >> as[i];

  ll res = 0;

  map<ll, ll> m;
  rep(i, N) m[-as[i]]++;

  auto dec = [&](ll val) {
    m[val]--;
    if (m[val] == 0) m.erase(val);
  };

  while (!m.empty()) {
    ll num = -m.begin()->first;
    dec(-num);

    ll sum = 1;
    while (sum <= num) sum *= 2;

    ll p = sum - num;

    if (m.count(-p)) {
      res++;
      dec(-p);
    }
  }

  cout << res << endl;
}

