using namespace std;

int bin(vector<int> arr, int s, int e, int x) {
    int mid = (s + e) / 2;
    if (s > e)
        return -1;
    if (arr[mid] == x)
        return mid;
    if (arr[mid] < x)
        return bin(arr, mid+1, e, x);
    else
        return bin(arr, s, mid-1, x);
}

