// Warshall–Floyd algorithm ワーシャルフロイド法
std::vector<std::vector<long long>> warshallFloyd(const WGraph &G) {
    int n = (int)G.size();
    std::vector<std::vector<long long>> dis(n, std::vector<long long>(n, LINF));
    for (int i=0; i<n; i++) {
        dis.at(i).at(i) = 0;
    }
    for (int i=0; i<n; i++) {
        for (auto e : G.at(i)) {
            dis.at(i).at(e.first) = e.second;
        }
    }

    for (int k=0; k<n; k++) {
        for (int i=0; i<n; i++) {
            for (int j=0; j<n; j++) {
                dis.at(i).at(j) = std::min(dis.at(i).at(j), dis.at(i).at(k) + dis.at(k).at(j));
            }
        }
    }

    return dis;
}

void solve() {
    int n;
    cin >> n;
    vector<ll> a(n);
    for (int i=0; i<n; i++) {
        cin >> a.at(i);
    }

    sort(a.begin(), a.end());
    vector<bool> used(n, false);
    int res = 0;
    for (int i=n-1; i>=0; --i) {
        if (used.at(i)) continue;
        used.at(i) = true;
        int tmp = 1;
        while (tmp < a.at(i)) {
            tmp *= 2;
        }
        int dif = tmp - a.at(i);
        int ng = -1, ok = i;
        while (abs(ok - ng) > 1) {
            int mid = (ok + ng) / 2;
            if (a.at(mid) < dif) {
                ng = mid;
            } else if (a.at(mid) == dif) {
                if (used.at(mid)) {
                    ng = mid;
                } else {
                    ok = mid;
                }
            } else {
                ok = mid;
            }
        }
        if (a.at(ok) == dif) {
            ++res;
            used.at(ok) = true;
        }
    }

    cout << res << '\n';
}

