int main(){
    ll n;
    cin >> n;
    vector<ll> a(n);
    rep(i, n)cin >> a[i];
    sort(ALL(a));

    ll ans = 0;
    bool used[n];
    rep(i, n)used[i]=false;
    for(ll i = n-1; i>=0; --i){
        if(used[i])continue;
        for(ll j=40; j>=0; --j){
            used[i]=true;
            ll dif = (1LL<<j)-a[i];
            if(dif<0)break;
