void solve(){
  ll n;
  cin>>n;
  vector<ll>a(n);
  map<ll,ll>mp;
  ll ans=0;
  rep(i,n){
    cin>>a[i];
    mp[a[i]]++;
  }
  for(int i=40;i>=0;--i){
    ll val=(1LL<<i);
    rep(j,n){
      if(mp[a[j]]==0)continue;
      ll b=val-a[j];
      if(mp[b]==0){
        mp.erase(mp[b]);
        continue;
      }
      if(b==a[j]){
        if(mp[b]>1){
          mp[a[j]]--;
          mp[b]--;
          if(mp[a[j]]==0)mp.erase(mp[a[j]]);
          if(mp[b]==0)mp.erase(mp[b]);
          ans++;
        }
      }
      else {
        mp[a[j]]--;mp[b]--;ans++;
      }
    }
  }
  cout<<ans<<"\n";
}

int main(){
	ios::sync_with_stdio(false);
  cin.tie(0);
	cout<<fixed<<setprecision(15);
	solve();
	return 0;
}

