int getEdgeNum(map<int,int>& m, int cur, int pow){
	int need = pow - cur;
	if(need <= 0 or not m.count(need)) return 0;

	if(cur == need){ // 自分の値を二倍すれば条件を満たす
		return max(0LL, m[need] - 1);
	}else{
		return m[need];
	}

}

signed main(){
	int n;
	cin >> n;

	vector<int> a(n);
	cin >> a;

	map<int,int> m;
	for(auto& i : a){
		m[i]++;
	}

	map<int,int> e;
	for(auto& i : m){
		int num = i.first;
		for (int j = 1; j < (1LL << 32); j*=2) {
			//if(getEdgeNum(m, num, j)) cout << "-- " << num << ' ' << j << endl;
			e[num] += getEdgeNum(m, num, j);
		}
	}

	//for(auto i : e){ cout << i.first << ' ' << i.second << endl; }

	vector<pair<int, int>> p;
	for(auto& i : a){
		if(e[i] == 0) continue;
		p.emplace_back(e[i], i);
	}
	sort(all(p));

	//for(auto i : p){ cout << i.first << ' ' << i.second << endl; }

	int ans = 0;
	for(auto& i : p){
		int num = i.second;
		int mini = 1e9 + 9, target = -1;
		for (int j = 1; j < (1LL << 32); j*=2) {
			int edge = getEdgeNum(m, num, j);
			if(edge == 0) continue;

			if(mini > edge){
				mini = edge;
				target = j - num;
			}
		}
		if(target != -1){
			ans++;
			m[num]--;
			m[target]--;
		}
	}
	cout << ans << endl;
}

