            if(N - i - 1 != 0 && A[N - i - 1] == A[N - i - 2] && used[N - i - 2]){
                used[N - i - 1] = true;
                used[N - i - 2] = true;
                count++;
            }
            continue;
        }
        ll Y = getMinBi(currentX) * 2;
        auto it = lower_bound(A.begin(), A.end(), Y - currentX);
        if(*it == Y-currentX){
            int index = it - A.begin();
            used[index] = true;
            used[N - i - 1] = true;
            count++;
        }
    }
    cout << count << endl;

}

