struct Graph {
  int n;
  vector<vector<int>> adj;
  Graph(int n) : n(n), adj(n){};
  void addEdge(int u, int v) {
    adj[u].push_back(v);
    adj[v].push_back(u);
  }

  vector<int> mate;
  int maximumMatching() {
    mate.assign(n + 1, n);
    vector<int> first(n + 1, n), que(n);
    vector<pair<int, int>> label(n + 1, make_pair(-1, -1));
    int head = 0, tail = 0;

    function<void(int, int)> rematch = [&](int v, int w) {
      int t = mate[v];
      mate[v] = w;
      if (mate[t] != v) return;
      if (label[v].snd == -1) {
        mate[t] = label[v].fst;
        rematch(mate[t], t);
      } else {
        int x, y;
        tie(x, y) = label[v];
        rematch(x, y);
        rematch(y, x);
      }
    };
    auto relabel = [&](int x, int y) {
      function<int(int)> findFirst = [&](int u) {
        return label[first[u]].fst < 0 ? first[u]
                                       : first[u] = findFirst(first[u]);
      };
      int r = findFirst(x), s = findFirst(y);
      if (r == s) return;
      auto h = make_pair(~x, y);
      label[r] = label[s] = h;
      int join;
      while (1) {
        if (s != n) swap(r, s);
        r = findFirst(label[mate[r]].fst);
        if (label[r] == h) {
          join = r;
          break;
        } else {
          label[r] = h;
        }
      }
      for (int v : {first[x], first[y]}) {
        for (; v != join; v = first[label[mate[v]].fst]) {
          label[v] = make_pair(x, y);
          first[v] = join;
          que[tail++] = v;
        }
      }
    };
    auto augment = [&](int u) {
      label[u] = make_pair(n, -1);
      first[u] = n;
      head = tail = 0;
      for (que[tail++] = u; head < tail;) {
        int x = que[head++];
        for (int y : adj[x]) {
          if (mate[y] == n && y != u) {
            mate[y] = x;
            rematch(x, y);
            return true;
          } else if (label[y].fst >= 0) {
            relabel(x, y);
          } else if (label[mate[y]].fst == -1) {
            label[mate[y]].fst = x;
            first[mate[y]] = y;
            que[tail++] = mate[y];
          }
        }
      }
      return false;
    };
    int matching = 0;
    for (int u = 0; u < n; ++u) {
      if (mate[u] < n || !augment(u)) continue;
      ++matching;
      for (int i = 0; i < tail; ++i)
        label[que[i]] = label[mate[que[i]]] = make_pair(-1, -1);
      label[n] = make_pair(-1, -1);
    }
    return matching;
  }
};

int main() {
  int N;
  while (cin >> N) {
    vector<int> A(N);
