    map<int, vector<int>> nums;
    for (int i = 0; i < N; i++) nums[A[i]].push_back(i);
    Graph g(N);
    for (int i = 0; i < N; i++) {
      for (int k = 0; k < 40; k++) {
        ll pw = 1l << k;
        if (pw < A[i]) continue;
        for (int j : nums[pw - A[i]]) {
          if (j <= i) continue;
          g.addEdge(i, j);
        }
      }
    }
    cout << g.maximumMatching() << endl;
  }
  return 0;
}

