typedef long long int LL;

std::vector<std::vector<LL>>G;
std::vector<bool>vis;

LL dfs(LL v, bool flag)
{
	if (vis[v]) return 0;
	vis[v] = true;
	LL res = 0;
	bool exist = false;
	for (auto u : G[v])
	{
		if (!vis[u]) exist = true;
		res += dfs(u, !flag);
	}
	if (flag&&exist) ++res;
	return res;
}

LL cnt(LL v)
{
	if (vis[v]) return 0;
	vis[v] = true;
	LL res = 1;
	for (auto u : G[v]) res += cnt(u);
	return res;
}

int main()
{
	LL N;
	in >> N;
	std::vector<LL>A(N);
	rep(i, N) in >> A[i];

	std::sort(A.begin(), A.end());
	std::vector<LL>rui(33);
	rui[0] = 1;
	for (int i = 1; i <= 32; ++i) rui[i] = rui[i - 1] * 2;

	G.resize(N);
	rep(i, N)
	{
		rep(j, rui.size())
		{
			auto it1 = std::lower_bound(A.begin(), A.end(), rui[j] - A[i]);
			auto it2 = std::upper_bound(A.begin(), A.end(), rui[j] - A[i]);
			for (auto it = it1; it < it2; ++it)
			{
				if (it - A.begin() <= i) continue;
				G[i].push_back(it - A.begin());
			}
		}
	}

	LL ans = 0;
	vis.resize(N);
	rep(i, N)
	{
		if (!vis[i] && G[i].size() == 1)
		{
			auto temp = vis;
			LL res1 = dfs(i, true);
			vis = temp;
			LL res2 = dfs(i, false);
			ans += std::max(res1, res2);
		}
	}
	rep(i, N)
	{
		if (!vis[i])
		{
			ans += cnt(i) / 2;
		}
	}
	out << ans << std::endl;
	return 0;
}

