vector<int> A;
unordered_multimap<int, int> B;
int result = 0;


void find(){
    int tw = 1;
    for (int i = 1; i < 40; ++i) {
        tw *= 2;
        for (int j = 0; j < A.size() - 1; ++j) {
            int a = A[j];
            if(2 * a > tw){
                break;
            }
            int b = tw - a;
            auto itr= lower_bound(A.begin(),A.end(), b);

            for (itr; itr < A.end(); ++itr) {
                int k = itr - A.begin();
                if(k == j){
                    continue;
                }
                int b = A[k];
                if(a+b == tw){
                    B.insert(make_pair(j,k));
                    B.insert(make_pair(k,j));
                }
                if(a+b > tw){
                    break;
                }
            }
        }
    }
}

void checkOneB(){
    int count = A.size();
    int j,k;
    for (auto itr = B.begin(); itr != B.end(); ++itr) {
        int c = B.count(itr->first);
        if(count > c){
            count = c;
            j = itr->first;
            k = itr->second;
        }
        if(c == 1){
            j = itr->first;
            k = itr->second;
            break;
        }
    }
    B.erase(j);
    B.erase(k);
    result++;
    return;

}


void reduce(){
    while (B.size()>0){
        checkOneB();
    }
}

