  while(!ms.empty()){
    ll max_v=*(ms_.upper_bound(-inf));
    max_v*=-1;
    ll pr=pw(max_v)-max_v;
    ms.erase(ms.find(max_v));
    ms_.erase(ms_.find(-max_v));
    if(ms.empty()) break;
