    B/=2;
  }
  return 1;
}

long long r1(long long B){
  long long C=1;
  while (C<=B) {
    C*=2;
  }
  return C;
}

int fi(long long B, int N){
  int L=0,U=N,j,k=N;
  while (1) {
    int i=(U-L)/2 + L;
    if (A[i]==B) {
      if (f[i]==0) {
        j=1;
        while (i-j>=0 && A[i-j]==B && f[i-j]==0) {
          j++;
        }
        j--;
        return i-j;
      } else {
        j=1;
        while (i+j<N && A[i+j]==B && f[i+j]==1) {
          j++;
        }
        if (i+j == N || A[i+j]!=B) {
          return -1;
        } else {
          return i+j;
        }
      }
    } else if (A[i]>B) {
      U=i;
    } else {
      L=i+1;
    }
    if (U-L== k || U-L<=0) {
      return -1;
    }
    k=U-L;
  }
}

int main(){
  int i,n,j,k,N,S=0;
  cin >> N;
  for (i=0;i<N;++i) {
    cin >> A[i];
    f[i]=0;
  }
  sort(A,A+N);
  for (j=N-1;j>0;j--) {
    if (f[j]==1) {
      continue;
    }
    k=fi(r1(A[j])-A[j],j);
    if (k != -1) {
      f[k]=1;
      S+=1;
    }
  }
  cout << S << endl;
  return 0;
}

