	while (n < 1e9)
	{
		n *= 2;
	}

	rep(N, i)
	{
		ll nibeki = n;
		while (nibeki > 1)
		{
			ll part = nibeki - as[i];
			if (part > 0)
			{
				int res = upper_bound(as.begin() + i + 1, as.end(), part) - lower_bound(as.begin() + i + 1, as.end(), part);
				if (res)
				{
					ans++;
					break;
				}
			}
			nibeki /= 2;
		}
	}

	cout << ans << endl;
}

