int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    read(N);
    read(A, A + N);
    fill(cnt, cnt + N, 0);
    FOR(i, N) freq[A[i]]++;
    FOR(i, N) {
        if (freq[A[i]]-- == 1) freq.erase(A[i]);
        FOR(j, 31) {
            int x = 1 << j;
            if (freq.count(x - A[i])) cnt[i] += freq[x - A[i]];
        }
        freq[A[i]]++;
    }
    iota(ord, ord + N, 0);
    sort(ord, ord + N, [&] (const int &i, const int &j) {
        return cnt[i] < cnt[j];
    });
    int ans = 0;
    FOR(i, N) freq2[A[i]] = queue<int>();
    FOR(i, N) {
        int minj = -1, mini = INT_INF;
        FOR(j, 31) {
            int x = 1 << j;
            if (!freq2[x - A[ord[i]]].empty() && freq2[x - A[ord[i]]].front() < mini) {
                mini = freq2[x - A[ord[i]]].front();
                minj = j;
            }
        }
        if (minj == -1) freq2[A[ord[i]]].push(i);
        else {
            int x = 1 << minj;
            freq2[x - A[ord[i]]].pop();
            ans++;
        }
    }
    writeln(ans);
