inline void solve()
{
	sort(a + 1, a + n + 1);
	int ans = 0;
	for(int p = MAX_LOG; p >= 0; --p)
	{
		int d = 1 << p;

		static int vis[MAXN + 5], b[MAXN + 5];
		for(int j = 1; j <= n; ++j) vis[j] = 0;

