			if(a[i] + a[j] == d) vis[i] = vis[j] = 1, ++ans;
		}
		int m = 0;
		for(int i = 1; i <= n; ++i) if(!vis[i]) b[++m] = a[i];
		for(int i = 1; i <= m; ++i) a[i] = b[i];
		n = m;
	}
	printf("%d\n", ans);
}

