int N; 
int A[200010];
int binary_search(int key) {
    int left = 0, right = N - 1; // 配列 a の左端と右端
    while (right >= left) {
        int mid = left + (right - left) / 2; // 区間の真ん中
        if (A[mid] == key) return mid;
        else if (A[mid] > key) right = mid - 1;
        else if (A[mid] < key) left = mid + 1;
    }
    return -1;
}


int main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N;
    rep(i, N) cin >> A[i];
    sort(A, A + N);
    int k = (1<<30);
    map<int, int> cnt;
    rep(i, N) cnt[A[i]]++;
    int ans = 0;
    while(k >= 1) {
        rrep(i, N - 1) {
            //cout << A[i] << endl;
            int idx = binary_search(k - A[i]);
            if (idx != -1 && cnt[A[i]] >= 1 && ((A[i] != A[idx] && cnt[A[idx]] >= 1) || (A[i] == A[idx] && cnt[A[i]] >= 2))) {
                //cout << A[i] << " " << A[idx] << endl;
                cnt[A[i]]--; cnt[A[idx]]--;
                ans++;
            }
        }
        k = k >> 1;
    }
    cout << ans << endl;


    return 0;
}

