			if (mp.find(y) != mp.end() && mp[y] > 0)
			{
				mp[y]--;
				return y;
			}
			y += power;
			power *= 2;
		}
		return -1;
	}
	else
	{
		while (num)
		{
			dq.push_back(num % 2);
			num /= 2;
		}
		dq.pop_front();
		y = 1, power = 2;
		while (dq.size())
		{
