int binary_search(vector<int> v,int x){
  int l = 0;
  int r = v.size()-1;

  while(r > l){
    int m = (r+l)/2;
    if(v[m] == x) return m;
    else if(v[m] > x) r = m-1;
    else l = m+1;
  }

  if(v[r]==x) return r;
  if(v[l]==x) return l;
  return -1;
}

