                ans+=num[i].con/2;
                num[i].con%=2;
                break;
            }
            else
            {
                l=0;
                r=i;
                while((r-l)>1)
                {
                    if(num[(r+l)/2].how>=Pow[j]-num[i].how) l=(r+l)/2;
                    else r=(r+l)/2;
                }
                if(num[l].how+num[i].how==Pow[j])
                {
                    //printf("%lld %lld %lld\n",num[l].how,num[i].how,Pow[j]);
                    t=min(num[l].con,num[i].con);
                    num[l].con-=t;
                    num[i].con-=t;
                    ans+=t;
                }
                else if(num[r].how+num[i].how==Pow[j])
                {
                    //printf("%lld %lld %lld\n",num[r].how,num[i].how,Pow[j]);
                    t=min(num[r].con,num[i].con);
                    num[r].con-=t;
                    num[i].con-=t;
                    ans+=t;
                }
                break;
            }
        }
    }
    printf("%lld\n",ans);
    return 0;
}

