const int mod = 1000000007;
struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x(x%mod){}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

const int MOD = 1000000007;
const int inf=1e9+7;
const ll longinf=1LL<<60 ;

void addM(ll &a, ll b) {
    a += b;
    if (a >= MOD) a -= MOD;
}

void mulM(ll &a, ll b) {
    a = ((a%MOD)*(b%MOD))%MOD ;
}

ll powM(ll a,ll b) {
    ll ret = 1;
    ll tmp = a;
    while(b>0) {
        if((b&1)==1) ret = (ret * tmp) % MOD;
        tmp = (tmp * tmp) % MOD;
        b = b >> 1;
    }
    return ret;
}

map<int, int> mp;
int get2beki(int a){
  if(mp[a]) return mp[a];
  int ret = 1;
  while(ret <= a) ret *= 2;
  return mp[a] = ret;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);  

  int N;
  cin >> N;

  vector<int> v(N);
  REP(i, N) cin >> v[i];
  sort(all(v));

  vector<bool> isUsed(N, false);

  vector<int> skip(N);
  REP(i, N) skip[i] = i;

  int ans = 0;
  for(int i = N - 1; i >= 0; i--) {
    if(isUsed[i]) continue;

    isUsed[i] = true;
    int b = get2beki(v[i]) - v[i];
    auto ite = lower_bound(all(v), b);

    if(*ite != b) continue;

    int j1 = ite - v.begin();

    int j = skip[j1];
    while(isUsed[j] && *ite == b) {
      ite++;
      j = ite - v.begin();
    }
    skip[j1] = j;

    if(*ite == b){
      ans++;
      isUsed[j] = true;
    }
  }
  cout << ans << endl;

  return 0;
}

