    ll A[200000];
    bool checked[200000];
    cin >> N;
    for(int i=0;i<N;i++){
        cin >> A[i];
        checked[i]=false;
    }

    int ans=0;
    sort(A, A+N);

    for(int i=N-1;i>=0;i--){
        if(checked[i]) continue;
        checked[i]=true;
        int lgA=log2(A[i]);
        lgA++;
        int val = (1LL<<lgA)-A[i];
        int l=0, r=i;
        while(l<r){
            int m=(l+r)/2;
            if(val<A[m] || (A[m]==val && checked[m])) r=m;
            else l=m;
            if(l+1==r){
                if(checked[l]==false && A[l]==val){
                    checked[l]=true;
                    ans++;
                }
                break;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

