int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}
void read_cr() {
    fgets(_buf, 256, stdin);
}

ll solve(int N, vi& a) {
    if (N == 1) return 0;
    if (N == 2) return (__builtin_popcount(a[0] + a[1]) == 1);

    sort(ALL(a));
    ll msum = a[N-1] + a[N-2];

    map<int,int> st;
    rep(i,N) st[a[i]]++;
    int curr = N-1;
    int pairs = 0;
    for (ll sum=1LL<<31LL; sum >= 2LL; sum >>= 1LL) {
        if (sum > msum) continue;

        while (curr >= 0) {
            int x = a[curr--];
            if (st[x] == 0) continue;
            if (x < sum/2) break;

            int rem = sum - x;
            if (rem == sum/2) {
                pairs += st[rem]/2;
                st[rem] %= 2;
            } else {
                int tmp = min(st[x], st[rem]);
                pairs += tmp;
                st[x] -= tmp;
                st[rem] -= tmp;
            }
        }
    }
    return pairs;
}

int main() {
    vi a;
    int N = loadvec(a);
    cout << solve(N,a) << endl;
    return 0;
}

