	for(ds[qu[hd=tl=1]=t]=1;hd<=tl;++hd)for(register Edge *i=la[qu[hd]];i;i=i->ne)
	if(i->re->c&&!ds[i->v]) ds[i->v]=ds[qu[hd]]+1,qu[++tl]=i->v;
