    map<ll, bool> mp;
    for(int i = 1; i < 40; i++){
        mp[pow(2, i)] = true;
    }
    UnionFind uf(n);
    for(int i = 0; i < n; i++){
        for(int j = i + 1; j < n; j++){
            if(mp[a[i] + a[j]]) uf.unite(i, j);
        }
    }
    int ans = 0;
    bool use[n] = {};
    REP(i,n){
        if(!use[uf.root(i)]){
            ans += uf.size(i) / 2;
            use[uf.root(i)] = true;
        }
    }
    cout << ans << endl;
    return 0;
}

