struct UnionFind
{
	//number of parents(par[i] = i => root)
	vector<int> par;
	//rank of tree
	vector<int> rank;

	UnionFind(int n) : par(n), rank(n, 1)
	{
		//initialize
		rep(n, i) par[i] = i;
	}

	//find root (keiroasshuku at the same time)
	int root(int x)
	{
		if (par[x] == x)
			return x;
		else
			return par[x] = root(par[x]);
	}

	//unite
	void unite(int x, int y)
	{
		x = root(x);
		y = root(y);
		if (x == y)
			return;
		if (rank[x] > rank[y])
			swap(x, y);
		par[x] = y;
		rank[y] += rank[x];
	}

	//same tree?
	bool same(int x, int y)
	{
		return root(x) == root(y);
	}
};

void solve()
{
	int N;
	cin >> N;
	vec as(N);
	rep(N, i) cin >> as[i];
	sort(all(as));

	UnionFind uf(N);

	ll ans = 0;

	vec adj[N];

	rep(N, i)
	{
		ll nibeki = 2;
		while(nibeki < 1e9)
		{
			ll part = nibeki - as[i];
			if (part > 0)
			{
				auto e = upper_bound(as.begin() + i + 1, as.end(), part);
				auto b = lower_bound(as.begin() + i + 1, as.end(), part);
				while(b != e)
				{
					uf.unite(i, b-as.begin());
					b++;
				}
			}
			nibeki *= 2;
		}
	}

	vec used(N, 0);

	rep(N, i)
	{
		if (used[uf.root(i)]) continue;
		ans += uf.rank[uf.root(i)] / 2;
		used[uf.root(i)] = 1;
	}

	cout << ans << endl;
}

int main()
{
	solve();
