const int N = 2 * 1e5;

int n;
map<int, int> compressed, cnt;
bitset<N> isHalf, vis;
set<int> halves;

vi conn[N];
int ans = 0;

void dfs(int v, int m) {
	if (isHalf[v] && m) return;
	if (!cnt[v]) return;
	vis[v] = true;

	for (int u : conn[v]) {
		if ((isHalf[u] && m) || !cnt[u]) continue;
		int lim = min(cnt[u], cnt[v]);
		cnt[u] -= lim, cnt[v] -= lim;
		ans += lim;
		if (cnt[u]) dfs(u, m);
		else {
			for (int uu : conn[u]) dfs(uu, m);
		}
	}

	if (!m && isHalf[v]) ans += cnt[v] / 2;
}

int main() {
	cin.tie(0)->sync_with_stdio(0);
	cin >> n;
