void solve(long long n, vector<long long> a)
{
    mi[0] = 1;
    for (int i = 1; i <= 32; ++i) {
        mi[i] = mi[i - 1] * 2;
    }
    sort(a.begin(), a.end());
    for (int i = 0; i < n; ++i) {
        if (mp.count(a[i]) == 0)
            mp[a[i]] = 1;
        else
            mp[a[i]]++;
    }
    reverse(a.begin(), a.end());
    int ans = 0;
