llong judge( llong A[],llong tmp){
    int left = 0,right = n -1 ;
    llong ans = 0;
    while(1){
        if(left >= right) break;
        while(visit[right]){
            right --;
            if( left >= right) break;
        }
        while(A[left] + A[right] < tmp){
            left += 1;
            if( left >= right) break;
        }
        if( A[left ] + A[right] == tmp){
            llong init = A[left];
            while(visit[left] and init == A[left]){
                left ++;
                if(left >= right) break;
            }
            if( init == A[left]){
                if(left >= right) break;
                ans += 1;
                visit[left] = true;
                visit[right] = true;
                left += 1;
            }
        }
        right --;
    }
    return ans;
}



