const ll INF = 1e9;
int ans = 0;

int dfs(ll x, ll p) {
	int tot = 0;
	ll s = 1;
	while (s <= x) s <<= 1;
	for (; s-x <= INF; s <<= 1) {
		ll y = s-x;
		if (y == p) continue;
		if (M.count(y)) tot += dfs(y,x); 
	}
	ans += min(M[x], tot);

	return max(0, M[x]-tot);
}

