using namespace std;

int N, i, j, ans;
vector<int> A;
int pow2s[32];

int binSearch(int x, int left, int right) {
    // cout << "x:" << x << endl;
    // cout << "left:" << left << ",right:" << right << endl;
    if (left + 1 == right) { //探索終了
        return (A[left] == x) ? left : -1;
    }
    int med;
    if ((left + right) % 2 == 0) {
        med = (left + right) / 2;
    } else {
        med = (left + right + 1) / 2;
    }
    // cout << "med:" << med << endl;
    if (A[med] < x) { //xはmedより左側
        return binSearch(x, left, med);
    } else { //xはmedと同じ または medより右側
        return binSearch(x, med, right);
    }
}

int main(void) {
    pow2s[0] = 1;
    for (i=1; i<=32; i++) {
        pow2s[i] = pow2s[i-1] * 2;
    }
    cin >> N;
    int tmp;
    for (i=0; i<N;i ++) {
        cin >> tmp;
        A.push_back(tmp);
    }
    sort(A.begin(), A.end());
    reverse(A.begin(), A.end());

    ans = 0;
    while (A.size() >= 2) {
        //まず，作れる２べきを探す
        for (i=0; i<32; i++) {
            if (pow2s[i] <= A[0] && A[0] < pow2s[i+1]) {
                break;
            }
        }
        //このとき，pow2s[i+1]が作れる２べき
        int pair_num = pow2s[i+1] - A[0];
        int pair_index = binSearch(pair_num, 0, (int)A.size());
        if (pair_index > 0) { //ペアがある
            A.erase(A.begin() + pair_index);
            ans++;
        }
        A.erase(A.begin());
    }
    cout << ans << endl;

    return 0;
}

