map < ll, int > mapp;
vll arr;
vi v[N];
ll p2[N];
int deg[N];
set < int > temp;
queue < int > q;
bool mark[N];

void perform(int n, int &ans)
{
	int i, val, z;
	fo(i,1,n+1)
	{
		deg[i] = sz(v[i]);
		mark[i] = 0;
	}
	while(!q.empty())
		q.pop();

	z = deg[1];
	fo(i,1,n+1)
		z = min(z, deg[i]);

	fo(i,1,n+1)
		if(deg[i] == z)
		{
			mark[i] = 1;
			q.push(i);
		}

	while(!q.empty())
	{
		z = q.front();
		q.pop();
		for(auto x : v[z])
		{
			val = min(cnt[z],cnt[x]);
			ans += val;
			cnt[z] -= val;
			cnt[x] -= val;
			if(!mark[x])
			{
				mark[x] = 1;
				q.push(x);
			}
		}
	}
	return;
}

void solve()
{
	int n, i, j, ans = 0;
	p2[0] = 1;
	fo(i,1,alpha+1)
		p2[i] = p2[i-1]+p2[i-1];
	cin >> n;
	fo(i,1,n+1)
	{
		cin >> a[i];
		temp.insert(a[i]);
	}
	arr.pb(0);
	for(auto x : temp)
		arr.pb(x);
	fo(i,1,sz(arr))
		mapp[arr[i]] = i;
	fo(i,1,n+1)
		cnt[mapp[a[i]]]++;

	n = sz(arr)-1;
	fo(i,1,n+1)
		fo(j,0,alpha+1)
			if(mapp[p2[j]-arr[i]] && p2[j]-arr[i] != arr[i])
				v[i].pb(mapp[p2[j]-arr[i]]);
	fo(i,1,n+1)
		if((arr[i]&(arr[i]-1LL)) == 0LL)
		{
			ps_cnt[i] = cnt[i];
			cnt[i] = 0;
		}
	perform(n,ans);
	fo(i,1,n+1)
		if(ps_cnt[i] != 0)
			cnt[i] = ps_cnt[i];
	perform(n,ans);
	fo(i,1,n+1)
		if(cnt[i] > 0 && (arr[i]&(arr[i]-1LL)) == 0LL)
			ans += (cnt[i]/2);
	cout << ans << '\n';
	return;
}

