signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int N;
    cin >> N;
    vector<int> A(N);
    map<int, int> cnt;
    REP(i, N) {
        cin >> A[i];
        cnt[A[i]]++;
    }

    sort(A.begin(), A.end(), greater<int>());

    vector<int> two(31);
    two[0] = 2;
    FOR(i, 1, 30) two[i] = two[i - 1] * 2;

    int ans = 0;
    REV(i, 30, 1) {
        int t = two[i];
        REP(j, A.size()) {
            int a = A[j];
            if (a > t) continue;
            if (a != t - a) {
                if (cnt[a] > 0 && cnt[t - a] > 0) {
                    cnt[a]--;
                    cnt[t - a]--;
                    ans++;
                }
            } else {
                if (cnt[a] >= 2) {
                    cnt[a] -= 2;
                    ans++;
                }
            }
        }
    }

    cout << ans << endl;
    return 0;
}

