      if(A.at(i-1) == d){
        cnt++;
        a.at(i-1) = true;
        continue;
      }
      else continue;
    }

    ll left = 0, right = N;
    ll mid;
    while(left < right){
      mid = (left+right)/2;
      if(A.at(mid) == d){
        cnt++;
        a.at(mid) = true;
        break;
      }
      if(A.at(mid) > d) right = mid;
      if(A.at(mid) < d) left = mid;
    }
  }
  cout << cnt << endl;
