long long int not_1(long long int a) {
	stack<int> stk;
	while (a != 1) {
		if (a % 2 == 0) {
			stk.push(0);
		}
		else {
			stk.push(1);
		}
		a /= 2;
	}
	long long int c = 0;
	while (!stk.empty()) {
		c *= 2LL;
		int b = stk.top();
		stk.pop();
		if (b == 0) {
			c++;
		}
	}
	c++;
	return c;
}

