            ll diff = i - num;
            if(diff < 0) continue;
            auto itr = mp.find(diff);
            if( itr != mp.end() ) {
                ans++;
                used[mp[diff]] = true;
                used[k] = true;
                mp.erase(diff);
            } 
            else {
                mp[num] = k+1;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

#include<cstdio>
