using namespace std;
typedef long long ll;

void solve(long long N, vector<long long> A){
	map<long long, ll> mp;

	for(int i = 0; i < N; ++i) {
		mp[A[i]]++;
	}
	sort(A.begin(), A.end());
	A.erase(unique(A.begin(), A.end()), A.end());
	long long res = 0;
	for(int k = 30; k > 0; --k) {
		long long t = 1LL << k;
		for(int i = 0; i < A.size() && A[i] <= t / 2; ++i){
			ll a = A[i];
			ll b = t - a;
			if (a != b) {
				ll m = min(mp[a], mp[b]);
				mp[a] -= m;
				mp[b] -= m;
				res += m;
			} else {
				res += mp[a] / 2;
				mp[a] %= 2;
			}
		}
	}
	cout << res << endl;
}

