int ans;

int bins (int value, int ind) {
    int lb = 0;
    int ub = N;
    while (lb < ub) {
        int mid = (lb + ub) / 2;
        if (A[mid] == value && used[mid] == false && mid != ind) {
            return mid;
        } else if (A[mid] < value) {
            lb = mid + 1;
        } else {
            ub = mid;
        }
    }
    return -1;
}

int lpow (int A) {
    int ans = 1;
    while (ans <= A) {
        ans *= 2;
    }
    return ans;
}

int main() {
    cin >> N;

    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }
    sort(A, A + N);

    used[MAX] = {};
    ans = 0;
    for (int i = N - 1; i >= 0; i--) {
        if (used[i]) {
            continue;
        }
        int lp = lpow(A[i]);
        int opp = bins(lp - A[i], i);
        if (opp != -1) {
            used[i] = true;
            used[opp] = true;
            ans ++;
        }
    }
    cout << ans;
}

