int solve( vector <int> v )
{
    if( v.size() == 0  ) return 0 ;
    ms.clear() ;
    vector <int> toSend ;
    for(int i=0 ; i<v.size() ; i++)
    {
        if( v[i]%2==1 ) ms.insert(  v[i] ) ;
        else toSend.pb( v[i]/2 ) ;
    }
    int ans = 0 ;

    while( !ms.empty() )
    {
      multiset<int> :: iterator it = ms.end() ;
      it-- ;
      int val = *it ;
      ms.erase(it) ;
      if( ms.empty() ) break ;
      int p = 1 ;
      while( 1 )
      {
          if( p <= val )
          {
              p *= 2 ;
              continue ;
          }
          if( ms.find( p-val ) != ms.end() )
          {
              ans++ ;
              ms.erase( ms.find( p-val ) ) ;
          }
          break ;
      }
    }
    ans += solve(toSend) ;
    return ans ;
}

