    }
    sort(begin(A), end(A), greater<>());

    int ans = 0;
    for (auto a : A) {
        auto pa = S.find(a);
        if (pa == S.end()) {
            continue;
        }
        S.erase(pa);

        int b = ceil2(a) - a;
        auto pb = S.find(b);
        if (pb != S.end()) {
            S.erase(pb);
            ans += 1;
        }
    }

    cout << ans << '\n';
}

