signed main() {
    int N; cin >> N;
    vector< pair<int, int> > vec(N);
    for(int i=0; i<N; i++) {
        int val; cin >> val;
        vec[i] = make_pair(val, 1);
    }
    sort(vec.begin(), vec.end());

    int ans = 0;
    for(int i=0; i<N; i++) {
        // used element
        if(vec[i].second == 0) continue;

        // とりあえず使用済みにしておく
        vec[i].second = 0;
        int val = vec[i].first;

        int pow2 = 1;
        while(pow2 <= val) pow2 *= 2;

        // fprintf(stderr, "val = %lld, pow2 = %lld\n", val, pow2);

        int target = pow2 - val, last = INF;
        for(int k=0; k<32; k++) {
            int plus = 1LL << k;
            if(max(val, target) < plus) {
                target += plus;
                if(last == INF) {
                    // fprintf(stderr, "i = %lld, last = %lld\n", i, k);
                }
                last = min(last, k);
            }
        }

        bool found = false;
        for(int k=31; k>=last; k--) {
            // fprintf(stderr, "i = %lld, val = %lld, target = %lld\n", i, val, target);
            int plus = 1LL << k;
            auto itr = lower_bound(vec.begin(), vec.end(), make_pair(target, 1LL));
            if(itr != vec.end() and itr->first == target) {
                found = true;
                itr->second = 0;
                vec[i].second = 0;
                ans++;
                break;
            }
            target -= plus;
        }

        if(!found) {
            vec[i].second = 1;
        }
    }
    cout << ans << endl;
    return 0;
}

