		int num = 0;
		for (int sum = 1 << 30; sum >= x + 1; sum >>= 1) {
			int y = sum - x;
			if (mpcnt.count(y)) {
				num++;
			}
		}
		v.push_back({num, x});
	}
	sort(v.begin(), v.end());
	int cnt = 0;
	for (auto p: v) {
