struct edge{
	int to; edge *nxt;
}edges[MAXN + 5], *adj[MAXN + 5], *ecnt;
void addedge(int u, int v) {
	edge *p = (++ecnt);
	p->to = v, p->nxt = adj[u], adj[u] = p;
}
bool tag[MAXN + 5], vis[MAXN + 5];
int tot[MAXN + 5], arr[MAXN + 5], cnt;
vector<int>vec[MAXN + 5];
map<int, int>mp;
int lowbit(int x) {
	return x & -x;
}
long long dp[MAXN + 5][2];
void dfs(int rt) {
	dp[rt][1] = tot[rt]; dp[rt][0] = 0;
	for(edge *p=adj[rt];p!=NULL;p=p->nxt) {
		dfs(p->to);
		dp[rt][1] += dp[p->to][0];
		dp[rt][0] += max(dp[p->to][0], dp[p->to][1]);
	}
	adj[rt] = NULL, vis[rt] = false;
}
int main() {
	int N, A; scanf("%d", &N);
	for(int i=1;i<=N;i++) {
		scanf("%d", &A);
		vec[int(log2(lowbit(A)))].push_back(A/lowbit(A)/2);
	}
	long long ans = 0;
	for(int i=0;i<=MAXL;i++) {
		cnt = 0; ecnt = &edges[0]; mp.clear();
		for(int j=0;j<vec[i].size();j++) {
			if( !mp.count(vec[i][j]) ) mp[vec[i][j]] = (++cnt);
			arr[j] = mp[vec[i][j]]; tot[arr[j]]++;
		}
		for(int j=0;j<vec[i].size();j++) {
			if( vis[arr[j]] ) continue;
			vis[arr[j]] = true;
			int p = 0;
			for(int k=0;k<=MAXL;k++) {
				if( (1<<k) > vec[i][j] ) break;
				if( !((1<<k) & vec[i][j]) ) p |= (1<<k);
			}
			if( mp.count(p) && vec[i][j] != 0 ) addedge(mp[p], arr[j]);
			else tag[arr[j]] = true;
		}
		ans += vec[i].size();
		for(int j=0;j<vec[i].size();j++) {
			if( tag[arr[j]] ) {
				dfs(arr[j]);
				if( vec[i][j] == 0 ) {
					long long del = -(1LL<<40);
					for(int k=0;k<=tot[arr[j]];k+=2)
						del = max(del, -max(dp[arr[j]][0]+k/2, dp[arr[j]][1]-k/2));
					ans += del;
				}
				else ans -= max(dp[arr[j]][0], dp[arr[j]][1]);
				tag[arr[j]] = false;
			}
			tot[arr[j]] = 0;
		}
	}
	printf("%lld\n", ans);
}

