bool check(int n, const vector<int> &a, int m) {
  int pos = a[0] - 1;

  vector<int> b(n, 1);
  stack<int> undo;

  for(int i = 1; i < n; i++){
    const int next = a[i] - 1;

    if(next > pos) {
    } else {
      while(undo.size() && undo.top() > next) {
	b[undo.top()] = 1;
	undo.pop();
      }
      b[next] += 1;

      if(b[next] > m) return false;
    }

    pos = next;
  }

  return true;
}

int main(){
