  REP(i,n) a[i] = getInt();

  int low = 1;
  int high = n;
  while(low <= high) {
    const int med = (low + high) / 2;
    if(check(n, a, med)) {
      high = med - 1;
    } else {
      low = med + 1;
    }
  }

  printf("%d\n", low);

  return 0;
}

