int32_t main() {

    int n; cin >> n;
    set<pair<int, int>> a;
    for(int i = 0; i < n; ++i) {
        int x; cin >> x;
        a.insert({x, i});
    }

    vector<int> twopows = getpows();
    vector<vector<int>> cs(n, vector<int>(1, 0));
    for(int i = 0; i < n; ++i) cs[i][0] = i;
    map<int, int> deg;

    for(auto it = a.begin(); it != a.end(); it++) {
        int ai = it->first;
        for(int p : twopows) {
            if(p <= ai) continue;

            auto f = a.lower_bound(make_pair(p-ai, 0));
            auto g = a.lower_bound(make_pair(p-ai+1, 0));
            while(f != g) {
                if(it->second != f->second) {
                    cs[it->second].push_back(f->second);
                    deg[it->second]++;
                }
                f++;
            }
        }
    }

    sort(cs.begin(), cs.end(),
         [](const vector<int> & a, const vector<int> & b){ return a.size() < b.size(); });

    vector<bool> used(n, false);
    int ans = 0;
    for(int i = 0; i < n; ++i) {
        vector<int>& csi = cs[i];
        if(used[csi[0]] || (int)csi.size() == 1) continue;
        int cur = -1, curdeg = 1000000000;
        for(int j = 1; j < (int) csi.size(); ++j) {
            int d = deg[csi[j]];
            if(!used[j] && d < curdeg) {
                cur = j;
                curdeg = d;
            }
        }
        if(cur >= 0) {
            ans++;
            used[csi[0]] = true;
            used[csi[cur]] = true;

        }
    }

    cout << ans << endl;

    return 0;
}

