template<class T> struct hammultiset{
	multiset<T> s;
	typename multiset<T>::iterator it;
	bool empty() const { return s.empty(); }
	ll size() const { return (ll)s.size(); }
	void clear() { return s.clear(); }//
	void insert(const T &x){ it=s.insert(x); }
	template <class Iter> void insert(Iter b, Iter e){ s.insert(b, e); }
	void eraseall(const T &x){ s.erase(x); } //全て削除
	void erase1(const T &x){ find(x); s.erase(it); } //1つ削除
	void swap(hammultiset &st){ s.swap(st.s); }
	ll count(const T &x) { return (ll)s.count(x); }
	bool contains(const T &x) const { return s.find(x) != s.end(); }
	void find(const T &x){ it=s.find(x); }
	T next() { return *(++it); }
	T prev() { return *(--it); }
	pair<T, bool> Next(){
		if (it!=s.end()) it++;
		if (it!=s.end()) return {*it,true};
		else return {T(),false};
	}
	pair<T, bool> Prev(){
		if (it!=s.begin()) return {*(--it), true};
		else return {T(),false};
	}
	T front() const{ return *s.begin(); }
	T back() const{ return *(--s.end()); }
	void pop_front(){ s.erase(s.begin()); }
	void pop_back(){ s.erase(--s.end()); }
#ifdef _DEBUG
	void dump(){
		each(e, s) cout << e << " ";
		cout << '\n';
	}
#endif
};


