            if (rest < 1) continue;

            auto lb = lower_bound(A, A + N, rest);
            auto ub = upper_bound(A, A + N, rest);
            for (auto it = lb; it != ub; it++) {
                if (it - A == i) continue;
                G[i].push_back(it - A);
            }
        }
    }

    cout << bipartite_matching() << endl;
    return 0;
}

