using namespace std;

const int MAX_V = 2 * 100010;
const int INF = 1 << 30;

struct Edge {
  int to;
  int capacity;
  int reverse;
};  // struct Edge

vector<Edge> G[MAX_V];
bool used[MAX_V];

void AddEdge(int from, int to, int capacity) {
  G[from].emplace_back(Edge{to, capacity, (int)G[to].size()});
  G[to].emplace_back(Edge{from, 0, (int)G[from].size() - 1});
}

int DFS(int source, int target, int flow) {
  if (source == target) return flow;
  used[source] = true;
  for (auto& edge : G[source]) {
    if (used[edge.to]) continue;
    if (edge.capacity <= 0) continue;

    int actualFlow = DFS(edge.to, target, min(edge.capacity, flow));
    if (actualFlow <= 0) continue;

    edge.capacity -= actualFlow;
    G[edge.to][edge.reverse].capacity += actualFlow;
    return actualFlow;
  }
  return 0;
}

int MaxFlow(int source, int target) {
  int totalFlow = 0;
  while (true) {
    memset(used, false, sizeof(used));
    int flow = DFS(source, target, INF);
    if (flow == 0) {
      break;
    }
    totalFlow += flow;
  }
  return totalFlow;
}

int main() {
  int N;
  cin >> N;
  vector<int> A(N);
  for (int i = 0; i < N; i++) cin >> A[i];

  for (int a = 0; a < N; a++) {
    for (int b = a + 1; b < N; b++) {
      int sum = A[b] + A[a];
      if ((sum & (sum - 1)) == 0) {
        AddEdge(a, b + N, 1);
      }
    }
  }
  for (int a = 0; a < N; a++) {
    AddEdge(2 * N, a, 1);
  }
  for (int b = 0; b < N; b++) {
    AddEdge(b + N, 2 * N + 1, 1);
  }

  cout << MaxFlow(2 * N, 2 * N + 1) << endl;

  return 0;
}

