using ll=long long;
int main(){
  ll n;
  cin>>n;
  vector<ll> a(n);
  for(int i=0;i<n;i++) cin>>a[i];
  sort(a.rbegin(),a.rend());

  vector<int> used(n,false);
  multiset<pair<ll,int>> as;
  for(int i=0;i<n;i++) as.insert(make_pair(a[i],i));

  int res=0;
  for(int i=0;i<n;i++){
    if(!used[i]){
      as.erase({a[i],i});
      for(int j=31;j>=0;j--){
	ll tar=(1LL<<j)-a[i];
	if(tar<=0) continue;
	auto it=as.lower_bound({tar,-1});
	if(it==as.end() || it->first!=tar) continue;
	pair<int,int> tmp=*it;
	used[tmp.second]=true;
	as.erase(tmp);
	res++;
      }
    }
  }
  cout<<res<<endl;
  return 0;
}

