int n,a[200010],ans;
ll two[35];
map<ll,int>mp;

void input(){
	cin>>n;
	for(int i=0;i<n;i++){
		cin>>a[i];
		mp[a[i]]++;
	}
	return;
}

void solve(){
	two[0]=1;
	for(int i=1;i<32;i++){
		two[i]=two[i-1]*2;
	}
	sort(a,a+n);
	for(int i=n-1;i>0;i--){
		if(!mp[a[i]])continue;
		mp[a[i]]--;
		ll base;
		for(int j=0;j<32;j++){
			if(a[i]<two[j]){
				base=two[j];
				break;
			}
		}
		ll want=base-a[i];
		if(mp[want])mp[want]--,ans++;
	}
	cout<<ans<<endl;
	return;
}

int main(){
	input();
	solve();
	return 0;
}

