                    flag = true;
                    break;
                }else{
                    temp /= 2;
                }
            }
            if(flag){
                flag = false;
                continue;
            }else{
                ++ans;
                array.erase(array.begin()+i);
                --n;
                max = 0;
                break;
            }
        }
        if(i == -1){max = 0;}
    }
    cout << ans << endl;
    return 0;
}

