long long pairing(long long X){
	int l = 0, r = 60, msb = 60;
	while(l<=r){
		int mid = (l+r)>>1;
		long long val = (1LL << mid);
		if(val > X) msb = mid, r = mid-1;
		else l = mid+1;
	}
	return (1LL<<msb) - X;
}

int main() {
	// your code goes here
	cin >> n;
	for(int i=1; i<= n; ++i){
		cin >> a[i].first; a[i].second = i;
	}
