	for(int i=n; i>= 1;--i){
		if(b[i]) continue;
		long long X = pairing(a[i].first);
		int l = 1, r = i-1, j = -1;
		while(l<=r){
			int mid = (l+r)>>1;

			if(a[mid].first < X) l = mid+1;
			else if(a[mid].first > X) r =mid-1;
			else if(b[mid]) l = mid+1;
			else j = mid, r = mid-1;
		}
