    for(int i = 0; i < odd_size-1; i++) {
        for(int j = i+1; j < odd_size; j++) {
            if((odd[i] & odd[j]) == 1) {
                // odd[j] = 0;
                odd.erase(odd.begin() + j);
                odd_size--;
