    for(int i = 0; i < even_size-1; i++) {
        for(int j = i+1; j < even_size; j++) {
            if(((even[i]+1) & (even[j]-1)) == 1) {
                // even[j] = 1;
                even.erase(even.begin() + j);
                even_size--;
                num_pow2++;
                break;
            }
        }
    }
    cout << num_pow2 << endl;
