ll top(int x) {
	return 1 << (31 - __builtin_clz(x));
}

int main()
{
	int N;
	cin >> N;
	vector<ll> A(N);
	map<ll, int> mp;
	for (int i = 0; i < N; i++) {
		cin >> A[i];
		mp[A[i]] += 1;
	}
	sort(A.rbegin(), A.rend());
	int res = 0;
	for (int i = 0; i < N; i++) {
		if ((A[i] & (A[i] - 1)) == 0) {
			res += mp[A[i]] / 2;
			mp.erase(A[i]);
		}
		else {
			ll val = top(A[i]) * 2 - A[i];
			int cnt = min(mp[A[i]], mp.count(val) ? mp[val] : 0);
			res += cnt;
			if (mp.count(val)) mp[val] -= cnt;
			mp.erase(A[i]);
		}
	}
	cout << res << endl;
	return 0;
}

