int result = 0;
int DD[200000] = {};

int Func(int k, int N, int A[]) {
    int pow2k = pow(2,k);
    int pow2k_1 = pow(2,k-1);
    int C_index = 0;
    while (A[C_index]<pow2k_1) {
        C_index += 1;
    }
    int N_b = C_index;
    int N_c = N - C_index;
    //cout << C_index << endl;

    int index = 0;
    vector<int> D{};
    int N_d = 0;

    int temp_0 = 0;
    for (int i=0;i<N;i++) {
        if (A[i]==pow2k_1) temp_0 += 1;
    }
    result += temp_0/2;
    //cout << result << endl;

    for (int i=0;i<N_c;i++) {
        int target = pow2k - A[N-1-i];
        while (A[index]<target) {
            if (index==C_index) {A[index]=target+1; break;}
            D.push_back(A[index]);
            N_d += 1;
            index += 1;
        }
        if (index==C_index) {break;}
        if (A[index]==target) {
            result += 1;
            index += 1;
        }
    }
    for (int i=index;i<N_b;i++) {
        D.push_back(A[i]);
        N_d += 1;
    }

    //cout << k << " " << result << endl;
    //cout << result << endl;
    //cout << "DD=[";
    for (int i=0;i<N_d;i++) {
        DD[i] = D[i];
        //cout << DD[i] << " ";
    }
    //cout << "]" << endl;

    return N_d;
}


int main(){
