    for (int i=0;i<N;i++) {
        DD[i] = A[i];
    }
    //cout << k << endl;

    while (k>0) {
        N = Func(k, N, DD);
        k = 0;
        now = DD[N-1];
        while (now>=pow(2,k)) {k += 1;}
    }

    cout << result << endl;

    return 0;
}

