    int n, m, ans = 0;
    cin >> n;
    vector<int> v(n);
    // 値に対して個数を持つ。ペアとして使用する際に個数を数える。
    map<int, int> mp;

    for (int i = 0; i < n; i++) {
        cin >> m;
        v[i] = m;
        if (mp.count(m) == 0) {
            mp[m] = 1;
        } else {
            mp[m]++;
        }
    }
    sort(ALLR(v));

    // 大きい値から順に処理する
    for (auto x : v) {
        // ２つの数を足して実現可能な２のべき乗は１通り
        uint32_t un = x, um;
        int bitPos = 31;
        while (bitPos >= 0) {
            if (un & (1 << bitPos)) {
                break;
            }
            bitPos--;
        }
        // 現在の数字よりも大きい２のべき乗を作成
        um = 1 << (bitPos + 1);
        int search = um - un;
        // 自分自身は使用済みにする
        mp[x]--;
        if (mp[search] >= 1) {
            ans++;
            mp[search]--;
        }
    }
    cout << ans << endl;

    return 0;
}

