ll calc_good(vector<ll> &a, int i, int b_length, vector<map<int, int>> &cache) {


  if (cache[i].find(b_length) != cache[i].end()) {
    return cache[i][b_length];
  }


  ll good_count = 0;
  for (int j = i; j < a.size(); j++) {
    if ((a[j] % (b_length + 1)) == 0) {
      good_count += 1;
      good_count += calc_good(a, j + 1, b_length + 1, cache);
      good_count = mod_1097(good_count);
    }
  }


  cache[i][b_length] = good_count;
  //debug(cache);

  return good_count;

}

vector<ll> get_primes(ll n) {
  vector<ll> primes = {};
  vector<ll> nums(n, 0);
  for (ll i = 2; i < n; i++) {
    if (nums[i] == 0) {
      primes.push_back(i);
      for (ll j = i*2; j < n; j += i) {
        nums[j] = i;
      }
    }
  }

  return primes;
}

vector<ll> sieve(ll n) {
  vector<ll> res(n+1, 0);
  res[n] = n;
  for (int i = 2; i < pow(n, 1/2); i++) {
    ll shuttle = i*i;
    while (shuttle < n) {
      res[shuttle] = i;
      shuttle += i;
    }
  }
  return res;
}




