    for(long long i = 0 ; i < n ; ++i)
    {
        for(long long j = 0 ; j <= 31 ; ++j)
        {
            long long x = 1ll << j ;
            if(arr[i] >= x)
                continue;
            if(mp[x - arr[i]] > 0)
            {
                if(x - arr[i] == arr[i] && mp[arr[i]] == 1)
                    continue;
                mp2[arr[i]]++;
            }
        }
    }
    vector<long long>v ;
    for(auto &i : mp2)
        v.push_back(i.first);
    for(int i = 0 ; i < v.size() ; ++i)
    {
        if(mp[v[i]] == 0)
            continue;
        int idx = -1 , MIN = 1e9+1 ;
        for(long long j = 0 ; j <= 31 ; ++j)
        {
            long long x = 1ll << j ;
            if(v[i] >= x)
                continue ;
            if(mp[x - v[i]] > 0)
            {
                if(mp[x-v[i]] == 1 && x - v[i] == v[i])
                    continue;
                if(mp2[x - v[i]] < MIN)
                    MIN = mp2[x - v[i]] , idx = x - v[i] ;
            }
        }
        if(idx != -1)
        {
            if(idx == v[i] && mp[v[i]] == 1)
                continue;
            if(mp[v[i]] == 1)
                mp2[idx]--;
            if(mp[idx] == 1)
                mp2[v[i]]--;
            mp[v[i]]-- , mp[idx]-- , ans++;
        }
    }
    return cout<<ans<<"\n" , 0 ;
}

