  set<int> used;
  for (int i=32; i>=0; i--) {
    long b = pow(2, i);
    auto start = lower_bound(a, a + n, b);
    --start;
    for (int j=start-a; j>=1; j--) {
      if (used.find(j) != used.end()) {
        continue;
      }
      long c = b - a[j];
      if (c > a[j-1]) {
        break;
      }
      auto it = lower_bound(a, a + j, c);
      if (it == a + j) {
        continue;
      }
      while (it != a + j && *it == c) {
        if (used.find(it-a) == used.end()) {
          used.insert(j);
          used.insert(it - a);
          break;
        }
        ++it;
      }
    }
  }
  cout<<used.size()/2<<endl;
}

