bitset<N> isHalf, vis;
set<int> halves;

vi conn[N];
int ans = 0;

void dfs(int v, int m) {
	if (isHalf[v] && m) return;
	vis[v] = true;

	for (int u : conn[v]) {
		if ((isHalf[u] && m) || !cnt[u]) continue;
		int lim = min(cnt[u], cnt[v]);
		cnt[u] -= lim, cnt[v] -= lim;
		ans += lim;
		if (cnt[u]) dfs(u, m);
	}

	if (!m && isHalf[v]) ans += cnt[v] / 2;
}

