multiset<ll> s;

void solve(){
    rep(i, n){
        ll a; in1(a);
        s.insert(a);
    }

    auto it = s.begin();
    revrep(i, 31){
        ll target = 1LL << i;
        while (!s.empty() && *it <= target / 2 && it != s.end()){
            auto lb = s.lower_bound(target - *it);

            if (it == lb){
                if (*next(it) != *lb) break;
                else it++;
            }

            if (*lb + *it == target){
                answer++;
                s.erase(lb);
                it++;
                s.erase(prev(it));
            }else it++;
        }
        it = s.begin();
    }

    prl(answer);
}

