    }
    let mut res = 0;
    let mut mat = vec![None; g.len()];
    for v in 0..g.len() {
        if mat[v].is_none() {
            let mut used = vec![false; g.len()];
            if dfs(v, g, &mut mat, &mut used) {
                res += 1;
            }
        }
    }
    res
}

fn solve() {
    let n = get!(usize);
    let mut aa = get!([u64]);

    aa.sort();
    let mut g = vec![Vec::new(); 2 * n];

    for i in 0..60 {
        let sum = 1u64 << i;

        for j in 0..n {
            if sum > aa[j] {
                let mut k = aa.lower_bound(&(sum - aa[j]));
                while k < n && aa[k] + aa[j] == sum {
                    g[j].push(k);
                    k += 1;
                }
            }
        }
    }

    for i in 0..n {
        g[i].retain(|&x| x > i);
    }

    for v in &mut g {
        for x in v {
            *x += n;
        }
    }

    println!("{}", bipartite_matching(&g));
}

