int main() {
    ll N;
    cin >> N;
    vector<int> A(N);
    ll count = 0;
    bool used[N];
    for(int i = 0; i < N; i++){
        cin >> A[i];
        used[i] = false;
    }
    sort(A.begin(),A.end());
    for (int i = 0; i < N; ++i) {
        ll currentX = A[N - i -1];
        if(used[N - i - 1]){
            continue;
        }
        if(isBi(currentX)){
            if(i != 0 && A[i - 1] == A[i]){
                used[i] = true;
                used[i-1] = true;
                count++;

            }
            continue;
        }
        ll Y = getMinBi(currentX) * 2;
        auto it = lower_bound(A.begin(), A.end(), Y - currentX);
        if(*it == Y-currentX){
            int index = it - A.begin();
            used[index] = true;
            used[N - i - 1] = true;
            count++;
        }
    }
    cout << count << endl;

}

