const long long POT[31]={2,4,8,16,32,64,128,256,512,1024,2048,4096,8192,16384,32768,65536,131072,262144,524288,1048576,2097152,4194304,8388608,16777216,33554432,67108864,134217728,268435456,536870912,1073741824,2147483648};

int V;
vector<vector<int>> G;
vector<int> match;
vector<bool> used;

void add_edge(int u,int v){
    G[u].push_back(v);
    G[v].push_back(u);
}

bool dfs(int v){
    used[v]=true;
    for (int i = 0; i < G[v].size(); ++i) {
        int u=G[v][i],w=match[u];
        if(w<0||!used[w]&&dfs(w)){
            match[v]=u;
            match[u]=v;
            return true;
        }
    }
    return false;
}

int bipartite_matching(){
    int res=0;
    for (int v = 0; v < V; ++v) {
        if(match[v]<0){
            used=vector<bool>(V,false);
            if(dfs(v))++res;
        }
    }
    return res;
}
int main(){
    cin>>V;
    G=vector<vector<int>>(V,vector<int>());
