        cin>>a[i];
    }
    sort(a.begin(),a.end());
    for (int i = 0; i < V; ++i) {
        for (int j = 0; j < 31; ++j) {
            if(POT[j]<a[i])continue;
            auto itl=lower_bound(a.begin(),a.end(),POT[j]-a[i]);
            if(*itl==POT[j]-a[i]&&i!=itl-a.begin()){
                add_edge(i,itl-a.begin());
            }
        }
    }

    cout<<bipartite_matching()<<endl;
    return 0;
}

