                int pos=lower_bound(a.begin(),a.end(),num-a[v])-a.begin();
                deg[pos]--;
                if(deg[pos]==0) q.push(pos);
            }
            ++ans;
        }
        int cnt=0;
        for(int i=0;i<n;++i)
            if(deg[i]>1)
                ++cnt;
        ans+=cnt/2;
        cout<<ans;
    }

}   
