const int MAX = 100000;

int N;
int A[MAX];
int match[MAX];
map<int,vector<int>> table;

bool matching(bool visit[],int n){
    if(table.count(A[n]) == 0)return false;
    if(visit[n])return false;
    visit[n] = true;

    for(int i = 0;i < table[A[n]].size();i++){
        int m = match[table[A[n]][i]];
        if(visit[table[A[n]][i]])continue;
        if((m != -1 && matching(visit,match[m])) || m == -1){
            match[table[A[n]][i]] = n;
            match[n] = table[A[n]][i];
            return true;
        }
    }
    return false;
}

