uint32_t counter_part(uint32_t val)
{
	uint32_t in = val;
	uint32_t digit = 0;
	while (val != 0) {
		val >>= 1;
		digit++;
	}
	uint32_t ans = (1 << digit);
	uint32_t ret = ans - in;
	return ret;
}

