	sort(as.begin(), as.end());
	for (int i = as.size() - 1; i > 0; i--) {
		if (used[i]) continue;

		uint32_t cp = counter_part(as[i]);

		auto it  = lower_bound(as.begin(), as.begin() + i - 1, cp);
		int  idx = it - as.begin();
		bool found = false;
		while (as[idx] == cp) {
			if (!used[idx]) {
				found = true;
				break;
			}
			idx++;
		}

		if (found) {
			used[i]   = true;
			used[idx] = true;
			count++;
		}
	}

