using namespace std;

set<unsigned> powers = {2};

unsigned count_pairs(multiset<unsigned>& S)
{
  unsigned count = 0;

  while (S.size()>1) {
    auto x1 = S.begin();
    random_device rand;
    advance(x1,rand()%S.size());
    auto s1 = *x1;    
    S.erase(s1);

    unsigned num_possible_pairs = 0;
    unsigned possible_pair;
    for (auto& s2 : S) {
      unsigned sum = s1 + s2;
      if (powers.find(sum)!=powers.end()) {
	++num_possible_pairs;
	possible_pair = s2;
      }
    }
    if (num_possible_pairs==1) {
      S.erase(possible_pair);
      ++count;
    } else if (num_possible_pairs > 1) {
      S.insert(s1);
    }
  }
  return count;
}

int main()
{
  int N;
  cin >> N;

  multiset<unsigned> odds, evens;

  for (int n=0; n<N; ++n) {
    unsigned a;
    cin >> a;
    if (a%2)
      odds.insert(a);
    else
      evens.insert(a);
  }

  while(true) {
    unsigned next = *powers.rbegin()*2;
    if (next > 2e9)
      break;
    powers.insert(next);
  }

  unsigned count = 0;

  count += count_pairs(odds);
  count += count_pairs(evens);

  cout << count << endl;

  return 0;
}

