int b_search(int i, int t){
  int ub=i, lb=-1;
  while(ub-lb>1){
    int mid=(ub+lb)/2;
    if(A[mid]+A[i]>=(ll)pow(2, t)) ub=mid;
    else lb=mid;
  }
  return ub;
}

int main(){
  cin>>N;
  for (int i=0;i<N;++i){ll a;cin>>a;A[i]=a;}
  sort(A.begin(), A.end());
