  for (int i=N-1;i>=1;--i){
    for (int t=1;t<40;++t){
      int j=b_search(i, t);
      ll a=A[j];
      while(A[j]==a&&used[j]==1&&j<i) j++;
      if(A[j]+A[i]==(ll)pow(2, t)&&j!=i){
        ans++;
        used[j]=1;
        break;
      }
    }
  }

  cout << ans << endl;
  return 0;
}

