int N;

int pair_of(int n) {
    int pow = 1;
    while(pow <= n) {
        pow *= 2;
    }
    return pow - n;
}

int main() {

    cin >> N;

    map<int, int> m;
    int a;
    for (int i = 0; i < N; i++) {
        cin >> a;
        m[a] += 1;
    }

    int ans = 0;
    for (auto itr = m.rbegin(); itr != m.rend(); ++itr) {
        if (!(*itr).second) continue;

        int i = (*itr).first;
        int j = pair_of(i);
        int c = min(m[j], m[i]);
        if (i == j) {
            ans += c / 2;
            m[i] %= 2;
            continue;
        }
        if (c > 0) {
            ans += c;
            m[j] -= c;
            m[i] -= c;
        }
    }

    cout << ans << endl;
}

