vector<ll> a;
bool isOK(int index, ll key)
{
  if (a[index] >= key)
    return true;
  else
    return false;
}
int binary_search(ll key)
{
  int ng = -1;
  int ok = (int)a.size();
  while (abs(ok - ng) > 1)
  {
    int mid = (ok + ng) / 2;
    if (isOK(mid, key))
      ok = mid;
    else
      ng = mid;
  }
  return ok;
}

ll repeatSquaring(ll n, ll p)
{
  if (p == 0)
    return 1;
  if (p % 2 == 0)
  {
    ll t = repeatSquaring(n, p / 2);
    return t * t;
  }
  return n * repeatSquaring(n, p - 1);
}

vector<ll> memo;

int main()
{
  int n;
  cin >> n;
  for (ll i = 0; i < 40; ++i)
  {
    memo.push_back(repeatSquaring(2, i));
  }
  unordered_map<ll, ll> mp;
  for (int i = 0; i < n; ++i)
  {
    ll tmp;
    cin >> tmp;
    mp[tmp]++;
    a.push_back(tmp);
  }
  sort(a.begin(), a.end());
  int cnt = 0;
  for (int i = a.size() - 1; i > -0; --i)
  {
    if (!mp[a[i]])
      continue;

    for (int j = memo.size() - 1; j >= 0; --j)
    {
      ll key = memo[j] - a[i];
      if (key > a[a.size() - 1] || key < 0)
        continue;
      int itr;
      itr = binary_search(key);
      if (itr >= a.size() || a[itr] != key || a[i] == a[itr])
        continue;
      if (itr < a.size() && a[i] + a[itr] == memo[j] && i != itr && mp[a[itr]] && mp[a[i]])
      {
        ll diff = mp[a[itr]] < mp[a[i]] ? mp[a[itr]] : mp[a[i]];
        cnt += diff;
        mp[a[itr]] -= diff, mp[a[i]] -= diff;
        break;
      }
    }
  }
  for (auto &e : mp)
  {
    for (int i = 0; i < memo.size(); ++i)
    {
      if (2 * e.first == memo[i])
      {
        cnt += e.second / 2;
        break;
      }
    }
  }
  cout << cnt << endl;

  return 0;
}

