  vll a(n);
  map<int, int> m;
  REP(i, n) {
    cin >> a[i];
    m[a[i]] = i+1;
  }

  Bipartite_Matching bm(n, 1<<10);

  REP(i, n) {
    REP(j, 30) {
      int tmp = (1<<(j+1)) - a[i];
      if(m[tmp] && m[tmp] != i+1) {
        bm.add_edge(i, m[tmp]-1);
      }
    }
  }

  cout << bm.bipartite_matching() / 2 << endl;


}

