const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, n2[35];
vl as;
bool used[MAX_N];
mll cnt;

void solve(){
    rep(i, 31) n2[i] = 0;
    rep(i, n){
        okay = false;
        ll a; in1(a);
        For(j, 1, 31) if (a == 1LL << j) {n2[j]++; okay = true; break;}
        if (!okay) as.pb(a);
    }

    rep(i, 31) answer += n2[i] / 2;
    sort(all(as));

    revrep(i1, 31){
        ll target = 1LL << i1;
        rep(i2, as.size()){
            if (as[i2] > target / 2) break;
            if (used[i2]) continue;
            ll lb = lower_bound(all(as), target - as[i2]) - as.begin();
            if (lb + cnt[as[lb]] < n &&
                !used[lb + cnt[as[lb]]] &&
                as[lb + cnt[as[lb]]] + as[i2] == target){
                used[i2] = used[lb + cnt[as[lb]]] = true;
                cnt[as[lb]]++; cnt[as[i2]]++;
            }
        }
    }

    rep(i, as.size()) answer += used[i];
    prl(answer / 2);
}

int main(void){
    in1(n);
    solve();
    // assert(n <= 10000);
    return 0;
}

