struct Vertex {
	int num;
	vector<int> edge;
	bool operator==(Vertex &left) {
		return num == left.num;
	}
	friend ostream& operator<<(ostream &s, const Vertex &i);
};

ostream& operator<<(ostream &s, const Vertex& i) {
	s << i.num;
	return s;
}

int main() {
	static int N, A[MAX];
	cin >> N;
	for (int i = 0;i < N;++ i) cin >> A[i];
	sort(A, A+N);
	static Vertex v[MAX];
	for (int i = 0;i < N;++ i) v[i].num = i;
	for (int i = 1;i >= 0;i <<= 1) { // ちょっと非本質的な書き方だけど、オーバーフローするんだもん……
		for (int j = 0, k = N - 1;j < k;) {
			if (A[j] + A[k] > i) -- k;
			else if (A[j] + A[k] < i) ++ j;
			else {
				for (int l = k;j < l && A[l] == A[k];-- l) {
					v[j].edge.push_back(l);
					v[l].edge.push_back(j);
				}
				++ j;
			}
		}
	}

	queue<int> que;
	for (int i = 0;i < N;++ i) if (v[i].edge.size() == 1) que.push(i);

	int tmp, tmp2, tmp3;
	int ans = 0, ans2 = 0;
	while(!que.empty()) {
		tmp = que.front();
		que.pop();
		if (v[tmp].edge.empty()) continue;
		++ ans;
		tmp2 = v[tmp].edge[0]; // tmpとペアだった奴
		for (int i = 0, l = v[tmp2].edge.size();i < l;++ i) {
			tmp3 = v[tmp2].edge[i]; // tmp2を消し去りたい
			for (int j = 0, l2 = v[tmp3].edge.size();j < l2;++ j) {
				if (v[tmp3].edge[j] == tmp2) {
					v[tmp3].edge.erase(v[tmp3].edge.begin() + j);
					if (v[tmp3].edge.size() == 1) que.push(tmp3);
					break;
				}
			}
		}
		v[tmp2].edge.clear();
		v[tmp].edge.clear();
	}
	/*
	for (int i = 0;i < N;++ i) {
		cerr << i << ":";
		for (int j = 0;j < v[i].edge.size();++ j) {
			cerr << " " << v[i].edge[j];
		}
		cerr << endl;
	}*/

	for (int i = 0;i < N;++ i) if (!v[i].edge.empty()) ++ ans2;
	cout << ans + ans2 / 2;
	return 0;
}
