	for(i64 i = 0; i < n; ++i) cin >> a[i];
	sort(a.begin(), a.end(), greater<i64>());
	vector<bool> used(n, false);
	i64 ans = 0;
	for(i64 i = 0; i < n - 1; ++i){
		if(used[i]) continue;
		for(i64 j = 33; j >= 1; --j){
			if((1LL<<j) <= a[i]) continue;
			i64 ng = i;
			i64 ok = n;
			while(abs(ok - ng) > 1){
				i64 mid = (ok + ng) / 2;
				if(a[mid] <= (1LL<<j) - a[i] && !used[mid]) ok = mid;
				else ng = mid;
			}
			if(ok == i || ok == n) continue;
			if(a[ok] + a[i] == (1LL<<j)){
				used[ok] = a[i] = true;
				ans++;
				break;
			}
		}
	}
	cout << ans << endl;
}

