template<class U> void rev(vector<vector<U>> &a) {
    vector<vector<U> > b(sz(a[0]), vector<U>(sz(a)));
    rep(h, sz(a)) rep(w, sz(a[0]))b[w][h] = a[h][w];
    a = b;
}
