class bimatch {//@formatter:off
    int n;
    vector<vector<int> >G;
    vector<int>match;
    vector<bool>used;
    bool dfs(int v)    {        used[v]=true;        for(int u:G[v]){            int w=match[u];            if(w<0||!used[w]&&dfs(w))            {                match[v]=u;                match[u]=v;                return true;            }        }        return false;    }
public :
    bimatch(int _n=0):n(_n),G(n),match(n),used(n){}
    bimatch(undigraph<int> &g):n(g.n),G(n),match(n),used(n){rep(i, n)forg(gi, g[i])if(f<t)add(f,t);}
    bimatch(grid_k6<int> &g):n(g.n),G(n),match(n),used(n){rep(i, n)forg(gi, g[i])if(f<t)add(f,t);}
    void add(int u,int v)    {        G[u].push_back(v);        G[v].push_back(u);    }
    int solve()    {        int ans=0;        bool flag=true;        fill(match.begin(),match.end(),-1);        while(flag)        {            flag=false;            fill(used.begin(),used.end(),false);            for(int v=0;v<n;v++)if(match[v]<0&&dfs(v))ans++,flag=true;        }        return ans;    }//@formatter:on
