    bool used(edge<T> &e) { return usedv[e.id]; }
    bool used(int id) { return usedv[id]; }
    void del(edge<T> &e) { usedv[e.id] = usedv[e.id ^ 1] = 1; }
    void del(int id) { usedv[id] = usedv[id ^ 1] = 1; }
    void set_edges() {        if (sz(edges))return;        rep(i, n)fora(e, g[i])edges.push_back(e);    }
};
template<class T=int> class undigraph : public graph<T> {
public:
    using graph<T>::g;
    using graph<T>::n;
    using graph<T>::edges;
    using graph<T>::usedv;
    int eid = 0;
    undigraph(int n) : graph<T>(n) {}
    void add(int f, int t, T c = 1, int id = -1, int ty = -1) {
        if (!(0 <= f && f < n && 0 <= t && t < n)) {
            debugline("undigraph add");
            deb(f, t, c, id, ty);
            ole();
        }
        if (id == -1)id = eid, eid += 2;
        g[f].emplace_back(f, t, c, id, ty);
        g[t].emplace_back(t, f, c, id + 1, ty);
        edges.emplace_back(f, t, c, id, ty);
        edges.emplace_back(t, f, c, id + 1, ty);
    }
    void add(edge<T> &e) {        int f = e.f, t = e.t, ty = e.type;        T c = e.c;        add(f, t, c, ty);    }
    bool used(edge<T> &e) { return usedv[e.id]; }
    bool used(int id) { return usedv[id]; }
    void del(edge<T> &e) { usedv[e.id] = usedv[e.id ^ 1] = 1; }
    void del(int id) { usedv[id] = usedv[id ^ 1] = 1; }
    void set_edges() {        if (sz(edges))return;        rep(i, n)fora(e, g[i])edges.push_back(e);    }
};
template<typename T> struct radixheap {    vector<pair<u64, T> > v[65];    u64 size, last;    radixheap() : size(0), last(0) {}    bool empty() const { return size == 0; }    inline int getbit(int a) { return a ? 64 - __builtin_clzll(a) : 0; }    void push(u64 key, const T &value) {        ++size;        v[getbit(key ^ last)].emplace_back(key, value);    }    pair<u64, T> pop() {        if (v[0].empty()) {            int idx = 1;            while (v[idx].empty()) ++idx;            last = min_element(begin(v[idx]), end(v[idx]))->first;            for (auto &p : v[idx]) v[getbit(p.first ^ last)].emplace_back(p);            v[idx].clear();        }        --size;        auto ret = v[0].back();        v[0].pop_back();        return ret;    }};
//radiq_heap
vi dijkstra2(const graph<int> &g, int s, int cant_arrive = -1) {    if (!(0 <= s && s < g.n)) {        debugline("dijkstra");        deb(s, g.n);        ole();    }    int initValue = MAX(int);    vi dis(g.n, initValue);    radixheap<int> q;    dis[s] = 0;    q.push(0, s);    while (!q.empty()) {        int nowc, i;        tie(nowc, i) = q.pop();        if (dis[i] != nowc)continue;        for (auto &&e  : g.g[i]) {            int to = e.t;            int c = nowc + e.c;            if (dis[to] > c) {                dis[to] = c;                q.push(dis[to], to);            }        }    }    /*基本、たどり着かないなら-1*/    if (cant_arrive == -1)for (auto &&d :dis) if (d == initValue)d = -1;    return dis;}
//priority_queue
template<class T> vector<T> dijkstra(const graph<T> &g, int s, int cant_arrive = -1) {    if (!(0 <= s && s < g.n)) {        debugline("dijkstra");        deb(s, g.n);        ole();    }    T initValue = MAX(T);    vector<T> dis(g.n, initValue);    priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> q;    dis[s] = 0;    q.emplace(0, s);    while (q.size()) {        T nowc = q.top().fi;        int i = q.top().se;        q.pop();        if (dis[i] != nowc)continue;        for (auto &&e  : g.g[i]) {            int to = e.t;            T c = nowc + e.c;            if (dis[to] > c) {                dis[to] = c;                q.emplace(dis[to], to);            }        }    }    /*基本、たどり着かないなら-1*/    if (cant_arrive == -1)for (auto &&d :dis) if (d == initValue)d = -1;    return dis;}
template<class T> vector<vector<T>> warshall(const graph<T> &g, int cant_arrive = -1) {    int n = g.n;    vector<vector<T> > dis(n, vector<T>(n, linf));    rep(i, n)fora(e, g.g[i])chmi(dis[e.f][e.t], e.c);    rep(i, n)dis[i][i] = 0;    rep(k, n)rep(i, n)rep(j, n)chmi(dis[i][j], dis[i][k] + dis[k][j]);    /*基本、たどり着かないなら-1*/    if (cant_arrive == -1)rep(i, n)rep(j, n) if (dis[i][j] == linf)dis[i][j] = -1;    return dis;}
template<class T=int> class tree : public undigraph<T> {public:    using undigraph<T>::g;    using undigraph<T>::n;    using undigraph<T>::edges;    using undigraph<T>::usedv;    vi disv;private:    bool never = 1;    int root = -1;    vi dep;/*到着した順の深さ*/    vi vis;/*到着した順*/    vi first;/*初めてiに到着した時*/    vector<int> bestt;/*タイミングを持つ*/    int sn = 0;/*seg木の底辺の長さ euler tourの長さ*/    void built() {        never = 0;        n = g.size();        /*euler tour*/        disv.resize(n);        first.resize(n);        dep.resize(n * 2);        vis.resize(n * 2);        function<void(int, int, int, int &)> dfs = [&](int i, int p, int d, int &k) {            first[i] = k;            vis[k] = i;            dep[k++] = d;            forg(gi, g[i]) {                if (t == p)continue;                disv[t] = disv[i] + c;                dfs(t, i, d + 1, k);                vis[k] = i;                dep[k++] = d;            }        };        int k = 0;        dfs(root, -1, 0, k);        /*rmq*/        sn = 1;        while (sn < n * 2)sn <<= 1;        bestt.resize((sn << 1) - 1);        rep(i, k)bestt[i + sn - 1] = i;/*時間を持つ*/        rer(i, sn - 2) {            int lt = (i << 1) + 1, rt = (i << 1) + 2;            if (dep[bestt[lt]] < dep[bestt[rt]]) {                bestt[i] = bestt[lt];            } else {                bestt[i] = bestt[rt];            }        }    }    /*最小の深さを持つタイミングが知りたい*/    inline int lca_rmq(int l, int r) {        int midv = inf;        int midi = -1;        l += sn - 1;        r += sn - 1;        while (l < r) {            /*右なら、次に右上へ移動してしまうので*/            if (!(l & 1)) {                if (chmi(midv, dep[bestt[l]])) {                    midi = bestt[l];                }            }            /*右なら、左を取らないと機会を逃す*/            if (!(r & 1)) {                if (chmi(midv, dep[bestt[r - 1]])) {                    midi = bestt[r - 1];                }            }            l >>= 1;            r = (r - 1) >> 1;        }        return vis[midi];    }public:    tree(int n, int root = 0) : undigraph<T>(n), root(root) {}    bool leaf(int v) {        return sz(g[v]) == 1 && v != root;    }    int lca(int u, int v) {        if (never)built();        if (first[u] > first[v])swap(u, v);        return lca_rmq(first[u], first[v] + 1);    }    int dis(int u, int v) {        if (never) built();        if (first[u] > first[v])swap(u, v);        int p = lca_rmq(first[u], first[v] + 1);        return disv[u] + disv[v] - disv[p] * 2;    }};
