vector<fedge> fg[MAX_V];
int level[MAX_V];
int iter[MAX_V];

void addEdge(int from, int to, int cap = 1) {
    fg[from].eb(to, cap, fg[to].size());
    fg[to].eb(from, 0, fg[from].size() - 1);
}
void addEdge_(digraph<int> &g) {
    rep(i, g.n) {
        forg(gi, g[i]) {
            fg[f].eb(t, c, fg[t].size());
            fg[t].eb(f, 0, fg[f].size() - 1);
        }
    }
}
void addEdge_(undigraph<int> &g) {
    rep(i, g.n) {
        forg(gi, g[i]) {
            if (f > t)con;
            fg[f].eb(t, c, fg[t].size());
            fg[t].eb(f, c, fg[f].size() - 1);
        }
    }
}
void unaddEdge(int from, int to, int cap = 1) {
    fg[from].eb(to, cap, fg[to].size());
    fg[to].eb(from, cap, fg[from].size() - 1);
}
bool fbfs(int s, int t) {
    memset(level, -1, sizeof(level));
    queue<int> que;
    level[s] = 0;
    que.push(s);
    while (!que.empty() && level[t] < 0) {
        int v = que.front();
        que.pop();
        for (int i = 0; i < fg[v].size(); i++) {
            fedge &e = fg[v][i];
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
    return level[t] != -1;
}
int fdfs(int v, int t, int f) {
    if (v == t) return f;
    for (int &i = iter[v]; i < fg[v].size(); i++) {
        fedge &e = fg[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = fdfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                fg[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}
