int maxflow(int s, int t) {
    int flow = 0;
    while (fbfs(s, t)) {
        memset(iter, 0, sizeof(iter));
        int f;
        while ((f = fdfs(s, t, inf)) > 0) { flow += f; }
    }
    return flow;
}
