struct HopcroftKarp {
  vector< vector< int > > graph;
  vector< int > dist, match;
  vector< bool > used, vv, used2;

  HopcroftKarp(int n, int m) : graph(n), match(m, -1), used(n), used2(m) {}

  void add_edge(int u, int v) {
    graph[u].push_back(v);
  }

  void bfs() {
    dist.assign(graph.size(), -1);
    queue< int > que;
    for(int i = 0; i < graph.size(); i++) {
      if(!used[i]) {
        que.emplace(i);
        dist[i] = 0;
      }
    }

    while(!que.empty()) {
      int a = que.front();
      que.pop();
      for(auto &b : graph[a]) {
        int c = match[b];
        if(c >= 0 && dist[c] == -1) {
          dist[c] = dist[a] + 1;
          que.emplace(c);
        }
      }
    }
  }

  bool dfs(int a) {
    vv[a] = true;
    for(auto &b : graph[a]) {
      int c = match[b];
      if(c < 0 || (!vv[c] && dist[c] == dist[a] + 1 && dfs(c))) {
        match[b] = a;
        used[a] = true;
        used2[b] = true;
        return (true);
      }
    }
    return (false);
  }

  int bipartite_matching() {
    int ret = 0;
    while(true) {
      bfs();
      vv.assign(graph.size(), false);
      int flow = 0;
      for(int i = 0; i < graph.size(); i++) {
        if(!used[i] && dfs(i)) ++flow;
      }
      if(flow == 0) return (ret);
      ret += flow;
    }
  }

  void output() {
    for(int i = 0; i < match.size(); i++) {
      if(~match[i]) {
        cout << match[i] << "-" << i << endl;
      }
    }
  }
};


signed main(){
    CIN(n);
    VC1(n,a);
    sort(ALL(a));
    map<int,vector<int>> m;
    REP(i,n)
        m[a[i]].push_back(i);

    vector<vector<int>> edges(n);

    for(ll i = 1LL << 32; i; i >>= 1){
        for(int j = 0; j < n; ++j){
            if(i <= a[j])
                break;
            for(auto& xx : m[i - a[j]]){
                if(a[xx] == a[j])
                    continue;
                edges[j].push_back(xx);
            }
        }
    }
    vector<int> col(n, -1);

    function<void(int,int)> f = [&](int x, int c){
        for(auto& y : edges[x]){
            if(col[y] == -1){
                col[y] = c;
                f(y, c ^ 1);
            }
        }
    };

    REP(i,n){
        if(col[i] == -1){
            col[i] = 0;
            f(i, 1);
        }
    }
    V c0, c1;
    REP(i,n){
        (col[i] ? c1 : c0).emplace_back(i);
    }
    V rev(n);
    REP(i,c0.size()){
        rev[c0[i]]=i;
    }
    REP(i,c1.size()){
        rev[c1[i]]=i;
    }

    HopcroftKarp h(c0.size(), c1.size());
    REP(i,n){
        FOREACH(xx, edges[i]){
            if(col[i] != col[xx]){
                h.add_edge(rev[i], rev[xx]);
            }
        }
    }

    int ans = h.bipartite_matching();

    M z;
    REP(i,h.used.size()){
        if(!h.used[i]){
            ++z[a[c0[i]]];
        }
    }
    REP(i,h.used2.size()){
        if(!h.used2[i]){
            ++z[a[c1[i]]];
        }
    }
    FOREACH(xx, z){
        if(__builtin_popcount(xx.first) == 1){
            ans += xx.second / 2;
        }
    }

    COUT(ans);

}

