int update(int idx, int num, int orig) {
    num /= 2;
    long long pwr = 1;
    while (pwr <= num)
        pwr <<= 1;
    while (pwr <= (1 << 30)) {
        // fprintf(stderr, "Here with pwr = %d\n", pwr);
        int match = (int)(pwr - 1) ^ num;
        if (have[idx].find(match) != have[idx].end()) {
            if (have[idx][match] > 0) {
                have[idx][match]--;
                // fprintf(stderr, "Matched %d.\n", orig);
                return 1;
            }
        }
        pwr <<= 1;
    }
    have[idx][num]++;
    return 0;
}

