#include <bits/stdc++.h>
using namespace std;
using ll = long long;
constexpr int N = 1e5+5;
struct FlowEdge {
    int v, u;
    ll cap, flow = 0;
    FlowEdge(int v, int u, ll cap) : v(v), u(u), cap(cap) {}
};
struct Dinic {
    const ll flow_inf = 1e18;
    vector<FlowEdge> edges;
    vector<vector<int>> adj;
    int n, m = 0;
    int s, t;
    vector<int> level, ptr;
    queue<int> q;
    Dinic(int n, int s, int t) : n(n), s(s), t(t) {
        adj.resize(n);
        level.resize(n);
        ptr.resize(n);
    }
    void add_edge(int v, int u, ll cap) {
        edges.emplace_back(v, u, cap);
        edges.emplace_back(u, v, 0);
        adj[v].push_back(m);
        adj[u].push_back(m + 1);
        m += 2;
    }
    bool bfs() {
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int id : adj[v]) {
                if (edges[id].cap - edges[id].flow < 1)
                    continue;
                if (level[edges[id].u] != -1)
                    continue;
                level[edges[id].u] = level[v] + 1;
                q.push(edges[id].u);
            }
        }
        return level[t] != -1;
    }
    ll dfs(int v, ll pushed) {
        if (pushed == 0)
            return 0;
        if (v == t)
            return pushed;
        for (int& cid = ptr[v]; cid < (int)adj[v].size(); cid++) {
            int id = adj[v][cid];
            int u = edges[id].u;
            if (level[v] + 1 != level[u] || edges[id].cap - edges[id].flow < 1)
                continue;
            ll tr = dfs(u, min(pushed, edges[id].cap - edges[id].flow));
            if (tr == 0)
                continue;
            edges[id].flow += tr;
            edges[id ^ 1].flow -= tr;
            return tr;
        }
        return 0;
    }
    ll flow() {
        ll f = 0;
        while (true) {
            fill(level.begin(), level.end(), -1);
            level[s] = 0;
            q.push(s);
            if (!bfs())
                break;
            fill(ptr.begin(), ptr.end(), 0);
            while (ll pushed = dfs(s, flow_inf)) {
                f += pushed;
            }
        }
        return f;
    }
};
int n, col[N];
unordered_map<int,vector<int>> mp;
vector<int> adj[N];
void dfs(int u, int c=0) {
    col[u]=c;
    for(int v : adj[u]) {
        if(col[v]==c) assert(false);
        if(col[v]!=-1) continue;
        dfs(v,c^1);
    }
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    memset(col, -1, sizeof col);
    cin >> n;
    vector<ll> pws;
    ll now = 1;
    for(int i = 0; i < 30; i++) {
        pws.push_back(now);
        now=now*2;
    }
    for(int i = 0; i < n; i++) {
        int x;
        cin >> x;
        for(ll pw : pws) {
            if(pw<=x) continue;
            for(int other : mp[pw-x]) {
                adj[other].push_back(i+1);
                adj[i+1].push_back(other);
            }
        }
        mp[x].push_back(i+1);
    }
    for(int i = 1; i <= n; i++) {
        if(col[i]==-1) dfs(i);
    }
    Dinic d(n+2,0,n+1);
    for(int i = 1; i <= n; i++) {
        if(col[i]==0) {
            d.add_edge(0,i,1);
            for(int v : adj[i]) {
                assert(col[v]==1);
                d.add_edge(i,v,1);
            }
        }
        else {
            d.add_edge(i,n+1,1);
        }
    }
    int ans=d.flow();
    cout << ans;
    return 0;
}

