void addE(int u,int v)
{
	edge[++id] = (Edge){v,first[u]};
	first[u] = id;
}

void dfs(int now)
{
	mark[now] = true;
	for (int i = first[now];i;i = edge[i].next)
		if (!mark[edge[i].to])
		{
			dfs(edge[i].to);
			int val = min(v[edge[i].to].second,v[now].second);
			v[edge[i].to].second -= val;
			v[now].second -= val;
			ans += val;
		}
}

