    REP(i,n)
        m[a[i]].push_back(i);

    vector<vector<int>> edges(n);

    for(ll i = 1LL << 32; i; i >>= 1){
        for(int j = 0; j < n; ++j){
            if(i <= a[j])
                break;
            for(auto& xx : m[i - a[j]]){
                if(a[xx] == a[j])
                    continue;
                edges[j].push_back(xx);
            }
        }
    }
    vector<int> col(n, -1);

    function<void(int,int)> f = [&](int x, int c){
        for(auto& y : edges[x]){
            assert(col[y] != (c ^ 1));
            if(col[y] == -1){
                col[y] = c;
                f(y, c ^ 1);
            }
        }
    };

    REP(i,n){
        if(col[i] == -1){
            col[i] = 0;
            f(i, 1);
        }
    }
    V c0, c1;
    REP(i,n){
        (col[i] ? c1 : c0).emplace_back(i);
    }
    V rev(n);
    REP(i,c0.size()){
        rev[c0[i]]=i;
    }
    REP(i,c1.size()){
        rev[c1[i]]=i;
    }

    HopcroftKarp h(c0.size(), c1.size());
    REP(i,n){
        FOREACH(xx, edges[i]){
            if(col[i] != col[xx]){
                h.add_edge(rev[i], rev[xx]);
            }
        }
    }

    int ans = h.bipartite_matching();

    M z;
    REP(i,h.used.size()){
        if(!h.used[i]){
            ++z[a[c0[i]]];
        }
    }
    REP(i,h.used2.size()){
        if(!h.used2[i]){
            ++z[a[c1[i]]];
        }
    }
    FOREACH(xx, z){
        if(__builtin_popcount(xx.first) == 1){
            ans += xx.second / 2;
        }
    }

    COUT(ans);

}

