  for (ll i = N - 1; i >= 1; i--) {
    if (used[i]) {
      continue;
    }

    ll t = 0;
    ll a_tmp = A[i];
    while (a_tmp >= 1) {
      t++;
      a_tmp /= 2;
    }
    ll target = pow(2LL, t) - A[i];
    if (binary_search(A.begin(), A.end() - (N - i), target)) {
      ans++;
      used[lower_bound(A.begin(), A.end() - (N - i), target) - A.begin()] =
          true;
    }
  }

  cout << ans << endl;
  return 0;
}

