using namespace std;

using graph=vector<vector<int>>;

void add_edge(graph& G,int u,int v){
	G[u].emplace_back(v);
	G[v].emplace_back(u);
}

graph G;
vector<int> wt;

map<tuple<int,int,int>,int> memo;

// u: 注目している頂点
// p: u の親
// k: 次に調べる子が G[u][k]
// used: これまでに u をマッチングに使った回数
// one: u が 1 に対応する頂点かどうか
int dfs(int u,int p,int k,int used,bool one){
	if(memo.count(make_tuple(u,k,used))>0) memo[make_tuple(u,k,used)];

	int& res=memo[make_tuple(u,k,used)];

	if((p==-1 && k==G[u].size())
	|| (p!=-1 && k==G[u].size()-1)){
		return res=(one?(wt[u]-used)/2:0);
	}

	int v=G[u][k];
	if(v==p) return res=dfs(u,p,k+1,used,one);

	res=0;
	rep(x,min(wt[u]-used,wt[v])+1){ // u と v を x 回マッチングする
		res=max(res,dfs(v,u,0,x,false)+dfs(u,p,k+1,used+x,one)+x);
	}
	return res;
}

int solve_odd(vector<int> a){
	vector<int> X=a;
	sort(X.begin(),X.end());
	X.erase(unique(X.begin(),X.end()),X.end());

	int n=X.size();
	G.assign(n,{});
	wt.assign(n,0);
	for(int x:a){
		int u=lower_bound(X.begin(),X.end(),x)-X.begin();

		for(int t=0;t<31;t++){
			if(binary_search(X.begin(),X.end(),(1<<t)-x)){
				int v=lower_bound(X.begin(),X.end(),(1<<t)-x)-X.begin();
				if(u<v) add_edge(G,u,v);
			}
		}
		wt[u]++;
	}

	memo.clear();
	int res=0;
	rep(u,n) if(memo.count(make_tuple(u,0,0))==0) res+=dfs(u,-1,0,0,X[u]==1);
	return res;
}

int solve(vector<int> a){
	vector<int> E,O;
	for(int x:a){
		if(x%2==0) E.emplace_back(x/2);
		else       O.emplace_back(x);
	}
	return (E.empty()?0:solve(E))+(O.empty()?0:solve_odd(O));
}

