const int SQRT = BUCK+9;

const int alpha = 32;

ll a[N];
int cnt[N], ps_cnt[N];
map < ll, int > mapp;
vll arr;
vi v[N];
ll p2[N];
int deg[N];
set < int > temp;
set < pii > st;

void solve()
{
	int n, i, j, ans = 0, val;
	pii z;
	p2[0] = 1;
	fo(i,1,alpha+1)
		p2[i] = p2[i-1]+p2[i-1];
	cin >> n;
	fo(i,1,n+1)
	{
		cin >> a[i];
		temp.insert(a[i]);
	}
	arr.pb(0);
	for(auto x : temp)
		arr.pb(x);
	fo(i,1,sz(arr))
		mapp[arr[i]] = i;
	fo(i,1,n+1)
		cnt[mapp[a[i]]]++;

	n = sz(arr)-1;
	// fo(i,1,n+1)
		// cout << i << " : " << arr[i] << " : " << cnt[i] << '\n';
	fo(i,1,n+1)
		if((arr[i]&(arr[i]-1LL)) == 0LL)
		{
			ps_cnt[i] = cnt[i];
			cnt[i] = 0;
		}
	fo(i,1,n+1)
		fo(j,0,alpha+1)
			if(mapp[p2[j]-arr[i]] && p2[j]-arr[i] != arr[i])
				v[i].pb(mapp[p2[j]-arr[i]]);
	// fo(i,1,n+1)
