	// 	cout << arr[i] << " : ";
	// 	for(auto x : v[i])
	// 		cout << arr[x] << " ";
	// 	cout << '\n';
	// }
	fo(i,1,n+1)
		deg[i] = sz(v[i]);
	fo(i,1,n+1)
		st.insert({deg[i],i});

	while(!st.empty())
	{
		z = *st.begin();
		if(z.F > n)
			break;
		st.erase({deg[z.S],z.S});
		deg[z.S] = INF;
		st.insert({deg[z.S],z.S});
		for(auto x : v[z.S])
		{
			val = min(cnt[x],cnt[z.S]);
			ans += val;
			cnt[x] -= val;
			cnt[z.S] -= val;
			st.erase({deg[x],x});
			deg[x] = INF;
			st.insert({deg[x],x});
		}
	}
	fo(i,1,n+1)
		if(ps_cnt[i] != 0)
			cnt[i] = ps_cnt[i];
	fo(i,1,n+1)
		deg[i] = sz(v[i]);
	fo(i,1,n+1)
		st.insert({deg[i],i});

	while(!st.empty())
	{
		z = *st.begin();
		if(z.F > n)
			break;
		st.erase({deg[z.S],z.S});
		deg[z.S] = INF;
		st.insert({deg[z.S],z.S});
		for(auto x : v[z.S])
		{
			val = min(cnt[x],cnt[z.S]);
			ans += val;
			cnt[x] -= val;
			cnt[z.S] -= val;
			st.erase({deg[x],x});
			deg[x] = INF;
			st.insert({deg[x],x});
		}
	}
	fo(i,1,n+1)
		if(cnt[i] > 0 && (arr[i]&(arr[i]-1LL)) == 0LL)
			ans += (cnt[i]/2);
	cout << ans << '\n';
	return;
}

