long long int max, c = 0;
int max_i, pair_i, n = 0;

void solve(int x) {
  max = 0;
  max_i = 0;
  pair_i = -1;
  for (int i = 0; i < x; i++) {
    if (max < p[i]) {
      max = p[i];
      max_i = i;
    }
  }
  for (int i = 0; i < x; i++) {
    if (i != max_i && !((p[i] + max) & (p[i] + max - 1))) {
      pair_i = i;
      c += 1;
    }
  }
  for (int i = 0; i <= x; i++) {
    if (i > max_i) {
      p[i - 1] = p[i];
    }
  }
  if (pair_i > max_i) {
    pair_i -= 1;
  }
  if (pair_i != -1) {
    for (int i = 0; i < x; i++) {
      if (i > pair_i) {
        p[i - 1] = p[i];
      }
    }
    solve(x - 2);
  } else {
    if (x > 0) {
      solve(x - 1);
    }
  }
}

