int modinv(int a,int m){
  int b=m,u=1,v=0;
  while(b){
    int t=a/b;
    a-=t*b;
    swap(a,b);
    u-=t*v;
    swap(u,v);
  }
  u%=m;
  if(u<0)
    u+=m;
  return u;
}
