ll power(ll a,ll b)
{
    ll res = 1;
    while(b != 0)
    {
        if(b & 1)
            res = (res * a);
        a = (a * a);
        b /= 2;
    }
    return res;
}
int main() 
{ 
	map <ll, ll> m, tm;
	ll n, cnt = 0, val, x;
	cin >> n;
	for (int i = 0; i < n; ++i)
	{
		cin >> x;
		m[x]++;
		tm[x]++;
	}
	for (int i = 58; i >= 1; --i)
	{
		val = power(2, i);
		for (auto g : m)
		{
			if(g.ff <= val)
			{
				if(2 * g.ff == val)
				{
					cnt += tm[g.ff] / 2;
					tm[g.ff] -= tm[g.ff] / 2;
				}
				else
				{
					ll pp = val - g.ff, tmp;
					tmp = min(tm[g.ff], tm[pp]);
					cnt += tmp;
					tm[g.ff] -= tmp;
					tm[pp] -= tmp;
				}
			}
		}
	}
	cout << cnt;
}

