static const double PI = 3.14159265358979;
static const ll MOD = 1e9 + 7;
static const ll INF = (ll)1 << 62;

static const int bn = 32;
ll n;
ll b[bn] = {};
vector<int> a(200001);
bool use[200001] = {};
ll total = 0;
void init() {
	repe(i, 0, bn) {
		ll j = i;
		ll m = 1;
		while (j--) {
			m *= 2;
		}
		b[i] = m;
	}
	reverse(b, b + bn);

	rep(i, 0, n)use[i] = false;
}

bool bs(int x) {
	if (binary_search(a.begin(), a.begin() + n, x)) {
		vector<int>::iterator p = lower_bound(a.begin(), a.begin() + n, x);
		if (!use[p - a.begin()]) {
			use[p - a.begin()] = true;
			return true;
		}
	}
	return false;
}

int main() {
	cin >> n;
	init();

	rep(i, 0, n) cin >> a[i];
	sort(a.begin(), a.begin() + n);

	ll cnt = 0;

	for (int i = n - 1; i >= 0; i--) {
		if (use[i])continue;

		rep(j, 0, bn) {
			ll t = b[j] - a[i];
			if (t < 0)continue;

			use[i] = true;
			if (bs(t)) {
				total++;
			}
			else {
				use[i] = false;
			}
		}
	}

	cout << total << endl;

	return 0;
}

