    long t = 1;
    while(t<=a[i]) t <<= 1;
    long ser = t - a[i];
    int bs = bsearch(0,i-1,a,ser);
    if(bs==-1) continue;
    count ++;
    a[bs] = -1;
  }
  cout << count << endl;
  return 0;
}

