const double PI = acos(-1.0);
const LL INF = 1e9;
const LL LINF = INF * INF;

const int MAX = 1 << 18;
int n;
int a[MAX];
map<int, int> mp;
vector<int> g[MAX];
int ans = 0;
char U[MAX];

void dfs(int v, int p = -1)
{
	U[v] = 1;
	for(auto i: g[v])
		dfs(i, v);

	if (p == -1)
	{
		if (__builtin_popcount(a[v]) == 1)
			ans += mp[a[v]] / 2;
		return;
	}

	int tut = mp[a[v]];
	int tam = mp[a[p]];

	if (tut <= tam)
	{
		ans += tut;
		mp[a[p]] -= tut;
		return;
	}

	if (__builtin_popcount(a[v]) > 1)
	{
		ans += tam;
		mp[a[p]] = 0;
		return;
	}

	if (tam == 0)
	{
		ans += tut / 2;
		return;
	}

	int she = tut - tam;
	if (she % 2 == 0)
	{
		ans += (tut + tam) / 2;
		mp[a[p]] = 0;
		return;
	}

	ans += tam / 2;
	mp[a[p]] = 1;

	tut -= tam - 1;
	ans += tut / 2;
}

