{
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	//freopen("In.txt", "r", stdin);
	//freopen("Out.txt", "w", stdout);

	cin >> n;
	FOR(i, 0, n)
	{
		cin >> a[i];
		mp[a[i]]++;
	}

	sort(a, a + n);	
	FOR(i, 0, n)
	{
		if (i && a[i] == a[i - 1])
			continue;

		FOR(j, 2, 31)
		{
			if (a[i] >= (1 << (j - 1)))
				continue;

			auto it = lower_bound(a, a + n, (1 << j) - a[i]) - a;
			if (a[it] + a[i] != (1 << j))
				continue;

			g[i].PB(it);
		}
	}

	FOR(i, 0, n)
	{
		if (i && a[i] == a[i - 1])
			continue;
		if (U[i])
			continue;
		dfs(i);
	}	

	cout << ans << endl;
	cerr << "Time elapsed: " << clock() / (double)CLOCKS_PER_SEC << endl;
	return 0;
}

