	for (int i = 0; i < edges[s].size();i++) {
		int to = edges[s][i];
		if (label[to]==0) {
			label[to] = label[s] % 2 + 1;
			if (label[s]==1) {
				NetworkFlow::AddEdge(s, to, 1);
			}
			else {
				NetworkFlow::AddEdge( to,s, 1);
			}			
			labeling(to);
		}
	}
}
