void dfs(int k, bool f){  // f:始点である
    if(f && cnt[a[k]]==0)return;
    //cout << a[k] << endl;
    if(cnt[a[k]]>0)f = true;
    for(auto to : g[k]){
        if(cnt[a[to]]==0)continue;
        if(deg[to]>1)continue;
        if(f){
            ll m = min(cnt[a[k]],cnt[a[to]]);
            ans+=m;
            cnt[a[k]] -= m;
            cnt[a[to]] -= m;
            deg[k]--;
            deg[to]--;
            dfs(to,false);
            if(cnt[a[k]]==0) f = false;
        }
        else{
            dfs(to,true);
        }
    }
    return;
}

