            while(b<a[i]*2)b*=2;
            while(b-a[i]<=a[n-1]){
                int k = lower_bound(a,a+n,b-a[i])-a;
                if(a[i]+a[k]==b && i!=k){
                    g[i].push_back(k);
                    g[k].push_back(i);
                    deg[i]++;
                    deg[k]++;
                }
                b*=2;
            }

        }
