int my_pow(int x, int n){
  if (n == 0){
    return 1;
  } else {
    return x * my_pow(x, n-1);
  }
}

int two_power(int m){
  if (m < 2){
    return 0;
  } else {
    return two_power(m/2) + 1;
  }
}

int binary_search(std::vector<int> ary, int key, int imin, int imax) {
    if (imax < imin) {
        return -1;
    } else {
        int imid = imin + (imax - imin) / 2;
        if (ary[imid] < key) {
            return binary_search(ary, key, imin, imid - 1);
        } else if (ary[imid] > key) {
            return binary_search(ary, key, imid + 1, imax);
        } else {
            return imid;
        }
    }
}

