        ans+=(j-i)/2;
        if ((j-i)&1)
            mp[a[i]]=++N;
    }
    for (auto p:mp)
        for (int b=0;b<31;++b)
        {
            LL c=(1LL<<b)-p.first;
            if (p.first<=c)   continue;
            if (mp.count(c))
                join(p.second,mp[c]);
        }
}

