        cin >> v;
//    N = 5;
//    A = {16, 16, 16, 16, 16};
}

ll solve() {
    sort(A.begin(), A.end());
    unordered_map<ll, int> fmap;
    map<ll, ll> ocmap;
    for (ll i = 0; i < N; i++) {
        auto a = A[i];
        if (fmap.find(a) == fmap.end()) {
            fmap[a] = 1;
        } else {
            fmap[a]++;
        }
        for (int k = 31; (1U << k) > a; k--) {
            auto tag = (1U << k) - a;
            ocmap[tag]++;
        }
    }

    vector<P> cmap;
    for (auto m : ocmap) {
        cmap.emplace_back(m);
    }
    sort(cmap.begin(), cmap.end(), [](auto l, auto r) {
        return l.second < r.second;
    });
    unordered_map<ll, ll> cmapi;
    for (ll i = 0; i < cmap.size(); i++) {
        cmapi[cmap[i].first] = i;
    }

    ll ans = 0;
    for (ll i = 0; i < cmap.size(); i++) {
        auto n = cmap[i].first;
        if (fmap.find(n) == fmap.end() || fmap[n] <= 0)
            continue;

        ll min_v = 99999;
        ll min_n = 0;
        for (int k = 31; (1U << k) > n; k--) {
            auto tag = (1U << k) - n;
            if (fmap.find(tag) == fmap.end() ||
                fmap[tag] <= (tag == n ? 1 : 0))
                continue;
            auto tm = cmap[cmapi[tag]];
            if (tm.second < min_v) {
                min_v = tm.second;
                min_n = tag;
            }
        }
        if (min_n != 0) {
            ans++;
            fmap[min_n]--;
            fmap[n]--;
            i--;
        }
    }
    return ans;
}


int main() {
    input();
    cout << solve() << endl;;

    return 0;
}

