  for (long long int i = 0; i < n; i++) {
    scanf("%lld", &p[i]);
  }
  for (long long int i = 0; i < n; i++) {
    p[i] *= 2;
  }
  quickSort(p, n);
  solve(n);
  printf("%lld\n", c);

  return 0;
}

