             return i;
        }else{
            i *= 2;
        }
    }
}
bool isBi(ll x){
    for(int i = 0; i <50; i++){
        if(x == (1ll << i)){
            return true;
        }
    }
    return false;
}

int main() {
    ll N;
    cin >> N;
    vector<ll> A(N);
    ll count = 0;
    bool used[N];
    for(int i = 0; i < N; i++){
        cin >> A[i];
        used[i] = false;
    }
    sort(A.begin(),A.end());
    for (int i = 0; i < N; ++i) {
        ll currentX = A[N - i -1];
        if(used[N - i - 1]){
            continue;
        }
        if(isBi(currentX)){
            if(N - i - 1 != 0 && A[N - i - 1] == A[N - i - 2]){
                used[N - i - 1] = true;
                used[N - i - 2] = true;
                count++;
            }
            continue;
        }
        ll Y = getMinBi(currentX) * 2;
        auto it = lower_bound(A.begin(), A.end(), Y - currentX);
        if(*it == Y-currentX){
            int index = it - A.begin();
            used[index] = true;
            used[N - i - 1] = true;
            count++;
        }
    }
    cout << count << endl;

}

