typedef long long int LL;

std::vector<std::vector<LL>>G;
std::vector<bool>vis;

LL dfs(LL v, bool flag)
{
	if (vis[v]) return 0;
	vis[v] = true;
	LL res = 0;
	bool exist = false;
	for (auto u : G[v])
	{
		if (!vis[u]) exist = true;
		res += dfs(u, !flag);
	}
	if (flag&&exist) ++res;
	return res;
}

int main()
{
	LL N;
	in >> N;
	std::vector<LL>A(N);
	rep(i, N) in >> A[i];

	std::sort(A.begin(), A.end());
	std::vector<LL>odd, even, rui(33);
	rep(i, N)
	{
		if (A[i] % 2 == 0) odd.push_back(A[i]);
		else even.push_back(A[i]);
	}
	rui[0] = 1;
	for (int i = 1; i <= 32; ++i) rui[i] = rui[i - 1] * 2;

	LL ans = 0;
	std::map<LL, LL>odd_cnt;
	for (auto i : odd) odd_cnt[i]++;
	for (auto i : odd_cnt)
	{
		auto it = std::lower_bound(rui.begin(), rui.end(), i.first * 2);
		if (it != rui.end())
		{
			if (*it == i.first * 2) ans += i.second / 2;
		}
	}

	G.resize(even.size());
	rep(i, even.size())
	{
		rep(j, rui.size())
		{
			auto it1 = std::lower_bound(even.begin(), even.end(), rui[j] - even[i]);
			auto it2 = std::upper_bound(even.begin(), even.end(), rui[j] - even[i]);
			for (auto it = it1; it < it2; ++it)
			{
				if (it - even.begin() == i) continue;
				G[i].push_back(it - even.begin());
			}
		}
	}

	vis.resize(even.size());
	rep(i, even.size())
	{
		if (!vis[i] && G[i].size() == 1)
		{
			auto temp = vis;
			LL res1 = dfs(i, true);
			vis = temp;
			LL res2 = dfs(i, false);
			ans += std::max(res1, res2);
		}
	}

	out << ans << std::endl;
	return 0;
}

