ll find_power(ll x){
	ll res = 1;
	while(1){
		if(res>x) break;
		res*=2;
	}
	return res - x;
}

int main()
{
	int n;
	cin >> n;
	vector<ll> a(n);
	for(int i = 0; i < n; i++){
		cin >> a[i];
	}
	sort(all(a));
	reverse(all(a));

	map<ll,ll> s;
	for(int i = 0; i < n; i++){
		s[a[i]]++;
	}
	int ans = 0;
	for(int i = 0; i < n; i++){
		if(s.find(a[i]) == s.end()) continue;
		ll x = find_power(a[i]);
		if(s.find(x) != s.end()){
			if(a[i] == x){
				if(s[x]>=2){
					ans++;
					s[x] -= 2;
				}
				if(s[a[i]] == 0) s.erase(a[i]);
			}else{
				ans++;
				s[a[i]]--;
				s[x]--;
				if(s[a[i]] == 0) s.erase(a[i]);
				if(s[x] == 0) s.erase(x);
			}
		}
	}
	cout << ans << endl;

	return 0;
}

