int bs(int x)
{
	int l = 1;
	int r = n;

	int pos = -1;

	while(l <= r)
	{
		int mid = (l + r) / 2;

		if(v[mid] > x)
			r = mid - 1;
		else
			if(v[mid] < x)
				l = mid + 1;
			else
			{
				pos = mid;
				r = mid - 1;
			}
	}

	return pos;
}

