namespace NetworkFlow {
	const int MAX_V = 200010;
	const int INF = 2000000000;
	struct edge {
		int to;//行先
		int capacity;//容量
		int reverse;//逆辺
	};

	vector<edge> G[MAX_V];
	bool used[MAX_V];

	void AddEdge(int from, int to, int capacity) {
		G[from].push_back(edge{ to, capacity, (int)G[to].size() });
		G[to].push_back(edge{ from,0,(int)G[from].size() - 1 });
	}

	int dfs(int v, int t, int f) {
		if (v == t) {
			return f;
		}
		used[v] = true;
		for (int i = 0; i < G[v].size(); i++) {
			edge &e = G[v][i];
			if (!used[e.to] && e.capacity > 0) {//使える辺を見つけたら
				int d = dfs(e.to, t, min(f, e.capacity));
				if (d > 0) {
					e.capacity -= d;
					G[e.to][e.reverse].capacity += d;
					return d;
				}
			}
		}
		return 0;
	}

	int max_flow(int s, int t) {
		int flow = 0;
		while (true) {
			memset(used, 0, sizeof(used));
			int f = dfs(s, t, INF);
			if (f == 0) {
				return flow;
			}
			else {
				flow += f;
			}
		}
	}
}


int main() {
	cin >> N;
	int mx = 0;
	for (int i = 0; i < N;i++) {
		cin >> a[i];
		mx = max(mx, a[i]);
	}
	sort(a, a + N);
	for (int i = 0; i < N; i++) {
		for (int j = 2; j <= mx * 2;j*=2) {
			for (int k = lower_bound(a, a + N, j - a[i]) - a; k < upper_bound(a, a + N, j - a[i]) - a; k++) {
				if (i!=k) {
					if (label[i] == 0) {
						label[i] = 1;
					}
					if (!checked[k]) {						
						if (label[i] == 1) {
							label[k] = 2;
							NetworkFlow::AddEdge(i, k, 1);
						}
						else {
							label[k] = 1;
							NetworkFlow::AddEdge(k, i, 1);
						}
					}
				}
			}
		}
		checked[i] = true;
	}

	for (int i = 0; i < N; i++) {
		if (label[i]==1) {
			NetworkFlow::AddEdge(N,i, 1);
		}
		else if (label[i]==2) {
			NetworkFlow::AddEdge(i, N+1, 1);
		}
	}
	cout << NetworkFlow::max_flow(N, N + 1);

	return 0;
}

