long long get_res(long long n) {
    long long tmp = 1;
    while ((tmp << 1) <= n) {
        tmp = (tmp << 1);
    }
    return n - tmp;
}

const int MAX_N = 200050;
int N;
long long A[MAX_N];

std::unordered_map<long long, int> mp;
std::vector<long long> vec;

int main(int argc, char **argv) {
    std::cin >> N;

    for (int i = 1; i <= N; i++) {
        std::cin >> A[i];
    }

    for (int i = 1; i <= N; i++) {
        vec.push_back(A[i]);
        if (mp.find(A[i]) == mp.end()) {
            mp[A[i]] = 1;
        } else {
            mp[A[i]] += 1;
        }
    }

    std::sort(vec.begin(), vec.end(), std::greater<long long>());

    int ret = 0;
    for (long long v : vec) {
        if (0 < mp[v]) {
            mp[v]--;
            long long res = get_res(v);
            long long cand = v - res * 2;
            if (mp.find(cand) != mp.end() && 0 < mp[cand]) {
                ret++;
                mp[cand]--;
            }
        }
    }

    std::cout << ret << std::endl;

    return 0;
}

