int N, A[200000];
vector<int> G[200000];
int match[200000];
bool used[200000];

bool dfs(int v) {
    used[v] = true;
    for (int u : G[v]) {
        int w = match[u];
        if (w < 0 || (!used[w] && dfs(w))) {
            match[v] = u;
            match[u] = v;
            return true;
        }
    }
    return false;
}

int bipartite_matching() {
    int ret = 0;
    REP(i, N) match[i] = -1;
    REP(v, N) {
        if (match[v] < 0) {
            REP(i, N) used[i] = false;
            if (dfs(v)) ret++;
        }
    }
    return ret;
}

int main() {
    cin >> N;
    REP(i, N) cin >> A[i];
    sort(A, A + N);

    REP(i, N) {
        ll p = 2;
        while (true) {
            if (p > 2e9) break;

            int rest = p - A[i];
            p <<= 1;
            if (rest < 1) continue;

            auto lb = lower_bound(A, A + N, rest);
            auto ub = upper_bound(A, A + N, rest);
            for (auto it = lb; it != ub; it++) {
                if (it - A == i) continue;
                G[i].push_back(it - A);
            }
        }
    }

    cout << bipartite_matching() << endl;
    return 0;
}

