class bipartite_matching {
public:
	int n;
	std::vector<std::vector<int>> g;
	std::vector<int> match;

	bipartite_matching(int n_) : n(n_), g(n_), match(n_), used(n_) {}

	void add_edge(int u, int v) {
		g[u].push_back(v);
		g[v].push_back(u);
	}

	int maximum_matching(void) {
		int res = 0;
		fill(begin(match), end(match), -1);
		for (int v = 0; v < n; ++v) {
			if (match[v] == -1) {
				fill(begin(used), end(used), false);
				if (dfs(v)) res++;
			}
		}
		return res;
	}

private:
	std::vector<int> used;
	bool dfs(int v) {
		used[v] = true;
		for (int u : g[v]) {
			int w = match[u];
			if (w == -1 || (!used[w] && dfs(w))) {
				match[v] = u;
				match[u] = v;
				return true;
			}
		}
		return false;
	}
};

