i64 compute_next(i64 v)
{
	assert(v > 0);
	for(int i = 61; i >= 0; --i) {
		if((1LL << i) & v) {
			return (1LL << (i + 1));
		}
	}
	return -1;
}

int main()
{
	int n;
	vector<i64> as;

	scanf("%d", &n);
	as.resize(n);
	for(int i = 0; i < n; ++i) {
		scanf("%lld", &as[i]);
	}

	sort(as.begin(), as.end());

	vector<pair<i64,int>> bs;

	for(int i = 0; i < n; ++i) {
		const i64 v = as[i];
		if(bs.size() > 0 && bs[bs.size() - 1].first == v) {
			bs[bs.size() - 1].second += 1;
		} else {
			bs.push_back({v, 1});
		}
	}

	int ans = 0;

	for(int it = bs.size() - 1; it >= 0; --it) {

		const i64 v = bs[it].first;
		const int c = bs[it].second;

		const i64 w = compute_next(v) - v;

		if(w > v) {
			continue;
		}

		if(w == v) {
			ans += c / 2;
			continue;
		}

		auto sv = make_pair(w, 0);
		int w_idx = lower_bound(bs.begin(), bs.end(), sv) - bs.begin();

		if(bs[w_idx].first != w) {
			continue;
		}

		int used = min(bs[w_idx].second, c);
		bs[w_idx].second -= used;
		ans += used;
	}

	printf("%d\n", ans);

	return 0;
}

