ll getPair(ll x, map<ll,ll>& cnt){
  if(pot.count(x) > 0) return -1;
  ll p = 1;
  while(p < x) p*=2;
  if(cnt.count(p-x) > 0) return p-x;
  return -1;
}

void calc(ll id){
  //cout << nmp[id] << endl;
  rep(i,G[id].size()){
    pair<ll,ll> tmp = G[id][i];
    if(tmp.second == -1) continue;
    //cout << " " << tmp.first << " " << tmp.second << endl;
    calc(tmp.first);
    if(Gc[id] > 0 && Gc[tmp.first] > 0){
      ll mn = min(Gc[id], Gc[tmp.first]);
      answer += mn;
      Gc[id] -= mn;
      Gc[tmp.first] -= mn;
    }
  }
}

ll solve(const vector<ll>& v){
  map<ll,ll> cnt;
  rep(i,v.size()){
    cnt[v[i]]++;
  }

  vector<ll> out(cnt.size(), 0);
  ll no = 0;
  FOR(it,cnt){
    ll id1 = no;
    mp[it->first] = id1;
    //nmp[id1] = it->first;
    Gc[id1] = it->second;

    //cout << "check: " << it->first << endl;
    ll tmp = getPair(it->first, cnt);
    if(tmp != -1){
      ll id2 = mp[tmp];
      //cout << " pair: " << nmp[id1] << " " << nmp[id2] << endl;
      G[id1].push_back(make_pair(id2,-1));
      G[id2].push_back(make_pair(id1,1));
      out[id1]++;
    }
    no++;
  }

  answer = 0;
  rep(i,out.size()){
    if(out[i] != 0) continue;
    calc(i);
  }
  return answer;
}


