const ll inf = 1e18;

int main() {
  ios::sync_with_stdio(false), cin.tie(0);
  int n; cin >> n;

  int a;
  vector<int> v;
  for(int i = 0; i < n; i++) cin >> a, v.emplace_back(a);
  auto w = v;
  uniq(v);
  auto mp = compress(v);

  int m = v.size();
  MaxFlow flow(m * 2 + 2, inf);
  int s = m * 2, t = m * 2 + 1;
  // BipartiteMatching tap(m * 2);
  vector<int> cnt(m);
  for(int i = 0; i < n; i++) cnt[mp[v[i]]]++;
  vector<int> ids(m);
  for(int i = 0; i < m; i++) {
    ids[i] = flow.addEdge(s, i, cnt[i]);
    flow.addEdge(i, t, cnt[i]);
  }

  for(int i = 0; i < m; i++) {
    for(int j = 2; j < (1 << 31); j <<= 1) {
      if(v[i] < j && (v[i] - j) >= 1) {
        int k = (i - j);
        if(mp.count(k)) {
          flow.addEdge(w[i], m + mp[k], inf);
        }
      }
    }
  }

  int ans = flow.build(s, t);
  ans /= 2;
  for(int i = 0; i < n; i++) {
    int rest = cnt[i] - flow.edges[ids[i]].cap;
    if(ispow2(v[i] + v[i])) {
      ans += rest / 2;
    }
  }
  cout << ans << endl;
  return 0;
}

