namespace fast_scanner {
    static char __ibuf__[1 << 20], *__p1__ = __ibuf__, *__p2__ = __ibuf__;
    bool advance() { return __p2__ = (__p1__ = __ibuf__) + fread(__ibuf__, 1, sizeof(__ibuf__), stdin), (__p1__ == __p2__); }
    char gc() { return (__p1__ == __p2__ && advance()) ? EOF : (*__p1__++); }
    static bool isspace(char c) { return static_cast<unsigned char>(c - '\t') < 5 || c == ' '; }
    static bool isdigit(char c) { return static_cast<unsigned char>(c - '0') < 10; }
    static inline bool isoneof(char c, const char *str) { return strchr(str, c) != nullptr; }
    template <const char *str> static inline bool isoneof(char c) { return strchr(str, c) != nullptr; }
    uint64_t read_ull() {
        char ch = gc();
        while (!isdigit(ch)) { ch = gc(); }
        uint64_t res = 0;
        while (isdigit(ch)) { res = res * 10 + (ch - '0'), ch = gc(); }
        return res;
    }
    int64_t read_ll() {
        char ch = gc();
        bool neg = false;
        while (!isdigit(ch)) { neg |= (ch == '-'), ch = gc(); }
        uint64_t res = 0;
        while (isdigit(ch)) { res = res * 10 + (ch - '0'), ch = gc(); }
        neg && (res = -res);
        return res;
    }
    long double read_ld() {
        char ch = gc();
        bool neg = false;
        while (!isdigit(ch)) { neg |= (ch == '-'), ch = gc(); }
        uint64_t integerPart = 0, fractionalPart = 0, len = 0, base = 1;
        while (isdigit(ch)) { integerPart = integerPart * 10 + (ch - '0'), ch = gc(); }
        if (ch == '.') {
            ch = gc();
            while (isdigit(ch)) { fractionalPart = fractionalPart * 10 + (ch - '0'), ch = gc(), len += 1; }
            while (len--) base *= 10;
        }
        long double res = (long double)integerPart + (long double)fractionalPart / base;
        neg && (res = -res);
        return res;
    }
    string read_delim(const char* str) {
        char ch = gc();
        while(isoneof(ch, str)) ch = gc();
        string res;
        while(!isoneof(ch, str)) res += ch, ch = gc();
        return res;
    }
    template<typename UnaryPredicate> string read_delim(UnaryPredicate predicate) {
        char ch = gc();
        while(predicate(ch)) ch = gc();
        string res;
        while(!predicate(ch)) res += ch, ch = gc();
        return res;
    }
    string read_line() { return read_delim([](char ch) { return ch == '\n'; }); }
    string read_string() { return read_delim(isspace); }
    char read_char() { return gc(); }
    int read_int() { return (int)read_ll();}
}
