    int N;
    cin >> N;

    for (int i = 0; i < N; ++i) {
        int n;
        cin >> n;
        A.push_back(n);
    }
    sort(A.begin(),A.end());

    find();
    reduce();

    cout << result << endl;


    return 0;
}

