struct s {
	int a;
	bool u;
	bool operator<(const s& o)const {
		if (a != o.a) {
			return a < o.a;
		}
		else {
			return u && !o.u;
		}
	}
};

int search(s *a, int s, int n) {
	int r = 0;
	if (a[0].a == s)return 0;
	for (int j = 30; j >= 0; j--) {
		int c = r + (1 << j);
		if (c >= n)continue;
		if (a[c].a == s && a[c - 1].a < s) {
			return c;
		}
		else if (a[c].a < s) {
			r = c;
		}
	}
	return -1;
}


int main() {
	int N;
	scanf("%d", &N);
	s *A = new s[N];
	for (int i = 0; i < N; i++) {
		scanf("%d", &A[i].a);
		A[i].u = false;
	}
	std::sort(A, A + N);
	int r = 0;
	for (int i = N - 1; i >= 0; i--) {
		if (A[i].u)continue;
		int p;
		for (int j = 0; j < 31; j++) {
			if ((1 << j) > A[i].a) {
				p = (1 << j) - A[i].a;
				break;
			}
		}
		int c = search(A, p, N);
		if (c != -1 && c != i) {
			while (A[c].u) {
				c++;
				if (A[c].a != p)break;
			}
			if (A[c].a == p && c != i)
				r++;
			A[c].u = true;
			A[i].u = true;
		}
	}
	printf("%d", r);
}

