    multiset<ll> st;
    for(int i=0; i<n; i++){
        cin>>a[i];
        st.insert(a[i]);
    }
    sort(a.begin(), a.end(), greater<ll>());

    int ans=0;
    for(int i=0; i<n; i++){
        for(ll num=2; num<=1e18; num*=2){
            if(a[i]<num/2) continue;
            ll x=num-a[i];
            if(x>a[i] || x<1) continue;
            st.erase(a[i]);

            auto itr=st.find(x);
            if(itr!=st.end()){
                //cout << a[i] << " " << x << endl;
                st.erase(x);
                ans++;
                break;
            }
            st.insert(a[i]);
        }
    }
    cout << ans << endl;
}

