        ll bit=1;
        while(bit<i.first)bit*=2;
        if(bit==i.first){
            ans+=i.second/2;
        }
        ll mn=min(i.second,m[bit-i.first]);
        ans+=mn;
        m[bit-i.first]-=mn;
    }
    out(ans);
}

