void solve(void)
{
  int P = 23;
  vector<int> pow_2;
  for (int i = 0; i <= P; i++)
  {
    pow_2.push_back(pow(2,i));
  }

  int N;cin>>N;
  set<int> SET;
  vector<int> vec(N);
  map<int,int> mp;
  for (int i = 0; i < N; i++)
  {
    int X;cin>>X;
    SET.insert(X);
    mp[X]++;
    vec[i] = X;
  }
  sort(ALL(vec));
  int ANS = 0;
  for (int i = N-1; i >= 0; i--) 
  {
    int X = vec[i];
    if(mp[X] <= 0)continue;
    mp[X]--;
    if(mp[X] <= 0)
    {
      SET.erase(X);
    }

    int T = *upper_bound(ALL(pow_2),X);
    T -= X;
    if(SET.find(T) != SET.end())
    {
      if(mp[T] <= 0)continue;

      ANS++;
      mp[T]--;
      if(mp[T] <= 0)
      SET.erase(SET.find(T));
    }
  }

  cout<<ANS<<endl; 
  return;
}
