vector<vector<int>> graph(200000);
vector<bool> done(200000);
vector<bool> used(200000);
void dfs(int v, int &cnt) {
    if (done.at(v)) return;

    done.at(v) = true;
    bool ok = false;
    for (int i = 0; i < (int)graph.at(v).size(); i++) {
        int to = graph.at(v).at(i);
        dfs(to, cnt);

        if (!ok && !used.at(to)) {
            cnt++;
            ok = true;
            used.at(v) = true;
            used.at(to) = true;
        }
    }
}

