int main() {
	int N;
	scanf("%d", &N);

	int* A = new int[N];
	for (int i = 0; i < N; i++) {
		scanf("%d", &A[i]);
	}

	list<int>* AKouho = new list<int>[N];

	// 調査対象
	for (int i = 0; i < N; i++) {
		// 相手
		for (int j = 0; j < N; j++) {
			if (i != j) {
				// 調査するべき数
				int tmp = A[i] + A[j];
				int check = true;
				while (tmp > 1) {
					if (tmp % 2 == 1) {
						check = false;
						break;
					}
					tmp /= 2;
				}
				if (check) AKouho[i].push_back(A[j]);
			}
		}
	}

	int max = 0;
	for (int i = 0; i < N; i++) {
		int size = AKouho[i].size();
		if (size > max) max = size;
	}

	int ans = 0;
	for (int i = 0; i < N; i++) {
		int size = AKouho[i].size();
		if (size > 0) ans++;
	}
	printf("%d\n", ans / 2);

	return 0;
}

