		all.erase(all.find(*cur));
		for(int i=0;i<31;i++)
		{
			if((1<<i)<=val) continue;
			if(all.count((1<<i)-val))
			{
				all.erase(all.find((1<<i)-val));
				ans++;
			}
		}
	}
	cout<<ans<<endl;
}

