//Bipartite_Matching
class Bipartite_Matching {
public:
	int V;
	vector<vector<int>> graph;
	vector<int> match, visit;

	Bipartite_Matching(const int V) :V(V), graph(vector<vector<int>>(V)), match(vector<int>(V, -1)), visit(vector<int>(V)) {
	}

	void make_edge(const int from, const int to) {
		graph[from].push_back(to);
	}

	bool dfs(int i) {
		visit[i] = 0;
		for (auto j : graph[i]) {
			int k = match[j];
			if (k < 0 || (visit[k] && dfs(k))) {
				match[i] = j;
				match[j] = i;
				return true;
			}
		}
		return false;
	}

	ll Max_Matching() {
		ll sum = 0;
		for (int i = 0; i < V; ++i) {
			if (match[i] < 0) {
				for (int j = 0; j < V; ++j) visit[j] = 1;
				if (dfs(i)) sum++;
			}
		}
		return sum;
	}

};


int main() {
	int N; cin >> N;
	V<ll> A(N),pow2(35,1);
	REP(i, N) cin >> A[i];
	FOR(i, 1, 31) pow2[i] = pow2[i-1] * 2;

	unordered_map<ll, vector<int>> mp;
	REP(i, N) mp[A[i]].push_back(i);

	Bipartite_Matching BP(N);
	REP(i,N) {
		FOR(j, 1, 31){
			ll c = pow2[j] - A[i];
			if (c <= 0) continue;
			for(auto u :mp[c]){
				if (i == u)continue;
				BP.make_edge(i, u);
			}
		}
	}
	cout << BP.Max_Matching() << endl;

	return 0;
}

