bool dfs(int u){
    for(int i=head[u],v;i;i=e[i].next){
        v=e[i].v;
        if(vis[v])continue;
        vis[v]=1;
        if(match[v]==-1 || dfs(match[v])){
            match[v]=u;
            return true;
        }
    }
