typedef long long int LL;

std::vector<std::vector<LL>>G;
std::vector<bool>vis;

LL dfs(LL v)
{
	if (vis[v]) return 0;
	vis[v] = true;
	LL res = 1;
	for (auto u : G[v]) res += dfs(u);
	return res;
}

int main()
{
	LL N;
	in >> N;
	std::vector<LL>A(N);
	rep(i, N) in >> A[i];

	std::sort(A.begin(), A.end());
	std::vector<LL>odd, even, rui(33);
	rep(i, N)
	{
		if (A[i] % 2 == 0) odd.push_back(A[i]);
		else even.push_back(A[i]);
	}
	rui[0] = 1;
	for (int i = 1; i <= 32; ++i) rui[i] = rui[i - 1] * 2;

	LL ans = 0;
	std::map<LL, LL>odd_cnt;
	for (auto i : odd) odd_cnt[i]++;
	for (auto i : odd_cnt)
	{
		auto it = std::lower_bound(rui.begin(), rui.end(), i.first * 2);
		if (it != rui.end())
		{
			if (*it == i.first * 2) ans += i.second / 2;
		}
	}

	G.resize(even.size());
	rep(i, even.size())
	{
		rep(j, rui.size())
		{
			auto it = std::lower_bound(even.begin(), even.end(), rui[j] - even[i]);
			if (it != even.end() && it - even.begin() != i)
			{
				if (even[i] + *it == rui[j]) G[i].push_back(it - even.begin());
			}
		}
	}

	vis.resize(even.size());
	rep(i, even.size())
	{
		if (!vis[i]) ans += dfs(i) / 2;
	}

	out << ans << std::endl;
	return 0;
}

