int ans, total;
struct Graph{
    struct Node{
        unordered_set<int> dests;
        int num = 0;
    };
    vector<Node> nodes;
    Graph(int num): nodes(num){ }
    int id(Node* n){ return n - &nodes[0]; }
    int id(Node& n){ return &n - &nodes[0]; }
    void print(){ for(auto& node : nodes){ prints(id(node), node.dests); } }
    void addEdge(int from, int dest, int num){
        nodes[from].dests.insert(dest);
        nodes[from].num = num;
    }
    void erase1(int idx){
        if(nodes[idx].dests.size() != 1){ 
            if(nodes[idx].dests.size() == 0){
                total--;
            }
            return;
        }
        auto didx = *nodes[idx].dests.begin();
        int mi = min(nodes[idx].num, nodes[didx].num);
        nodes[didx].num -= mi;
        // nodes[idx].num = 0;
        if(idx == didx){
            ans += mi / 2;
        }else{
            ans += mi;
        }
        printde(idx, didx, mi, ans);
        nodes[idx].dests.erase(didx);
        nodes[didx].dests.erase(idx);
    }
    int dfs(int idx, int from = -1){
        if(nodes[idx].num == 0){ return 0; }
        nodes[idx].num--;
        int ret = 1;
        for(auto p : nodes[idx].dests){
            int didx = p;
            ret += dfs(didx, idx);
        }
        return ret;
    }
};

