	map<long long, long long> A;
	int count = 0;
	int max = 0;
	for(int cnt = 0; cnt < N; cnt++){
		long long a;
		cin >> a;
		A[a] ++;
		if(max < a){
			max = a;
		}
	}
	int index = log2(max) + 2;

	map<long long, long long> pairCount;
	for(int i = 1; i <= index; i++){
		for(auto itr = A.begin(); itr != A.end(); ++itr){
			if(itr->second == 0) continue;
			long long a = itr->first;
			int j = pow(2, i) - a;
			if(j < 1) continue;
			if((a == j && A[j] > 1) || (a != j && A[j] > 0)){
				pairCount[a]++;
				pairCount[j]++;
			}
		}
	}
	for(auto itr = pairCount.begin(); itr != pairCount.end(); itr++){
		if(itr->second == 2){
			for(int i = 1; i <= index; i++){
				long long a = itr->first;
				int j = pow(2, i) - a;
				if(j < 1) continue;
				if((a == j && A[j] > 1) || (a != j && A[j] > 0)){
					++count;
					A[itr->first] = 0;
					A[j] = 0;
					break;
				}
			}
		}
	}
	cout << count << endl;

	return 0;
}

