struct graph {
  int L, R;
  vector<vector<int>> adj;
  graph(int L, int R) : L(L), R(R), adj(L+R) { }
  void add_edge(int u, int v) {
    adj[u].push_back(v+L);
    adj[v+L].push_back(u);
  }
  int maximum_matching() {
    vector<int> visited(L), mate(L+R, -1);
    function<bool(int)> augment = [&](int u) { // DFS
      if (visited[u]) return false;
      visited[u] = true;
      for (int w: adj[u]) {
        int v = mate[w];
        if (v < 0 || augment(v)) {
          mate[u] = w;
          mate[w] = u;
          return true;
        }
      }
      return false;
    };
    int match = 0;
    for (int u = 0; u < L; ++u) {
      fill(ALL(visited), 0);
      if (augment(u)) ++match;
    }
    return match;
  }
};

void solve(long long N, std::vector<long long> A){
    graph g(N, N);

    map<LL, VI> memo;
    REP(i, N) {
        if(memo.count(A[i]) == 0) {
            VI tmp;
            memo[A[i]] = tmp;
        }

        memo[A[i]].PB(i);
    }

    VLL pair_num;
    LL idx = 2;
    while(idx*idx <= 2000000000) {
        pair_num.PB(idx*idx);
        idx++;
    }

    for(auto i = memo.begin(); i != memo.end() ; ++i ) {
        REP(j, pair_num.size()) {
            LL key = pair_num[j] - i->first;
            if(memo.count(key) == 1) {
                REP(l, i->second.size()) {
                    REP(r, memo[key].size()) {
                        g.add_edge(i->second[l], memo[key][r]);
                    }
                }
            }
        }
    }

    cout << (g.maximum_matching() / 2) << endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    std::vector<long long> A(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&A[i]);
    }
    solve(N, std::move(A));
    return 0;
}

