long long A[Maxn+5];
long long num[35];
bool used[Maxn+5];

void Init() {
	num[0]=1;
	for(int i=1;i<=32;i++)
		num[i]=num[i-1]*2;
}

int find(int pos) {
	for(int i=32;i>=1;i--) {
		long long val=num[i]-A[pos];
		if(val<0)break;
		int k=lower_bound(A+1,A+N+1,val)-A;
		if(pos==k||used[k])continue;
		if(A[k]+A[pos]!=num[i])continue;
		return k;
	}
	return -1;
}

