}

int sub2(long n,long X[300000],long Y[300000],int p,int q){
  int r;
  while (p<=q){
    r=(p+q)/2;
    if (n==X[r]){
      break;
    }
    else if (n<X[r]){
      q=r-1;
    }
    else{
      p=r+1;
    }
  }
  if (n==X[r]){
    int s = r;
    while (n==X[s] && s<=q){
      if (Y[s]==1){
        Y[s]=0;
        return 1;
      }
      s++;
    }
    s=r;
    while (n==X[s] && s>=p){
      if (Y[s]==1){
        Y[s]=0;
        return 1;
      }
      s--;
    }
  }
  return 0;

}

