			int tmp=upper_bound(a, a+n, a[i])-lower_bound(a, a+n, a[i]);
			if(tmp>0 && tmp-used[a[i]]-1>0){
				++ans;
			}
			used[a[i]]+=2;
		}
		m=a[i];
		int cnt=0;
		while(m>0){
			m/=2;
			++cnt;
		}
		ll beki=1ll<<(cnt+1);
		ll b=beki-a[i];
		int tmp=upper_bound(a, a+n, b)-lower_bound(a, a+n, b);
		if(tmp>0 && tmp-used[b]>0){
			++ans;
		}
		++used[b];
		++used[a[i]];
		// DEBUG(ans);
	}
	cout<<ans<<'\n';
	return 0;
}

