	while (it < e) {
	  if (used[it-begin(v)]) continue;
	  used[it-begin(v)] = true;
	  ++ans;
	  ++it;
	}
      } else {
	vv.push_back(v[i]);
      }
    }
    v = move(vv);
  }
  cout << ans << endl;
  return 0;
}

