int n;
map<int,int> res;
int ans;
int main(){
    cin>>n;
    for(int i=0;i<n;i++){
        int a;
        cin>>a;
        res[a]++;
    }
    while(res.size()){
        map<int,int>::iterator it=res.end();
        it--;
        int now=it->first;
        int l2=2<<__lg(now);
        int now_ans=min(res[now],res[l2-now]);
        if(now==l2-now)
            now_ans/=2;
        res[now]-=now_ans;
        res[l2-now]-=now_ans;
        if(res[now]==0)
            res.erase(now);
        if(res[l2-now]==0)
            res.erase(l2-now);
        ans+=now_ans;
        if(it==res.begin())
            break;
    }
    cout<<ans<<endl;
    return 0;
}

