void solve() {
	int N; cin >> N;
	multiset<int> As;
	vector<int> A;
	REP(i,N){
		int a; cin >> a;
		As.insert(a);
		A.push_back(a);
	}
	vector<int> beki;
	beki.push_back(1);
	while(beki.back() <= 1000000000){
		beki.push_back(beki.back()*2);
	}
	reverse(ALL(A));
	int res = 0;
	for(auto &a:A) {
		auto cur = As.find(a);
		if(cur == As.end()) continue;
		int b = *lower_bound(ALL(beki), a);
		auto tar = As.find(b - a);
		if(tar == As.end()) continue;
		As.erase(cur);
		As.erase(tar);
		++res;
	}
	cout << res << endl;
}

