      for (lli j = 0; j < 40; ++j) {
        auto bit = (1LL << j) - x;
        each (k, idx[bit]) {
          if (i != k) add_edge(i, k);
        }
      }

      idx[x].push_back(i);
    }

    cout << matching() << endl;
  }

  return 0;
}

