struct BipartiteMatching {
  vector<vector<ll>> edges;
  vector<ll> match;
  vector<bool> used;

  BipartiteMatching(ll n)
      : edges(vector<vector<ll>>(n)), match(vector<ll>(n, -1)) {}

  void add(ll from, ll to) {
    edges[from].push_back(to);
    edges[to].push_back(from);
  }

  bool dfs(ll v) {
    used[v] = true;

    for (auto u : edges[v]) {
      ll w = match[u];
      if (w == -1 || !used[w] && dfs(w)) {
        match[u] = v;
        match[v] = u;
        return true;
      }
    }

    return false;
  }

  ll call() {
    ll res = 0;

    rep(v, edges.size()) {
      if (match[v] == -1) {
        used = vector<bool>(edges.size());

        if (dfs(v)) {
          res++;
        }
      }
    }

    return res;
  }
};

void solve() {
  ll N;
  cin >> N;

  VL as(N);
  rep(i, N) cin >> as[i];

  sort(all(as));

  BipartiteMatching bm(N);

  rep(i, N) {
    ll sum = 1;

    while (sum <= 2 * 1e9) {
      ll target = sum - as[i];
      // if (diff <= as[i]) continue;
      auto it = lower_bound(as.begin() + i + 1, as.end(), target);

      if (it != as.end() && *it == target) {
        while (*it == target) {
          ll pair_i = it - as.begin();
          bm.add(i, pair_i);
          it++;
        }
      }

      sum *= 2;
    }
  }

  ll res = bm.call();
  cout << res << endl;
}

