   }
   int s = 2 * N;
   int t = s + 1;
   for (int i = 0; i < N; i++) {
      add_edge(s, i, 1);
      add_edge(i + N, t, 1);
   }
   for (int i = 0; i < N; i++) {
      // cout << i << ": " << A[i] << endl;
      int k = calc(A[i]) + 1;
      ll amari = pow(2, k) - A[i];
      ll tmp;
      for (int j = k - 1; j <= 30; j++) {
         if (j == k - 1) tmp = amari;
         else tmp += pow(2, j);
