    }
    int ans = 0;
    while (!counts.empty())
    {
        auto cur_it = counts.rbegin();
        auto cur = cur_it->first;
        auto cnt = cur_it->second;
        if (cnt == 1)
            counts.erase(cur);
        else
            counts[cur] = cnt - 1;
        int need = 1;
        while (need <= cur)
            need *= 2;
        need -= cur;
        auto it = counts.find(need);
        if (it != counts.end())
        {
            ans++;
            if (it->second == 1)
                counts.erase(it->first);
            else
                counts[it->first] = it->second - 1;
        }
    }
    cout << ans;

    return 0;
}

