    for (long long &a : A)
    {
        cin >> a;
    }
    sort(A.begin(), A.end());

    vector<pair<long long, int>> B(1, make_pair(0, 0));
    for (long long a : A)
    {
        if (a == B.back().first)
        {
            B.back().second++;
        }
        else
        {
            B.push_back(make_pair(a, 1));
        }
    }

    long long ans = 0;
    for (int i = B.size() - 1; i > 0; i--)
    {
        long long x = B[i].first;
        long long y = 1;
        long long exp = 0;
        while (x > 0)
        {
            if (~x & 1)
            {
                y += (1 << exp);
            }
            exp++;
            x >>= 1;
        }

        int l = 0;
        int r = i;
        while (r - l > 1)
        {
            int c = (l + r) / 2;
            if (B[c].first >= y)
            {
                r = c;
            }
            else
            {
                l = c;
            }
        }

        if ((B[r].first == y) && (B[r].second > 0) && (B[i].second > 0))
        {
            ans++;
            B[r].second--;
            B[i].second--;
        }
    }
    cout << ans << endl;
}

