int subsolve(vector<int> a) {
    multiset<int> st;
    for (int x : a) st.insert(x);

    int ans = 0;
    while (!st.empty()) {
        int x = *st.rbegin();
        st.erase(st.find(x));
        int pw = 1;
        while (pw <= x) pw *= 2;
        int y = pw - x;

        auto it = st.find(y);
        if (it != st.end()) {
            st.erase(it);
            ans++;
        }
    }
    return ans;
}

