    vector<vector<int>> b(50);
    for (int x : a) {
        int y = 0;
        while (x % 2 == 0) {
            x /= 2;
            y++;
        }
        b[y].push_back(x);
    }
    int ans = 0;
    for (auto v : b) ans += subsolve(v);
    return ans;
}

