int In() {
    register char c;
    for(;c=getchar(),c!='-'&&!isdigit(c););
    register bool f=c=='-';
    register int s=f?0:c-'0';
    for(;c=getchar(),isdigit(c);)s=s*10+c-'0';
    return f?-s:s;
}
void ist(register int u,register int v) {
	*++zl=(Bridge){v,fr[u]},fr[u]=zl;
	*++zl=(Bridge){u,fr[v]},fr[v]=zl;
}
void ff(int x) {
	vs[x]=1;
	for(Bridge *i=fr[x];i;i=i->ne)if(!vs[i->v]) co[i->v]=!co[x],ff(i->v);
}
void ins(register int u,register int v,register int c) {
	++cl,*cl=(Edge){v,c,cl+1,la[u]},la[u]=cl;
	++cl,*cl=(Edge){u,0,cl-1,la[v]},la[v]=cl;
}
bool bfs() {
	memset(ds,0,sizeof ds);
	for(ds[qu[hd=tl=1]=t]=1;hd<=tl;++hd)for(register Edge *i=la[qu[hd]];i;i=i->ne)
	if(i->re->c&&!ds[i->v]) ds[i->v]=ds[qu[hd]]+1,qu[++tl]=i->v;
	return ds[s];
}
int dfs(int x,int f) {
	if(x==t) return f;
	int r=0;
	for(Edge *&i=cur[x];i;i=i->ne)if(i->c&&ds[i->v]==ds[x]-1) {
		int t=dfs(i->v,f-r<i->c?f-r:i->c);
		r+=t,i->c-=t,i->re->c+=t;
		if(r==f) return r;
	}
	return r;
}
