using namespace std;

vector<int> A;
pair<int, int> tree[1 << 19];
int lazy[1 << 19];

void lazy_propagation(int bit, int s, int e)
{
	tree[bit].first += lazy[bit];
	if (s < e) {
		lazy[2 * bit] += lazy[bit];
		lazy[2 * bit + 1] += lazy[bit];
	}
	lazy[bit] = 0;
}

void add_tree(int n1, int n2, int v, int bit = 1, int s = 0, int e = 200000)
{
	int m = (s + e) >> 1;
	lazy_propagation(bit, s, e);
	if (n2 < n1 || n2 < s || e < n1) return;
	if (n1 <= s && e <= n2) {
		tree[bit].first += v;
		if (s < e) {
			lazy[2 * bit] += v;
			lazy[2 * bit + 1] += v;
		}
		return;
	}
	add_tree(n1, n2, v, 2 * bit, s, m);
	add_tree(n1, n2, v, 2 * bit + 1, m + 1, e);
	tree[bit] = min(tree[2 * bit], tree[2 * bit + 1]);
}

void set_tree(int n, int v, int bit = 1, int s = 0, int e = 200000)
{
	int m = (s + e) >> 1;
	lazy_propagation(bit, s, e);
	if (s == e) {
		tree[bit] = { v,n };
		return;
	}
	if (n <= m) set_tree(n, v, 2 * bit, s, m);
	else set_tree(n, v, 2 * bit + 1, m + 1, e);
	tree[bit] = min(tree[2 * bit], tree[2 * bit + 1]);
}

pair<int, int> get_min(int n1, int n2, int bit = 1, int s = 0, int e = 200000)
{
	int m = (s + e) >> 1;
	lazy_propagation(bit, s, e);
	if (n2 < n1 || n2 < s || e < n1) return { 0x7fffffff,0x7fffffff };
	if (n1 <= s && e <= n2) return tree[bit];
	return min(get_min(n1, n2, 2 * bit, s, m), get_min(n1, n2, 2 * bit + 1, m + 1, e));
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(NULL); cout.tie(NULL);
	TEST(freopen("input.txt", "r", stdin));
	TEST(freopen("output.txt", "w", stdout));
	TEST(freopen("debug.txt", "w", stderr));
	int N, ans = 0;
	cin >> N;
	A.resize(N);
	fill(tree, tree + (1 << 19), make_pair(0x7fffffff, 0x7fffffff));
	for (int i = 0; i < N; i++) {
		cin >> A[i];
	}
	sort(A.begin(), A.end());
	for (int i = 0; i < N; i++) {
		int cnt = -(A[i] == (A[i] & -A[i]));
		for (int j = 30; j >= 0 && (1 << j) > A[i]; j--) cnt += upper_bound(A.begin(), A.end(), (1 << j) - A[i]) - lower_bound(A.begin(), A.end(), (1 << j) - A[i]);
		set_tree(i, cnt);
	}
	while (tree[1].first < 0x3f3f3f3f) {
		int i = tree[1].second, j, mcnt = 0x7fffffff;
		if (tree[1].first == 0) {
			set_tree(i, 0x7fffffff);
			continue;
		}
		set_tree(i, 0x7fffffff);
		for (int b = 30; b >= 0 && (1 << b) > A[i]; b--) {
			int s = lower_bound(A.begin(), A.end(), (1 << b) - A[i]) - A.begin();
			int e = upper_bound(A.begin(), A.end(), (1 << b) - A[i]) - A.begin();
			if (s < e--) {
				int v, n;
				for (;;) {
					tie(v, n) = get_min(s, e);
					if (v > 0) break;
					set_tree(n, 0x7fffffff);
				}
				if (v < mcnt) {
					mcnt = v;
					j = n;
				}
				add_tree(s, e, -1);
			}
		}
		if (mcnt < 0x3f3f3f3f) {
			set_tree(j, 0x7fffffff);
			for (int b = 30; b >= 0 && (1 << b) > A[j]; b--) {
				int s = lower_bound(A.begin(), A.end(), (1 << b) - A[j]) - A.begin();
				int e = upper_bound(A.begin(), A.end(), (1 << b) - A[j]) - A.begin();
				if (s < e--) {
					add_tree(s, e, -1);
				}
			}
			ans++;
		}
	}
	cout << ans << '\n';
	return 0;
}

