    int pow2k_1 = pow(2,k-1);
    int C_index = 0;
    while (A[C_index]<pow2k_1) {
        C_index += 1;
    }
    int N_b = C_index;
    int N_c = N - C_index;

    int index = 0;
    vector<int> D{};
    int N_d = 0;

    int temp_0 = 0;
    for (int i=0;i<N;i++) {
        if (A[i]==pow2k_1) temp_0 += 1;
    }
    result += temp_0/2;
    //cout << result << endl;

    for (int i=0;i<N_c;i++) {
        int target = pow2k - A[N-1-i];
        while (A[index]<target) {
            if (index==C_index) {A[index]=target+1; break;}
            D.push_back(A[index]);
            N_d += 1;
            index += 1;
        }
        if (index==C_index) {break;}
        if (A[index]==target) {
            result += 1;
            index += 1;
        }
    }

    //cout << result << endl;
    for (int i=0;i<N_d;i++) {
        DD[i] = D[i];
        //cout << DD[i] << " ";
    }
    //cout << endl;
    //cout << N_d << endl;

    return N_d;
}


int main(){
    int N;
    cin >> N;
    int A[N];
    for (int i=0;i<N;i++) cin >> A[i];
    sort(A, A+N);

    int now = A[N-1];
    int k = 0;
    while (now>=pow(2,k)) {k += 1;}

    for (int i=0;i<N;i++) {
        DD[i] = A[i];
    }

    while (k>0) {
        N = Func(k, N, DD);
        k -= 1;
    }

    cout << result << endl;

    return 0;
}

