int main() {

	ll N;
	cin >> N;

	vector<ll> A(N + 1,0);
	repn(i, N) cin >> A[i];

	sort(++A.begin(), A.end());

	vector<ll> B(1);
	vector<ll> C(1);
	ll M = 0;

	repn(i, N) {
		if (A[i] != A[i - 1]) {
			M++;
			C.push_back(A[i]);
			B.push_back(1);
		}

		else { B[M]++; }
	}

	ll ans = 0;

	for (ll i = M; i > 0; i--) {
		ll p = 1;

		while (p <= C[i]) {
			p *= 2;
		}

		ll X = p - C[i];
		auto itr = lower_bound(++C.begin(), C.end(), X);
		ll j = distance(C.begin(), itr);

		if (C[j] != X) { continue; }

		if (i == j) { ans += B[i] / 2; }
		if (j < i) { ans += min(B[i], B[j]); B[j] -= min(B[i], B[j]); }

	}

	cout << ans;

	system("PAUSE");

}

