  int v[N];
  REP(i, N) cin >> v[i];
  sort(v, v + N);

  vector<bool> isUsed(N, false);

  int ans = 0;
  for(int i = N - 1; i >= 0; i--) {
    if(isUsed[i]) continue;

    isUsed[i] = true;
    int b = get2beki(v[i]) - v[i];
    auto ite = lower_bound(v, v + N, b);

    int j = ite - v;
    while(isUsed[j] && *ite == b) {
      ite++;
      j = ite - v;
    }

    if(*ite == b){
      ans++;
      isUsed[j] = true;
    }
  }
  cout << ans << endl;

  return 0;
}

