                    st.pop();
                }
                else{
                    preds[res[cur][ep[cur]]->dest]=cur;
                    st.push(res[cur][ep[cur]]->dest);
                }
            }
            if(st.size() && st.top()==T){
                //cout<<st.size()<<endl;
                int flVal=1e9;
