                    flVal=min(flVal,res[cur][ep[cur]]->cap);
                }
                cur=T;
                while(cur!=S){
                    cur=preds[cur];
                    res[cur][ep[cur]]->addFlow(flVal);
                }
            }
            else{
                dead[S]=true;
            }

        }

    }

