{
    cin >> n;

    for(int i = 1; i <= n; i ++)
    {
        cin >> a[i];
        aps[a[i]] ++;
    }
}

void solve()
{
    for(lint p = 1; p <= (1LL << 30); p <<= 1)
        doi[p] = 1;

    for(int i = 1; i <= n; i ++)
    {
        lint p2 = 1;
        while((p2 << 1) <= a[i])
            p2 <<= 1;

        if(p2 != a[i])
        {
            for(; p2 <= (1LL << 30); p2 <<= 1)
            {
                if(aps.find(p2 - a[i]) != aps.end())
                {
                    if(doi.find(p2 - a[i]) == doi.end())
                        g[i].push_back(p2 - a[i]), cati[p2 - a[i]] ++;

                    else
                        g2[i].push_back(p2 - a[i]), cati[p2 - a[i]] ++;
                }
            }
        }
    }

    for(int i = 1; i <= n; i ++)
    {
        if(doi[a[i]] == 0 && aps[a[i]] > 0)
        {
            int mx = -n;
            int px = 0;
            for(auto u : g[i])
            {
                if(aps[u] - cati[u] > mx)
                {
                    mx = aps[u] - cati[u];
                    px = u;
                }
            }

            if(px == 0)
            {
                for(auto u : g2[i])
                {
                    if(aps[u] - cati[u] > mx)
                    {
                        mx = aps[u] - cati[u];
