                rez ++;
                aps[a[i]] --;
                aps[px] --;
                cati[px] --;
                cati[a[i]] --;
            }
        }
    }

    for(int i = 1; i <= n; i ++)
    {
        if(doi[a[i]] == 1 && aps[a[i]] > 0)
            rez += (aps[a[i]] >> 1);
    }
}

