	#ifdef LOACL
	freopen("in.txt","r",stdin);
	freopen("out.txt","w",stdout);
	#endif
	Init();
	scanf("%d",&N);
	for(int i=1;i<=N;i++) {
		scanf("%lld",&A[i]);
		S[A[i]]++;
	}
	sort(A+1,A+N+1);
	unique(A+1,A+N+1);
	N=S.size();
	long long ans=0;
	for(int i=1;i<=N;i++) {
		if(used[i])continue;
		if(S[A[i]]>1)
			do {
				int j=find(i);
				if(j<=0)break;
				ans++;
				S[A[i]]--,S[A[j]]--;
				if(S[A[i]]<=0)used[i]=true;
				if(S[A[j]]<=0)used[j]=true;
			}while(S[A[i]]>=1);
		else {
			int j=find(i);
			if(j<=0)break;
			ans++;
			S[A[i]]--,S[A[j]]--;
			if(S[A[i]]<=0)used[i]=true;
			if(S[A[j]]<=0)used[j]=true;
		}
	}
	printf("%lld\n",ans);
	return 0;
}

