map<int, int> M;
vector<int> X;

void rem(int x, int val)
{
    auto it = M.find(x);

    if(it->second == val)
        M.erase(it);
    else
        it->second -= val;
}

int main() {

    ios::sync_with_stdio(0);
    cin.tie(NULL), cout.tie(NULL);

    int N;
    cin >> N;

    for(int i=1; i<=N; i++)
    {
        int x;
        cin >> x;

        M[x]++;
        X.push_back(x);
    }

    int ans = 0;

    for(int goal = (1LL << 30); goal > 1; goal /= 2)
    {
        for(auto x : X)
        {
            int y = goal - x;

            if(x == y)
            {
                if(M[x] > 1)
                {
                    ans++;
                    rem(x, 2);
                }
            }
            else
            {
                if(M.count(x) && M.count(y))
                {
                    ans++;
                    rem(x, 1), rem(y, 1);
                }
            }
        }

        X.clear();

        for(auto &it : M)
        {
            for(int i=0; i<it.second; i++)
                X.push_back(it.first);
        }
    }

    cout << ans << "\n";
