ll cnt(ll x) {

    ll val = 1;
    while(x!=1) {
        x /= 2;
        val++;
    }
    return val;
}

ll power(ll x, ll n) {

    if(n==0)
        return 1;

    return n%2==0 ? power(x*x, n/2) : x*power(x*x, n/2);
}

int main()
