// ペアの候補となる数を返す
// 具体的には ( x の 2 進数表記の最上位の桁の 1 つ左に 1 が立っていて残り 0 であるような数 ) - x
int f( int x ){
	int k = 0;
	while( true ){
		if( x == (1<<k) ){
			return x;
		} else if( x < (1<<k) ){
			return (1<<k)-x;
		} else {
			++k;
		}
	}
}

