int getrev(int x)
{
	if(x==0) return 0;
	int r=1;
	while(x>=r)
	{
		r*=2;
	}
	return (x^(r-1));
}

int solve(vi vec, int mode=0)
{
	if(mode==1)
	{
		if(vec.empty()) return 0;
		map<int,int> ma;
		for(int v:vec) ma[v]++;
		int ans=0;
		while(!ma.empty())
		{
			int x=(*prev(ma.end())).fi;
			ma[x]--;
			if(ma[x]==0) ma.erase(x);
			int r = getrev(x);
			//cerr<<x<<' '<<r<<'\n';
			if(ma.find(r)==ma.end()) continue;
			ma[r]--;
			if(ma[r]==0) ma.erase(r);
			ans++;
		}
		return ans;
	}
	else
	{
		if(vec.size()<2) return 0;
		vi V[2];
		for(int i=0;i<vec.size();i++)
		{
			V[vec[i]%2].pb(vec[i]);
		}
		for(int i=0;i<V[0].size();i++) V[0][i]/=2;
		int ev = solve(V[0],mode);
		vi V2;
		for(int i=0;i<V[1].size();i++)
		{
			V2.pb((V[1][i]-1)/2);
		}
		return ev + solve(V2,mode^1);
	}
}

