// nを超える最大の2冪
int nibeki(int n) {
    int m = 0;
    while (n) {
        n >>= 1;
        m++;
    }
    return 1LL << m;
}

int main() {
    int n; cin >> n;
    vector<int> a(n);
    vector<bool> used(n, false);
    REP(i, n) {
        scanf("%d", &a[i]);
    }
    sort(a.begin(), a.end());
    int ans = 0;
    REP(j, n) {
        int i = n - 1 - j;
        if (used[i]) continue;
        int k = nibeki(a[i]);
        auto up = upper_bound(a.begin(), a.begin() + n - 1 - i, k - a[i]);
        auto lw = lower_bound(a.begin(), a.begin() + n - 1 - i, k - a[i]);
        if (up - lw == 0) continue;
        //cout << i << " " << a[i] << " " << *lw << endl;
        used[lw - a.begin()] = true;
        ans++;
    }
    cout << ans << endl;
    return 0;
}

