int main() {
	int N;
	cin >> N;
	vector<int> A;
	for (int i = 0; i < N; i++) {
		int x; cin >> x;
		A.push_back(x);
	}
	sort(A.begin(), A.end());
	if (N == 1) {
		cout << 0 << endl;
		return 0;
	}

	int maxcand = A[N - 1] + A[N - 2];
	int maxt = log2(maxcand);

	multiset<int> s;
	for (int i = 0; i < N; i++) {
		s.insert(A[i]);
	}

	int counterPair = 0;
	while (s.size()>0) {
		auto p = s.end(); p--;
		int x = *p;

		bool found = false;		
		for (int i = 0; i < maxt; i++) {
			int z = pow(2, maxt - i);
			int y = z - x;
			if (y <= 0) continue;			
			auto q = s.find(y);
			if (q != s.end()) {
				if (y == x && s.count(y) == 1) continue;
				s.erase(p); s.erase(q);
				found = true;
				counterPair++;
				break;
			}
		}
		if (!found) {
			s.erase(x);			
		}
	}
	cout << counterPair << endl;
	return 0;
}

