using namespace std;
typedef pair<int, int> pii;
typedef long double ld;
typedef long long ll;
typedef unsigned long long ull;

const int N = int(1e5 + 10);
ll a[N];
map< ll, vector< int > > mp;
vector< int > adj[N];
map< ll, int >deg;
const ll M = 32;
bool taked[N];
int pairs;
queue< int > q;

void run(){
    // printf("sz: %lu\n", q.size());
    while(!q.empty()){
        int u = q.front();
        q.pop();
        // printf("%d\n", u);

        for(int i = 0 ; i < adj[u].size() ; i++){
            int v = adj[u][i];

            if(!taked[v]){
                taked[v] = true;
                taked[u] = true;
                pairs++;
                break;
            }
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int n;

    scanf("%d", &n);

    for(int i = 0 ; i < n ; i++){
        scanf("%lld", &a[i]);

        mp[a[i]].push_back(i);
    }

    for(int i = 0 ; i < n ; i++){
        for(ll j = 0LL ; j < M ; j++){
            ll e = (1LL << j);
            // printf("%lld %lld\n", e, a[i]);
            if(e <= a[i]){
                continue;
            }

            ll r = e - a[i];
            // printf("%d %lld\n", i, r);

            for(int t = 0 ; t < mp[r].size() ; t++){
                int v = mp[r][t];
                if(v == i){
                    continue;
                }
                // printf("%d-%d\n", v, i);

                adj[i].push_back(v);
                // deg[v]++;
                deg[i]++;
            }
        }
    }
    // printf("quitei\n");

    for(int i = 0 ; i < n ; i++){
        if(deg[i] == 1){
            q.push(i);
        }
    }

    run();
    // printf("run1\n");
    for(int i = 0 ; i < n ; i++){
        if(taked[i]){
            continue;
        }

        ll d = __builtin_popcountll(a[i]);

        if(d != 1){
            q.push(i);
        }
    }

    // printf("tentando 2\n");
    run();

    // printf("run2\n");

    for(int i = 0 ; i < n ; i++){
        if(!taked[i]){
            q.push(i);
        }
    }

    run();

    printf("%d\n", pairs);

    return 0;
}

