  vector<ll>a(n);
  map<ll,ll>mp;
  ll ans=0;
  rep(i,n){
    cin>>a[i];
    mp[a[i]]++;
  }
  for(int i=30;i>=0;--i){
    ll val=(1LL<<i);
    rep(j,n){
