const int N = (2e5) + 9;
const int M = (N<<2) + 9;
const int LOGN = ((int)log2(N)) + 3;
const int LOGM = ((int)log2(M)) + 3;
const int BUCK = 2*550;
const int SQRT = BUCK+9;

const int alpha = 32;

ll a[N];
int cnt[N], ps_cnt[N];
map < ll, int > mapp;
vll arr;
vi v[N];
ll p2[N];
int deg[N];
set < int > temp;
priority_queue < pii > pq;

void perform(int n, int &ans)
{
	int i, val, z;
	fo(i,1,n+1)
		deg[i] = sz(v[i]);
	while(!pq.empty())
		pq.pop();

	fo(i,1,n+1)
		pq.push({-deg[i],i});

	while(!pq.empty())
	{
		z = pq.top().S;
		pq.pop();
		if(deg[z] <= 0)
			continue;
		deg[z] = 0;
		for(auto x : v[z])
			if(deg[x] > 0)
			{
				val = min(cnt[x],cnt[z]);
				ans += val;
				cnt[x] -= val;
				cnt[z] -= val;
				deg[x]--;
				if(deg[x] > 0)
					pq.push({-deg[x],x});
			}
	}
	return;
}

void solve()
{
	int n, i, j, ans = 0;
	p2[0] = 1;
	fo(i,1,alpha+1)
		p2[i] = p2[i-1]+p2[i-1];
	cin >> n;
	fo(i,1,n+1)
	{
		cin >> a[i];
		temp.insert(a[i]);
	}
	arr.pb(0);
	for(auto x : temp)
		arr.pb(x);
	fo(i,1,sz(arr))
		mapp[arr[i]] = i;
	fo(i,1,n+1)
		cnt[mapp[a[i]]]++;

	n = sz(arr)-1;
	fo(i,1,n+1)
		if((arr[i]&(arr[i]-1LL)) == 0LL)
		{
			ps_cnt[i] = cnt[i];
			cnt[i] = 0;
		}
	fo(i,1,n+1)
		fo(j,0,alpha+1)
			if(mapp[p2[j]-arr[i]] && p2[j]-arr[i] != arr[i])
				v[i].pb(mapp[p2[j]-arr[i]]);
	perform(n,ans);
	fo(i,1,n+1)
		if(ps_cnt[i] != 0)
			cnt[i] = ps_cnt[i];
	perform(n,ans);
	fo(i,1,n+1)
		if(cnt[i] > 0 && (arr[i]&(arr[i]-1LL)) == 0LL)
			ans += (cnt[i]/2);
	cout << ans << '\n';
	return;
}

