using namespace std;
using ll = long long;
const int INF = 1e9;
const int MOD = 1e9 + 7;

vector<ll> a;
bool isOK(int index, ll key)
{
  if (a[index] >= key)
    return true;
  else
    return false;
}
int binary_search(ll key)
{
  int ng = -1;
  int ok = (int)a.size();
  while (abs(ok - ng) > 1)
  {
    int mid = (ok + ng) / 2;
    if (isOK(mid, key))
      ok = mid;
    else
      ng = mid;
  }
  return ok;
}

ll repeatSquaring(ll n, ll p)
{
  if (p == 0)
    return 1;
  if (p % 2 == 0)
  {
    ll t = repeatSquaring(n, p / 2);
    return t * t;
  }
  return n * repeatSquaring(n, p - 1);
}

vector<ll> memo;

int main()
{
  int n;
  cin >> n;
  for (ll i = 0; i < 40; ++i)
  {
    memo.push_back(repeatSquaring(2, i));
  }
  unordered_map<ll, ll> mp;
  for (int i = 0; i < n; ++i)
  {
    ll tmp;
    cin >> tmp;
    mp[tmp]++;
    a.push_back(tmp);
  }
  sort(a.begin(), a.end());
  bool check[200010] = {};
  int cnt = 0;
  for (int i = a.size() - 1; i > -0; --i)
  {
    if (check[i])
      continue;
    int tmp = -1;
    if (mp[a[i]] > 1000)
    {
      int p = binary_search(a[i]);
      int tt = 0;
      int pp = p;
      for (; a[p] == a[i]; ++p)
      {
        if (tt == 2)
          cnt++, tt = 0;
        if (!check[p])
          check[p] = true, tt++;
      }
      bool flag = false;
      for (int j = pp; j < p; ++j)
      {
        if (!check[j])
          flag = true, tmp = j;
      }
      if (!flag)
        continue;
    }
    for (int j = memo.size() - 1; j >= 0; --j)
    {
      ll key = memo[j] - a[i];
      if (key > a[a.size() - 1] || key < 0)
        continue;
      int itr;
      if (tmp == -1)
        itr = binary_search(key);
      else
        itr = tmp;
      while (itr < a.size() && a[itr] == key && check[itr])
        itr++;
      if (itr >= a.size() || a[itr] != key)
        continue;
      if (itr < a.size() && a[i] + a[itr] == memo[j] && i != itr && !check[itr] && !check[i])
      {
        check[i] = check[itr] = true;
        cnt++;
        break;
      }
    }
  }
  cout << cnt << endl;

  return 0;
}

