const int N = 1e5 * 2 + 10;
vector<int> g[N];

void add_edge(int src, int dst)
{
  if (src == dst) return ;
  g[src].push_back(dst);
  g[dst].push_back(src);
  return ;
}

int match[N];
int vis[N], x;
bool rec(int curr)
{
  vis[curr] = x;
  each (next, g[curr]) {
    int w = match[next];
    if (w < 0 || (vis[w] != x && rec(w))) {
      match[curr] = next;
      match[next] = curr;
      return true;
    }
  }
  return false;
}

int matching(int n = N)
{
  int res = 0;
  fill(match, match + N, -1);
  x = 1;
  fill(vis, vis + N, 0);
  for (int i = 0; i < n; ++i) {
    if (match[i] < 0) {
      res += rec(i);
      ++x;
    }
  }
  return res;
}

int main(int argc, char *argv[])
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n;
  while (cin >> n) {
    fill(g, g + N, vector<int>());

    vector<lli> a(n);
    cin >> a;

    map<int, vector<int>> idx;
    for (int i = 0; i < a.size(); ++i) {
      idx[a[i]].push_back(i);
    }

    for (int i = 0; i < a.size(); ++i) {
      for (lli j = 0; j < 40; ++j) {
        auto bit = (1LL << j) - a[i];
        if (a[i] < bit && idx.count(bit)) {
          each (k, idx[bit]) {
            add_edge(i, k);
            add_edge(k, i);
          }
        }
      }
    }

    cout << matching() << endl;
  }

  return 0;
}

