{
  int n;
  cin >> n;
  multiset<int> s;
  for (int i = 0; i < n; ++i) {
    int x;
    scanf("%d", &x);
    s.insert(x);
  }

  int result = 0;
  int iterations = 0;
  while (!s.empty()) {
    int x = *prev(s.end());
    s.erase(prev(s.end()));

    iterations++;
    assert(iterations <= n);

    for (int d = 1; d <= 2 * x; d *= 2) {
      if (d < x) continue;
      int r = d - x;
      auto it = s.find(r);
      if (it == s.end()) {
        continue;
      }
      s.erase(it);
      result++;
      break;
    }
  }

  cout << result << endl;

  return 0;
}

