template< typename flow_t >
struct Dinic {
	const flow_t INF;

	struct edge {
		int to;
		flow_t cap;
		int rev;
		bool isrev;
		int idx;
	};

	vector< vector< edge > > graph;
	vector< int > min_cost, iter;

	Dinic(int V) : INF(numeric_limits< flow_t >::max()), graph(V) {}

	void add_edge(int from, int to, flow_t cap, int idx = -1) {
		edge a = { to, cap, (int)graph[to].size(), false, idx };
		graph[from].emplace_back(a);
		a = { from, 0, (int)graph[from].size() - 1, true, idx };
		graph[to].emplace_back(a);
	}

	bool bfs(int s, int t) {
		min_cost.assign(graph.size(), -1);
		queue< int > que;
		min_cost[s] = 0;
		que.push(s);
		while (!que.empty() && min_cost[t] == -1) {
			int p = que.front();
			que.pop();
			for (auto& e : graph[p]) {
				if (e.cap > 0 && min_cost[e.to] == -1) {
					min_cost[e.to] = min_cost[p] + 1;
					que.push(e.to);
				}
			}
		}
		return min_cost[t] != -1;
	}

	flow_t dfs(int idx, const int t, flow_t flow) {
		if (idx == t) return flow;
		for (int& i = iter[idx]; i < graph[idx].size(); i++) {
			edge& e = graph[idx][i];
			if (e.cap > 0 && min_cost[idx] < min_cost[e.to]) {
				flow_t d = dfs(e.to, t, min(flow, e.cap));
				if (d > 0) {
					e.cap -= d;
					graph[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	flow_t max_flow(int s, int t) {
		flow_t flow = 0;
		while (bfs(s, t)) {
			iter.assign(graph.size(), 0);
			flow_t f = 0;
			while ((f = dfs(s, t, INF)) > 0) flow += f;
		}
		return flow;
	}

	void output() {
		for (int i = 0; i < graph.size(); i++) {
			for (auto& e : graph[i]) {
				if (e.isrev) continue;
				auto& rev_e = graph[e.to][e.rev];
				cout << i << "->" << e.to << " (flow: " << rev_e.cap << "/" << e.cap + rev_e.cap << ")" << endl;
			}
		}
	}
};

ll N;
vector<ll> A;
map<ll, ll> MAP;

int main() {
	cin >> N;
	A.resize(N + 1);
	for (ll n = 0; n < N; n++) {
		cin >> A[n];
		auto itr = MAP.find(A[n]);
		if (itr == MAP.end())MAP.insert(pll(A[n], 1));
		else itr->second++;
	}
	A[N] = (ll)1 << 32;
	MAP.insert(pll(A[N], 0));
	ll ans = 0;
	::sort(A.begin(), A.end(), [](ll a, ll b) {return a > b; });
	for (ll n = 1; n <= N; n++) {
		if (A[n - 1] == A[n])continue;
		auto myitr = MAP.find(A[n-1]);
		if (myitr->second == 0)continue;
		for (ll p = 0; p <= 32; p++) {
			if (((ll)1 << p) <= A[n-1])continue;
			ll x = ((ll)1 << p) - A[n-1];
			auto taritr = MAP.find(x);
			if (taritr == MAP.end())continue;
			ll res = min(myitr->second, taritr->second);
			ans += res;
			myitr->second -= res;
			taritr->second -= res;
		}
		ll bitcount = 0;
		for (ll p = 0; p <= 32; p++) {
			bitcount += ((A[n-1] >> p) & 1);
		}
		if (bitcount == 1) {
			ans += myitr->second / 2;
		}
	}
	cout << ans << endl;
	return 0;
}

