		for(auto x : v[z.S])
		{
			val = min(cnt[x],cnt[z.S]);
			ans += val;
			cnt[x] -= val;
			cnt[z.S] -= val;
			st.erase({deg[x],x});
			deg[x]--;
			st.insert({deg[x],x});
		}
	}
	fo(i,1,n+1)
		if(ps_cnt[i] != 0)
			cnt[i] = ps_cnt[i];
	fo(i,1,n+1)
		deg[i] = sz(v[i]);
	fo(i,1,n+1)
