int main(void) {
    pow2s[0] = 1;
    for (i=1; i<=32; i++) {
        pow2s[i] = pow2s[i-1] * 2;
    }
    cin >> N;
    int tmp;
    for (i=0; i<N;i ++) {
        cin >> tmp;
        A.push_back(tmp);
        cntA[tmp]++;
    }
    sort(A.begin(), A.end());
    reverse(A.begin(), A.end());

    ans = 0;
    for (i=0; i<A.size() && A.size() > 1; i++) {
        //まず，作れる２べきを探す
        for (j=0; j<32; j++) {
            if (pow2s[j] <= A[i] && A[i] < pow2s[j+1]) {
                break;
            }
        }
        //このとき，pow2s[j+1]が作れる２べき
        int pair_num = pow2s[j+1] - A[i];
        cntA[A[i]]--;
        if (cntA[pair_num] > 0) { //ペアがある
            cntA[pair_num]--;
            ans++;
        }
    }
    cout << ans << endl;

    return 0;
}

