int n, ans;
int main() 
{
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i) 
	{
		scanf("%d", &a[i]);
		s.insert(a[i]);
	}
	for(auto v : s)
	{
		if(del.count(v) == s.count(v)) continue;
		for(int i = 30; ~i; --i)
		{
			if(i == 0)
			{
				del.insert(v);
				break;
			}
			if(v != (1 << i) - v && s.count((1 << i) - v) - del.count((1 << i) - v) >= 1)
			{
				del.insert((1 << i) - v);
				del.insert(v);
				++ans;
				break;
			}
			else if(v == (1 << i) - v && s.count(v) - del.count(v) >= 2)
			{
				del.insert(v);
				del.insert(v);
				++ans;
				break;
			}
		}
	}
	printf("%d\n", ans);
	return 0;
}

