int main()
{
	set<long long>pow_2_num;
	set<long long>num_sequ;
	for(long i = 1;1;++i)//setting power of 2 number series table
	{
		if(pow(2.0,i*1.0)<2*pow(10.0,9))
		{
			pow_2_num.insert((long long)pow(2.0,i*1.0));
		}
		else
			break;
	}
	 long col_num,single_num,count;
	while(cin>>col_num)//for each group
	{
		num_sequ.clear();
		count = 0;
		for(int i = 0;i<col_num;++i)//for each number
		{
			cin>>single_num;
			if(i == 0)
			{
				num_sequ.insert(single_num);
				continue;
			}
			for(set<long long >::iterator iter = num_sequ.begin();iter!=num_sequ.end();)
			{
				if(pow_2_num.find((long long)(single_num+*iter))!=pow_2_num.end())
				{
					count++;
					num_sequ.insert(single_num);
					break;
				}
				++iter;
				if(iter == num_sequ.end())//not find
				{
					num_sequ.insert(single_num);
					break;
				}
			}
		}
		cout<<count<<endl;
	}
	return 0;
}

