int main(){
  cout << std::fixed << std::setprecision(16);
  cin.tie(nullptr);
  std::ios::sync_with_stdio(false);

  int n;
  cin>>n;
  std::vector<int> a(n);
  for(int i=0;i<n;i++){
    cin>>a[i];
  }

  std::unordered_map<int,int> set[31];

  for(auto v:a){
    std::bitset<31> bs(v);
    for(int i=0;i<31;i++){
      if(bs[i]){
        if(set[i].find(v)==set[i].end()){
          set[i].insert(std::make_pair(v,1));
        }else{
          set[i][v]++;
        }
        break;
      }
    }
  }



  int result=0;
  for(int i=0;i<31;i++){
    for(auto v:set[i]){
      while(set[i][v.first]>1){
        set[i][v.first]--;

        std::bitset<31> looking(v.first);
        std::bitset<31> searching(0);
        int limiter=1;
        int break_itr=0;
        for(int bi=0;bi<31;bi++){
          if(bi<=i){
            searching[bi]=looking[bi];
          }else{
            searching[bi]=!looking[bi];
          }
          limiter=limiter*2;
          if(limiter>v.first){
            break_itr=bi+1;
            break;
          }
        }

        cerr<<looking<<" "<<searching<<endl;

        for(;break_itr<31; break_itr++){
          int     searching_value = 0;
          int     weight          = 1;
          for(int si              = 0; si < 31; si++){
            searching_value += searching[si] * weight;
            weight *= 2;
          }
          if(set[i].find(searching_value) != set[i].end()){
            if(set[i][searching_value] > 0){
              result++;
              set[i][searching_value]--;
              break;
            }
          }
          searching[break_itr] = true;
        }
      }




    }
  }

  cout<<result<<endl;

  return 0;
}

