	reverse(a,a+n);
	long long now=1LL;
	while (now<=a[0])
	{
		now*=2LL;
	}
	long long ans=0LL;
	for (int i = 0; i < n; ++i)
	{
		while (now>a[i]*2LL)
		{
			now/=2LL;
		}
		if (memo.count(a[i])==0)
		{
			continue;
		}
		if (now==a[i]*2LL)
		{
			if (memo.count(a[i])>1)
			{
				++ans;
				memo.erase(memo.lower_bound(a[i]));
				memo.erase(memo.lower_bound(a[i]));
			}
			else
			{
				memo.erase(memo.lower_bound(a[i]));
			}
		}
		else if (memo.count(a[i])>0&&memo.count(now-a[i])>0)
		{
			++ans;
			memo.erase(memo.lower_bound(a[i]));
			memo.erase(memo.lower_bound(now-a[i]));
		}
		else if (memo.count(a[i])>0)
		{
			memo.erase(memo.lower_bound(a[i]));
		}
	}
