const int Maxn = 2e5 + 100;

int N, A[Maxn];
int pw2[40];
map <int, int> Map;

inline void Solve ()
{
	pw2[0] = 1;
	for (int i = 1; i <= 31; ++i) pw2[i] = pw2[i - 1] * 2;
	sort (A + 1, A + N + 1, greater <int>());
	int ans = 0;
	for (int i = 1; i <= N; ++i)
	{
		if (!Map[A[i]]) continue;
		for (int j = 31; j >= 1; --j)
			if (Map[pw2[j] - A[i]])
			{
				if (pw2[j] == 2 * A[i] && Map[pw2[j] - A[i]] == 1) break;
				++ans;
				--Map[A[i]];
				--Map[pw2[j] - A[i]];
				break;
			}
	}
	cout << ans << endl;
}

inline void Input ()
{
	N = read<int>();
	for (int i = 1; i <= N; ++i) ++Map[A[i] = read<int>()];
}

