ll calc_val2(ll val1)
{
    ll exp = (ll)log2((double)val1);
    ll val1_floor = pow(2LL, exp);
    return val1_floor * 2LL - val1;
}

int _main()
{
    ll n; llin(n);
    V<ll> alist; llina(alist, n);

    sort(alist);
    static bool used[200003];
    memset(used, 0, sizeof(used));
    ll ans = 0LL;

    rrep (i, n) {
        if (used[i]) continue;
        used[i] = true;
        ll val1 = alist[i];
        ll val2 = calc_val2(val1);

        debug_printf("val1=%lld val2=%lld\n", val1, val2);
        assert(val2 <= val1);

        auto iter = lower_bound(ALL(alist), val2);
        assert(iter != alist.end());
        ll j = iter - alist.begin();
        if (*iter == val2 && !used[j]) {
            ans++;
            used[j] = true;
        }
    }

    cout << ans << endl;

    return 0;
}

