#define MAX_N (200000)
#define MAX_EXP (30)

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  int N, as[MAX_N];
  scanf("%d", &N);
  for (int i = 0; i < N; i++) {
    scanf("%d", &as[i]);
  }

  // put into map
  map<int, int> m;
  for (int i = 0; i < N; i++) {
    m[as[i]]++;
  }

  // create graph
  int ans = 0;
  for (int t = MAX_EXP; t > 0; t--) {
    const int pow2 = (1 << t);
    // remove all pow2/2
    const int k = (1 << (t - 1)), cnt_k = m[k], pair_k = cnt_k / 2;
    ans += pair_k;
    m[k] -= pair_k * 2;
    m.erase(k);
    // printf("k = %d, cnt_k = %d, pair_k = %d\n", k, cnt_k, pair_k);
    // make pairs
    map<int, int> used;
    for (pair<int, int> p : m) {
      const int a_i = p.first, cnt_a_i = p.second;
      if (a_i > k) {
        break;
      }
      const int a_j = pow2 - a_i, cnt_a_j = m[a_j];
      if (cnt_a_j > 0) {
        const int cnt = min(cnt_a_i, cnt_a_j);
        ans += cnt;
        used[a_i] = cnt;
        used[a_j] = cnt;
      }
    }
    for (pair<int, int> p : used) {
      m[p.first] -= p.second;
    }
  }
  printf("%d\n", ans);

  return 0;
}

