        for (int j = 0; j < A.size() - 1; ++j) {
            int a = A[j];
            if(2 * a > tw){
                break;
            }
            int b = tw - a;

            auto itrX = A.begin() + j;
            auto itr= lower_bound(itrX, A.end(), b);
            int k = itr - A.begin();
            for (k; k < A.size(); ++k) {
