		while(itr->first < beki/2)beki/=2;
		auto itr2=num.find(beki-(itr->first));
		if(itr2==num.end())num.erase(itr->first);
		else{
			if(itr->first == itr2->first){
				if(itr2->second<2){
					num.erase(itr->first);
				}
				else{
					if(itr2->second<2)num.erase(itr->first);
					else{
						ans++;
						if(itr2->second==2)num.erase(itr->first);
						else num[itr2->first]-=2;
					}
				}
				goto A;	
			}
			ans++;
			if(itr2->second==1)num.erase(itr2->first);
			else num[itr2->first]--;
		}
		A:;
	}
	cout << ans << endl;
    return 0;
}

