#include<bits/stdc++.h>
#define maxn 200050
using namespace std;
typedef long long LL;

int n;
int a[maxn];

int ans;

int N;
map<int,int> mp;
vector<int> G[maxn];

void join(int i,int j)
{
    G[i].push_back(j);
    G[j].push_back(i);
}

void init()
{
    scanf("%d",&n);
    for (int i=0;i<n;++i)
        scanf("%d",&a[i]);
    sort(a,a+n);
    for (int i=0,j=0;i<n;i=j)
    {
        while (j<n&&a[i]==a[j])    ++j;
        if (__builtin_popcount(a[i])==1)
            ans+=(j-i)/2;
        if ((j-i)&1)
            mp[a[i]]=++N;
    }
    for (auto p:mp)
        for (int b=0;b<31;++b)
        {
            LL c=(1LL<<b)-p.first;
            if (p.first<=c)   continue;
            if (mp.count(c))
                join(p.second,mp[c]);
        }
}

bool vis[maxn];
int dp[maxn][2];

void dfs(int i)
{
    vis[i]=1;
    for (auto j:G[i])
    {
        if (vis[j])  continue;
        dfs(j);
        dp[i][1]=max(dp[i][1]+max(dp[j][0],dp[j][1]),dp[i][0]+dp[j][0]+1);
        dp[i][0]+=max(dp[j][0],dp[j][1]);
    }
}

void solve()
{
    for (int i=1;i<=N;++i)
        if (!vis[i])
        {
            dfs(i);
            ans+=max(dp[i][0],dp[i][1]);
        }
    printf("%d\n",ans);
}

int main()
{
    init();
    solve();
    return 0;
}

