sort(a.begin(),a.end());
int ans = 0;
us.resize(n,0);
for(int i = n-1;i>=0;i--){
        if(!us[i]){
            int j = 0;
            us[i] = 1;
            while(b[j]<=a[i])j++;
            int q = b[j]-a[i];
            int fle = fnd(q);
            if(fle==-1){us[i] = 0;continue;}
            ans++;
            us[fle] = 1;
        }
}
cout << ans;
}

