	for (int tmp = 0; tmp < 30; tmp++) {
		power /= 2;
		vector<inti>::iterator upp;
		vector<inti>::iterator lowp;
		vector<inti>::iterator tempp;

		vector<inti>::iterator sp = lower_bound(A.begin(),A.end(),power);
