		if (*sp == power) {
			upp = sp + 1;
			lowp = sp - 1;
		}
		else {
			upp = sp;
			lowp = sp - 1;
		}
		while (lowp != A.begin() && upp+1 != A.end()&&*upp<power*2) {
			if (*lowp + *upp == power * 2) {
				resultcount++;
				if (lowp + 1 == upp) {
					tempp = lowp - 1;
					A.erase(upp);
					A.erase(lowp);
					lowp = tempp;
					upp = tempp + 1;
				}
				else {
					upp = upp - 1;
					A.erase(upp + 1);
					lowp = lowp - 1;
					A.erase(lowp + 1);
				}

			}
			else if (*lowp + *upp > power * 2) {
				upp++;
			}
			else if (*lowp + *upp < power * 2) {
				lowp--;
			}

		}
		while (*lowp + *upp == power * 2) {
			resultcount++;
			if (lowp == A.begin() && upp+1 == A.end()) {
				A.erase(upp); A.erase(lowp);
				if (A.size() < 2) {
					cout << resultcount << endl;
					return 0;
				}
				lowp = A.begin(); upp = A.end()-1;
			}
			else if (lowp == A.begin()) {
				if (lowp + 1 == upp) {
					A.erase(upp); A.erase(lowp);
					if (A.size() < 2) {
						cout << resultcount << endl;
						return 0;
					}

					lowp = A.begin(); upp = lowp + 1;
				}
				else {
					upp = upp - 1;
					A.erase(upp + 1);
					A.erase(lowp);
					lowp = A.begin();
				}
			}
			else if (upp + 1 == A.end()) {
				if (lowp + 1 == upp) {
					A.erase(upp); A.erase(lowp);
					if (A.size() < 2) {
						cout << resultcount << endl;
					}
					else {
						lowp = A.end() - 2;
						upp = A.end() - 1;
					}
				}
				else {
					A.erase(upp);
					lowp = lowp - 1;
					A.erase(lowp + 1);
					upp = A.end() - 1;
				}

			}

		}
	}
	cout << resultcount << endl;




	return 0;
