ll rmb(int n){
    ll res = 0;
    while(n > 0){
        res = n & -n;
        n -= n & -n;
    }
    return res;
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N;

    for(int i=0;i<N;++i){
        std::cin >> A[i];
