    for(int i=0,j=0;i<N;i=j){
        while(j < N && A[j] == A[i]){
            ++j;
        }

        B.emplace_back(A[i], j - i);
    }

    int M = B.size();
    int res = 0;
    for(int i=M-1;i>=0;--i){
        ll a1, c1;
        std::tie(a1, c1) = B[i];

        ll sum = rmb(a1) * 2;
        int j = std::lower_bound(B.begin(), B.end(), std::make_tuple(sum - a1, -1)) - B.begin();

        if(j >= M || a1 + fst(B[j]) != sum){
