                if (a == b) if (mp[-a] > 1) { ans++; mp[-a] -= 2; }
                if (a != b) { ans++; mp[-a]--; mp[-b]--; }
            }
        }
        tw /= 2LL;
    }

    printf("%d\n", ans);
    return 0;
