uint32_t counter_part(uint32_t val)
{
	uint32_t in = val;
	uint32_t digit = 0;
	while (val != 0) {
		val >>= 1;
		digit++;
	}
	uint32_t ans = (1 << digit);
	uint32_t ret = ans - in;
	return ret;
}

int main()
{
	int n;
	cin >> n;

	vector<uint32_t> as(n);
	for (uint32_t& a : as) {
		cin >> a;
	}
	vector<bool> used(n, false);

	uint32_t count = 0;

	sort(as.begin(), as.end());
	for (int i = as.size() - 1; i > 0; i--) {
		if (used[i]) continue;

		uint32_t cp = counter_part(as[i]);

		auto it  = lower_bound(as.begin(), as.begin() + i, cp);
		int  idx = it - as.begin();
		bool found = false;
		while (as[idx] == cp) {
			if (!used[idx]) {
				found = true;
				break;
			}
			idx++;
		}

		if (found) {
			used[i]   = true;
			used[idx] = true;
			count++;
		}
	}

	cout << count << endl;

	return 0;
}

