int search(s* S, int p, int n) {
	if (S[0].a == p)return 0;
	int r = 0;
	for (int j = 30; j >= 0; j--) {
		if ((1 << j) >= n)continue;
		int c = r + (1 << j);
		if (S[c].a == p) {
			return c;
		}
		else if (S[c].a > p) {
			r = c;
		}
	}
	return -1;
}

