int getPow(int a) {
	for (int i = 1; i < 1e18; i *= 2) {
		if (a <= i) { return i; }
	}
	return -1;
}

void decElement(map<int, int>& m, int a) {
	m[a]--;
	if (m[a] == 0) m.erase(a);
}

signed main() {
	int n;
	cin >> n;

	map<int, int> m;
	rep(i, n) {
		int a;
		cin >> a;
		m[a]++;
	}

	int ans = 0;
	while (not m.empty()) {
		int a = (--m.end())->first;
		decElement(m, a);

		auto b = getPow(a) - a;
		if (m.count(b)) {
			decElement(m, b);
			ans++;
		}
	}
	cout << ans << endl;
}

