int dp[200001]={};
vector<P> v;
int calc(int l,int r,int c){
	if(l==r){
		return l;
	}
	int s=(l+r)/2;
	if(v[s].first<c){
		return calc(s+1,r,c);
	}
	if(v[s].first>c){
		return calc(l,s,c);
	}
	return s;
}
int main() {
	cin>>n;
	rep(i,0,n){
		cin>>a[i];
	}
	sort(a,a+n);
	ll c=a[0],d=0;
	rep(i,0,n){
		if(c!=a[i]){
			v.push_back(P(c,d));
			c=a[i];
			d=1;
		}else d++;
	}
	v.push_back(P(c,d));

	ll ans=0;
	rrep(i,v.size()-1,0){
		if(dp[i]==v[i].second)continue;
		ll b=1;
		while(b<=v[i].first){
			b*=2;
		}
		if(b/2==v[i].first){
			int k=v[i].second-dp[i];
			ans+=k/2;
		}else{
			int o=calc(0,v.size(),b-v[i].first);
			if(v[o].first==b-v[i].first&&v[o].second>dp[o]){
				ans+=min(v[i].second-dp[i],v[o].second-dp[o]);
				dp[o]+=min(v[i].second-dp[i],v[o].second-dp[o]);
			}
		}
	}
	cout<<ans<<endl;
}

