int main(){
	ll n,memo = 0;
	cin >> n;
	ll a[n];
	bool is_used[n] = {false},flag = false;
	ll memo2[n] = {0};
	priority_queue<Pll, vector<Pll>, greater<Pll> > pq[n];

	rep(i,0,n) cin >> a[i];

	sort(a,a+n);


	ll r,l,mid;

	rep(i,0,n){
		flag = false;
		if(is_used[i]) continue;
		rep(j,1,32){
			if((ll)pow(2,j) <= a[i]) continue;
			l = 0,r = n-1;
			while(r - l > 1){
				mid = (r+l)/2;
				if(a[mid] >= (ll)pow(2,j)-a[i] && !is_used[mid]){
					r = mid;
				}
				else{
					l = mid;
				}
			}

			while(1){
				if(r >= n) break;
				if(a[r] == (ll)pow(2,j)-a[i] && !is_used[r] && i != r){
					memo2[i]++;
					flag = true;
					break;
				}
				else if(a[r] != (ll)pow(2,j)-a[i]){
					break;
				}
				r++;
			}

			if(flag) break;
		}
	}

	rep(i,0,n){
		flag = false;
		if(is_used[i]) continue;
		rep(j,1,32){
			if((ll)pow(2,j) <= a[i]) continue;
			l = 0,r = n-1;
			while(r - l > 1){
				mid = (r+l)/2;
				if(a[mid] >= (ll)pow(2,j)-a[i] && !is_used[mid]){
					r = mid;
				}
				else{
					l = mid;
				}
			}

			while(1){
				if(r >= n) break;
				if(a[r] == (ll)pow(2,j)-a[i] && !is_used[r] && i != r){
					pq[i].push(Pll(memo2[r],(ll)r));
					flag = true;
					break;
				}
				else if(a[r] != (ll)pow(2,j)-a[i]){
					break;
				}
				r++;
			}

			if(flag) break;
		}
	}

	rep(i,0,n){
		while(!pq[i].empty()){
			Pll pll = pq[i].top();
			pq[i].pop();

			if(!is_used[pll.sc]){
				is_used[pll.sc] = true;
				is_used[i] = true;
				memo++;
				break;
			}
		}
	}

	cout << memo << endl;
	return 0;
}

