vector<int> A;
unordered_multimap<int, int> B;
int result = 0;


void find(){
    int tw = 1;
    for (int i = 1; i < 40; ++i) {
        tw *= 2;
        for (int j = 0; j < A.size() - 1; ++j) {
            int a = A[j];
            for (int k = j+1; k < A.size(); ++k) {
                int b = A[k];
                if(a+b == tw){
                    B.insert(make_pair(a,b));
                    B.insert(make_pair(b,a));
                }
                if(a+b > tw){
                    break;
                }
            }
        }
    }
}

void checkOneB(){
    for (auto itr = B.begin(); itr != B.end(); ++itr) {
        int c = B.count(itr->first);

        if(c == 1){
            int a = itr->first;
            int b = itr->second;
            B.erase(a);
            B.erase(b);
            result++;
            return;
        }
    }
}


void reduce(){
    while (B.size()>0){
        checkOneB();
    }
}

int main() {

    int N;
    cin >> N;

    for (int i = 0; i < N; ++i) {
        int n;
        cin >> n;
        A.push_back(n);
    }
    sort(A.begin(),A.end());

    find();
    reduce();

    cout << result << endl;


    return 0;
}

