int main(){

    int n; cin >> n;

    long long a[n];
    for(int i=0; i<n; i++){
        cin >> a[i];
    }

    long long pow2[31];
    pow2[0] = 0;
    long long temp = 1;
    for(int i=1; i<31; i++){
        temp *= 2;
        pow2[i] = temp;
        // cout << pow2[i] << endl;
    }

    vector<long long> a_odd, a_even;
    for(int i=0; i<n; i++){
        if(a[i] % 2 == 1){
            a_odd.push_back(a[i]);
        }
        else{
            a_even.push_back(a[i]);
        }
    }

    sort(a_odd.begin(), a_odd.end(), greater<long long>());
    sort(a_even.begin(),a_even.end(),greater<long long>());

    int n_odd = a_odd.size();
    int n_even= a_even.size();
    int ans = 0;
    set<int> usedindex;
    if(n_odd >= 2){
        for(int i=0; i<n_odd-1; i++){
            if(usedindex.find(i) != usedindex.end()){
                continue;
            }
            for(int j=i+1; j<n_odd; j++){
                if(usedindex.find(i) != usedindex.end()){
                    continue;
                }
                for(int k=1; k<31; k++){
                    if(a_odd[i] + a_odd[j] == pow2[k]){
                        ans++;
                        usedindex.insert(i);
                        usedindex.insert(j);
                    }
                }
            }
        }
    }
    usedindex.clear();
    if(n_even >= 2){
        for(int i=0; i<n_even-1; i++){
            if(usedindex.find(i) != usedindex.end()){
                continue;
            }
            for(int j=i+1; j<n_even; j++){
                if(usedindex.find(i) != usedindex.end()){
                    continue;
                }
                for(int k=1; k<31; k++){
                    if(a_even[i] + a_even[j] == pow2[k]){
                        ans++;
                        usedindex.insert(i);
                        usedindex.insert(j);
                    }
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

