	std::vector<long long> expList;
	std::vector<bool> isUsed;
	std::cin>>n;
	aList.resize(n);
	expList.resize(30, 1);
	isUsed.resize(n, false);
	for(int i=0; i<n; i++)
		std::cin>>aList[i];

	for(int i=1; i<30; i++)
		expList[i]= expList[i-1]*2;

	for(int i=29; i>=0; i--){
		std::vector<long long> deltaList(n);
		for(int j=0; j<n; j++)
			deltaList[j]= aList[j]-expList[i];

		std::sort(deltaList.begin(), deltaList.end());

		int left=0;
		int right= n-1;

		while(left<right){
			if(isUsed[left]){
				left++;
				continue;
			}

			if(isUsed[right]){
				right--;
				continue;
			}

			if(deltaList[left]+deltaList[right]==0){
				isUsed[left]=true;
				isUsed[right]=true;
				left++;
				right--;
				ans++;
				continue;
			}

			if(std::abs(deltaList[left]) > std::abs(deltaList[right]))
				left++;
			else
				right--;
		}
	}

	std::cout<<ans<<std::endl;

	return 0;
}

