        memo[a[i]] += 1;
    }

    sort(a.begin(), a.end());

    int count = 0;
    for (int t = 30; t > 0; t--) {
        for (int i = n-1; i >= 0; i--) {
            if (memo[a[i]] == 0) continue;
            int front = lower_bound(a.begin(), a.end(), (1 << t) - a[i]) - a.begin();
            int back = upper_bound(a.begin(), a.end(), (1 << t) - a[i]) - a.begin();
            if (front == back) continue;
            if (front > i) continue;
            if (front == i and memo[a[i]] <= 1) continue;
            if (memo[a[front]] >= 1) {
                memo[a[front]] -= 1;
                memo[a[i]] -= 1;
                count += 1;
            }

        }
    }

    cout << count << endl;

    return 0;
}

