int n;
int ans = 0;

bool check(int x)
{
    for (int i = 31; i >= 0; --i)
    {
        if (x == (1 << i))
        {
            return true;
        }
    }
    return false;
}

unordered_map<int, int> m;

set<int> used;

set<pair<pii, pii> > s;

void dfs(int v, int p = -1)
{
    //cerr << v << endl;
    used.is(v);
    for (int i = 0; i <= 31; ++i)
    {
        int val = (1 << i) - v;
        if (val != v && val != p && m[val])
        {
            dfs(val, v);
        }
    }
    int sum = 0;
    for (int i = 0; i <= 31; ++i)
    {
        int val = (1 << i) - v;
        if (val != v && val != p)
        {
            sum += m[val];
        }
    }
    if (m[v] > sum)
    {
        ans += sum;
        m[v] -= sum;
    }
    else
    {
        ans += m[v];
        m[v] = 0;
    }
}

int solve()
{
    cin >> n;
    for (int i = 0; i < n; ++i)
    {
        int x;
        cin >> x;
        m[x]++;
    }
    for (auto it : m)
    {
        if (m[it.X] && used.find(it.X) == used.end())
        {
            dfs(it.X);
        }
    }
    for (auto it : m)
    {
        if (m[it.X] && check(it.X))
        {
            ans += it.Y / 2;
        }
    }
    cout << ans << endl;
    return 0;
}

