#define RFOR(i, a, b) for(int i=(b)-1;i>=0;--i)
#define REP(i, n) for(int i=0;i<(n);++i)
#define RREP(i, n) for(int i=(n)-1;i>=0;--i)


signed main() {
    INIT;
    VAR(int, n);
    map< int, int > mp;
    vector< int > a;
    REP(i, n) {
        VAR(int, j);
        a.push_back(j);
        mp[j]++;
    }

    sort(ALL(a));
    a.erase(unique(ALL(a)), a.end());

    int ans = 0;
    RREP(i, a.size()) {
        RREP(j, 31) {
            if (mp[a[i]] == 0) break;
