            int target = (1 << j) - a[i];
            if (target == a[i]) {
                int tmp = mp[target] / 2;
                mp[target] -= tmp * 2;
                ans += tmp;
            } else {
                int tmp1 = mp[target];
                int tmp2 = mp[a[i]];
                mp[target] -= min(tmp1, tmp2);
