using namespace std;

int main() {
    int n, ans = 0, i;
    map <int, int> mp;
    map <int, set <int>> mp2;
    map <int, int>::iterator it;
    map <int, set <int>>::iterator it2;
    priority_queue <pair<int, int>> q;

    scanf("%d", &n);

    for (i = 0; i < n; i++) {
        int x;

        scanf("%d", &x);

        mp[x]++;
    }

    for (it = mp.begin(); it != mp.end(); it++) {
        int x = it->first;

        for (i = 1; i - x <= 1e9; i *= 2) {
            if (i <= x) continue;

            if (mp.count(i - x)) {
                if (x * 2 == i) {
                    if (it->second >= 2) mp2[x].insert(x);
                } else {
                    mp2[x].insert(i - x);
                }
            }
        }
    }

    for (it2 = mp2.begin(); it2 != mp2.end(); it2++) {
        if (it2->second.size() == 0) continue;

        q.push(make_pair(-it2->second.size(), it2->first));
    }

    while (!q.empty()) {
        int x = q.top().second;
        int y = -q.top().first;
        int z;

        q.pop();

        if (mp2[x].size() != y) continue;
        if (y != 1) continue;

        z = *mp2[x].begin();

        if (x == z) {
            ans += mp[x] / 2;
        } else {
            int p = min(mp[x], mp[z]);

            ans += p;
            mp[z] -= p;

            mp2[z].erase(x);
            q.push(make_pair(-mp2[z].size(), z));
        }
    }

    printf("%d\n", ans);

    return 0;
}

