bool is_exp(uint32_t val) {
	return (((~val + 1) & val) == val);
}

bool is_digit_up(uint32_t a, uint32_t b)
{
	return (((((a + b) >> 1) & a) << 1) > a);
}

uint32_t counter_part(uint32_t val)
{
	uint32_t in = val;
	uint32_t digit = 0;
	while (val != 0) {
		val >>= 1;
		digit++;
	}
	uint32_t ans = (1 << digit);
	uint32_t ret = ans - in;
	return ret;
}

int main()
{
	int n;
	cin >> n;

	list<uint32_t> as(n);
	for (uint32_t& a : as) {
		cin >> a;
	}
	vector<bool> used(n, false);

	uint32_t count = 0;

	as.sort();
	while (as.size() >= 2) {
		uint32_t val = *as.rbegin();

		uint32_t cp = counter_part(val);
		auto it = lower_bound(as.begin(), as.end(), cp);
		if (it != as.end()) {
			if (*it == cp) {
				as.erase(it);
				count++;
			}
		}

		as.pop_back();
	}

	cout << count << endl;

	return 0;
}

