const int N = 200005;

int n;
int arr[N];
map <int, int> cnt;
multiset <int> s;
vector < pair <int, int> > vec;

int32_t main() {
  cin >> n;
  for (int i = 0; i < n; i++) {
    cin >> arr[i];
    cnt[arr[i]]++;
  }
  for (int i = 0; i < n; i++) {
    int el = arr[i];
    int here = 0;
    for (int j = 0; j <= 32; j++) {
      here += cnt[(1ll << j) - el];
    }
    if (((el * 2) & (el * 2 - 1)) == 0) here--;
    vec.push_back({here, el});
  }
  sort(vec.begin(), vec.end());
  int ans = 0;
  for (int i = 0; i < n; i++) {
    bool done = 0;
    for (int j = 32; j >= 0 && !done; j--) {
      if (s.find((1ll << j) - vec[i].second) != s.end()) {
        s.erase(s.find((1ll << j) - vec[i].second));
        ans++;
        done = 1;
      }
    }
    if (!done) s.insert(vec[i].second);
  }
  cout << ans << endl;
  return 0;
}

