					break;
				}
				else {
					k *= 2;
				}
			}

			k = k - a[i];

			long long end = i - 1;
			long long start = 0;
			long long mid = (start + end) / 2;

			if (a[end] == k && b[end]) {
				count++;
				b[end] = false;
				b[i] = false;
			}
			else if (a[start] == k && b[start]) {
				count++;
				b[start] = false;
