ll answer;

ll getPair(ll x, map<ll,ll>& cnt){
  ll p = 1;
  while(p < x) p*=2;
  if(cnt.count(p-x) > 0) return p-x;
  return -1;
}

void calc(int id){
  vector<int> order;
  order.push_back(id);
  int pos = 0;
  while(pos < order.size()){
    rep(i,G[order[pos]].size()){
      pair<int,int> tmp = G[order[pos]][i];
      if(tmp.second == -1) continue;
      order.push_back(tmp.first);
    }
    pos++;
  }
  reverse(ALLOF(order));

  //cout << nmp[id] << endl;
  //rep(i,G[id].size()){
  rep(i,order.size()){
    int iid = order[i];
    rep(j,G[iid].size()){
      pair<int,int> tmp = G[iid][j];
      if(tmp.second == -1) continue;
      //cout << " " << tmp.first << " " << tmp.second << endl;
      if(Gc[iid] > 0 && Gc[tmp.first] > 0){
        int mn = min(Gc[iid], Gc[tmp.first]);
        answer += mn;
        Gc[iid] -= mn;
        Gc[tmp.first] -= mn;
      }
    }
  }
}

ll solve(const vector<ll>& v){
  map<ll,ll> cnt;
  rep(i,v.size()){
    cnt[v[i]]++;
  }

  vector<ll> out(cnt.size(), 0);
  map<ll,int> mp;
  int no = 0;
  FOR(it,cnt){
    int id1 = no;
    mp[it->first] = id1;
    //nmp[id1] = it->first;
    Gc[id1] = it->second;

    //cout << "check: " << it->first << endl;
    ll tmp = getPair(it->first, cnt);
    if(tmp != -1){
      int id2 = mp[tmp];
      //cout << " pair: " << nmp[id1] << " " << nmp[id2] << endl;
      G[id1].push_back(make_pair(id2,-1));
      G[id2].push_back(make_pair(id1,1));
      out[id1]++;
    }
    no++;
  }

  answer = 0;
  rep(i,out.size()){
    if(out[i] != 0) continue;
    calc(i);
  }
  return answer;
}


