		cin >> a[i];
	sort(a.begin(), a.end());

	vector<ll> pows(0);
	pows.reserve(32);
	for (int i = 1; i <= a[n - 1] + a[n - 2]; i = (i << 1))
		pows.push_back(i);
	reverse(pows.begin(), pows.end());

	int i = n - 1, ans = 0;
	while (i >= 0) {
		int var = -1;
		for (int j = 0; j < 31 && pows[j] > a[i]; ++j) {
			int cur = find(a.begin(), a.end(), pows[j] - a[i]) - a.begin();
			if (cur != a.size())
				if (var == -1)
					var = cur;
				else {
					--i;
					continue;
				}
		}
		if (var == -1 || var == i) {
			a.erase(a.begin() + i);
			--i;
		}
		else {
			if (i < var) {
				a.erase(a.begin() + var);
				a.erase(a.begin() + i);
			}
			else {
				a.erase(a.begin() + i);
				a.erase(a.begin() + var);
			}
			++ans;
			i -= 2;
		}
	}
	cout << ans;
	return 0;
}

