typedef long long LL;
typedef long double LD;
typedef pair<LL, LL> pll;

bool picked[200001] = { false, };

LL binarySearch(vector<LL>& arr, int l, int r, LL x)
{
	if (r >= l) {
		int mid = l + (r - l) / 2;
		if (arr[mid] == x)
			return mid;

		if (arr[mid] > x)
			return binarySearch(arr, l, mid - 1, x);

		return binarySearch(arr, mid + 1, r, x);
	}

	return -1;
}
LL solution(vector<LL>& v, LL x) {
	LL answer = 0;
	LL obj = x;
	for (int i = 0; i < v.size();i++) {
		if (picked[i])continue;
		LL obj = x - v[i];
		LL fnd = binarySearch(v, 0, v.size() - 1, obj);
		if (fnd != -1 && (fnd!=i)) {
			answer++;
			picked[i] = true;
			picked[fnd] = true;
		}
	}
	return answer;
}

