constexpr int MX = 2 * ten(5) + 10;

struct pii : public Ordered<pii> {
  int fi, se;
  pii(int v=0, int k=0) : fi(v), se(k) {}
  int comp(const pii &p) const override { return fi - p.fi; }
};

int N;
vector<pii> p;  // first: value,   second: idx
vector<int> G[MX];
int match[MX];
bool used[MX];

void addEdge(int s, int t) {
  G[s].eb(t);
  G[t].eb(s);
}

bool dfs(int v)
{
  used[v] = true;
  rep(i, G[v].size()) {
    int u = G[v][i],  w = match[u];
    if (w < 0 || !used[w] && dfs(w)) {
      match[v] = u;
      match[u] = v;
      return true;
    }
  }
  return false;
}

int bipartite_matching()
{
  int res = 0;
  FILL(match, -1);
  rep(v, N) {
    if (match[v] < 0) {
      FILL(used, false);
      if (dfs(v)) ++res;
    }
  }
  return res;
}


void Xx_main_xX(const vector<char*> &args)
{
  map<int, int> cnt;
  cin >> N;

  rep(i, N) {
    int a; cin >> a;
    ++cnt[a];
  }

  ll baseAns = 0;

  for (ll k = (1 << 1); k <= (1LL << 31); k <<= 1) {
    for (auto itr = cnt.begin(); itr != cnt.end(); itr++) {
      val& e = *itr;
      int key = e.fi, num = e.se;
      int hoge = k - key;

      if (cnt.count(hoge) <= 0) continue;

      int minv = min(num-1, cnt[hoge]-1);
        baseAns += minv;
        cnt[key]  = num - minv;         chmax(cnt[key], 0);
        cnt[hoge] = cnt[hoge] - minv;   chmax(cnt[hoge], 0);
    }
  }

  for (val &e : cnt) {
    debug("%d -> %d\n", e.fi, e.se);
    rep(i, e.se) {
      p.eb(e.fi, p.size());
    }
  }

#ifdef DEBUG
  rep(i, p.size()) {
    debug("%d ", p[i].fi);
  }
  debug("\n");
#endif

  for (ll k = (1 << 1); k <= (1LL << 31); k <<= 1) {
    debug("------ k = %lld ----\n", k);
    rep(i, N) {
      const ll v = p[i].fi;
      const ll src = p[i].se;
      if (k - v < 0) continue;
      int l = lower_bound(p.begin() + i+1, p.end(), pii(k - v)) - p.begin();
      int r = upper_bound(p.begin() + i+1, p.end(), pii(k - v)) - p.begin();
      if (l == r) continue;

      debug("  v = %d, [%d, %d] (%d)\n", v, l, r, p[l].fi);

      for (int j = l; j < r; ++j) {
        addEdge(src, j);
      }
    }
  }

  outl( baseAns + bipartite_matching() );

}

