        continue;
      }
      int kk = k - A[n];

      int index = lower_bound(begin(A), end(A), kk) - begin(A);
      if(index < A.size()) {
        if(k == A[n] + A[index]) {
          uf.unite(n,index);
        }
      }

      k *= 2;
    }
  }

  int ans = 0;
  REP(n,A.size()) {
