int binarySearch(int a[],int n,int key) {
  int left=-1;
  int right=n;

  while (right-left>1) {
    int mid=left+(right-left)/2;

    if (a[mid]>=key) right=mid;
    else left=mid;
  }

  return right;
}

int main(void){
