  }
  long maxPT = 1;
  while (maxPT < maxA)
    maxPT <<= 1;

  long count = 0;
  map<long, long> used;
  for (long pt = maxPT; pt > 1; pt >>= 1) {
    for (auto it = as.rbegin(); it != as.rend(); it++) {
      if (it->first < (pt >> 1))
        break;
      if (used[it->first] == as[it->first])
