          ++count;
          used[a0]++;
          used[a1]++;
        }
      } else {
        if (as[a1] > used[a1] + 1) {
          ++count;
          used[a0]++;
          used[a1]++;
        }
      }
    }
  }

  cout << count << endl;
  return 0;
}

