typedef vector<int> vec;
typedef vector<vec> mat;
mat path, dp;

int N,M;
const int MAX_N = 200005;
int a[MAX_N],b[MAX_N];
bool chk[MAX_N];

int dfs(int v){
	chk[v]=1;
	for(int u:path[v]){
		if(chk[u])continue;
		dfs(u);

		for(int i=0;i<=b[v];i++){
			for(int j=0;j<=min(i,b[u]);j++){
				dp[v][i] = max(dp[v][i], dp[v][i-j] + dp[u][j] + j);
			}
		}
	}

	// printf("v=%d\n",v);
	// for(int i:dp[v])printf("%d ",i);
	// 	puts("");

	return *max_element(dp[v].begin(),dp[v].end());
}

int main(){
	scanf("%d",&N);
	for(int i=0;i<N;i++){
		scanf("%d",&a[i]);
	}
	sort(a,a+N);

	for(int i=0,j=1;i<N;i=j++){
		while(a[i]==a[j])j++;
		b[M++] = j-i;
	}
	unique(a,a+N);

	path.assign(M,vec(M));
	dp.assign(M,vec());
	int ans = 0;
	for(int i=0,j=1;i<M;i++){
		while(j<=a[i])j<<=1;
		int k = lower_bound(a,a+M,j-a[i])-a;
		if(a[k]+a[i]==j){
			if(i==k){
				ans += b[i]/2;
			}else if(k<i){
				path[i].push_back(k);
				path[k].push_back(i);
			}else{
				assert(0);
			}
		}
		dp[i].resize(b[i]+1);
	}

	for(int i=0;i<N;i++){
		if(!chk[i]){
			ans += dfs(i);
		}
	}
	printf("%d\n",ans);
	return 0;
}

