#include <bits/stdc++.h>
typedef long long ll; 

using namespace std;

int main() {
	ll N;
	cin >> N;
	vector<ll> a(N);
	for (int i = 0; i < N; ++i) { cin >> a[i]; }
	sort(a.begin(), a.end());

	ll min_t = 0;
	ll max_t = 0;
	while (pow(2, max_t) <= a[N - 1]) {
		++max_t;
		if ((min_t == 0) && (pow(2, max_t) > a[0])) {
			min_t = max_t - 1;
		}
	}

	// mp1:= a[i] と a[i]の個数
	map<ll, ll> mp1;
	for (int i = 0; i < N; ++i) {
		mp1[a[i]] += 1;
	}
	// mp2:= a[i] と a[i]の番号
	map<ll, ll> mp2;
	ll num = 1;
	for (int i = 0; i < N; ++i) {
		if (mp2[a[i]] == 0) {
			mp2[a[i]] = num++;
		}
	}
	// cnt_use[i]:= i番の数字をいくつ使ったか
	vector<ll> cnt_use(num + 1, 0);

	ll res = 0;
	// 作るペアの最低値を2^tとする
	for (ll t = min_t; t <= max_t; ++t) {
		ll tmp = 0;
		for (int i = 0; i < cnt_use.size(); ++i) { cnt_use[i] = 0; }
		// 2^uを作る
		for (ll u = t; u <= max_t; ++u) {
			for (int i = 0; i < N; ++i) {
				// a[i]を既に使いきっている
				if (mp1[a[i]] - cnt_use[mp2[a[i]]] == 0) {
					continue;
				}
				if (pow(2, u) < a[i]) { break; }

				ll x = pow(2, u) - a[i];
				// x が数列aに存在しない
				if (mp1[x] == 0) { continue; }
				// a[i] == x && 使えるa[i]が1以下ならダメ
				if (mp2[a[i]] == mp2[x]) {
					if (mp1[a[i]] - cnt_use[mp2[a[i]]] < 2) {
						continue;
					}
				}
				if (mp1[x] - cnt_use[mp2[x]] > 0) {
					++tmp;
					cnt_use[mp2[a[i]]] += 1;
					cnt_use[mp2[x]] += 1;
				}
			}
		}
		res = max(res, tmp);
	}

	cout << res << endl;

	return 0;
}

