void solve(){
  ini(N);
  vl a(N); in(a);
  multiset<ll> s;
  each(x , a) s.emplace(x);
  int ans = 0;
  while(sz(s) > 1){
    auto it = --s.end();
    ll val = *it;
    s.erase(it);
    ll p = 1LL << (msb(val) + 1);
    auto it2 = s.find(p - val);
    if(it2 != s.end()){
    trc(val , *it2);
      ans++;
      s.erase(it2);
    }
  }
  out(ans);
}

