int N;
vector<int> A;
vector<bool> used;

pair<int, int> dfs(int i, int parent) {
    used[i] = true;

    int c = 0;
    int j = i + 1;
    for (; j < N && A[j] == A[i]; ++j);
    c = j - i;

    int p = 0;
    rep(b, 1, 31) {
        int target = (1 << b) - A[i];
        if (target <= 0 || target == parent) continue;

        int k = lower_bound(all(A), target) - A.begin();
        if (k == N || used[k] || A[k] != target) continue;

        auto r = dfs(k, A[i]);
        p += r.first;
        p += min(c, r.second);
        c -= min(c, r.second);
    }

    return { p, c };
}

int dfs_bin(int i) {
    used[i] = true;

    int c = 0;
    for (int j = i + 1; j < N; ++j) if (A[j] != A[i]) {
        c = j - i;
        break;
    }

    int p = 0;
    rep(b, 1, 31) {
        int target = (1 << b) - A[i];
        if (target <= 0 || target == A[i]) continue;

        int k = lower_bound(all(A), target) - A.begin();
        if (k == N || used[k] || A[k] != target) continue;

        auto r = dfs(k, i);
        p += r.first;
        p += min(c, r.second);
        c -= min(c, r.second);
    }

    p += c / 2;
    return p;
}

int main() {
    cin >> N;
    A.resize(N);
    rep(i, N) cin >> A[i];
    sort(all(A));

    used.resize(N);

    int ans = 0;

    rep(b, 1, 31) {
        int target = 1 << b;
        int k = lower_bound(all(A), target) - A.begin();
        if (k == N || A[k] != target) continue;

        ans += dfs_bin(k);
    }

    for (int i = 0, j; i < N; i = j) {
        for (j = i + 1; j < N && A[j] == A[i]; ++j);

        if (!used[i]) {
            auto r = dfs(i, -1);
            ans += r.first;
        }
    }

    write(ans);
}

