int main() {
	int N;
	cin >> N;

	map<ll, int> mp;
	for(int i=0;i<N;i++) {
		ll a;
		cin >> a;
		mp[-a]++;
	}

	int ans = 0;
	while(!mp.empty()) {
		auto it = mp.begin();
		ll a = -it->first;
		ll p = 1;
		while(p <= a) {
			p <<= 1;
		}
		ll target = -(p - a);

		it->second--;
		if(it->second == 0) {
			mp.erase(it);
		}

		auto nit = mp.find(target);
		if(nit != mp.end()) {
			ans++;
			nit->second--;
			if(nit->second == 0) {
				mp.erase(nit);
			}
		}
	}
	cout << ans << endl;

	return 0;
}

