void solve(long long N, vector<long long> A){
	map<long long, ll> mp;

	for(int i = 0; i < N; ++i) {
		mp[A[i]]++;
	}
	sort(A.begin(), A.end());
	A.erase(unique(A.begin(), A.end()), A.end());
	long long res = 0;
	for(int k = 30; k > 0; --k) {
		long long t = 1LL << k;
		for(auto a: A) {
			ll b = t - a;
			if (a != b) {
				ll m = min(mp[a], mp[b]);
				mp[a] -= m;
				mp[b] -= m;
				res += m;
			} else {
				res += mp[a] / 2;
				mp[a] %= 2;
			}
		}
	}
	cout << res << endl;
}

