int binary_search_find_index(const std::vector<ll>& v, ll data) {
	auto it = std::lower_bound(v.begin(), v.end(), data);
	if (it == v.end() || *it != data) {
		return -1;
	}
	else {
		std::size_t index = std::distance(v.begin(), it);
		return index;
	}
}

//https://min-25.hatenablog.com/entry/2016/11/21/222625より引用
class MaximumMatching {
	/*
	Maximum Matching in General Graphs
	- O(nm \log_{\max\{2, 1 + m/n\}} n) time
	- O(n + m) space
	Note: each vertex is 1-indexed.
	*/

public:
	struct Edge { ll from, to; };

	MaximumMatching(ll N, const vector<Edge>& raw_edges) : N(N) {
		ofs.assign(N + 2, 0);
		for (auto& e : raw_edges) ++ofs[e.from + 1], ++ofs[e.to + 1];
		for (ll i = 1; i <= N + 1; ++i) ofs[i] += ofs[i - 1];
		edges.resize(2 * raw_edges.size());
		for (auto& e : raw_edges) {
			edges[ofs[e.from]++] = { e.from, e.to };
			edges[ofs[e.to]++] = { e.to, e.from };
		}
		for (ll i = N + 1; i > 0; --i) ofs[i] = ofs[i - 1];
		ofs[0] = 0;
	}

	ll maximum_matching() {
		vector<ll> label(N + 1, -1), mate(N + 1, 0), first(N + 1, 0);
		vector<ll> que(N);
		ll qh = 0, qt = 0;

		auto enqueue = [&](ll v) { que[qt++] = v; };
		auto dequeue = [&] { return que[qh++]; };
		auto encode = [&](ll eid) { return (N + 1) + eid; };
		auto decode = [&](ll h) { return h - (N + 1); };

		function< ll(ll) > find_first = [&](ll v) {
			return label[first[v]] < 0 ? first[v] : first[v] = find_first(first[v]);
		};

		function< void(ll, ll) > rematch = [&](ll v, ll w) {
			auto t = mate[v]; mate[v] = w;
			if (mate[t] != v) return;
			if (label[v] <= N) {
				mate[t] = label[v];
				rematch(label[v], t);
			}
			else {
				auto& e = edges[decode(label[v])];
				ll x = e.from, y = e.to;
				rematch(x, y); rematch(y, x);
			}
		};

		auto contract = [&](ll x, ll y, ll eid) {
			ll r = find_first(x), s = find_first(y);
			if (r == s) return;
			auto h = encode(eid);
			label[r] = label[s] = -h;
			ll join = -1; // mate[lca]
			while (1) {
				if (s != 0) swap(r, s);
				r = find_first(label[mate[r]]);
				if (label[r] == -h) {
					join = r;
					break;
				}
				else label[r] = -h;
			}
			for (auto v : { first[x], first[y] }) {
				for (; v != join; v = first[label[mate[v]]]) {
					label[v] = h;
					first[v] = join;
					enqueue(v);
				}
			}
		};

		auto augmented = [&](ll u) {
			label[u] = first[u] = 0;
			for (qh = qt = 0, enqueue(u); qh < qt; ) {
				auto x = dequeue();
				for (ll eid = ofs[x]; eid < ofs[x + 1]; ++eid) {
					auto y = edges[eid].to;
					if (mate[y] == 0 && y != u) {
						mate[y] = x;
						rematch(x, y);
						return true;
					}
					else if (label[y] >= 0) {
						contract(x, y, eid);
					}
					else if (label[mate[y]] < 0) {
						label[mate[y]] = x;
						first[mate[y]] = y;
						enqueue(mate[y]);
					}
				}
			}
			return false;
		};

		ll match = 0;
		for (ll u = 1; u <= N; ++u) if (mate[u] == 0 && augmented(u)) {
			match += 1;
			if (N - 2 * match <= 1) break;
			if (10 * qt < N) {
				label[0] = -1;
				for (ll qi = 0; qi < qt; ++qi) {
					label[que[qi]] = label[mate[que[qi]]] = -1;
				}
			}
			else fill(label.begin(), label.end(), -1);
		}

		/*
		vector< pair<ll, ll> > matching(match);
		match = 0;
		rep(u, 1, N + 1) if (mate[u] > u) {
		  matching[match++] = {u, mate[u]};
		}
		*/

		return match;
	}

private:
	ll N;
	vector<ll> ofs;
	vector<Edge> edges;
};

int main(void) {
	ll N;
	cin >> N;
	vec<ll> A(N);

	REP(i, N) {
		cin >> A[i];
	}
	sort(ALL(A));

	using Edge = MaximumMatching::Edge;
	vector<Edge> edges;
	REP(i, N) {
		for (int t = 1; t < 63; ++t) {
			ll x = (2LL << t) - A[i];
			if (x <= 0)continue;
			int id = binary_search_find_index(A, x);
			if (id != -1 && i != id) {
				edges.push_back({ 1 + i, 1 + id });
				if (A[i] == A[id]) {
					A[i] = A[i] - 1;
					A[id] = A[id] - 1;
					break;
				}
			}
		}
	}
	auto mm = MaximumMatching(N, edges);
	auto ans = mm.maximum_matching();
	cout << ans << endl;
	return 0;
}

