#define MAX_N (200000)
#define MAX_EXP (30)

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  int N, as[MAX_N];
  scanf("%d", &N);
  for (int i = 0; i < N; i++) {
    scanf("%d", &as[i]);
  }

  // sort
  sort(as, as + N);

  // create graph
  vector<int> used(N, 0);
  int ans = 0;
  for (int t = MAX_EXP; t > 0; t--) {
    const int pow2 = (1 << t);
    // remove all pow2/2
    const int k = (1 << (t - 1));
    int l = lower_bound(as, as + N, k) - as;
    while (l < N - 1 && as[l] == k && as[l + 1] == k) {
      used[l] = 1;
      used[l + 1] = 1;
      ans++;
      l += 2;
    }
    for (int i = 0; i < N; i++) {
      const int a_i = as[i];
      if (!used[i]) {
        // try to find pair
        const int a_j = pow2 - a_i;
        const int *it = lower_bound(as, as + N, a_j);
        if (it != as + N && it != as + i && *it == a_j) {
          const int j = it - as;
          if (!used[j]) {
            used[i] = 1;
            used[j] = 1;
            ans++;
          }
          // printf("%d + %d = %d\n", a_i, a_j, pow2);
        }
      }
    }
  }
  printf("%d\n", ans);

  return 0;
}

