vi vec;
int binary__search(int num)
{
	int lo = 0, hi = vec.size() - 1, mid;
	while (lo <= hi)
	{
		mid = (lo + hi) / 2;
		if (vec[mid] == num)
			return mid;
		if (vec[mid] > num)
			hi = mid - 1;
		else
			lo = mid + 1;
	}
	return -1;
}
