using namespace std;

typedef long long tint;



const tint MAXN = 262144;
const tint MAXA = 2000000000;
tint A[MAXN];
tint pot2[MAXN];

tint matched[MAXN];

int main()
{
	//~ #ifdef ACMTUYO
		//~ assert(freopen("entrada.in", "r", stdin));
	//~ #endif
	ios_base::sync_with_stdio(0);
	cin.tie(NULL);

	pot2[0] = 1;
	tint k = 1;
	while (pot2[k-1] < MAXA)
	{
		pot2[k] = (pot2[k-1]*2);
		k++;
	}
	tint n;
	//~ while (cin >> n)
	cin >> n;
	{
		map<tint,vector<tint> > hist;
		vector<vector<tint> > ladj (n);
		forn(i,n)
		{
			cin >> A[i];
			hist[A[i]].push_back(i);
			matched[i] = 0;
		}

		forn(i,n)
			forn(j,k)
				if (pot2[j] > A[i] && !hist[pot2[j]-A[i]].empty())
				{
					ladj[i].push_back(j);
					matched[i] += tint(hist[pot2[j]-A[i]].size()) - (pot2[j]==2*A[i]);
				}

		set<pair<tint,tint> > next_to;
		forn(i,n)
			if (matched[i] > 0)
				next_to.insert({matched[i],i});

		tint ans = 0;

		while (tint(next_to.size()) > 1)
		{
			pair<tint,tint> actual = *next_to.begin();
			tint x = actual.second;
			next_to.erase(next_to.find(actual));
			matched[x] = 0;
			pair<tint,tint> mini = {MAXA,MAXN};
			for (const auto &j : ladj[x])
				if (pot2[j] > A[x])
					for (const auto &y : hist[pot2[j]-A[x]])
					{
						if (x != y)
						{
							if (matched[y] > 0)
							{
								next_to.erase(make_pair(matched[y],y));
								matched[y]--;
								mini = min(mini,make_pair(matched[y],y));
								if (matched[y] > 0)
									next_to.insert(make_pair(matched[y],y));
							}
						}
					}
			tint y = mini.second;
			next_to.erase(make_pair(matched[y],y));
			matched[y] = 0;
			for (const auto &j : ladj[y])
				if (pot2[j] > A[y])
					for (const auto &z : hist[pot2[j]-A[y]])
					{
						if (matched[z] > 0)
						{
							next_to.erase(make_pair(matched[z],z));
							matched[z]--;
							if (matched[z] > 0)
								next_to.insert(make_pair(matched[z],z));
						}
					}
			ans++;
		}
		cout << ans << "\n";
	}
	return 0;
}

