long long solve();

int main() {
  cin >> n;
  for(long long i = 0; i < n; ++i) {
    long long x;
    cin >> x;
    a.push_back(x);
    ++mp[x];
  }
  sort(a.begin(), a.end(), greater<long long>());
  cout << solve() << endl;
  return 0;
