long long solve() {
  long long ans = 0;
  for(int i = 0; i < n; ++i) {
    for(long long j = 32; j >= 0; --j) {
      long long now = (1LL << j);
      if(now <= a[i]) break;
      if(mp[now - a[i]] > 0) {
        if(a[i] == now - a[i] && mp[a[i]] == 1) continue;
        ++ans;
        --mp[a[i]];
        --mp[a[now - a[i]]];
        break;
      }
    }
  }
  return ans;
}

