using namespace std;

bool used[100010];

struct Data {
  int a;
  vector<int> ids;
  int offset = 0;
  Data() {}
  void add(int a_, int id) { 
    a = a_;
    ids.push_back(id);
  }
  bool full() { return offset == ids.size(); }
  void use() {
    used[offset++] = true;
  }
};

int upperPow2(int a) {
  int ret = 2;
  while (ret < a) {
    ret += ret;
  }
  return ret;
}

struct A {
  int a;
  int id;
  A() {}
  A(int a, int id): a(a), id(id) {}
};

int main() {
  int n;
  cin >> n;
  vector<A> la;
  map<int, Data> remain;
  map<int, int> p2count;
  for (int i = 0; i < n; ++i) {
    int a;
    cin >> a;
    int p2 = upperPow2(a);
    if (p2 == a) ++p2count[p2];
    else remain[a].add(a, i);
    la.emplace_back(a, i);
  }
  sort(la.begin(), la.end(), [](const A& lhs, const A& rhs) {
    return lhs.a > rhs.a;
  });
  int ans = 0;
  for (A e: la) {
    if (used[e.id]) continue;
    int a = e.a;
    int p2 = upperPow2(a);
    int opp = p2-a;
    if (remain.find(opp) == remain.end()) continue;
    if (remain[opp].full()) continue;
    remain[opp].use();
    ++ans;
  }
  for (auto it: p2count) { 
    ans += it.second/2;
  }
  cout << ans << endl;
}

