    vnum.reserve(N);
    {
        vector<ll> vllnew;
        vllnew.push_back(vll[0]);
        vnum.push_back(1);
        for (int l = 1; l < L; ++l) {
            if (vll[l] == vll[l-1]) {
                vnum[vllnew.size()-1]++;
            } else {
                vllnew.push_back(vll[l]);
                vnum.push_back(1);
            }
        }
        vll = vllnew;
        L = vll.size();
    }

    vector<vi> G(L);
    for (int l = 0; l < L; ++l) {
        for (int t = 1; t <= 30; ++t) {
            auto it = find(vll.begin(), vll.end(), (1 << t) - vll[l]);
            if (it != vll.end()) {
                int m = (int)(it - vll.begin());
                G[l].push_back(m);
            }
        }
    }

    vi color(L, -1);
    vector<vi> vvi;
    function<void(int, int)> dfsC = [&](int v, int c)->void
    {
        for (int u: G[v]) {
            if (color[u] == -1) {
                vvi[c].push_back(u);
                color[u] = c;
                dfsC(u, c);
            }
        }
    };
    int C = 0;
