        if (color[l] == -1) {
            color[l] = C;
            vvi.push_back(vi(1, l));
            dfsC(l, C);
            ++C;
        }
    }

    int res = 0;
    for (int c = 0; c < C; ++c) {
        int num = 0;
        for (auto K = vvi[c].size(); K > 0; --K) {
            for (int k = 0; k < K; ++k) {
                int v = vvi[c][k];
                if (G[v].size() != 1) continue;
                remove(vvi[c].begin(), vvi[c].end(), v);
                if (G[v][0] == v) {
                    num += vnum[v] / 2;
                    G[v].clear();
                } else {
                    num += vnum[v];
                    vnum[G[v][0]] -= vnum[v];
                    G[v].clear();
                    remove(G[G[v][0]].begin(), G[G[v][0]].end(), v);
                }
                break;
            }
        }

        res += num;
    }

    cout << res << endl;

    return 0;
}

