i64 CLZ(i64 x) {
    return x == 0 ? 64 : __builtin_clzll(x);
}

bool is_pow2(i64 x) {
    ASSERT(x > 0);
    return (x&(x-1)) == 0;
}

i64 pow2_ceil(i64 x) {
    ASSERT(x > 0);
    return 1LL << (64-CLZ(x-1));
}

void solve() {
    i64 N = RD();

    multiset<i64,greater<>> s;
    REP(_, N) {
        s.emplace(RD());
    }
    DBG(s);

    i64 ans = 0;
    while(SIZE(s) >= 2) {
        i64 a = *begin(s);
        i64 b = is_pow2(a) ? a : pow2_ceil(a)-a;
        s.erase(begin(s));
        auto it = s.find(b);
        if(it != end(s)) {
            ++ans;
            s.erase(it);
        }
        DBG(s);
    }

    PRINTLN(ans);
}

