using namespace std;

const int MAXN=200111;

int N;
int Ans=0;

int A[MAXN];

struct Node{
	int v, c;
} T[MAXN];

int Tc;

inline int lowbit(int a){
	return a&(-a);
}

bool Norm(int v){
	return lowbit(v)==v;
}

int Val(int v){
	int r=1;
	while(r<=v)	r<<=1;
	return r;
}

bool Find(int v, int l, int r){
	if(l>r || T[l].v>v)	return false;
	int m;
	while(l<r){
		m=(l+r)>>1;
		if(T[m+1].v>v)	r=m;
		else	l=m+1;
	}
	m=(l+r)>>1;
	if(T[m].v!=v)	return false;
	if(!T[m].c)	return false;
	--T[m].c;++Ans;
	return true;
}

int main(){
	ios_base::sync_with_stdio(false);

	cin >> N;

	for(int i=1;i<=N;++i)	cin >> A[i];

	sort(A+1, A+N+1);

	for(int i=1, c=0;i<=N;++i){
		++c;
		if(i==N || A[i]!=A[i+1]){
			++Tc;
			T[Tc].v=A[i];T[Tc].c=c;
			c=0;
		}
	}

	for(int i=N;i>=1;--i){
		if(Norm(T[i].v)){
			Ans+=T[i].c>>1;
			T[i].c&=1;
		}
		for(int k=1;k<=T[i].c;++k){
			if(!Find(Val(T[i].v)-T[i].v, 1, i-1))	break;
		}
	}

	cout << Ans << endl;

	return 0;
}

