		int sum = 1 << e;
		fore (i, 0, n) {
			ll* b = lower_bound(ns + i + 1, ns + n, sum - ns[i]);
			if (b != ns + n && *b == sum - ns[i]) {
				//cerr << ns[i] << " + " << *b << " = " << sum << endl;
				pots.push_back({ns[i], *b});
			}
		}
	}

	for (auto v : pots) {
		//cerr << v.first << " -- " << v.second << endl;
		g[v.first].insert(v.second);
		g[v.second].insert(v.first);
		cants[v.first].cands++;
		cants[v.second].cands++;
	}

	for (const auto& c : cants)
		cands.emplace(c.second.cands, c.second.n);

	ll count = 0;
	for (auto n = cands.begin(); n != cands.end(); n = cands.begin()) {
		ll menos_cands = 9999999;
		ll match = 0;
		for (auto v : g[n->second]) {
			if (cants[v].cands < menos_cands
				&& ((v != n->second && cants[v].cant > 0)
					|| (v == n->second && cants[v].cant > 1)))
				menos_cands = cants[v].cands, match = v;
		}
		if (menos_cands == 9999999) {
			cants.erase(n->second);
			cands.erase(n);
			continue;
		}
		//cerr << "Puedo usar " << match << " con " << n->second << endl;
		ll& ncant = cants[n->second].cant;
		ll& ncand = cants[n->second].cands;
		ll& mcant = cants[match].cant;
		ll& mcand = cants[match].cands;
		ll cmatches = min(ncant, mcant);
		if (match != n->second)
			cands.erase(make_pair(mcand, match));
		if (match == n->second)
			cmatches /= 2;
		ncant -= cmatches;
		mcant -= cmatches;
		ncand -= cmatches;
		mcand -= cmatches;
		if (match != n->second && ncant)
			cands.insert(make_pair(ncand, n->second));
		if (mcant)
			cands.insert(make_pair(mcand, match));
		cands.erase(n);
		count++;

	}
	cout << count << endl;
	return 0;
}

