}


int main(){

    long long N; cin >> N;

    std::vector<long long> v;
    for(long long i=0; i<N; i++){
        long long temp; cin>>temp;
        v.push_back(temp);
    }

    sort(v.begin(),v.end());

    long long left=0;
    long long right=N-1;
    long long cnt=0;

    while(left<right){

        if(beki(v[left]+v[right])){
            cnt+=1;
            left++;
            right--;
        } else {
            if(left+1 == right-1){
                left++;
                right--;               
            } else {
                if(v[right]-v[right-1] > v[left+1]-v[left]){
                    left++;
                } else{
                    right--;
                }
            }
        }
    }   

    cout << cnt <<endl;
    return 0;

}

