int main(){
	int N; cin >> N;
	vector<int> A(N);
	rep(i,N) cin >> A[i];
	sort(A.rbegin(),A.rend());
	multiset<int> st;
	rep(i,N) st.insert(A[i]);
	int ans = 0;
	rep(i,N){
		int cnt = 0;
		int k = A[i];
		while(k > 0){
			k /= 2;
			cnt++;
		}
		int d = (1<<cnt)-A[i];
		if(A[i] < d) continue;
		int a = st.count(A[i]);
		int b = st.count(d);
		if(a == 0) continue;
		if(A[i] == d){
			ans += a/2;
			st.erase(A[i]);
			continue;
		}
		st.erase(A[i]);
		if(st.find(d) != st.end()){
			st.erase(d);
			ans += min(a,b);
		}

	}
	cout << ans << endl;
}

