int power[40];
int len=0;
int main()
{
	int n;
	scanf("%d",&n);
	for(int i=0;i<n;i++)
		scanf("%d",&a[i]),mp[a[i]]++;
	sort(a,a+n);
	for(ll i=2;i<=2000000000;i*=2)
		power[len++]=i;
	ll sum=0;
	for(int i=n-1;i>=0;i--)
	{
		for(int k=len-1;k>=0;k--)
		{

			if(power[k]>a[i])
			{
				int q=a[i];
				int b=power[k]-q;
				int c,d;

				c=mp[q];
				d=mp[b];
				if(d!=0)
				{
				//	printf("%d %d %d %d\n",q,b,c,d);
					if(b==q)
						sum+=((ll)c*(ll)(d-1));
					else
						sum+=(ll)c*(ll)d;
					mp[q]=mp[b]=0;
				}
			}
		}
	}
	printf("%lld\n",sum);
	return 0;
}

