void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;
	FOR(i,N) cin>>x, M.insert(x);

	int ret=0;
	while(M.size()) {
		x=*M.rbegin();
		M.erase(M.find(x));

		for(int i=32;i>=0;i--) {
