const LL MOD = 1e9+7;

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N;
  cin >> N;
  VI xs(N);
  cin >> xs;

  map<int,int> cnt;
  for(int x: xs) ++cnt[x];

  LL MX = 2e9;
  map<int,VI> G;
  map<int,int> in;
  for(auto& p: cnt){
	LL p2 = 1;
	for(;p2<=MX;p2<<=1){
	  LL r = p2 - p.FF;
	  if(r > 0 && cnt.count(r)){
		G[p.FF].PB(r);
		in[r]++;
	  }
	}
  }

  queue<int> q;
  for(auto& p: in){
	if(p.SS == 1){
	  q.push(p.FF);
	}
  }

  int ans = 0;
  while(!q.empty()){
	int u = q.front();
	q.pop();
	int& w = cnt[u];
	for(auto to: G[u]){
	  int rw = min(w, u != to ? cnt[to] : cnt[to] / 2);
	  w -= rw;
	  cnt[to] -= rw;
	  ans += rw;

	  --in[to];
	  if(in[to] == 1){
		q.push(to);
	  }
	}
  }
  cout << ans << endl;


  return 0;
}

