pair<lli,lli> calc(int u, int p){
    lli remain = sz[u];
    dp[u] = 0;
    for(auto s: e[u]){
        if(s==p)continue;
        if(s==u){
            lli p = remain/2;
            remain = remain - 2 * p;
            dp[u] += p;
            continue;
        }
        auto res = calc(s,u);
        dp[u] += res.second;
        if(res.first > remain){
            dp[u] += remain;
            remain = 0;
        }else {
           remain -= res.first;
           dp[u] += res.first;
        }
    }
    //cout << u << " " << dp[u] << endl;
    return make_pair(remain, dp[u]);
}
