ll pow(int n) {
    ll ret = 1;
    ll x = 2;
    while (n > 0) {
        if (n & 1) ret *= x;
        x *= x;
        n >>= 1;
    }
    return ret;
}

bool C1(ll x, int k) {
    if (x < pow(k)) return true;
    return false;
}

bool C2(ll x, int k) {
    if (x <= a[k]) return true;
    return false;
}


int main() {
