    }
    sort(a.begin(), a.end());

    int ans = 0;
    while (n > 1) {
        ll x = a[n - 1];
        --n;

        int ok = 30;
        int ng = 0;
        while (abs(ok - ng) > 1) {
            int mid = (ok + ng) / 2;
            if (C1(x, mid)) ok = mid;
            else ng = mid;
        }

        ll b = pow(ok) - x;

        ok = n - 1;
        ng = -1;
        while (abs(ok - ng) > 1) {
            int mid = (ok + ng) / 2;

            if (used[mid]) {
                ++mid;
                continue;
            }

            if (C2(b, mid)) ok = mid;
            else ng = mid;
        }

        if (a[ok] == b) {
            ++ans;
            used[ok] = true;
            --n;
        }
    }

