            auto t = lower_bound(a, a + N, Must[j] - a[i]) - a;
            if (t != N)
            {

                auto t2 = upper_bound(a, a + N, Must[j] - a[i]) - lower_bound(a, a + N, Must[j] - a[i]);
                for (int k = 0; k < t2; ++k)
                {
                    if (i > t + k)
                    {
                        if (s1.count({t + k, i}) == 0)
                        {
                            s2.insert(t + k);
                            vp.push_back({t + k, i});
                            s1.insert({t + k, i});
                        }
                    }
                    else if (i < t + k)
                    {
                        if (s1.count({i, t + k}) == 0)
                        {
                            s2.insert(i);
                            vp.push_back({i, t + k});
                            s1.insert({i, t + k});
                        }
                    }
                }
            }
        }
    }
    bipartite_matching bm(s1.size());

    int arr1[100010];
    int arr2[100010];
    for (int i = 0; i < N; ++i)
    {
        arr1[i] = -1;
        arr2[i] = -1;
    }
    int idx1 = 0, idx2 = 0;
    for (int i = 0; i < (int)vp.size(); ++i)
    {
        if (arr1[vp[i].first] != -1 && arr2[vp[i].second] != -1)
        {
            bm.add_edge(arr1[vp[i].first], arr2[vp[i].second]);
        }
        else if (arr1[vp[i].first] == -1 && arr2[vp[i].second] == -1)
        {

            arr1[vp[i].first] = idx1;
            arr2[vp[i].second] = idx2;
            idx1++;
            idx2++;
            bm.add_edge(arr1[vp[i].first], arr2[vp[i].second]);
        }
        else if (arr1[vp[i].first] == -1)
        {
            arr1[vp[i].first] = idx1;
            idx1++;

            bm.add_edge(arr1[vp[i].first], arr2[vp[i].second]);
        }
        else
        {
            arr2[vp[i].second] = idx2;
            idx2++;

            bm.add_edge(arr1[vp[i].first], arr2[vp[i].second]);
        }
    }
