#define all(c) (c).begin(), (c).end()

struct graph {
  int L, R;
  vector<vector<int>> adj;
  graph(int L, int R) : L(L), R(R), adj(L + R) {}
  void add_edge(int u, int v) {
    adj[u].push_back(v + L);
    adj[v + L].push_back(u);
  }
  int maximum_matching() {
    vector<int> visited(L), mate(L + R, -1);
    function<bool(int)> augment = [&](int u) {  // DFS
      if (visited[u]) return false;
      visited[u] = true;
      for (int w : adj[u]) {
        int v = mate[w];
        if (v < 0 || augment(v)) {
          mate[u] = w;
          mate[w] = u;
          return true;
        }
      }
      return false;
    };
    int match = 0;
    for (int u = 0; u < L; ++u) {
      fill(all(visited), 0);
      if (augment(u)) ++match;
    }
    return match;
  }
};

int main() {
  int N;
  while (cin >> N) {
    vector<int> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    map<int, vector<int>> nums;
    for (int i = 0; i < N; i++) nums[A[i]].push_back(i);
    graph g(N, N);
    for (int i = 0; i < N; i++) {
      for (int k = 0; k < 40; k++) {
        ll pw = 1l << k;
        if (pw < A[i]) continue;
        for (int j : nums[pw - A[i]]) {
          if (j <= i) continue;
          g.add_edge(i, j);
        }
      }
    }
    cout << g.maximum_matching() << endl;
  }
  return 0;
}

