struct IO {
#ifdef _WIN32
  inline char getchar_unlocked() { return getchar(); }
  inline void putchar_unlocked(char c) { putchar(c); }
#endif
  string separator = " ";
  template <class T>
  inline void read(T &x) {
    char c;
    do {
      c = getchar_unlocked();
    } while (c != '-' && (c < '0' || '9' < c));
    bool minus = 0;
    if (c == '-') {
      minus = 1;
      c = getchar_unlocked();
    }
    x = 0;
    while ('0' <= c && c <= '9') {
      x *= 10;
      x += c - '0';
      c = getchar_unlocked();
    }
    if (minus) x = -x;
  }
  inline void read(string &x) {
    char c;
    do {
      c = getchar_unlocked();
    } while (c == ' ' || c == '\n');
    x.clear();
    do {
      x += c;
      c = getchar_unlocked();
    } while (c != ' ' && c != '\n' && c != EOF);
  }
  template <class T>
  inline void read(vector<T> &v) {
    for (auto &x : v) read(x);
  }
  template <class Head, class... Tail>
  inline void read(Head &head, Tail &... tail) {
    read(head);
    read(tail...);
  }
  template <class T>
  inline void write(T x) {
    char buf[32];
    int p = 0;
    if (x < 0) {
      x = -x;
      putchar_unlocked('-');
    }
    if (x == 0) putchar_unlocked('0');
    while (x > 0) {
      buf[p++] = (x % 10) + '0';
      x /= 10;
    }
    while (p) {
      putchar_unlocked(buf[--p]);
    }
  }
  inline void write(string x) {
    for (char c : x) putchar_unlocked(c);
  }
  inline void write(const char s[]) {
    for (int i = 0; s[i] != 0; ++i) putchar_unlocked(s[i]);
  }
  template <class T>
  inline void write(vector<T> v) {
    for (auto itr = v.begin(); itr + 1 != v.end(); ++itr) {
      write(*itr);
      write(separator);
    }
    write(v.back());
  }
  template <class Head, class... Tail>
  inline void write(Head head, Tail... tail) {
    write(head);
    write(separator);
    write(tail...);
  }
  void set_separator(string s) { separator = s; }
} io;

int main() {
  int N;
  io.read(N);
  vector<int> A(N);
  io.read(A);
  map<int, int> mp, degs;
  REP(i, N) mp[A[i]]++;
  for (auto p : mp) {
    int ct = 0;
    REP(x, 30) {
      int t = 1 << x;
      int pad = t - p.first;
      int y = 0;
      if (mp.count(pad)) y = mp[pad];
      if (p.first == pad) {
        y--;
      }
      if (y > 0) {
        ct += y;
      }
    }
    degs[p.first] = ct;
  }
  int ans = 0;
  REP(i, N) {
    if (mp[A[i]] < 1) continue;
    mp[A[i]]--;
    int best = N, best_pad = -1;
    REP(x, 30) {
      int t = 1 << x;
      int pad = t - A[i];
      int deg = 0;
      if (degs.count(pad)) deg = degs[pad];
      if (deg > 0 && best > deg) {
        best = deg;
        best_pad = pad;
      }
    }
    if (best < N) {
      ans++;
      degs[best_pad]--;
      if (best_pad == A[i]) degs[best_pad]--;
      if (degs[best_pad] == 0) degs.erase(best_pad);
      mp[best_pad]--;
    }
  }
  io.write(ans);
  io.write("\n");
  return 0;
}

