int bsearch(int b,int e,long* arr,long dst){
  if(arr[b]==dst) return b;
  if(arr[e]==dst) return e;
  int m = (b+e)/2;
  if(b==m) return -1;
  if(arr[m]<dst) return bsearch(m,e,arr,dst);
  else if(arr[m]>dst) return bsearch(b,m,arr,dst);
  return m;
}
int main() {
  int n;
  cin >> n;
  long a[200000];
  for(int i=0;i<n;i++) {
    cin >> a[i];
  }
  int count = 0;
  sort(a,a+n);
  for(int i=n-1;i>=0;i--){
    if(a[i]==-1) continue;
    long t = 1;
    while(t<=a[i]) t <<= 1;
    long ser = t - a[i];
    int bs = bsearch(0,i,a,ser);
    if(bs==-1) continue;
    if(bs==i){
      if(i==0 || a[i-1]!=ser) continue;
    }
    count ++;
    a[bs] = -1;
  }
  cout << count << endl;
  return 0;
}

