				if (v[N - 1] < pow2(2, i) / 2)continue;
				ll x = pow2(2, i) - v[j];
				if (binary_search(v.begin(), v.end(), x)) {
					if (v[j] == x) {
						if (mp[x] >= 2) {
							ans++;
							mp[x] -= 2;
						}
					}
					else {
						if (mp[x] >= 1) {
							ans++;
							mp[x]--;
							mp[v[j]]--;
						}
					}
				}
			}
		}
	}
	cout << ans << endl;
}

