long long int ret = 0;
int lowid, midid, highid;
long long int target = 0;

long long int nearPow = 1;

int find = 0;


void q_sort(long long int numbers[], int left, int right) {
  int pivot, l_hold, r_hold;

  l_hold = left;
  r_hold = right;
  pivot = numbers[left];
  while (left < right) {
    while ((numbers[right] >= pivot) && (left < right))
      right--;
    if (left != right) {
      numbers[left] = numbers[right];
      left++;
    }
    while ((numbers[left] <= pivot) && (left < right))
      left++;
    if (left != right) {
      numbers[right] = numbers[left];
      right--;
    }
  }
  numbers[left] = pivot;
  pivot = left;
  left = l_hold;
  right = r_hold;
  if (left < pivot)
    q_sort(numbers, left, pivot-1);
  if (right > pivot)
    q_sort(numbers, pivot+1, right);
}

void quickSort(long long int numbers[], int array_size) {
  //q_sort(numbers, 0, array_size - 1);
  std::sort(numbers, numbers+array_size);
}

void solve(int x) {
  if (x > 0){
    if ((p[x - 1] & (p[x - 1] - 1)) == 0) {
      if (p[x - 2] == p[x - 1]) {
        c += 1;
        solve(x - 2);
      } else {
        solve(x - 1);
      }
    } else {
      nearPow = pow(2.0, (floor(log2(p[x - 1] - 1)) + 1.0));
      target = nearPow - p[x - 1];

      highid = x;
      lowid = 0;
      find = 0;

      while (lowid <= highid) {
        midid = (lowid + highid) / 2;
        if (p[midid] == target) {
          c += 1;
          find = 1;
          break;
        } else if (p[midid] < target) {
          lowid = midid + 1;
        } else {
          highid = midid - 1;
        }
      }
      if (find == 1) {
        for (int i = midid; i < x; i++) {
          p[i] = p[i + 1];
        }
        solve(x - 2);
      } else {
        solve(x - 1);
      }
    }
  }
}

int main() {
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%lld", &p[i]);
  }
  quickSort(p, n);
  solve(n);
  printf("%lld\n", c);

  return 0;
}

