  for (int i = 0; i < n; i++) {
    std::cin >> input.at(i);
  }
  std::unordered_map<int, int> cnt;
  for (auto x : input) {
    auto it = cnt.find(x);
    if (it == cnt.end()) {
      cnt[x] = 1;
    } else {
      cnt[x]++;
    }
  }
  std::sort(input.begin(), input.end());
  int npairs = 0;
  for (auto it = input.rbegin(); it != input.rend(); it++) {
