namespace IntegerMath
{
  int64_t sqrt(int64_t x) {
    return static_cast<int64_t>(
      ::floorl( ::sqrtl( 
        static_cast<long double>(x)
      ) )
    );
  }

  int64_t log2(int64_t x) {
    return static_cast<int64_t>(
      ::floorl( ::log2l( 
        static_cast<long double>(x)
      ) )
    );
  }    

  int64_t log10(int64_t x) {
    return static_cast<int64_t>(
      ::floorl( ::log10l( 
        static_cast<long double>(x)
      ) )
    );
  }

  int64_t number_of_digits(int64_t x) {
    return static_cast<int64_t>(
      ::ceill( ::log10l( 
        static_cast<long double>(x + 1)
      ) )
    );
  }

  uint64_t gcd(uint64_t a, uint64_t b)
  {
    uint64_t n = std::min(a, b), m = std::max(a, b);
    return (n == 0) ? m : gcd(m % n, n);
  }

  uint64_t lcm(uint64_t a, uint64_t b)
  {
    uint64_t d = gcd(a, b);
    return (a % d == 0) ? (a / d) * b : a * (b / d);
  }
};

int main(int argc, char **argv)
{
  uint64_t N;
  std::cin >> N;

  std::vector<uint64_t> A(N);
  N_TIMES(n, N) {
    std::cin >> A[n];
  }
  std::sort(A.begin(), A.end(), std::greater<uint64_t>());
  //std::cerr << A << std::endl;

  std::map<uint64_t, uint64_t> cache;
  N_TIMES(n, N) {
    auto itr = cache.find(A[n]);
    if (itr == cache.end()) {
      cache.emplace(A[n], 1);
    } else {
      ++cache[A[n]];
    }
  }

  uint64_t count = 0;
  N_TIMES(n, N) {
    if (cache[A[n]] == 0) { continue; }

    uint64_t k = IntegerMath::log2(2 * A[n]);
    uint64_t p = (1 << k) - A[n];

    auto itr = cache.find(p);

    if (itr != cache.end() && cache[p] > 0) {
      if ((A[n] != p) || (A[n] == p && cache[A[n]] >= 2)) {
        --cache[A[n]];
        --cache[p];

        ++count;
      }
    }
  }
  std::cout << count << std::endl;

  return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> graph(200000);
vector<bool> done(200000);
vector<bool> used(200000);
void dfs(int v, int &cnt) {
    if (done.at(v)) return;

    done.at(v) = true;
    for (int i = 0; i < (int)graph.at(v).size(); i++) {
        int to = graph.at(v).at(i);
        if (done.at(to)) continue;

        dfs(to, cnt);
    }

    for (int i = 0; i < (int)graph.at(v).size(); i++) {
        if (!used.at(v) && !used.at(graph.at(v).at(i))) {
            cnt++;
            used.at(v) = true;
            used.at(graph.at(v).at(i)) = true;
            return;
        }
    }
}

int main() {
    int n;
    cin >> n;
    map<int, int> m;
    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        for (int j = 1; j <= 30; j++) {
            int x = (1 << j) - a;
            if (0 <= x && x <= 1000000000) {
                if (m.count(x)) {
                    graph.at(m[x]).push_back(i);
                    graph.at(i).push_back(m[x]);
                }
            }
        }
        if (!m.count(a)) m[a] = i;
    }

    int cnt = 0;
    for (int i = 0; i < n; i++) {
        dfs(i, cnt);
    }

    cout << cnt << endl;
}

