	int maxflow(std::vector<std::map<int, int>>& edge, int start, int goal)
	{
		struct node_t
		{
			int prev;
			int cap;
		};
		std::vector<boost::optional<int>> node(edge.size());
		int ret = 0;
		while (true)
		{
			for (auto& n : node)
			{
				n = boost::none;
			}
			std::queue<std::pair<int, node_t>> queue;
			for (auto const& e : edge[start])
			{
				if (e.second != 0)
				{
					queue.emplace(e.first, node_t{ 0, e.second });
				}
			}
			while (queue.size())
			{
				auto top = queue.front();
				queue.pop();
				if (node[top.first])
				{
					continue;
				}
				node[top.first] = top.second.prev;
				if (top.first == goal)
				{
					int flow = top.second.cap;
					int v = goal;
					while (v != 0)
					{
						edge[v][*node[v]] += flow;
						edge[*node[v]][v] -= flow;
						v = *node[v];
					}
					ret += flow;
					goto next;
				}
				for (auto const& e : edge[top.first])
				{
					if (e.second != 0)
					{
						queue.emplace(e.first, node_t{ top.first,std::min(top.second.cap,e.second) });
					}
				}
			}
			break;
		next:;
		}
		return ret;
	}
}

bool check(std::vector<std::map<int, int>>const& edge, std::vector<int>& flag, int now, int c)
{
	if (flag[now] != 0)
	{
		return flag[now] == c;
	}
	flag[now] = c;
	for (auto const& v : edge[now])
	{
		if (!check(edge, flag, v.first, 3 - c))
		{
			return false;
		}
	}
	return true;
}

void Main()
{
	int N;
	std::cin >> N;
	lib::randomizer random;
	const std::uint32_t max = 0b111111111111111111111111111111;
	std::map<std::uint32_t, int> count;
	for (auto i : boost::irange(0, N))
	{
		std::uint32_t c;
		std::cin >> c;
		++count[c];
	}
	std::map<std::uint32_t, int> indexes;
	int index = -1;
	int K = count.size();
	std::vector<std::uint32_t> data(K);
	for (auto p : count)
	{
		indexes[p.first] = ++index;
		data[index] = p.first;
	}
	std::vector<std::map<int, int>> edge(K + 2);
	for (std::uint32_t i = 1; i <= max + 1; i <<= 1)
	{
		for (int k : boost::irange(0, K))
		{
			auto d = data[k];
			if (d >= i)
			{
				continue;
			}
			if (i - d != d && indexes.count(i - d))
			{
				edge[k].emplace(indexes[i - d], std::min(count[d], count[i - d]));
			}
		}
	}
	std::vector<int> flag(K);
	for (int i : boost::irange<int>(0, K))
	{
		if (flag[i] != 0)
		{
			continue;
		}
		if (!check(edge, flag, i, 1))
		{
			throw std::logic_error("");
		}
	}
	for (int i : boost::irange(0, K))
	{
		if (flag[i] == 1)
		{
			edge[i].emplace(K, 1);
			edge[K].emplace(i, 1);
		}
		else
		{
			edge[i].emplace(K + 1, 1);
			edge[K + 1].emplace(i, 1);
		}
	}
	out::write_line(lib::maxflow(edge, K, K + 1));
}

