void input() {
    cin >> N;
    A.resize(N);
    for (auto& v : A)
        cin >> v;
//    N = 7;
//    A = {3, 11, 14, 5, 13, 3, 5};
}

ll solve() {
    sort(A.begin(), A.end());
    unordered_map<ll, ll> fmap;
    unordered_map<ll, ll> ocmap;
    for (ll i = 0; i < N; i++) {
        auto a = A[i];
        fmap[a]++;
    }
    for (ll i = 0; i < N; i++) {
        auto a = A[i];
        for (int k = 32; (1ULL << k) > a; k--) {
            ll tag = (1ULL << k) - a;
            if (fmap.find(tag) == fmap.end())
                continue;
            ocmap[tag]++;
        }
    }

    vector<P> cmap;
    for (auto m : ocmap) {
        cmap.emplace_back(m);
    }
    sort(cmap.begin(), cmap.end(), [&fmap](auto l, auto r) {
        return (l.second != r.second ? l.second < r.second :
                fmap[l.first] < fmap[r.first]);
    });
    unordered_map<ll, ll> cmapi;
    for (ll i = 0; i < cmap.size(); i++) {
        cmapi[cmap[i].first] = i;
    }

    ll ans = 0;
    for (ll i = 0; i < cmap.size(); i++) {
        auto n = cmap[i].first;
        if (fmap.find(n) == fmap.end() || fmap[n] <= 0)
            continue;

        ll min_v = 99999;
        ll min_n = 0;
        ll max_c = 0;
        for (int k = 32; (1ULL << k) > n; k--) {
            auto tag = (1ULL << k) - n;
            if (fmap.find(tag) == fmap.end() ||
                fmap[tag] <= (tag == n ? 1 : 0))
                continue;
            auto tm = cmap[cmapi[tag]];
            if (tm.second < min_v) {
                min_v = tm.second;
                min_n = tag;
            } else if (tm.second == min_v) {
                if (fmap[tag] < max_c) {
                    max_c = fmap[tag];
                    min_n = tag;
                }
            }
        }
        if (min_n != 0) {
            ans++;
            fmap[min_n]--;
            fmap[n]--;
            i--;
        }
    }
    return ans;
}


