unsigned np(int n){
    // nが0以下の時は0とする。
    if (n <= 0) return 0;

    // (n & (n - 1)) == 0 の時は、nが2の冪乗であるため、そのままnを返す。
    if ((n & (n - 1)) == 0) return (unsigned)n;

    // bitシフトを用いて、2の冪乗を求める。
    unsigned ret = 1;
    while (n > 0) { ret <<= 1; n >>= 1; }
    return ret;
}

