long int answer(vector<long int> box, long int t){
    if(box.size()<2) return t;
    long int x = box.back();
    long int y=2;
    box.pop_back();
    while(y<x){
        y*=2;
    }
//    cout << y <<" " << x <<endl;
    vector<long int>::iterator ans=find(box.begin(),box.end(),y-x);
    if(ans!=box.end()){
        box.erase(ans);
        t=answer(box,t+1);
    }else{
        t=answer(box,t);
    }
    return t;
}

