int main()
{
    int N;
    cin >> N;
    vector<int> A(N);
    rep(i, N) cin >> A[i];

    unordered_map<int, set<int>> a_to_indice;
    rep(i, N) a_to_indice[A[i]].insert(i);

    // make pair
    int npair = 0;
    sort(A.rbegin(), A.rend());
    rep(i, N)
    {
        int a = A[i];
        if (a == 0)
