void solve()
{
	int n, answ = 0;
	multiset<int> setik;

	cin >> n;

	while(n--)
	{
		int x;
		cin >> x;

		setik.insert(x);
	}

	while(!setik.empty())
	{
		int mx = *prev(setik.end());
		setik.erase(prev(setik.end()));

		for(int s = 0; s < 31; ++s)
		{
			int r = 1 << s;

			if(r - mx < 1 || r - mx > mx)
				continue;

			auto iter = setik.lower_bound(r - mx);

			if(iter == setik.end() || *iter != r - mx)
				continue;

			++answ;
			setik.erase(iter);

			break;
		}
	}

	cout << answ << endl;
}

int main()
{
	fast_io();
	solve();

	return 0;
}

