const int MAX_N = 2e5+10;
int a[MAX_N];
int N;

void solve()
{
	sort(a, a+N);
	int ans = 0;
	multiset<int> have;
	for(int i=0;i<N;++i) have.emplace(a[i]);
	while(!have.empty()){
		long long biggest = *have.rbegin();
		have.erase(have.rbegin());
		long long sum = 1;
		while(sum <= biggest) sum <<= 1;
		auto it = have.find(sum-biggest);
		if(it != have.end()){
			ans++;
			have.erase(it);
		}
	}
	cout << ans << endl;
}

int main()
{
	cin >> N;
	for(int i=0;i<N;++i) cin >> a[i];
	solve();
	return 0;
}

