		}
		dfs(v,u);
		sum+=cnt[v];
	}
	if(sum<cnt[u]){
		cnt[u]-=sum;
		ans+=sum;
		if(sum){
			ans+=cnt[u]>>1;
			cnt[u]=cnt[u]&1;
		}
	}else{
		ans+=cnt[u];
		cnt[u]=0;
	}
	return;
}

