    cin >> A[i];
  }

  multiset<ll> ms;
  for(int i = 0; i < N; i++){
    ms.insert(A[i]);
  }

  sort(A.begin(), A.end(), greater<ll>());

  ll ans = 0;
  for(int i = 0; i < N; i++){
