	return dist[nil] != INF;
}

bool dfs(int u){
	if(u != nil){
		for(int v : adj[u]){
			if(dist[match[v]] != dist[u]+1)
				continue;
			if(dfs(match[v])){
				match[v] = u;
				match[u] = v;
				return true;
			}
		}
		dist[u] = INF;
		return false;
	}
	return true;
}

int bipMatching(){
	nil = n+m+1;
	for(int i = 1; i <= n+m; ++i)
		match[i] = nil;
	int matching = 0;
	while(bfs()){
		for(int i = 1; i <= n; ++i)
			if(match[i] == nil and dfs(i))
				++matching;
	}
	return matching;
}

