        if(choice == -1) continue;

        counts[x]--;
        counts[choice]--;
        if(counts[x] == 0)
            graph[choice].erase(x);
        if(counts[choice] == 0)
            graph[x].erase(choice);

        pairs++;
    }

    cout << pairs << endl;
