int main() {
  int N=0;
  cin >> N;
  vector<int> vA(N),next(N);
  vector<bool> able(N,true);
  int n_2 = 2;
  for (int i=0; i<N; i++) {
    cin >> vA.at(i);
  }
  sort(vA.begin(),vA.end());
  int count = 0;

  for (int i=0; i<N; i++) {
    n_2 = 2;
    for (int j=0; j<100; j++) {
      if (vA.at(i) < n_2) {
        next.at(i) = n_2;
        break;
      }
      n_2 = n_2 * 2;
    }
  }

  for(int i=0; i<N; i++) {
    cerr << vA.at(i) << ' ' << next.at(i) << endl;
  }

  int small,big,mid,plus;

  for (int i=N-1; i>0; i--) {
    if (able.at(i) == false) {
      continue;
    }
    big = i;
    small = -1;
    plus = 0;
    while (big - small > 1) {
      mid = (big + small)/2 + plus;
      if (mid == i) {
        big --;
        continue;
      }
      if (able.at(mid) == false) {
        plus++;
        continue;
      }
      if (vA.at(i) + vA.at(mid) == next.at(i)) {
        count++;
        able.at(i) = false;
        able.at(mid) = false;
        break;
      }
      if (vA.at(i) + vA.at(mid) > next.at(i)) {
        big = mid;
      }
      if (vA.at(i) + vA.at(mid) < next.at(i)) {
        small = mid;
      }
      if (mid == big) {
        big -= plus;
        plus = 0;
      }
    }
  }

  cout << count << endl;
}

