void find(){
    int tw = 1;
    for (int i = 1; i < 40; ++i) {
        tw *= 2;
        for (int j = 0; j < A.size() - 1; ++j) {
            int a = A[j];
            if(a >= tw){
                break;
            }
            for (int k = j+1; k < A.size(); ++k) {
                int b = A[k];
                if(a+b == tw){
                    B.insert(make_pair(j,k));
                    B.insert(make_pair(k,j));
                }
                if(a+b > tw){
                    break;
                }
            }
        }
    }
}

void checkOneB(){
    int count = A.size();
    int j,k;
    for (auto itr = B.begin(); itr != B.end(); ++itr) {
        int c = B.count(itr->first);
        if(count > c){
            count = c;
            j = itr->first;
            k = itr->second;
        }
        if(c == 1){
            break;
        }
    }
    B.erase(j);
    B.erase(k);
    result++;
    return;

}


void reduce(){
    while (B.size()>0){
        checkOneB();
    }
}

