struct BipartiteMatching {
  vector< vector< int > > graph;
  vector< int > match, alive, used;
  int timestamp;

  BipartiteMatching(int n) : graph(n), alive(n, 1), used(n, 0), match(n, -1), timestamp(0) {}

  void add_edge(int u, int v) {
    graph[u].push_back(v);
    graph[v].push_back(u);
  }

  bool dfs(int idx) {
    used[idx] = timestamp;
    for(auto &to : graph[idx]) {
      int to_match = match[to];
      if(alive[to] == 0) continue;
      if(to_match == -1 || (used[to_match] != timestamp && dfs(to_match))) {
        match[idx] = to;
        match[to] = idx;
        return true;
      }
    }
    return false;
  }

  int bipartite_matching() {
    int ret = 0;
    for(int i = 0; i < graph.size(); i++) {
      if(alive[i] == 0) continue;
      if(match[i] == -1) {
        ++timestamp;
        ret += dfs(i);
      }
    }
    return ret;
  }

  void output() {
    for(int i = 0; i < graph.size(); i++) {
      if(i < match[i]) {
        cout << i << "-" << match[i] << endl;
      }
    }
  }
};

int f(int k) {
	int r = 0;
	while (k) {
		k >>= 1;
		r++;
	}
	return r;
}
int main(void)
{
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n;
	cin >> n;
	BipartiteMatching bm(n);
	map<int, int> m;
	rep (i, n) {
		int x, y, k;
		cin >> x;
		k = f(x);
		y = (1 << k) - x;
		if (m[y]) {
			eprintf("(%lld,%d)", i, m[y] - 1);
			bm.add_edge(i, m[y] - 1);
		}
		repp (j, k, 30) {
			int l = m[y + (1 << j)] - 1;
			if (l >= 0) {
				eprintf("(%lld,%d)", i, l);
				bm.add_edge(i, l);
			}
		}
		m[x] = i + 1;
	}
	cout << bm.bipartite_matching() << "\n";
	return 0;
}

