	tint k = 1;
	while (pot2[k-1] < MAXA)
	{
		pot2[k] = (pot2[k-1]*2);
		k++;
	}
	tint n;
	//~ while (cin >> n)
	cin >> n;
	{
		map<tint,vector<tint> > hist;
		forn(i,n)
		{
			cin >> A[i];
			hist[A[i]].push_back(i);
			matched[i] = 0;
		}

		forn(i,n)
			forn(j,k)
				if (pot2[j] > A[i] && !hist[pot2[j]-A[i]].empty())
					matched[i] += tint(hist[pot2[j]-A[i]].size()) - (pot2[j]==2*A[i]);

		set<pair<tint,tint> > next_to;
		forn(i,n)
			if (matched[i] > 0)
				next_to.insert({matched[i],i});

		tint ans = 0;

		while (tint(next_to.size()) > 1)
		{
			pair<tint,tint> actual = *next_to.begin();
			tint x = actual.second;
			next_to.erase(next_to.find(actual));
			matched[x] = 0;
			pair<tint,tint> mini = {MAXA,MAXN};
			forn(j,k)
				if (pot2[j] > A[x])
					for (const auto &y : hist[pot2[j]-A[x]])
					{
