							matched[y]--;
							mini = min(mini,make_pair(matched[y],y));
						}
					}
			tint y = mini.second;
			next_to.erase(make_pair(matched[y]+1,y));
			matched[y] = 0;
			forn(j,k)
				if (pot2[j] > A[y])
					for (const auto &z : hist[pot2[j]-A[y]])
						matched[z]--;
			ans++;
		}
		cout << ans << "\n";
	}
	return 0;
}

