void solve() {
  int n; cin >> n;
  vi arr(n); cin >> arr;
  map<int, int, greater<int>> mp;
  for (auto &a : arr) mp[a]++;
  int k = 1<<30;
  int ans = 0;
  for (auto &p : mp) {
    if (p.second == 0) continue;
    while ((k>>1) > p.first) k >>= 1;
    if ((k>>1) == p.first) {
      ans += p.second / 2;
    } else if (mp.count(k - p.first)) {
      int cnt = max(mp[k - p.first], p.second);
      ans += cnt;
      mp[k - p.first] -= cnt;
    }
  }
  cout << ans << endl;
}


