		for (auto j = 0; j < v[i].size(); j++) {
			if (isused[j]) continue;
			for (int k = (1 << 30); k > 0; k /= 2) {
				int tmp = k - v[i][j];
				int idx =
				    lower_bound(v[i].begin(), v[i].end(), tmp) - v[i].begin();
				if (idx == v[i].size() || (idx == 0 && v[i][0] != tmp))
					continue;
				while (idx == j ||
				       (idx < v[i].size() && isused[idx] && v[i][idx] == tmp))
					idx++;
				if (v[i][idx] != tmp) continue;
				isused[idx] = true;
				isused[j] = true;
				// cout << v[i][idx] << " " << v[i][j] << endl;
				ans++;
				break;
			}
		}
	}
	cout << ans << endl;
}

