int dfs(int v) {
    used[v] = true;
    for (int u: g[v]) {
        if (!used[u]) {
            int tmp = min(dfs(u), cnt[v]);
            cnt[v] -= tmp;
            ans += tmp;
        }
    }
    return cnt[v];
}

