int res=0;
int main()
{
	scanf("%d",&n);
	for (int i=0;i<n;i++)
	{
		int x;
		scanf("%d",&x);
		mp[x]++;
	}
	for (int i=30;i>=0;i--)
	{
		for (map<int, int>::iterator it=mp.begin();it!=mp.end() && 2*it->first<=(1<<i);it++)
		{
			if (it->second==0) continue;
			int t=(1<<i)-it->first;
			if (t==it->first)
			{
				int tt=it->second/2;
				res+=tt;
				it->second-=tt*2;
			}
			else
			{
				map<int, int>::iterator tt=mp.find(t);
				if (tt!=mp.end())
				{
					int tap=min(it->second,tt->second);
					it->second-=tap;
					tt->second-=tap;
					res+=tap;
				}
			}
		}
	}
	printf("%d",res);
	return 0;
}

