int main() {
	int N;
	cin >> N;
	vector<ll> a(N);
	for (int i = 0; i < N; ++i) { cin >> a[i]; }
	sort(a.begin(), a.end());

	unordered_map<ll, ll> mp;
	for (int i = 0; i < N; ++i) {
		mp[a[i]] += 1;
	}

	ll res = 0;
	for (int t = 35; t >= 0; --t) {
		ll x = pow(2, t);
		if (a[N - 1] + a[N - 2] < x) { continue; }
		for (int i = N - 1; i >= 0; --i) {
			if (mp[a[i]] == 0) { continue; }
			if (a[i] > x) { continue; }

			ll y = x - a[i];
			if (y == a[i]) {
				if (mp[y] >= 2) {
					mp[y] -= 2;
					++res;
				}
			} else if (mp[y] > 0) {
				mp[a[i]] -= 1;
				mp[y] -= 1;
				++res;
			}
		}
		if (N - res*2 < 2) { break; }
	}

	cout << res << endl;

	return 0;
}

