ll solve() {
    sort(A.begin(), A.end());
    reverse(A.begin(), A.end());
    unordered_map<ll, int> fmap;
    for (ll i = 0; i < N; i++) {
        fmap[A[i]]++;
    }

    ll ans = 0;
    for (auto a : A) {
        if (fmap[a] <= 0)
            continue;
        ll to = 1;
        while (to <= a)
            to <<= 1;
        auto pair = to - a;
        if (fmap.find(pair) != fmap.end() &&
            fmap[pair] >= (pair == a ? 2 : 1)) {
            ans++;
            fmap[a]--;
            fmap[pair]--;
        }
    }

    return ans;
}


