	long long mx = -1;
	map<long long, long long>cnt;
	for (long long i = 0; i < n; i++) {
		cin >> a[i];
		cnt[a[i]]++;
		mx = max(mx, a[i]);
	}
	long long powerof2 = 1;
	long long ans = 0;
	while (powerof2 <= mx * 4) {
		powerof2 *= 2;
	}
	while (powerof2 >= 1) {
		for (auto cur : cnt) {
			if (cnt.find(cur.first) == cnt.end() || cnt.find(powerof2 - cur.first) == cnt.end())
				continue;
			ans += min(cnt[cur.first], cnt[powerof2 - cur.first]);
			if (cnt[cur.first] <= cnt[powerof2 - cur.first]) {
				cnt[powerof2 - cur.first] -= cnt[cur.first];
				cnt[cur.first] = 0;
			}
			else {
				cnt[cur.first] -= cnt[powerof2 - cur.first];
				cnt[powerof2 - cur.first] = 0;
			}
		}
		powerof2 /= 2;
	}
	cout << ans;
	return 0;
}

