vector<P> v;
int calc(int l,int r,int c){
	if(l==r){
		return l;
	}
	int s=(l+r)/2;
	if(v[s].first<c){
		return calc(s+1,r,c);
	}
	if(v[s].first>c){
		return calc(l,s,c);
	}
	return s;
}
int main() {
