	int tmp;
	for (int i = 0; i < N; i++) {
		dummy = scanf("%d", &tmp);
		A.push_front(tmp);
	}

	A.sort(std::greater<int>());

	int ans = 0;
	forward_list<int>::iterator itr;
	forward_list<int>::iterator bitr;
	int n;

	// 調査対象
	while (!A.empty()) {
		int target = A.front();
		A.pop_front();

		if (A.empty()) break;

		itr = A.begin();
		while (itr != A.end()) {
			// 調査するべき数
			n = target + *itr;
