std::multimap<uint64_t, uint64_t> edges;
std::map<uint64_t, uint64_t> match;
std::vector<bool> used;

bool dfs(uint64_t n)
{
  used[n] = true;

  auto itr = edges.lower_bound(n);
  while ((itr != edges.end()) && (itr->first == n)) {
    uint64_t m = itr->second;

    auto match_itr = match.find(m);
    if ((match_itr == match.end()) || (!used[match_itr->second] && dfs(match_itr->second))) {
      match.emplace(n, m);
      match.emplace(m, n);
      return true;
    }

    ++itr;
  }

  return false;
}

int main(int argc, char **argv)
{
  uint64_t N;
  std::cin >> N;

  std::multimap<uint64_t, uint64_t> A;
  N_TIMES(n, N) {
    uint64_t a;
    std::cin >> a;

    A.emplace(a, n);
  }
  //std::cerr << A << std::endl;

  for (const std::pair<uint64_t, uint64_t> &p : A) {
    for (uint64_t m : pow_of_2) {
      if (p.first >= m) continue;

      uint64_t k = m - p.first;
      auto itr = A.lower_bound(k);
      while ((itr != A.end()) && (itr->first == k)) {
        if (p.second < itr->second) {
          edges.emplace(p.second, itr->second);
        }
        ++itr;
      }
    }
  }
  //std::cerr << edges << std::endl;

  uint64_t count = 0;
  N_TIMES(n, N) {
    if (match.find(n) == match.end()) {
      used = std::vector<bool>(N, false);
      if (dfs(n)) ++count;
    }
  }
  //std::cerr << match << std::endl;

  std::cout << count << std::endl;

  return 0;
}

