using namespace std;
typedef long long LL;

int n;
int a[maxn];

int ans;

int N;
map<int,int> mp;
vector<int> G[maxn];

int d[maxn];
int cnt[maxn];

void join(int i,int j)
{
    ++d[i],++d[j];
    G[i].push_back(j);
    G[j].push_back(i);
}

void init()
{
    scanf("%d",&n);
    for (int i=0;i<n;++i)
        scanf("%d",&a[i]);
    sort(a,a+n);
    for (int i=0,j=0;i<n;i=j)
    {
        while (j<n&&a[i]==a[j])    ++j;
        cnt[mp[a[i]]=++N]=j-i;
    }
    for (auto p:mp)
        for (int b=0;b<31;++b)
        {
            LL c=(1LL<<b)-p.first;
            if (p.first<=c)   continue;
            if (mp.count(c))
                join(p.second,mp[c]);
        }
}

bool vis[maxn];

queue<int> q;

void solve()
{
    for (int i=1;i<=N;++i)
        if (d[i]==1)
            q.push(i);
    while (!q.empty())
    {
        int i=q.front();    q.pop();
        for (auto j:G[i])
        {
            int c=min(cnt[i],cnt[j]);
            ans+=c;
            cnt[i]-=c;
            cnt[j]-=c;
            if (--d[j]==1)
                q.push(j);
        }
    }
    for (int b=0;b<31;++b)
        if (mp.count(1<<b))
            ans+=cnt[mp[1<<b]]/2;
    printf("%d\n",ans);
}

int main()
{
    init();
    solve();
    return 0;
}

