    int N;
    cin >> N;
    vector<ll> vll(N);
    for (int i = 0; i < N; ++i) {
        cin >> vll[i];
    }
    size_t L = vll.size();
    sort(vll.begin(), vll.end());

    vector<vi> G(N);
    for (int l = 0; l < L; ++l) {
        for (int t = 1; t <= 30; ++t) {
            auto it = find(vll.begin(), vll.end(), (1 << t) - vll[l]);
            if (it != vll.end()) {
                int m = (int)(it - vll.begin());
                if (m == l) break;
                G[l].push_back(m);
            }
        }
    }

    vi color(N, -1);
    function<void(int, int)> dfsC = [&](int v, int c)->void
    {
        for (int u: G[v]) {
            if (color[u] == -1) {
                color[u] = c;
                dfsC(u, c);
            }
        }
    };
    int C = 0;
    vi rep;
    for (int n = 0; n < N; ++n) {
        if (color[n] == -1) {
            color[n] = C;
            rep.push_back(n);
            dfsC(n, C);
            ++C;
        }
    }

    int res = 0;
    for (int c = 0; c < C; ++c) {
        int a = rep[c];
        int max = 0;
        for (int b : G[a]) {
            vi us(N, 0);
            int tmp = 0;

            function<void(pii)> dfs = [&](pii e)
            {
                ++tmp;
                int v = e.first;
                for (int u : G[v]) {
                    if (us[u]) continue;
                    us[u] = 1;
                    for (int x : G[u]) {
                        if (us[x]) continue;
                        us[x] = 1;
                        dfs({u, x});
                    }
                }
                v = e.second;
                for (int u : G[v]) {
                    if (us[u]) continue;
                    us[u] = 1;
                    for (int x : G[u]) {
                        if (us[x]) continue;
                        us[x] = 1;
                        dfs({u, x});
                    }
                }
            };

            us[a] = us[b] = 1;
            dfs({a, b});

            if (tmp > max) max = tmp;
        }
        res += max;
    }

    cout << res << endl;

    return 0;
}

