    int temp_0 = 0;
    for (int i=0;i<N;i++) {
        if (A[i]==pow2k_1) temp_0 += 1;
    }
    result += temp_0/2;

    for (int i=0;i<N_c;i++) {
        int target = pow2k - A[N-1-i];
        while (A[index]<target) {
            D.push_back(A[index]);
            N_d += 1;
            index += 1;
            if (index==C_index) {A[index]=target+1; break;}
        }
        if (A[index]==target) {
            result += 1;
            index += 1;
        }
        if (index==C_index) {break;}
    }

    for (int i=0;i<N_d;i++) {
        DD[i] = D[i];
    }


