struct s {
	int a, n;
};

int search(s* S, int p, int n) {
	if (S[0].a == p)return 0;
	int r = 0;
	for (int j = 30; j >= 0; j--) {
		if ((1 << j) >= n)continue;
		int c = r + (1 << j);
		if (S[c].a == p) {
			return c;
		}
		else if (S[c].a > p) {
			r = c;
		}
	}
	return -1;
}

int main() {
	int N;
	scanf("%d", &N);
	int *A = new int[N];
	for (int i = 0; i < N; i++) {
		scanf("%d", A + i);
	}
	std::vector<s> S;
	std::sort(A, A + N);
	int l = 0, c = -1;
	for (int i = N - 1; i >= 0; i--) {
		if (A[i] == l) {
			S[c].n++;
		}
		else {
			s b = { A[i],1 };
			l = A[i];
			c++;
			S.push_back(b);
		}
	}
	int res = 0;
	for (int i = 0; i < S.size();) {
		if (S[i].n == 0) {
			i++;
		}
		else {
			int p;
			for (int j = 0;; j++) {
				if ((1 << j) > S[i].a) {
					p = (1 << j) - S[i].a;
					break;
				}
			}
			int c = search(S.data(), p, S.size());
			if (c != -1) {
				if (c == i){
					if (S[c].n >= 2) {
						S[c].n -= 2;
						res++;
					}
					else {
						i++;
					}
				}
				else if (c != i) {
					if (S[c].n >= 1) {
						S[c].n--;
						S[i].n--;
						res++;
					}
					else {
						i++;
					}
				}
			}
			else {
				i++;
			}
		}
	}
	printf("%d", res);
}

