      set[i][v.first]--;

      std::bitset<31> looking(v.first);
      std::bitset<31> searching(0);
      int limiter=1;
      int break_itr=0;
      for(int bi=0;bi<31;bi++){
        if(bi<=i){
          searching[bi]=looking[bi];
        }else{
          searching[bi]=!looking[bi];
        }
        limiter=limiter*2;
        if(limiter>v.first){
          break_itr=bi+1;
          break;
        }
      }

      cerr<<looking<<" "<<searching<<endl;

      for(;break_itr<31; break_itr++){
        int searching_value=0;
        int weight=1;
        for(int si=0;si<31;si++){
          searching_value+=searching[si]*weight;
          weight*=2;
        }
        if(set[i].find(searching_value)!=set[i].end()){
          if(set[i][searching_value]>0){
            result++;
            set[i][searching_value]--;
            break;
          }
        }
        searching[break_itr]=true;
      }

    }
  }

  cout<<result<<endl;

  return 0;
}

