        int u = A[i];
        if (mp[u] == 0) continue;

        for (int j = 30; j >= 1; --j) {
            if (Pow[j] > u) {
                int v = Pow[j] - u;
                if (mp[v] != 0) {
                    if (u == v && mp[u] == 1) continue;
                    mp[u]--; mp[v]--; ans++; break;
                }
            }
        }
    }

    cout << ans << endl;
}

