class BIT {

public:
	vll d;
	vll v;
	ll size;
	BIT(ll sizeget) {
		size = sizeget;
		d.asn(size + 1, 0);
		v.asn(size, 0);
	}
	BIT(vll cpyvec) {
		copy(cpyvec);
	}
	void add(ll index, ll num) {
//		if (index < 0) return false;
//		if (index >= size) return false;
		v[index] += num;
		index++;
		while (index <= size) {
			d[index] += num;
			index += LSB(index);
		}
//		return true;
		return;
	}
	ll sum(ll index = INF) {
		index++;
		index = min(index, size);
		ll ans = 0;
		while (index) {
			ans += d[index];
			index -= LSB(index);
		}
		return ans;
	}
	void copy(vll cpyvec) {
		size = cpyvec.sz;
		d.asn(size + 1, 0);
		v.asn(size, 0);
		REP(i, size) add(i, cpyvec[i]);
	}

};

class UFT {

public:
	ll size;
	ll mode;
	vll root;
	vll rank;
	UFT(ll sizeget, ll modeget = 0){
		size = sizeget;
		mode = modeget;
		root.res(size, 0);
		if (!mode) rank.res(size, 0);
		IOTA(root, 0);
	}
	ll find(ll x) {
		return root[x] == x ? x : root[x] = find(root[x]);
	}
	bool same(ll x, ll y) {
		return find(x) == find(y);
	}
	void unite(ll x, ll y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (mode) root[y] = x;
		else {
			if (rank[x] < rank[y]) {
				root[x] = y;
			}
			else {
				root[y] = x;
				if (rank[x] == rank[y]) rank[x]++;
			}
		}
	}
};

