int n;
int a[200000 + 5];
vector<vector<int>> g(200000 + 5);
bool used[200000 + 5];
int ans = 0;
map<int, int> cnt, id, num;

void dfs(int now, int par) {
  used[now] = true;
  for (auto nx : g[now]) {
    if (nx == par) continue;
    dfs(nx, now);
    int x = num[nx];
    //cout << num[now] << " " << cnt[num[now]] << " " << x << " " << cnt[x] << endl;
    if (cnt[x] <= cnt[num[now]]) {
      ans += cnt[x];
      cnt[num[now]] -= cnt[x];
      cnt[x] = 0;
    }
  }
  if (cnt[num[now]] >= 2) {
    ans += cnt[num[now]] / 2;
    if (cnt[num[now]] % 2 == 0) cnt[num[now]] = 0;
    else cnt[num[now]] = 1;
  }
}

