    mp[a[i]]++;
    cnt[a[i]]++;
  }
  int idx = 0;
  for (auto p : mp) {
    int x = p.fi;
    id[x] = idx;
    num[idx] = x;
    idx++;
  }
  for (auto d : mp) {
    int x = d.fi;
    int y = 1;
    while (y < (1LL<<32)) {
      if (y < x) {
        y *= 2;
        continue;
      }
      else {
        if (cnt[y - x] == 0) {
          y *= 2;
          continue;
        }
        //cout << y - x << endl;
        if (x == y - x) {
          y *= 2;
          continue;
        }
        g[id[x]].push_back(id[y - x]);
        //g[id[y - x]].push_back(id[x]);
        y *= 2;
      }
    }
  }
  rep(i, idx) {
    if (used[i]) continue;
    dfs(i, -1);
  }
  cout << ans << endl;
}

