using namespace std;

int M, N, a[200009], b[200009], c[200009], dp[200009][2];
bool isRoot[200009], can[200009];
vector < int > v[200009];
map < int, int > mp;

int main ()
{
//freopen ("input", "r", stdin);
//freopen ("output", "w", stdout);

scanf ("%d", &M);
for (int i=1; i<=M; i++)
    scanf ("%d", &a[i]);
sort (a + 1, a + M + 1);
for (int i=1; i<=M; i++)
{
    int j = i;
    while (a[j + 1] == a[i] && j < M)
        j ++;
    b[++N] = a[i], c[N] = j - i + 1;
    mp[b[N]] = N, i = j;
}
for (int i=1; i<=N; i++)
{
    int p2 = 1;
    while (p2 <= b[i])
        p2 += p2;
    if (b[i] + b[i] == p2) can[i] = 1, isRoot[i] = 1;
    else
    if (mp.count (p2 - b[i]))
        v[mp[p2 - b[i]]].push_back (i);
    else
        isRoot[i] = 1;
}
int ans = 0;
for (int i=N; i>=1; i--)
{
    dp[i][1] = c[i], dp[i][0] = 0;
    for (auto j : v[i])
        dp[i][0] += dp[j][1],
        dp[i][1] += min (dp[j][0], dp[j][1]);
    if (isRoot[i])
    {
        if (!can[i])
            ans += min (dp[i][0], dp[i][1]);
        else
        if (dp[i][1] < dp[i][0])
            ans += dp[i][1];
        else
        {
            int maxK = min (c[i] / 2, (dp[i][1] - dp[i][0]) / 2);
            ans += dp[i][0] + maxK;
        }
    }
}
printf ("%d\n", ans);
return 0;
}

