int main(int argc, char **argv)
{
  uint64_t N;
  std::cin >> N;

  std::vector<uint64_t> A(N);
  N_TIMES(n, N) {
    std::cin >> A[n];
  }
  std::sort(A.begin(), A.end(), std::greater<uint64_t>());
  //std::cerr << A << std::endl;

  std::vector<bool> used(N, false);
  for (uint64_t n = 0; n < N; ++n) {
