template<typename T>
void readv(vector<T> &a){ REP(i, a.size()) cin >> a[i]; }
void readi(vector<int> &a){ REP(i, a.size()){cin >> a[i]; a[i]--;} }
void debug(mat m){REP(i, m.size()){ REP(j, m[i].size()){ cout << m[i][j] << ","; } cout << endl; }}



signed main(){

    int N; cin >> N;
    vec A(N); readv(A);
    vector<Pii> p(N);
    set<Pii> s;
    REP(i, N){
        p[i] = Pii(A[i], i);
        s.insert(p[i]);
    }
    SORT(p);
    s.insert(Pii(INF, INF));

    vector<bool> used(N, false);
    int ans = 0;
    IREP(i, N){
        if(used[i]) continue;
        int x = p[i].first;
        int n = 1;
        while(n <= x) n = (n << 1);
        int y = n - x;
        auto it = s.lower_bound(p[i]);
        s.erase(it);
        if(s.size() == 0) continue;
        if(y <= x){
            auto it2 = s.lower_bound(Pii(y, -INF));
            if((*it2).first == y){
                ans++;
                used[(*it2).second] = true;
                s.erase(it2);
            }
        }
        //cout << i << "," << x << "," << y << "," << ans << endl;
    }
    cout << ans;

    return 0;
}

