    map<long, int> m;
    for(int i=0; i<n; ++i) {
        cin>>a[i];
        m[a[i]]++;
    }
    vector<int> c(n);
    for(int i=0; i<n; ++i) {
        for(long j=1; j<1L<<31; j*=2) {
            if (m.count(j-a[i])==0) continue;
            c[i]+=m[j-a[i]];
            if (a[i]==j-a[i]) c[i]--;
        }
    }

    vector<pair<int, int>> b;
    for(int i=0; i<n; ++i) b.emplace_back(c[i], i);
    sort(begin(b), end(b));
    map<int, int> v;
    for(auto& e: b) v[a[e.second]]=e.first;

    int res=0;
    for(auto& e: b) {
        int i=e.second;
        if (m[a[i]]==0) continue;
        m[a[i]]--;

        int k=-1, x=INT_MAX;
        for(long j=1; j<1L<<31; j*=2) {
            if (m.count(j-a[i])==0) continue;
            if (m[j-a[i]]) {
                if (k<0 || x>v[j-a[j]]) k=j-a[j], x=v[k];
            }
        }
        if (k>=0) {
            m[k]--;
            ++res;
        }
    }
    cout<<res<<endl;
}

