void solve() {
  ll N;
  cin >> N;

  multiset<ll> as;
  rep(i, N) {
    ll a;
    cin >> a;
    as.insert(a);
  }

  ll res = 0;

  while (!as.empty()) {
    auto num_it = --as.end();
    ll num = *num_it;

    ll sum = 1;
    while (sum < num) sum *= 2;

    ll pair = sum - num;
    auto pair_it = as.find(pair);

    if (pair_it != as.end() && !(num_it == pair_it && as.count(num) == 1)) {
      res++;
      as.erase(pair_it);
    }

    as.erase(as.find(num));
  }

  cout << res << endl;
}

