int Func(int k, int N, int A[]) {
    int pow2k = pow(2,k);
    int pow2k_1 = pow(2,k-1);
    int C_index = 0;
    while (A[C_index]<pow2k_1) {
        C_index += 1;
    }
    int N_b = C_index;
    int N_c = N - C_index;

    int index = 0;
    vector<int> D{};
    int N_d = 0;

    for (int i=0;i<N_c;i++) {
        int target = pow2k - A[N-1-i];
        while (A[index]<target) {
            D.push_back(A[index]);
            N_d += 1;
            index += 1;
            if (index==C_index) {index-=1; break;}
        }
        if (A[index]==target) {
            result += 1;
            index += 1;
        }
        if (index==C_index) {break;}
    }

    for (int i=0;i<N_d;i++) {
        DD[i] = D[i];
    }

    return N_d;
}


int main(){
