bool used[200000 + 10];
int pow2s[32];

int binSearch(int x, int left, int right) {
    if (right <= left + 1 ) {
        if (A[left] == x) {
            return left;
        } else {
            return -1;
        }
    }
    int middle;
    if ((left + right) % 2 == 0) {
        middle = (left + right) / 2;
    } else {
        middle = (left + right - 1) / 2;
    }
    // cout << "left = " << left << ",middle = " << middle << ",right = " << right <<  endl;
    if (A[middle] > x) {
        return binSearch(x, middle + 1, right);
    } else if (A[middle] < x){
        return binSearch(x, left, middle);
    } else {
        return middle;
    }
}

int main(void) {
    pow2s[0] = 1;
    for (i=1; i<=32; i++) {
        pow2s[i] = pow2s[i-1] * 2;
    }
    cin >> N;
    for (i=0; i<N;i ++) {
        cin >> A[i];
        used[i] = false;
    }
    sort(A, A+N);
