    //     cout << A[i] << " ";
    // }
    // cout << endl;

    ans = 0;
    for (i=0; i<N; i++) {
        if (used[i] == true) {
            continue;
        } else {
            used[i] = true;
        }
        for (j=1; j<=32; j++) {
            if (pow2s[j-1] <= A[i] && A[i] < pow2s[j]) {
                break;
            }
        }
        int pair_num = pow2s[j] - A[i];
        j = binSearch(pair_num, 0, N);
        // cout << "i=" << i << " A[" << i << "]=" << A[i] << " pair_num=" << pair_num << " j=" << j << endl;
        if (j == -1) {
            continue;
