            do {
                if (used[j+1] == false) {
                    used[j+1] = true;
                    ans++;
                } else {
                    j++;
                }
            } while(A[j] == pair_num);
        } else {
            do {
                j--;
            } while(A[j] == pair_num);
            used[j+1] = true;
            ans++;
        }
    }
    cout << ans << endl;

    return 0;
}

