        if (A[i] != j - A[i] && T[j - A[i]] > 0) {
            T[j - A[i]]--;
            T[A[i]]--;
            ans++;
        } else if (A[i] == j - A[i] && T[A[i]] >= 2) {
            T[A[i]] -= 2;
            ans++;
        }
    }
    cout << ans << endl;
}

