template <class T>
struct edge
{
    int to;
    T cap;
    int rev;
    edge(int to, T cap, int rev) : to(to), cap(cap), rev(rev) {}
};

template <class T>
class graph
{
    private:
        const int number_of_nodes;
    public:
        vector<edge<T> > *edges;
        graph(int number_of_nodes) : number_of_nodes(number_of_nodes) {
            edges = new vector<edge<T> >[number_of_nodes];
        }
        ~graph() {
            delete [] edges;
        }
        int size() const {return number_of_nodes;}
        void make_edge(int u, int v, T cap) {
            edges[u].push_back(edge<T>(v, cap, edges[v].size()));
            edges[v].push_back(edge<T>(u, 0, edges[u].size() - 1));
        }
};

template <class T>
T maximum_flow(graph<T> &g, int source, int sink)
{
    bool *used = new bool[g.size()]();
    function<T(int, T)> dfs = [&](int u, T f) -> T {
        if (u == sink) {
            return f;
        }
        used[u] = true;
        for (edge<T> &e: g.edges[u]) {
            if (!used[e.to] && e.cap > 0) {
                T d = dfs(e.to, u == source ? e.cap : min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g.edges[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    };
    T result = 0;
    while (true) {
        fill (used, used + g.size(), 0);
        T flow = dfs(source, 0);
        if (flow == 0) {
            return result;
        }
        result += flow;
    }
    delete [] used;
    return result;
}

