    REP(n, N) {
        ll a;
        cin >> a;
        As[n] = a;
        A_count[a]++;
    }

    vector<ll> targets;
    ll tmp = 2;
    while(1) {
        targets.pb(tmp);
        tmp *= 2;
        if (tmp > (1e9) * 2) break;
    }

    vector<ll> As2;
    map<ll, int> a_to_idx;
    int idx = 0;
    for(auto kv: A_count) {
        auto a = kv.first;
        As2.pb(kv.first);
        a_to_idx[a] = idx;
        ++idx;
    };
    int V = SIZE(As2);
    FordFulkerson<int> ff(V * 2 + 2);
    int S = V * 2;
    int T = S + 1;
    REP(n, V) {
        auto a = As2[n];
        for (auto t: targets) {
            auto b = t - a;
            if (b <= 0) continue;
            if (a_to_idx.count(b)) {
                auto m = a_to_idx[b];
                if (n == m) {
                    int pair_max = A_count[a] / 2;
                    if (pair_max > 0) {
                        ff.add_uni_edge(n, V + n, pair_max);
                    }
                }
                ff.add_uni_edge(n, V + m, min(A_count[a], A_count[b]));
            }
        }
    }
    REP(n, V) {
        auto a = As2[n];
        ff.add_uni_edge(S, n, A_count[a]);
        ff.add_uni_edge(V + n, T, A_count[a]);
    }

    auto res = ff.max_flow(S, T);
    cout << res / 2 << endl;
    return 0;
}

