    for (auto itr = A.end() - 1; itr != A.begin(); --itr) {
        if (*itr < 0)   continue;

        int i = pair_of(*itr);
        auto pair_itr = lower_bound(A.begin(), itr, i);
        if (pair_itr != itr && *pair_itr == i) {
