using namespace std;

const long long POT[31]={2,4,8,16,32,64,128,256,512,1024,2048,4096,8192,16384,32768,65536,131072,262144,524288,1048576,2097152,4194304,8388608,16777216,33554432,67108864,134217728,268435456,536870912,1073741824,2147483648};

struct edge{int to,cap,rev;};

vector<vector<edge>> G;
vector<bool> used;
int V;


void add_edge(int from,int to,int cap){
    G[from].push_back((edge){to,cap,G[to].size()});
    G[to].push_back((edge){from,0,G[from].size()-1});
}

int dfs(int v,int t,int f){
    if(v==t)return f;
    used[v]=true;

    for (int i = 0; i < G[v].size(); ++i) {
        edge &e=G[v][i];
        if(!used[e.to]&&e.cap>0){
            int d=dfs(e.to,t,min(f,e.cap));
            if(d>0){
                e.cap-=d;
                G[e.to][e.rev].cap+=d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s,int t){
    int flow=0;
    for (;;) {
        used=vector<bool>(2*V,false);
        int f=dfs(s,t,INT32_MAX);
        if(f==0)return flow;
        flow+=f;
    }
}

int main(){
    cin>>V;
    G=vector<vector<edge>>(2*V+2,vector<edge>());

    int s=2*V,t=2*V+1;

    for (int i = 0; i < V; ++i) {
        add_edge(s,i,1);
    }
    for (int i = V; i < 2*V; ++i) {
        add_edge(i,t,1);
    }

    vector<long long> a(V);
    for (int i = 0; i < V; ++i) {
        cin>>a[i];
    }

    sort(a.begin(),a.end());
    for (int i = 0; i < V; ++i) {
        for (int j = 0; j < 31; ++j) {
            if(POT[j]<a[i])continue;
            auto itl=lower_bound(a.begin(),a.end(),POT[j]-a[i]);
            if(itl==a.end())break;
            if(*itl==POT[j]-a[i]&&i!=itl-a.begin()){
                add_edge(i,V+itl-a.begin(),1);
            }
        }
    }

    int ans=max_flow(s,t);
    cout<<ans/2<<endl;
    return 0;
}

