namespace NetworkFlow {
	const int MAX_V = 200010;
	const int INF = 2000000000;
	struct edge {
		int to;//行先
		int capacity;//容量
		int reverse;//逆辺
	};

	vector<edge> G[MAX_V];
	bool used[MAX_V];

	void AddEdge(int from, int to, int capacity) {
		edge e1 = { to, capacity, (int)G[to].size() };
		edge e2 = { from,0,(int)G[from].size() - 1};
		G[from].push_back(e1);
		G[to].push_back(e2);
	}

	int dfs(int v, int t, int f) {
		if (v == t) {
			return f;
		}
		used[v] = true;
		for (int i = 0; i < G[v].size(); i++) {
			edge &e = G[v][i];
			if (!used[e.to] && e.capacity > 0) {//使える辺を見つけたら
				int d = dfs(e.to, t, min(f, e.capacity));
				if (d > 0) {
					e.capacity -= d;
					G[e.to][e.reverse].capacity += d;
					return d;
				}
			}
		}
		return 0;
	}

	int max_flow(int s, int t) {
		int flow = 0;
		while (true) {
			memset(used, 0, sizeof(used));
			int f = dfs(s, t, INF);
			if (f == 0) {
				return flow;
			}
			else {
				flow += f;
			}
		}
	}
}

