typedef long long ll;

bool twobeki(ll s) {
    for (int i = 1; i < 32; i++) {
        if (s == pow(2, i)) {
            return 1;
        }
    }
    return 0;
}

int main() {
    int N;
    vector<ll> A;
    cin >> N;
    ll a;
    for (int i = 0; i < N; i++) {
        cin >> a;
        A.push_back(a);
    }

    sort(A.begin(), A.end(), greater<ll>());
    ll s;
    bool flag = 0;
    int ans = 0;
    for (int i = 0; i < A.size()-1; i++) {
        for (int j = i+1; j < A.size(); j++) {
            s = A.at(i) + A.at(j);
            flag = twobeki(s);
            if (flag) {
                ans++;
                A.erase(A.begin() + j);
                break;
            }
        }
    }

    cout << ans << endl;
}

