			int t = lower_bound(A + i + 1, A + 1 + N, F[R[j]] - A[i]) - A;
			if (t <= N && A[t] == F[R[j]] - A[i]) {
				Mk[t] = 1, ++ans;
				break;
			}
		}
	}
	fkans = max(ans, fkans);
	}
	printf("%d\n", fkans);
	return 0;
}

