#include "bits/stdc++.h"
#define in std::cin
#define out std::cout
#define rep(i,N) for(int i=0;i<N;++i)
typedef long long int LL;

class bipartite_matching
{
public:
	int n;
	std::vector<std::vector<int>> G;
	std::vector<int> match;

	void init(int n_)
	{
		G.resize(n_), match.resize(n_), used.resize(n_);
		n = n_;
	}

	void add_edge(int u, int v)
	{
		G[u].push_back(v);
		G[v].push_back(u);
	}

	int maximum_matching()
	{
		int res = 0;
		std::fill(match.begin(), match.end(), -1);
		rep(v, n)
		{
			if (match[v] == -1)
			{
				std::fill(used.begin(), used.end(), false);
				if (dfs(v)) ++res;
			}
		}
		return res;
	}

private:
	std::vector<bool> used;
	bool dfs(int v)
	{
		used[v] = true;
		for (auto u : G[v])
		{
			int w = match[u];
			if (w == -1 || !used[w] && dfs(w))
			{
				match[v] = u;
				match[u] = v;
				return true;
			}
		}
		return false;
	}
};

int main()
{
	LL N;
	in >> N;
	std::vector<LL>A(N);
	rep(i, N) in >> A[i];

	std::sort(A.begin(), A.end());
	std::vector<LL>rui(33);
	rui[0] = 1;
	for (int i = 1; i <= 32; ++i) rui[i] = rui[i - 1] * 2;

	bipartite_matching match;
	match.init(N);
	rep(i, N)
	{
		rep(j, rui.size())
		{
			auto it1 = std::lower_bound(A.begin(), A.end(), rui[j] - A[i]);
			auto it2 = std::upper_bound(A.begin(), A.end(), rui[j] - A[i]);
			for (auto it = it1; it < it2; ++it)
			{
				if (it - A.begin() <= i) continue;
				match.add_edge(i, it - A.begin());
			}
		}
	}

	out << match.maximum_matching() << std::endl;
	return 0;
}

