int main(){
  ll n;cin>>n;
  vector<ll> a(n);
  rep(i, n)cin>>a[i];

  sort(a.begin(), a.end());

  int result=0;
  while(true){

    pll min_p={n, -1};
    map<ll,ll> cc;
    for(auto c: a){
      int count = 0;
      rep1(i, 31){
        ll t = pow(2LL, i)-c;
        if(t<=0)continue;

        ll d = ( upper_bound(a.begin(), a.end(), t) - lower_bound(a.begin(), a.end(), t) );

        // cout<<c<<' '<<t<<' '<<d<<endl;

        count += d;
        if( d>0 && (*lower_bound(a.begin(), a.end(), t))==c )count--;
      }
      if(count==0)continue;

      cc[c]=count;
      if(min_p.first>count)min_p = {count, c};
    }

    if(min_p.second==-1)break;

    // 最小可能ペア数を持つmin_pと組める数値のうち、可能ペア数最少を選択
    pll c_pt={n, -1};
    ll min_p_num=min_p.second;
    rep1(i, 31){
      ll t = pow(2LL, i)-min_p_num;
      if(t<=0 || cc[t]==0)continue;

      if(c_pt.first>cc[t])c_pt = { cc[t], t };
    }

    if(c_pt.second==-1)break;

