    // delete targets are c_pt.second and min_p_num
    auto it1 = lower_bound(a.begin(), a.end(), min_p_num);
    a.erase(it1);

    auto it2 = lower_bound(a.begin(), a.end(), c_pt.second);
    a.erase(it2);

//cout<<"-----"<<endl;
//cout<<c_pt.second<<' '<<min_p_num<<endl;
//cout<<"-----"<<endl<<endl;

    result++;

  }

  cout<<result<<endl;

  return 0;
}

