int bin_search(std::vector<long long>& A, long long x, int start) {
    int N = A.size();
    int L = start;
    int R = N;

    while (R - L > 1) {
        int M = (R + L) / 2;
        if (A[M] == x) return M;
        if (A[M] > x){
            L = M;
        }
        else {
            R = M;
        }

    }
    return -1;

}

int main() {
    int N;
    scanf("%d", &N);
    std::vector<long long> A(N);
    for (int i = 0; i < N; i++) {
        long long a;
        scanf("%lld", &a);
        A[i] = a;
    }
    std::sort(A.begin(), A.end(), std::greater<long long>());
    //std::unordered_map<int, std::vector<int>> pair_map;
    std::vector<bool> is_paired(N + 1, false);
    int count = 0;
    for (int i = 0; i < N; i++) {
        if(is_paired[i] == false) {
            bool is_break = false;
            for (int t = 1; t <= 32; t++) {
                long long t2 = long long(std::pow(2, t));

                int j = bin_search(A, t2 - A[i], i);

                if (j >= 0 && is_paired[j] == false) {
                    is_paired[i] = true;
                    is_paired[j] = true;
                    is_break = true;
                    count++;
                    break;
                    //pair_map[i].push_back(j);
                }
           }
        }
    }

    std::cout << count << std::endl;
    return 0;
}

