	while(!A.empty()) {
		const int target = tar(A.back()) - A.back();
		A.pop_back();
		const bool exist = std::binary_search(A.begin(), A.end(), target);
		if(exist) {
			result++;
			const auto itr = std::lower_bound(A.begin(), A.end(), target);
			A.erase(itr);
		}
	}

	std::cout << result << std::endl;

	return 0;
}

