        cin >> a[i];
    }

    sort(a.begin(), a.end());

    vector<int> memo(a[n-1]+1, 0);
    for (int i = 0; i < n; i++) {
        memo[a[i]] += 1;
    }


    int count = 0;
    for (int t = 30; t > 0; t--) {
        for (int i = n-1; i >= 0; i--) {
            if (memo[a[i]] == 0) continue;
            if (((1 << t) - a[i]) >= a[n-1]) continue;
            int front = lower_bound(a.begin(), a.end(), (1 << t) - a[i]) - a.begin();
            int back = upper_bound(a.begin(), a.end(), (1 << t) - a[i]) - a.begin();
            if (front == back) continue;
            if (front > i) continue;
            if (front == i && memo[a[i]] <= 1) continue;
            if (memo[a[front]] >= 1) {
                memo[a[front]] -= 1;
                memo[a[i]] -= 1;
                count += 1;
            }

        }
    }

    cout << count << endl;

    return 0;
}

