  ll a[n]; for(int i=0;i<n;i++) cin>>a[i];
  map<ll,int> mp; // 値、個数
  for(int i=0;i<n;i++) mp[a[i]]++;

  unordered_map<ll,int> zak;
  int kos=mp.size(), idx=0;
  int o[kos];
  for(P x:mp) zak[x.first]=idx, o[idx++]=x.second;

  set<int> v[kos];
  for(P x:mp) {
    ll val=x.first;
    for(ll j=2;j<2*1e9;j*=2) {
      ll nm=j-val;
      if (nm<=0) continue;
      if (mp.find(nm) == mp.end()) continue;
      int from=zak[val], to=zak[nm];
      v[from].insert(to);
    }
  }

  queue<int> que;
  for(int i=0;i<kos;i++) {
    if (v[i].size() == 1) que.push(i);
  }

  /*
  for(int i=0;i<kos;i++) {
    cout<<i<<": ";
    for(int x:v[i]) {
      cout<<x<<" ";
    } cout<<endl;
  }*/

  int an=0;
  while(!que.empty()) {
    int from = que.front(); que.pop();
    if (o[from] == 0 || v[from].size() != 1) continue;
    //cout<<from<<"* ";

    int to;
    for(int xx:v[from]) to=xx;
    //cout<<to<<endl;

    if (from == to) {
      int gt = o[from] / 2;
      an+=gt; v[from].erase(to); continue;
    }

    int gt = min(o[from], o[to]);
    an+=gt; o[from]-=gt; o[to]-=gt;
    if (o[from] == 0) {
      v[to].erase(from);
      if (v[to].size() == 1) que.push(to);
      v[from].clear();
    }
    if (o[to] == 0) {
      //cout<<from<<" "<<to<<"@@"<<endl;
      for(int tw:v[to]) {
        if (tw == to) continue;
        //cout<<tw<<" "<<to<<endl;
        v[tw].erase(to);
      }
      v[to].clear();
    }
  }
  cout<<an<<endl;
}

