        ms.insert(a[i]);
    }   

    int ans = 0;
    while (ms.size()) {
        auto u = *ms.rbegin();
        ms.erase(ms.find(*ms.rbegin()));
        int w = getp(u) - u;
        if (ms.find(w) != ms.end()) {
            ms.erase(ms.find(w));
            ++ans;
        }   
    }   

    cout << ans << '\n';
