	m = n;
	for(int i = 1; i < n+1; ++i){
		for(int j = 1; j < 31; ++j){
			int goal = (1<<j) - a[i];
			if(goal <= 0) continue;
			auto it = lower_bound(vec.begin(),vec.end(),ii(goal,-1));
			while(it != vec.end() and it->first == goal){
				if(it->second != i){
					adj[i].pb(it->second+n);
				}
				it++;
			}
		}
	}
	int ans = bipMatching();
	printf("%d\n",bipMatching()/2);

	return 0;
}

