        cin >> A[i];
        value2count[A[i]]++;
    }

    map<ll, ll> value2index;
    ll i = 0;
    for (auto p : value2count) {
        value2index[p.first] = i++;
    }

    N = value2count.size();

    FordFulkerson ff(2 * N + 2);

    i = 0;
    for (auto itr = value2count.begin(); itr != value2count.end(); itr++, i++) {
        ff.addEdge(0, i + 1, N);
        ff.addEdge(i + N + 1, 2 * N + 1, N);

        for (ll j = 1; (1LL << j) <= (2 * (ll)1e9); j++) {
            ll target = (1LL << j) - itr->first;
            if (value2count.count(target)) {
                ff.addEdge(i + 1, N + 1 + value2index[target], min(itr->second, value2count[target]) - (A[i] == target));
            }
        }
    }

    cout << ff.getflow(0, 2 * N + 1) / 2 << endl;
}

