    sort(ALL(a));
    vector<bool> use(n,0);
    int ans=0;
    rrep(i,n){
        rep(j,50){
            if(a[i]<(1ull<<j)&&(1ull<<j)<=2*a[i]){
                ll p=(1ull<<j)-a[i];
                if(p==a[i]){
                    int k=1;
