int main(void) {
  ll i, n, ans = 0, a;
  scanf("%lld", &n);
  multiset<ll> s;
  priority_queue<ll> q;
  bool flg[n];
  for(i = 0; i < n; ++i) scanf("%lld", &a), flg[i] = true, s.insert(a), q.push(a);
  while(q.size()){
    a = q.top(), q.pop();
    if(s.find(a) == s.end()) continue;
    s.erase(s.find(a));
    ll now = 1;
    while(now <= a) now *= 2;
    now -= a;
    if(*s.lower_bound(now) == now) s.erase(s.find(now)), ++ans;
  }
  printf("%lld", ans);
  return 0;
}

