unsigned int onesComplement(unsigned int n) 
{ 
   // Find number of bits in the given integer 
   int number_of_bits = floor(log2(n))+1; 

   // XOR the given integer with poe(2,  
   // number_of_bits-1 and print the result  
   return ((1 << number_of_bits) - 1) ^ n; 
}
vector<int> g[100001];
vector<bool> vis(100001);
vector<int> c(2,0);
void dfs(int node,int col=0)
{
    vis[node]=1;
    c[col]++;
    for(int to:g[node]){
        if(!vis[to])
            dfs(to,col^1);
    }
}
void solve()
{   
    int n;
    cin>>n;
    map<ll,vector<ll>> cnt;
    for(int i=0;i<n;++i)
    {
        ll x;
        cin>>x; cnt[x].push_back(i);
    }
    for(ll res=2;res<=binpow(2,34);res*=2)
    {
        for(auto it:cnt)
        {
            if(cnt.count(res-it.first)){
                for(auto it1:cnt[it.first])
                    for(auto it2:cnt[res-it.first])
                        g[it1].push_back(it2);
            }
        }
    }
    int ans=0;
    for(int i=0;i<n;++i){
        if(!vis[i])
        {
            dfs(i);
            ans+=min(c[0],c[1]);
            c[0]=0; c[1]=0;
        }
    }
    cout<<ans;

}   
int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL); 
    solve();
}

