void solve(){
    i64 N;
    cin >> N;

    vector<i64> A(N);
    rep(i,0,N) cin >> A[i];

    sort(begin(A),end(A));

    i64 ans=0;
    vector<bool> del(N);
    rep(i,0,30){
        vector<i64> idx;
        rep(j,0,N){
            if(A[j]==(1LL<<i)){
                idx.push_back(j);
            }
        }
        ans+=idx.size()/2;
        for(i64 j=0; j+1<idx.size(); j+=2){
            del[idx[j]]=del[idx[j+1]]=true;
        }
    }

    vector<i64> B;
    rep(i,0,N) if(!del[i]) B.push_back(i);
    N=B.size();

    if(N<=1){
        cout << ans << endl;
        return;
    }

    unordered_map<i64,vector<i64>> mp;
    rep(i,0,N){
        mp[A[i]].push_back(i);
    }

    vector<vector<i64>> from(N);
    vector<bool> term(N,true);

    rep(i,0,N){
        rep(j,0,30){
            i64 s=1LL<<j;
            if(s-A[i]<A[i]) continue;
            if(mp.find(s-A[i])==mp.end()) continue;
            for(i64 k:mp[s-A[i]]){
                if(i>=k) continue;
                from[i].push_back(k);
                term[k]=false;
            }
        }
    }

    static i64 dp[200010][2];
    fill_n((i64*)dp,200010*2,0);

    for(i64 i=N-2; i>=0; --i){
        vector<bool> bs(from[i].size());
        rep(j,0,from[i].size()){
            i64 k=from[i][j];
            dp[i][0]+=max(dp[k][0],dp[k][1]);
            if(dp[k][0]<dp[k][1]) bs[j]=true;
        }
        rep(j,0,from[i].size()){
            i64 k=from[i][j];
            if(bs[j]) dp[i][1]=max(dp[i][1],dp[i][0]-dp[k][1]+dp[k][0]+1);
            else dp[i][1]=max(dp[i][1],dp[i][0]+1);
        }
    }

    rep(i,0,N) if(term[i]) ans+=max(dp[i][0],dp[i][1]);

    cout << ans << endl;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

