const int DX[]={1,0,-1,0},DY[]={0,-1,0,1};

struct graph {
  int L, R;
  vector<vector<int>> adj;
  set<LL> remove_node_set;
  graph(int L, int R) : L(L), R(R), adj(L+R) { }
  void add_edge(int u, int v) {
    adj[u].push_back(v+L);
    adj[v+L].push_back(u);
  }
  void remove_node(LL x) {
      remove_node_set.insert(x);
      remove_node_set.insert(x+L);
  }
  int maximum_matching() {
    vector<int> visited(L), mate(L+R, -1);
    function<bool(int)> augment = [&](int u) { // DFS
      if(remove_node_set.count((LL)u) == 1) return false;
      if (visited[u]) return false;
      visited[u] = true;
      for (int w: adj[u]) {
        int v = mate[w];
        if (v < 0 || augment(v)) {
          mate[u] = w;
          mate[w] = u;
          return true;
        }
      }
      return false;
    };
    int match = 0;
    for (int u = 0; u < L; ++u) {
      fill(ALL(visited), 0);
      if (augment(u)) ++match;
    }
    return match;
  }
};

void solve(long long N, std::vector<long long> A){
    graph g(N, N);

    map<LL, VI> memo;
    REP(i, N) {
        if(memo.count(A[i]) == 0) {
            VI tmp;
            memo[A[i]] = tmp;
        }

        memo[A[i]].PB(i);
    }

    VLL pair_num;
    LL idx = 1;
    LL ans = 0;
    while(idx <= 2000000000) {
        if(memo.count(idx) == 1 && memo[idx].size() >= 4) {
            while(memo[idx].size() > 3) {
                memo[idx].pop_back();
                memo[idx].pop_back();
                ans++;
            }
        }
        pair_num.PB(idx);
        idx *= 2;
    }

    for(auto i = memo.begin(); i != memo.end() ; ++i ) {
        REP(j, pair_num.size()) {
            LL key = pair_num[j] - i->first;
            if(memo.count(key) == 1) {
                while(memo[key].size() > 2 && i->second.size() > 2) {
                    LL idx1 = memo[key][memo[key].size()-1];
                    LL idx2 = i->second[i->second.size()-1];
                    memo[key].pop_back();
                    i->second.pop_back();
                    ans++;
                    g.remove_node(idx1);
                    g.remove_node(idx2);
                }

                REP(l, i->second.size()) {
                    REP(r, memo[key].size()) {
                        g.add_edge(i->second[l], memo[key][r]);
                    }
                }
            }
        }
    }

    cout << (g.maximum_matching() / 2) + ans << endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    std::vector<long long> A(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&A[i]);
    }
    solve(N, std::move(A));
    return 0;
}

