int binary_search(int key,vector<int> vec){
  int left=0,right=vec.size()-1;
  while(right>=left){
    int mid=(left+right)/2;
    if(vec[mid]==key) return mid;
    else if(vec[mid]>key) right=mid-1;
    else if(vec[mid]<key) left=mid+1;
  }
  return -1;
}
