    vector<int> array(n);
    int i;
    for(i = 0;i < n;++i){
        cin >> array.at(i);
    }
    sort(array.begin(),array.end());
    int temp,ans = 0;
    bool flag = false;
    while(n > 1){
        if(array.at(n-1) == 0){
            --n;
            continue;
        }
        for(i = n-2;i >= 0;--i){
            if(array.at(i) == 0){
                continue;
            }
            temp = array.at(n-1)+array.at(i);
            while(temp > 1){
                if(temp%2 == 1){
                    flag = true;
                    break;
                }else{
                    temp /= 2;
                }
            }
            if(flag){
                flag = false;
                continue;
            }else{
                ++ans;
                array.at(i) = 0;
                --n;
                break;
            }
        }
        if(i == -1){
            --n;
        }
    }
    cout << ans << endl;
    return 0;
}

