int main() {
  int n;
  cin >> n;
  int arr[n];
  multiset <int> s;
  map <int, int> cnt;
  vector < pair <int, int> > vec;
  for (int i = 0; i < n; i++) {
    cin >> arr[i];
    cnt[arr[i]]++;
  }
  for (int i = 0; i < n; i++) {
    int el = arr[i];
    int here = 0;
    for (int j = 0; j <= 31; j++) {
      here += cnt[(1 << j) - el];
    }
    if (((el * 2) & (el * 2 - 1)) == 0) here--;
    vec.push_back({here, el});
  }
  sort(vec.begin(), vec.end());
  int ans = 0;
  for (int i = 0; i < n; i++) {
    bool done = 0;
    for (int j = 31; j >= 0 && !done; j--) {
      if (s.find((1 << j) - vec[i].second) != s.end()) {
        s.erase(s.find((1 << j) - vec[i].second));
        ans++;
        done = 1;
      }
    }
    if (!done) s.insert(vec[i].second);
  }
  cout << ans << endl;
  return 0;
}

