int over(int k) {
    int ans = 1;
    while (ans < k) {
        ans *= 2;
    }
    return ans;
}

int main() {
    cin >> n;
    for (int i=0; i<n; i++) cin >> a[i];

    sort(a, a+n);

    int ans = 0;
    for (int i=n-1; ~i; i--) {
        int j = lower_bound(a, a+n, over(a[i]) - a[i]) - a;
        if (!c[i] and !c[j] and a[i] + a[j] == over(a[i])) {
            c[i] = 1; c[j] = 1; ans += 1;
        }
    }

    cout << ans;
}

