int main() {
    int N, a, p;
    vector<int> A;
    map<int, int> mp;
    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> a;
        mp[a]++;
        A.push_back(a);
    }

    sort(A.begin(), A.end(), greater<int>());
    int ans = 0;
    for (int i = 0; i < N; i++) {
        if(mp[A.at(i)] == 0) continue;
        for (int j = 4; j > 0; j--) {
            p = pow(2, j);
            if (mp.count(p - A.at(i))) {
                if (A.at(i) == p / 2 && mp[A.at(i)] >= 2) {
                    mp[A.at(i)] -= 2;
                    ans++;
                    break;
                } else if (mp[A.at(i)] >= 1) {
                    mp[A.at(i)]--;
                    mp[p - A.at(i)]--;
                    ans++;
                    break;
                }
            }
        }
    }

    cout << ans << endl;
}

