  while(true){

    pll min_p={n, -1};
    map<ll,ll> cc;
    for(auto c: a){
      int count = 0;
      rep1(i, 31){
        ll t = pow(2LL, i)-c;
        if(t<=0)continue;

        ll d = ( upper_bound(a.begin(), a.end(), t) - lower_bound(a.begin(), a.end(), t) );

