      }
      if(count==0)continue;

      cc[c]=count;
      if(min_p.first>count)min_p = {count, c};
    }

    if(min_p.second==-1)break;

    // 最小可能ペア数を持つmin_pと組める数値を選択
    ll pt=-1;
