const int MAX_N=210101;

struct edge{
    int to,cap,rev;
};

vector<edge> G[MAX_N];
vector<int> check(MAX_N,0);

int dfs(int v,int t, int f ){
    if(v==t){return f;}
    check[v]=1;
    for(int i=0;i<G[v].size();i++){
        if(check[G[v][i].to]==0 && G[v][i].cap > 0){
            int ff =dfs(G[v][i].to,t,min(f,G[v][i].cap));
            if(ff>0){
                G[v][i].cap -= ff;
                G[G[v][i].to][G[v][i].rev].cap += ff;
                return ff;
            }
        }
    }
    return 0;
}

int maxflow(int s,int t){
    int flow = 0;
    while(1){
        fill(check.begin(),check.end(),0);
        int f = dfs(s,t,INT_MAX);
        if(f==0){return flow;}
        flow += f;
    }
}

int bipartite_matching_flow(int X, int Y, vector<pii> &edge_list){
    //X: 二部グラフの片方の頂点数，Y: もう片方の頂点数，edge_list: エッジをタプルで表したリスト
    for(int i=0;i<edge_list.size();i++){
        int s = edge_list[i].first;
        int t = edge_list[i].second;
        G[s].push_back((edge){X+t,1,G[X+t].size()});
        G[X+t].push_back((edge){s,0,G[s].size()-1});
    }

    for(int i=0;i<X;i++){
        G[X+Y].push_back((edge){i,1,G[i].size()});
        G[i].push_back((edge){X+Y,0,G[X+Y].size()-1});
    }

    for(int i=X;i<X+Y;i++){
        G[i].push_back((edge){X+Y+1,1,G[X+Y+1].size()});
        G[X+Y+1].push_back((edge){i,0,G[i].size()-1});
    }
    return maxflow(X+Y,X+Y+1);
}

int main(){
	int N;
	cin >> N;
	vector<ll> A(N);
	REP(i, N) cin >> A[i];

	sort(A.begin(), A.end());
	vector<pii> edge_list;

	ll beki = 2;
	while(beki<(1<<30)){
		REP(i, N){
			auto up = upper_bound(A.begin(), A.end(), beki-A[i]);
			auto lo = lower_bound(A.begin(), A.end(), beki-A[i]);
			int ba = lo-A.begin();
			if(up-lo>0 && i<ba){
				edge_list.push_back(make_pair(i, ba));
			}
		}
		beki *= 2;
	}

	/*
	REP(i, edge_list.size()){
		cout << edge_list[i].first << " " << edge_list[i].second << endl;
	}
	*/

    cout << bipartite_matching_flow(N, N, edge_list) << endl;
    return 0;
}

