ll binary_matching(vector<ll> now)
{
	if(now.empty())return 0;
	BM bm(now.size());

	// 左右分割
	REP(i, now.size())
	{
		if(now[i] % 2 == 0)bm.add_left(i);
		else bm.add_right(i);
	}

	int lim=0;
	while(powi(2,lim)<now.back())lim++;

	// 結合探知
	ll res=0;
	REP(id, now.size())
	{
		REP(p, lim+2)
		{
			ll opp = powi(2, p) - now[id] - 1;
			if(opp<1)continue;

			auto itrL = lower_bound(now.begin(), now.end(), opp);
			auto itrR= upper_bound(now.begin(), now.end(), opp);
			if(itrL != now.end() && (*itrL) == opp)
			{
				ll oppIdL = distance(now.begin(), itrL);
				ll oppIdR = distance(now.begin(), itrR);
				if(id == oppIdL)continue;

				FOR(m, oppIdL, oppIdR)
				{
					if(now[id] == 0)bm.add_mid(id, m);
					else bm.add_mid(m, id);
				}
			}
		}
	}
	res += bm.max_matching();
	return res;
}

