            int pos2=upper_bound(a.begin(),a.end(),num-a[i])-a.begin();
            int pos1=lower_bound(a.begin(),a.end(),num-a[i])-a.begin();
            deg[i]+=(pos2-pos1);
            if(num==2*a[i]) deg[i]--;
        }
    }
