    {
        ll ans=0;
        for(int i=0;i<n;++i)
            if(deg[i]>0)
                ans++;
        cout<<ans/2;
    }
    else
    {
        ll ans=0;
        while(!q.empty())
        {
            int v=q.front(); q.pop();
            if(deg[v]<=0) continue;
            deg[v]=0;
            for(int p=0;p<40;++p){
                ll num=p2[p];
                if(num<=a[v]) continue;
                int pos2=upper_bound(a.begin(),a.end(),num-a[v])-a.begin();
