int solve(vector < int >& cur) {
    multiset < int > all;
    for (int v : cur) all.insert(v);
    int ans = 0;
    while (!all.empty()) {
        auto it = --(all.end());
        int v = *it;
        all.erase(it);
        int pw = 1;
        while (v >= pw) pw *= 2;
        if (all.find(pw - v) != all.end()) {
            ans++;
            all.erase(all.find(pw - v));
        }
    }
    return ans;
}
