int solve(int n, vector<int> const & a) {
    unordered_map<int, int> f;
    for (int a_i : a) {
        f[a_i] += 1;
    }

    unordered_map<int, vector<int> > g;
    unordered_map<int, int> degree;
    queue<int> que;
    for (int a_i : a) if (not g.count(a_i)) {
        REP (k, 30) {
            int a_j = (1 << k) - a_i;
            if (f.count(a_j)) {
                g[a_i].push_back(a_j);
            }
        }
        degree[a_i] = g[a_i].size();
        if (degree[a_i] == 1) {
            que.push(a_i);
        }
    }

    int ans = 0;
    while (not que.empty()) {
        int a_i = que.front();
        que.pop();
        for (int a_j : g[a_i]) {
            int delta = min(f[a_i], f[a_j]);
            if (a_i == a_j) {
                delta /= 2;
            } else {
                f[a_i] -= delta;
            }
            f[a_j] -= delta;
            ans += delta;
        }
        for (int a_j : g[a_i]) {
            degree[a_j] -= 1;
            if (degree[a_j] == 1) {
                que.push(a_j);
            }
        }
    }
    return ans;
}

