	for(int i=b[0];i>=1;i--){
		if(st.count(b[i])){
			ans+=tot[i]/2;
		}else{
			int res=*st.upper_bound(b[i])-b[i];
			if(upper_bound(a+1,a+n+1,res)-lower_bound(a+1,a+n+1,res)){
				res=lower_bound(a+1,a+n+1,res)-a;
				int tmp=min(tot[res],tot[i]);
				ans+=tmp;
				tot[i]-=tmp;
				tot[res]-=tmp;
			}
		}
	}
	printf("%d\n",ans);
	return 0;
}

