int binary_search(vector<int> v,int x){
  int l = 0;
  int r = v.size()-1;

  while(r > l){
    int m = l + (r-l)/2;
    if(v[m] == x) return m;
    else if(v[m] > x) r = m-1;
    else l = m+1;
  }

  if(v[l]==x) return l;
  if(v[r]==x) return r;

  return -1;
}

