void solve() {
    ll N;
    cin >> N;
    vector<ll> A(N);
    for(int i = 0; i < N; i++) cin >> A[i];
    sort(all(A));

    vector<P> B(N);

    map<ll, ll> S, S2;
    for (int i = 0; i < N; i++) {
        int cnt = 0;
        for(ll j = 1; j <= 10000000000LL; j *= 2) {
            cnt += S[j - A[i]];
        }
        S[A[i]]++;
        B[i] = {cnt, i};
    }


    for (int i = N - 1; i >= 0; i--) {
        int cnt = 0;
        for(ll j = 1; j <= 10000000000LL; j *= 2) {
            cnt += S2[j - A[i]];
        }
        S2[A[i]]++;
        B[i].a += cnt;
    }

    map<ll, ll> C;
    for(int i = 0; i < N; i++) {
        C[A[i]] = B[i].a;
    }
    sort(all(B));

    ll ans = 0;
    for (int i = 0; i < N; i++) {
        ll v = A[B[i].i];
        if (C[v] == 0 || S[v] == 0) continue;
        ll mi = 0;

        int ma_j = -1, ma_c = 0;
        for(ll j = 1; j <= 10000000000LL; j *= 2) {
            if (S[j - v] > 0 && C[j - v] > ma_c) {
                ma_c = C[j - v];
                ma_j = j;
            }
        }
        if (ma_j != -1) {
            ans++;
            S[v]--;
            S[ma_j - v]--;
        }
    }
    cout << ans << endl;
}

