typedef long long ll;

vector<int> edg[200005];
vector<int> cnt(200005);
vector<int> dup(200005);

int main() {
	int n; cin >> n;
	vector<ll> a(n + 10);
	for (int i = 0; i < n; i++) cin >> a[i];
	sort(a.begin(), a.end() - 10);
	int idx = 0, c = 0;
	while (idx < n) {
		int t = idx + 1;
		while (a[t] == a[idx]) t++;
		dup[c] = t - idx;
		idx = t;
		c++;
	}
	n = c;
	for (int i = 0; i < n; i++) {
		for (ll t = 1; t <= 30; t++) {
			ll tg = (1LL << t) - a[i];
			if (tg <= 0) continue;

			int lo = -1, hi = n;
			while (hi - lo > 1) {
				int mid = lo + (hi - lo) / 2;
				if (a[mid] >= tg) hi = mid;
				else lo = mid;
			}
			if (a[hi] != tg) continue;
			if (hi == i && dup[i] <= 1) continue;
			edg[i].push_back(hi);
			if (hi == i) cnt[i] += dup[i] - 1;
			else cnt[i]++;
		}
	}
	int ans = 0;
	priority_queue<pair<int, int>> que;
	for (int i = 0; i < n; i++) que.push({ -cnt[i], i });
	while (!que.empty()) {
		int idx = que.top().second; que.pop();
		if (cnt[idx] <= 0) continue;
		if (dup[idx] <= 0) continue;

		for (int i : edg[idx]) {
			if (cnt[i] <= 0) continue;
			if (idx == i && dup[idx] <= 1) continue;

			ans++;
			dup[idx]--;
			dup[i]--;

			for (int j : edg[idx]) {
				cnt[j]--;
				if (cnt[j] > 0 && dup[j] > 0) que.push({ -cnt[j], j });
			}
			for (int j : edg[i]) {
				cnt[j]--;
				if (cnt[j] > 0 && dup[j] > 0) que.push({ -cnt[j], j });
			}
		}

	}
	cout << ans << endl;
	return 0;
}

