long long upperP2(long long a){
    long long r = 2;
    while (r <= a)
    {
        r *= 2;
    }
    return r;
}

int main(){
    int n;
    map<long long, int> m;

    scanf("%d", &n);
    for(int i = 0; i < n; i++){
        long long a;
        scanf("%lld", &a);
        m[a] += 1;
    }

    int r = 0;

    for (auto i = m.rbegin(), e = m.rend(); i != e; ++i) {
        long long a = i->first;
        int c = i->second;
        if(c == 0){
            continue;
        }
        long long s = upperP2(a) - a;
        if(a == s){
            r += c / 2;
        }else{
            auto f = m.find(s);
            if(f != m.end()){
                int u = min(c, f->second);
                r += u;
                f->second -= u;
            }
        }
    }

    printf("%d\n", r);

    return 0;
}

