    if (it->second == 0) continue;
    ll x = it->first;
    ll nxt = 1;
    while (nxt <= x) nxt <<= 1;
    ll y = nxt - x;
    if (y > x) continue;
    if (m.count(y) > 0) {
      if (x == y) {
        ans += it->second / 2;
        it->second %= 2;
      }
      else {
        ll use = min(it->second, m[y]);
        it->second -= use;
        m[y] -= use;
        ans += use;
      }
    }
  }
  cout << ans << endl;
}

