    rep(i, 0, N)
    {
        ll A;
        cin >> A;
        ++m[A];
    }

    vector<pair<ll, ll>> A;
    for (const auto& p : m)
    {
        A.push_back(p);
    }

    vector<ll> twos;
    ll two = 1;
    while (two <= 2000000000LL)
    {
        twos.push_back(two);
        two *= 2;
    }

    ll ans = 0;
    while (true)
    {
        ll prevAns = ans;

        rrep(i, A.size() - 1, 0)
        {
            const ll a = A[i].first;
            const ll num = A[i].second;

            if (num <= 0) continue;

            for (const ll two : twos)
            {
                const ll b = two - a;
                if (b <= 0) continue;

                ll ng = -1;
                ll ok = A.size();
                while (abs(ng - ok) > 1)
                {
                    const ll mid = (ng + ok) / 2;
                    if (A[mid].first >= b) ok = mid;
                    else ng = mid;
                }

                if (A[ok].first != b) continue;

                if (a != b && A[ok].second <= 0) continue;
                if (a == b && A[ok].second <= 1) continue;

                --A[i].second;
                --A[ok].second;
                ++ans;
                break;
            }
        }

        if (ans == prevAns)
        {
            break;
        }
    }
