int N;

bool power_of_two(int n) {
    while (n % 2 == 0) {
        n /= 2;
    }
    return n == 1;
}

int main() {
    cin >> N;

    list<int> A;
    int a;
    for (int i = 0; i < N; i++) {
        cin >> a;
        A.push_back(a);
    }
    A.sort(greater<int>());

    int ans = 0;
    while(A.size() > 1) {
        int largest = *A.begin();
        A.erase(A.begin());
        for (auto itr = A.begin(); itr != A.end(); ++itr) {
            if (power_of_two(largest + *itr)) {
                A.erase(itr);
                ans++;
                break;
            }
        }
    }
    cout << ans << endl;
}

