typedef long long ll;

vector<int> edg[200005];
vector<int> cnt(200005);
vector<int> dup(200005);

int main() {
	int n; cin >> n;
	vector<ll> a(n + 10);
	for (int i = 0; i < n; i++) cin >> a[i];
	sort(a.begin(), a.end() - 10);
	int idx = 0, c = 0;
	while (idx < n) {
		int t = idx + 1;
		while (a[t] == a[idx]) t++;
		dup[c] = t - idx;
		idx = t;
		c++;
	}
	n = c;
	for (int i = 0; i < n; i++) {
		if (dup[i] > 1) {
			edg[i].push_back(i);
			cnt[i] = dup[i] - 1;
		}
	}
	for (int i = 0; i < n; i++) {
		for (ll t = 1; t <= 30; t++) {
			ll tg = (1LL << t) - a[i];
			if (tg <= 0) continue;

			int lo = -1, hi = n;
			while (hi - lo > 1) {
				int mid = lo + (hi - lo) / 2;
				if (a[mid] >= tg) hi = mid;
				else lo = mid;
			}
			if (a[hi] != tg) continue;
			int j = hi;
			while (j < n && a[j] == a[hi]) {
				if (j == i) {
					j++;
					continue;
				}
				edg[i].push_back(j);
				cnt[i]++;
				j++;
			}
			j = hi - 1;
			while (j >= 0 && a[j] == a[hi]) {
				if (j == i) {
					j--;
					continue;
				}
				edg[i].push_back(j);
				cnt[i]++;
				j--;
			}
		}
	}
	int ans = 0;
	priority_queue<pair<int, int>> que;
	for (int i = 0; i < n; i++) que.push({ -cnt[i], i });
	while (!que.empty()) {
		int idx = que.top().second; que.pop();
		if (cnt[idx] <= 0) continue;
		if (dup[idx] <= 0) continue;

		int d, mi = 1e9;
		for (int i : edg[idx]) {
			if (cnt[i] <= 0) continue;
			if (cnt[i] < mi) {
				mi = cnt[i];
				d = i;
			}
		}
		if (mi != 1e9) {
			ans++;
			dup[idx]--;
			dup[d]--;

			for (int j : edg[idx]) {
				cnt[j]--;
				if (cnt[j] > 0 && dup[j] > 0) que.push({ -cnt[j], j });
			}
			for (int j : edg[d]) {
				cnt[j]--;
				if (cnt[j] > 0 && dup[j] > 0) que.push({ -cnt[j], j });
			}
		}
	}
	cout << ans << endl;
	return 0;
}

