				int pos = lower_bound(A_vec.begin(), A_vec.end(), b - A_vec[i]) - A_vec.begin();
				if (pos == i) pos++;
				for (; pos > i && pos < A_vec.size() && A_vec[pos] == b - A_vec[i]; pos++) {
					graph.add_edge(i, pos);
				}
			}
			if (b == 1 << 30) break;
		}
	}

