const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
vl as;
bool used[MAX_N];
mll cnt;

void solve(){
    as = vl(n);
    rep(i, n) in1(as[i]);
    sort(all(as));

    revrep(i1, 31){
        ll target = 1LL << i1;
        rep(i2, n){
            if (as[i2] > target / 2) break;
            if (used[i2]) continue;
            ll lb = lower_bound(all(as), target - as[i2]) - as.begin();

            if (as[i2] == target / 2){
                if (lb + cnt[as[lb]] < n - 1 && 
                    as[lb + cnt[as[lb]]] == target / 2 && 
                    as[lb + cnt[as[lb]] + 1] == target / 2){
                    used[lb + cnt[as[lb]]] = used[lb + cnt[as[lb]] + 1] = true;
                    cnt[as[lb]] += 2;
                }
            }else{
                if (lb + cnt[as[lb]] < n &&
                    !used[lb + cnt[as[lb]]] &&
                    as[lb + cnt[as[lb]]] + as[i2] == target){
                    used[i2] = used[lb + cnt[as[lb]]] = true;
                    cnt[as[lb]]++; cnt[as[i2]]++;
                }
            }
        }
    }

    rep(i, n) answer += used[i];
    prl(answer / 2);
}

int main(void){
    in1(n);
    solve();
    // assert(n <= 10000);
    return 0;
}

