int solve(int x,bool b) {
    int ret=0;
    int deg=0;
    int num=0;
    for(int v:G[x]) {
        deg++;
        int tmp0=solve(v,0),tmp1=solve(v,1);
        ret+=tmp1;
        if(tmp1==tmp0) num++;
    }
    if(num<cnt[x]) {
        ret+=num;
        if(b) ret+=(cnt[x]-num)/2;
        else ret+=(cnt[x]-1-num)/2;
    } else {
        if(b) ret+=cnt[x];
        else ret+=cnt[x]-1;
    }
    return ret;
}

