  rep(i,0,N - 1) cin >> a[i];
  i64 MAX = 1e9;
  map<i64,queue<int>> mp;
  rep(i,0,N - 1) mp[a[i]].push(i);
  vector<vector<int>> v(N);
  for(int i = 0;i < N;i++){
    mp[a[i]].pop();
    for(i64 b = 1;b <= MAX;b <<= 1) {
      if(mp.count(b - a[i])) {
        auto& s = mp[b - a[i]];
        if(!s.empty()) {
          int j = s.front();
          v[j].push_back(i);
          v[i].push_back(j);
        }
      }
    }
  }

  cout << gabow_edmonds(v).size() << endl;
}

