ll n, a[MAX_N], deg[MAX_N];
ll ans=0;
vector<vector<int> > g;
map<ll, ll> cnt;

void dfs(int k, int pre = IINF){
    //cout << a[k] << endl;
    for(auto to : g[k]){
        if(cnt[a[to]]==0)continue;
        if(to == pre)continue;
        ll m = min(cnt[a[k]],cnt[a[to]]);
        ans+=m;
        cnt[a[k]] -= m;
        cnt[a[to]] -= m;
        if(deg[k]>0)deg[k]--;
        if(deg[to]>0)deg[to]--;
        if(deg[to]>1 && cnt[a[to]]>0)continue;
        dfs(to, k);
    }
    return;
}

int main() {
