const long long int MAX_N = 200000;

long long int p[MAX_N];

long long int n = 0;
long long int lowid, midid, highid;
long long int c = 0;
long long int target = 0;

long long int nearPow = 1;

void quickSort(long long int numbers[], long long int array_size) {
  std::sort(numbers, numbers + array_size);
}

void solve(long long int x) {
  if (x > 0){
    if ((p[x - 1] & (p[x - 1] - 1)) == 0) {
      if (p[x - 2] == p[x - 1]) {
        c += 1;
        solve(x - 2);
      } else {
        solve(x - 1);
      }
    } else if (p[x - 1] % 2 == 1) {
      solve(x - 1);
    } else {
      nearPow = pow(2.0, (floor(log2(p[x - 1] - 1)) + 1.0));
      target = nearPow - p[x - 1];

      highid = x;
      lowid = 0;

      while (lowid <= highid) {
        midid = (lowid + highid) / 2;
        if (p[midid] == target) {
          while (p[midid - 1] == target) {
            midid -= 1;
          }
          p[midid] -= 1;
          c += 1;
          break;
        } else if (p[midid] < target) {
          lowid = midid + 1;
        } else {
          highid = midid - 1;
        }
      }
      solve(x - 1);
    }
  }
}

