int solve(int x,bool b) {
    if(memo[b].count(x)) return memo[b][x];
    int ret=0;
    int deg=0;
    int num=0;
    for(int v:G[x]) {
        deg++;
        int tmp0=solve(v,0),tmp1=solve(v,1);
        ret+=tmp1;
        if(tmp1==tmp0) num++;
    }
