const double EPS = 1e-9;

const int DX[]={1,0,-1,0},DY[]={0,-1,0,1};

void solve(long long N, std::vector<long long> A){
    map<int, int> memo;
    REP(i, N) {
        if(memo.count(A[i]) == 0) {
            memo[A[i]] = 0; 
        }

        memo[A[i]]++;
    }

    VLL beki;
    LL idx = 1;
    while(idx <= 2000000000LL) {
        beki.PB(idx);
        idx *= 2LL;
    }

    sort(ALL(A));
    A.erase(unique(ALL(A)), A.end());
    int ans = 0;
    RREP(i, A.size()-1) {
        REP(j, beki.size()) {
            int idx = beki[j] - A[i];
            if(memo.count(idx) == 1) {
                if(A[i] == idx) {
                    int add_ans = memo[idx] / 2;
                    memo[idx] -= add_ans * 2;
                    ans += add_ans;
                } else {
                    int add_ans = min(memo[idx], memo[A[i]]);
                    memo[idx] -= add_ans;
                    memo[A[i]] -= add_ans;
                    ans += add_ans;
                }
            }
        }
    }

    cout << ans << endl;
}

