const int Maxn=2e5;
typedef long long ll;

int N;
ll A[Maxn+5];
ll num[35];
bool used[Maxn+5];
map<ll,int> S;

void Init() {
	num[0]=1;
	for(int i=1;i<=32;i++)
		num[i]=num[i-1]*2;
}

int find(int pos) {
	ll x=A[pos];
	for(int i=32;i>=1;i--) {
		ll val=num[i]-x;
		if(val<1||val>A[N])continue;
		int k=lower_bound(A+1,A+N+1,val)-A;
		if(used[k])continue;
		if(A[k]+x!=num[i])
			continue;
		else if(S[A[k]]==1&&k==pos) {
			S[A[k]]=0;
			continue;
		} else return k;
	}
	return -1;
}

