int rec(vector<int> a) {
  bool ok = true;
  for (int i = 0; i < sz(a); i++) {
    if (!(a[i] & 1)) {
      ok = false;
    }
  }
  int res = 0;
  if (!ok) {
    vector<int> b;
    int k = 0;
    for (int i = 0; i < sz(a); i++) {
      if (a[i] & 1) {
        a[k++] = a[i];
      } else {
        b.push_back(a[i] >> 1);
      }
    }
    a.resize(k);
    res += rec(b);
  }
  sort(a.begin(), a.end(), greater<int>());
  set<pair<int, int>> st;
  for (int i = 0; i < sz(a); i++) {
    st.insert(make_pair(a[i], i));
