        cin >> a[i];
    }
    Dinic<int> dinic(n*2+2);
    for(int i = 0; i < n; ++i){
        dinic.add_edge(0, i+1, 1);
        dinic.add_edge(n+1+i, n*2+1, 1);
    }
    for(int i = 0; i < n; ++i){
        for(int j = 0; j < n; ++j){
            if(i == j) continue;
            int sum = a[i] + a[j];
            ll m = 1;
