struct Vertex {
	vector<int> edge;
	int size;

	Vertex() {
		size = 0;
	}

	void addEdge(int e) {
		edge.push_back(e);
		++ size;
	}
};

int main() {
	static int N, A[MAX];
	cin >> N;
	for (int i = 0;i < N;++ i) cin >> A[i];
	sort(A, A+N);
	static Vertex v[MAX];
	for (int i = 1;i >= 0;i <<= 1) { // ちょっと非本質的な書き方だけど、オーバーフローするんだもん……
		for (int j = 0, k = N - 1;j < k;) {
			if (A[j] + A[k] > i) -- k;
			else if (A[j] + A[k] < i) ++ j;
			else {
				v[j].addEdge(k);
				v[k].addEdge(j);
				++ j;
			}
		}
	}

	queue<int> que;
	for (int i = 0;i < N;++ i) if (v[i].size == 1) que.push(i);

	int tmp, pair = 0;
	while(!que.empty()) {
		tmp = que.front();
		que.pop();
		if (v[tmp].size -- <= 0) continue;
		++ pair;
		for (int i = 0, l = v[tmp].edge.size();i < l;++ i) {
			if (v[v[tmp].edge[i]].size == 1) que.push(v[tmp].edge[i]);
		}
	}
	for (int i = 0;i < N;++ i) if (v[i].size > 1) ++ pair;
	cout << pair / 2;
	return 0;
}
