const int MAX = 100010;

int N;
int A[MAX];
int match[MAX];
map<long long,vector<int>> table;

bool matching(bool visit[],int n){
    if(table.count(A[n]) == 0)return false;
    if(visit[n])return false;
    visit[n] = true;

    for(int i = 0;i < table[A[n]].size();i++){
        int m = match[table[A[n]][i]];
        if(visit[table[A[n]][i]])continue;
        if((m != -1 && matching(visit,match[m])) || m == -1){
            match[table[A[n]][i]] = n;
            match[n] = table[A[n]][i];
            return true;
        }
    }
    return false;
}

int main(){
    cin >> N;
    for(int i = 0;i < N;i++){
        cin >> A[i];
        table[A[i]] = vector<int>();
    }

    for(int i = 0;i < N;i++){
        match[i] = -1;

        for(int j = 0;j < 32;j++){
            long long n = pow(2,j + 1) - A[i];
            if(n <= 0)continue;
            if(table.count(n) == 0)continue;
            table[n].push_back(i);
        }
    }

    int cnt = 0;
    for(int i = 0;i < N;i++){
        bool visit[MAX] = {false};
        if(matching(visit,i)){
            cnt++;
        }
    }

    cout << cnt << endl;

    return 0;
}

