int main(){
	int N; cin>>N;
	vector<ll> A(N);
	map<ll,ll> hash;
	priority_queue<pair<ll,ll>> Q;
	rep(i,N){cin>>A[i]; hash[A[i]]++;}
	rep(i,N){
		ll cand = 0;
		ll t = 2;
		while(t < 1000000100){
			if(hash.count(t - A[i]) == 1){
				if(A[i] == t-A[i]){
					if(hash[A[i]] >= 2){++cand;}
				}else{
					++cand;
				}
			}
			t *= 2;
		}
		if(cand != 0){
			Q.push(make_pair(cand, i));
		}
	}
	// while(!Q.empty()){
	// 	cout<<Q.top().second<<" has "<<Q.top().first<<endl;
	// 	Q.pop();
	// }
	// return 0;
	ll ans = 0;
	while(!Q.empty()){
		ll e = A[Q.top().second];
		Q.pop();
		if(hash[e] <= 0)continue;
		ll t = 2;
		while(t < 1000000100){
			if(hash[t-e] > 0){
				++ans;
				--hash[t-e];
				--hash[e];
				if(hash[e] < 0)--ans;
				break;
			}
			t *= 2;
		}
	}
	cout<<ans<<endl;
	return 0;
}

