using namespace std;
using lli = long long int;

lli N;

int main() {

	lli ans = 0;
	cin >> N;

	map<lli, lli> m;

	for (int i = 0; i < N; i++) {
		lli a;
		cin >> a;
		m[a]++;
	}

	for (auto itr = m.rbegin(); itr != m.rend(); itr++) {
		while (itr->second > 0) {
			bool update = false;
			for (int i = 35; i >= 1; i--) {
				lli target = (1LL << i) - itr->first;
				auto find_itr = m.find(target);
				if (find_itr != m.end() && find_itr->second > 0) {
					if (itr->first == find_itr->first && find_itr->second == 1) {
						continue;
					}
					itr->second--;
					find_itr->second--;
					ans++;
					update = true;
					break;
				}
			}
			if (!update)
				break;
		}
	}

	cout << ans << endl;

	return 0;
}

