        a.push_back(j);
        mp[j]++;
    }

    sort(ALL(a));
    a.erase(unique(ALL(a)), a.end());

    int ans = 0;
    RREP(i, a.size()) {
        REP(j, 31) {
            if (mp[a[i]] == 0) break;
            if (2LL * a[i] > 1LL << j) break;
            int target = (1 << j) - a[i];
            if (target == a[i]) {
                int tmp = mp[target] / 2;
                mp[target] -= tmp * 2;
                ans += tmp;
            } else {
                int tmp1 = mp[target];
                int tmp2 = mp[a[i]];
                mp[target] -= min(tmp1, tmp2);
                mp[a[i]] -= min(tmp1, tmp2);
                ans += min(tmp1, tmp2);
            }
        }
    }

    OUT(ans)BR;

    return 0;
}

