typedef long long ll;
typedef unsigned int uint;
using namespace std;

struct node {
    int val;
    node *lch;
    node *rch;
};

node *insert(node *p, int x) {
    if (p == NULL) {
        node *q = new node;
        q->val = x;
        q->lch = q->rch = NULL;
        return q;
    } else {
        if (x < p->val) {
            p->lch = insert(p->lch, x);
        } else {
            p->rch = insert(p->rch, x);
        }
        return p;
    }
}

bool find(node *p, int x) {
    if (p == NULL) {
        return false;
    } else if (x == p->val) {
        return true;
    } else if (x < p->val) {
        return find(p->lch, x);
    } else {
        return find(p->rch, x);
    }
}

node *remove(node *p, int x) {
    if (p == NULL) {
        return NULL;
    } else if (x < p->val) {
        p->lch = remove(p->lch, x);
    } else if (x > p->val) {
        p->rch = remove(p->rch, x);
    } else if (p->lch == NULL) {
        node *q = p->rch;
        delete p;
        return q;
    } else if (p->lch->rch == NULL) {
        node *q = p->lch;
        q->rch = p->rch;
        delete p;
        return q;
    } else {
        node *q;
        for (q = p->lch; q->rch->rch != NULL; q = q->rch);
        node *r = q->rch;
        q->rch = r->lch;
        r->lch = p->lch;
        r->rch = p->rch;
        delete p;
        return r;
    }
    return p;
}

int find_max(node *p) {
    if (p == NULL) {
        return 0;
    } else {
        while (p->rch) {
            p = p->rch;
        }
    }
    return p->val;
}

int main() {
    cin.sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    int A[n];
    node *root = NULL;
    for (int i = 0; i < n; i++) {
        cin >> A[i];
        root = insert(root, A[i]);
    }

    int ans = 0;

    int w = (1 << 30);
    while (n > 0) {
        int mx = find_max(root);
        if (mx == 0) break;
        while (mx * 2 < w) {
            w /= 2;
        }

        remove(root, mx);
        if (find(root, w-mx)) {
            ans++;
            remove(root, w-mx);
            n--;
        }

        n--;
    }


    cout << ans << "\n";
    return 0;
}

