int bsearch(int b,int e,long* arr,long dst){
  if(b>e) return -1;
  if(arr[b]==dst) return b;
  if(arr[e]==dst) return e;
  int m = (b+e)/2;
  if(b==m) return -1;
  if(arr[m]<dst) return bsearch(m,e,arr,dst);
  else if(arr[m]>dst) return bsearch(b,m,arr,dst);
  return m;
}
