typedef long long ll;

using namespace std;

ll tob(ll x){
	ll ret = 0;
	for(;x;x >>= 1)ret++;
	return ret;
}

int main(){
	ll n; cin >> n;
	map<ll, ll> m;
	for(int i = 0; i < n; i++){
		ll a; cin >> a;
		if(m.find(a) == m.end())m[a] = 0;
		m[a]++;
	}

	ll ans = 0;
	for(auto itr = m.rbegin(); itr != m.rend(); ++itr){
		//cerr << itr->first << endl;
		ll c = (1 << tob(itr->first)) - itr->first;
		if(m.find(c) != m.end()){
			if(itr->first == c){
				ans += itr->second >> 1;
				itr->second = itr->second & 1;
				continue;
			}
			ll cc = min(m[itr->first], m[c]);
			ans += cc;
			//for(auto e : m)cerr << e.first << ":" << e.second << " ";
			//cerr << endl;
			m[c] -= cc;
		}
	}
	cout << ans << endl;


	return 0;
}

