multiset<int> AA;
int result = 0;

void findAndReduce() {
    while (!AA.empty()) {
        auto itr = AA.rbegin();
        auto a = *itr;
        //itrを削除
        AA.erase(AA.find(a));
        int tw = 1;
        for (int i = 1; i < 40; ++i) {
            tw *= 2;
            if(tw > a){
                break;
            }
        }
        auto b = tw - a;
        auto itr2 = AA.find(b);
        if (itr2 == AA.end()) {
            continue;
        }
        AA.erase(itr2);
        result++;
    }
}

int main() {

    int N;
    cin >> N;

    for (int i = 0; i < N; ++i) {
        int n;
        cin >> n;
        AA.insert(n);
    }


    findAndReduce();

    cout << result << endl;


    return 0;
}

