	for (int i = 1; i <= n; i++) {
		scanf("%d", &a[i]);
		mp[a[i]]++;
	}
	int mx = (1 << 30);
	while (mx > 1) {
		vector < pair < int, int > > vec;
		for (auto to : mp) {
			vec.push_back({to.first, to.second});
		} 
		sort(vec.begin(), vec.end());
