			if (vec[i].second == 0) {
				mp.erase(vec[i].first);
			} else {
				if (vec[i].first * 2 != mx) {
					if (mp.count(mx - vec[i].first)) {
						int mn = min(vec[i].second, mp[mx - vec[i].first]);
						ans += mn;
						mp[vec[i].first] -= mn;
						mp[mx - vec[i].first] -= mn;
					}
				} 
			}
		}
		mx >>= 1;
	}
	mx = (1 << 30);
	while (mx > 1) {
		vector < pair < int, int > > vec;
		for (auto to : mp) {
			vec.push_back({to.first, to.second});
		} 
		sort(vec.begin(), vec.end());
		for (int i = 0; i < vec.size(); i++) {
			if (vec[i].second == 0) {
				mp.erase(vec[i].first);
			} else {
				if (vec[i].first * 2 == mx) {
					int mn = vec[i].second / 2;
					ans += mn;
					mp[vec[i].first] -= mn;
				}
			}
		}
		mx >>= 1;
	}

