typedef long long ll;
using namespace std;

int main(void) {
  ll i, n, ans = 0;
  scanf("%lld", &n);
  ll a[n];
  bool flg[n];
  for(i = 0; i < n; ++i) scanf("%lld", &a[i]), flg[i] = true;
  sort(a, a + n);
  for(i = n - 1; i; --i) if(flg[i]) {
    ll now = 1;
    flg[i] = false;
    while(now <= a[i]) now *= 2;
    now -= a[i];
    ll tmp = lower_bound(a, a + n, now) - a;
    while(tmp != n && a[tmp] == now) {
      if(flg[tmp]) {
        ++ans;
        flg[tmp] = false;
        break;
      }
      ++tmp;
    }
  }
  printf("%lld", ans);
  return 0;
}

#include <iostream>
#include <vector>
#include <map>
using namespace std;

void dec(map<long long, long long> &ma, long long a) {
    ma[a]--;
    if (ma[a] == 0) {
        ma.erase(a);
    }
}

int main() {
    int N; cin >> N;
    vector<long long> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];
    map<long long, long long> ma;
    for (int i = 0; i < N; ++i) ma[-a[i]]++;

    long long res = 0;
    for (int i = 0; i < N && !ma.empty(); ++i) {
        long long val = -ma.begin()->first;

        dec(ma, -val);
        long long po = 1;
        while (po <= val) po *= 2;
        long long rem = po - val;
        if (ma.count(-rem)) {
            ++res;
            dec(ma, -rem);
        }
    }
    cout << res << endl;
}

