int main() {
    int N;
    cin >> N;
    multiset<int> A;

    for (int i = 0; i < N; ++i) {
        int t;
        cin >> t;
        A.insert(t);
    }

    int ans = 0;
    auto it = A.end();
    --it;
    while (A.size() > 1 && it != A.begin()) {
        int n = *it;
        A.erase(it);
        it = A.end();
        --it;

        int mask = 0;
        int tmp = n;
        while (tmp) {
            tmp >>= 1;
            mask = (mask << 1) | 1;
        }
        int op = (~n & mask) + 1;

        auto opi = A.find(op);
        if (opi != A.end()) {
            ++ans;
            A.erase(opi);
        }
    }

    cout << ans << endl;



    return 0;
}

