        if(chmax(res,res + cnt[a[i]] / 2)){
          cnt[a[i]] -= cnt[a[i]] / 2;
        }
      }else{
        if(chmax(res,res + min(cnt[a[i]],cnt[bit-a[i]]))){
          int tmp = min(cnt[a[i]],cnt[bit-a[i]]);
          cnt[a[i]] -= tmp;
          cnt[bit-a[i]] -= tmp;
        }
      }
    }
  }

  cout << res << '\n';

  return 0;
}

