int main() {
    int n;
    cin >> n;
    int a[n];
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    sort(a, a + n);
    int size = a[n - 1] * 2;
    vector<int> pow2 {1}, graph[n];
    while (pow2.back() * 2 <= size) {
        pow2.emplace_back(pow2.back() * 2);
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < pow2.size(); j++) {
            auto it = lower_bound(a, a + n, pow2[j] - a[i]);
            if (it != a + n && distance(a, it) != i) {
                graph[i].emplace_back(distance(a, it));
            }
        }
    }
    int result = 0;
    vector<bool> visited(n);
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            int current = 0;
            visited[i] = true;
            stack<int> stack;
            stack.emplace(i);
            do {
                auto top = stack.top();
                current++;
                stack.pop();
                for (int j : graph[top]) {
                    if (!visited[j]) {
                        visited[j] = true;
                        stack.emplace(j);
                    }
                }
            } while (!stack.empty());
            result += current / 2;
        }
    }
    cout << result;
    return 0;
}

