using vvi = vector<vi>;
#pragma GCC optimize("O3")
#pragma GCC optimize("unroll-loops")

int main() {
    int n;
    cin >> n;
    map<int, int> mp;
    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        mp[a]++;
    }
    map<int, int> rev;
    for (auto &p : mp) {
        for (int i = 1; i < 31; i++) {
            if (mp.count((1 << i) - p.first)) {
                if (p.first == (1 << i) - p.first) continue;
                rev[p.first];
            }
        }
    }

    int N = 0;
    vi rev2;
    for (auto &p : rev) {
        p.second = N++;
        rev2.push_back(p.first);
    }

    int cnt = 0;
    if (N) {
        vvi adj(N);
        for (auto &p : mp) {
            for (int i = 1; i < 31; i++) {
                if (mp.count((1 << i) - p.first)) {
                    if (p.first == (1 << i) - p.first) continue;
                    adj[rev[p.first]].push_back(rev[(1 << i) - p.first]);
                }
            }
        }

        vi visited(N);
        int leaf = 0;
        function<void(int, int)> dfs = [&](int v, int p) {
            leaf = v;
            for (int s : adj[v]) {
                if (s != p) {
                    assert(visited[s] == 0);
                    visited[s] = 1;
                    dfs(s, v);
                }
            }
        };

        dfs(0, -1);

        function<void(int, int)> dfs2 = [&](int v, int p) {
            for (int s : adj[v]) {
                if (s != p) {
                    int k = min(mp[rev2[v]], mp[rev2[s]]);
                    cnt += k;
                    mp[rev2[v]] -= k;
                    mp[rev2[s]] -= k;
                    dfs2(s, v);
                }
            }
        };

        dfs2(leaf, -1);
    }

    for (int i = 0; i < 30; i++) {
        if (mp.count(1 << i)) {
            cnt += mp[1 << i] / 2;
        }
    }
    cout << cnt << endl;
}

