void dfs(int u,int p){
	vis[u]=1;
	int sum=0;
	bool f=false;
	FOR(i,0,g[u].size()){
		int v=g[u][i];
//		printf("u=%d v=%d\n",u,v);
		if(v==p) continue;
		if(u==v){
			f=true;
			continue;
		}
		dfs(v,u);
		sum+=cnt[v];
	}
//	printf("u=%d p=%d sum=%d\n",u,p,sum);
	if(sum<cnt[u]){
		cnt[u]-=sum;
		ans+=sum;
		if(f){
			ans+=cnt[u]>>1;
			cnt[u]=cnt[u]&1;
		}
	}else{
		ans+=cnt[u];
		cnt[u]=0;
	}
	return;
}

