int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    lint N; cin >> N;

    lint K = 30;
    vector<vector<lint>> V(K);

    REP(i, K) {
      V[i] = vector<lint>();
    }


    REP(i, N) {
      lint a; cin >> a;

      REP(j, K) {
        if (a & (1<<j)) {
          V[j].push_back(a);
          break;
        }
      }
    }

    lint res = 0;

    REP(j, K) {
      vector<lint> v(K, 0);
      SORT(V[j]);

      sort(V[j].begin(), V[j].end(), greater<lint>());

      map<lint, lint> cnt_list;
      REP(i, V[j].size()) {
        cnt_list[V[j][i]]++;
      }

      REP(i, V[j].size()) {
        lint a = V[j][i];
        if (cnt_list[a] == 0) continue;

        lint max_bit = -1;
        lint copy_a = a;
        while(copy_a > 0) {
          max_bit++;
          copy_a = copy_a>>1;
        }

        lint mask = 1<<j;
        FOR(bit, 0, max_bit+1) {
          if(!(a & 1<<bit)) {
            mask += 1<<bit;
          }
        }

        if(cnt_list[mask] > 0) {
