// O(V(V+E))
class BipartiteMatching
{
    int size;
    vector<vector<int>> g;
    vector<int> match;
    vector<bool> used;
    bool dfs(int v)
    {
        used[v] = true;
        for (int u : g[v])
        {
            int w = match[u];
            if (w < 0 || (!used[w] && dfs(w)))
            {
                match[v] = u;
                match[u] = v;
                return true;
            }
        }
        return false;
    }

  public:
    BipartiteMatching(int v) : size(v), g(v), match(v), used(v) {}
    void add_edge(int u, int v)
    {
        g[u].push_back(v);
        g[v].push_back(u);
    }
    int maximum_matching(void)
    {
        int res = 0;
        fill(begin(match), end(match), -1);
        for (int v = 0; v < size; ++v)
        {
            if (match[v] >= 0)
                continue;
            fill(begin(used), end(used), 0);
            if (dfs(v))
                ++res;
        }
        return res;
    }
    vector<bool> usedVector()
    {
        return used;
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    vector<ll> a(n);
    for (int i = 0; i < n; i++)
    {
        cin >> a[i];
    }
    sort(a.begin(), a.end());
    BipartiteMatching bm(n);
    vector<bool> check(n, false);
    map<ll, vector<int>> mp;
    for (ll i = 0; i < n; i++)
    {
        for (ll j = 1; j <= 30; j++)
        {
            ll gt = (1LL << j) - a[i];
            if (gt <= 0)
                continue;
            if (mp.find(gt) == mp.end())
                continue;
            if (a[i] == gt)
            {
                check[i] = true;
                continue;
            }
            for (auto v : mp[gt])
            {
                bm.add_edge(i, v);
            }
        }
        mp[a[i]].push_back(i);
    }
    int res = bm.maximum_matching();
    vector<bool> used = bm.usedVector();
    for (int i = 0; i < n; i++)
    {
        if (!check[i] || used[i])
            continue;
        used[i] = true;
        for (auto v : mp[a[i]])
        {
            if (used[v])
                continue;
            used[v] = true;
            res++;
            break;
        }
    }
    cout << res << endl;
}

