    for (int i = 0; i < n; i++) {
        ll x;
        cin >> x;
        int p = bsf(ull(x));
        g[p].push_back(x >> p);
    }
    int ans = 0;
    for (auto v: g) ans += solve(v);
    cout << ans << endl;
    return 0;
}

