const int MAX_N = 200005;
const int K = 35;

int n;
ll a[MAX_N];
bool used[MAX_N];
map<ll, set<int>> cnt;
vector<int> g[MAX_N];

int main()
{
	ios::sync_with_stdio(false);
	cin >> n;
	for (int i = 0; i < n; i++)
		cin >> a[i];
	sort(a, a + n);
	for (int i = n - 1; i >= 0; i--)
		cnt[a[i]].insert(i);

	for (int i = 0; i < n; i++)
	{
		if (used[i])
			continue;
		cnt[a[i]].erase(i);
		if (cnt[a[i]].empty())
			cnt.erase(a[i]);
		for (ll pow = 1LL << K; pow > 0; pow >>= 1)
		{
			ll x = pow - a[i];
			if (x < 1)
				break;
			if (cnt.count(x) != 0)
			{
				auto it = cnt[x].begin();
				if (x == a[i])
					used[*it] = true;
				//cout << "! " << i << " " << *it << endl;
				g[i].push_back(*it);
				cnt[x].erase(it);
				if (cnt[x].empty())
					cnt.erase(x);
				break;
			}
		}
	}

	set<pair<int, int>> s;
	for (int i = 0; i < n; i++)
		if (!g[i].empty())
			s.emplace((int)g[i].size(), i);

	int result = 0;
	while (!s.empty())
	{
		auto it = s.begin();
		pair<int, int> p = *it;
		s.erase(it);
		if (p.first == 0)
			continue;
		int v = g[p.second].back();
		result++;
		//cout << "! " << p.second << " " << v<< endl;
		s.erase(pair<int, int>((int)g[v].size(), v));
		g[p.second].pop_back();
	}
	cout << result << endl;
}

