namespace adaptor = boost::adaptors;
using index_t = std::size_t;

std::set<std::int64_t> powers;
int run(std::size_t N, std::vector<std::int64_t>values)
{
	std::vector<std::set<index_t>> edges(N);
	for (auto i : boost::irange<index_t>(0, N))
	{
		for (auto t : powers)
		{
			if (t - values[i] <= values[i])
			{
				continue;
			}
			auto beg = boost::lower_bound(values, t - values[i] + 0) - values.begin();
			auto end = boost::lower_bound(values, t - values[i] + 1) - values.begin();
			for (auto j : boost::irange(beg, end))
			{
				edges[i].emplace(j);
				edges[j].emplace(i);
			}
		}
	}
	std::vector<int> match(N, -1), used(N, 0);
	int timestamp = 0;
	std::function<bool(int)> dfs = [&](int idx)
	{
		used[idx] = timestamp;
		for (auto&& to : edges[idx])
		{
			auto to_match = match[to];
			if (to_match == -1 || (used[to_match] != timestamp && dfs(to_match)))
			{
				match[idx] = to;
				match[to] = idx;
				return true;
			}
		}
		return false;
	};
	int ret = 0;
	for (auto i : boost::irange<index_t>(0, N))
	{
		if (match[i] == -1)
		{
			++timestamp;
			ret += dfs(i);
		}
	}
	return ret;
}

void Main()
{
	for (std::int64_t v = 2; v <= 2'000'000'000; v <<= 1)
	{
		powers.emplace(v);
	}
	std::size_t N;
	std::cin >> N;
	std::vector<std::int64_t> values(N);
	for (auto& v : values)
	{
		std::cin >> v;
	}
	boost::sort(values);
	std::cout << run(N, std::move(values)) << std::endl;
}

