                for (auto it = p.first; it != p.second; it++) {
                    if (distance(a, it) != i) {
                        graph[i].emplace_back(distance(a, it));
                    }
                }
            }
        }
    }
    int result = 0;
    vector<bool> visited(n);
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            int current = 0;
            visited[i] = true;
            stack<int> stack;
            stack.emplace(i);
            do {
                auto top = stack.top();
                current++;
                stack.pop();
                for (int j : graph[top]) {
                    if (!visited[j]) {
                        visited[j] = true;
                        stack.emplace(j);
                    }
                }
            } while (!stack.empty());
            result += current / 2;
        }
    }
