    A.erase(unique(A.begin(), A.end()), A.end());
    ll beki[32];
    beki[0] = 1;
    for(ll i = 1; i <= 30; i++) {
        beki[i] = beki[i - 1] * 2;
    }
    ll ans = 0;
    ll index = N - 1;
    for(ll i = 30; i >= 0; i--) {
