int getLeast(int n)
{
  int pow2 = 1 << 30;
  while (pow2) {
    if (n & pow2) {
      if (n == pow2) {
        return pow2;
      }
      return pow2 << 1;
    }
    pow2 >>= 1;
  }
  return 0;
}

int find(int v)
{
