pair<int, int> dfs(int v) {
  used[v] = true;
  int score = 0, child = 0;
  for (int u : G[v]) {
    if (used[u]) continue;
    auto p = dfs(u);
    score += p.fst;
    child += p.snd;
  }
  int c = cnt[v];
  int n = num[v];
  int got = min(child, c);
  score += got;
  c -= got;
  if (__builtin_popcount(n) == 1) {
    int got = c / 2;
    score += got;
    c -= 2 * got;
  }
  return make_pair(score, c);
}

