ll ans = 0;
vector<int> G[maxn];
map<ll, int> pos, c;

void dfs(int v, int fa) {
    vis[v] = true;
    int *sim, *dl;
    bool isLeaf = true;
    if(c[a[v]] & 1) {
        sim = &dp[v][1];
        dl = &dp[v][0];
        dp[v][0] = dp[v][1] = c[a[v]] / 2;
    } else {
        sim = &dp[v][0];
        dl = &dp[v][1];
        dp[v][0] = c[a[v]] / 2;
        dp[v][1] = dp[v][0] - 1;
    }
    int mn = 0x3f3f3f3f;
    for(auto u : G[v]) {
        if(u == fa) continue;
        isLeaf = false;
        dfs(u, v);
        int mmx = max(dp[u][0], dp[u][1]);
        int mmn = min(dp[u][0], dp[u][1]);
        (*sim) += mmx;
        (*dl) += mmx;
        mn = min(mn, mmx - mmn);
    }
    if(isLeaf) {
        dp[v][0] = dp[v][1] = c[a[v]] / 2;
        if((c[a[v]] & 1) == 0) dp[v][1]--;
        return;
    }
    (*dl) -= mn;
    (*dl)++;
}
