template<class T>
class Dinic {
private:

    struct edge {
        T to, cap, rev;
        edge(T to, T cap, T rev) :to(to), cap(cap), rev(rev) {}
    };

    T V;
    vector<vector<edge>> g;
    vector<T> level;      // sourceからの距離
    vector<T> itr;        // どこまで調べ終わったか

public:
    Dinic(T V) :V(V), g(V, vector<edge>()) {}

    void add_edge(T from, T to, T cap) {
        g[from].emplace_back(to, cap, g[to].size());
        g[to].emplace_back(from, 0, g[from].size()-1);
    }

    // sourceからの最短路を幅優先で探索
    void bfs(T s) {
        level = vector<T>(V, -1);
        queue<T> que;
        que.push(s);
        level[s] = 0;
        while (que.size()) {
            int v = que.front(); que.pop();
            for (edge &e : g[v]) {
                if (e.cap > 0 and level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }

    // v->tの増加路を探す
    T dfs(T v, T t, T f) {
        if (v == t) return f;
        for (T& i = itr[v]; i < g[v].size(); ++i) {
            edge& e = g[v][i];
            if (e.cap > 0 and level[v] < level[e.to]) {
                int d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    T max_flow(T s, T t) {
        T flow = 0, f;
        while (true) {
            bfs(s);
            if (level[t] < 0) return flow;
            itr = vector<T>(V, 0);
            while ((f = dfs(s, t, numeric_limits<T>::max())) > 0) {
                flow += f;
            }
            if (flow%2 and flow>0) flow--;
        }
    }
};

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    unordered_map<ll, int> mp;
    rep(i, n) {
        cin >> a[i];
        ok[a[i]] = true;
        if (mp.count(a[i]) == 0) mp[a[i]] = i;
    }

    // pow(2, 32)あれば足りる
    rep(i, 32) {
        two[i] = powl(2, i);
        // cout << two[i] << endl;
    }

    int s = 0, t = 1;
    Dinic<ll> flow(n*2 + 2);

    // １つだけ辺を張る
    for (int i=0; i<n; ++i) {
        flow.add_edge(s, i+2, 1);
        flow.add_edge(i+2, n+2+i, 1);
        flow.add_edge(n+2+i, t, 2);
    }

    sort(a.begin(), a.end());
    rep(i, n) {
        rep(j, 32) {
            ll tmp = two[j];
            if (tmp < a[i]) continue;
            else if (tmp <= 2e9 and ok[tmp-a[i]]) {
                //
                int k = mp[tmp-a[i]];
                if (tmp == a[i]*2) k;
                for (; k<n; ++k) {
                    if (a[k] != tmp-a[i]) break;
                    flow.add_edge(i+2, n+2+k, 1);
                }
            }
        }
    }

    cout << flow.max_flow(0, 1)/2 << endl;
}

