i64 CLZ(i64 x) {
    return x == 0 ? 64 : __builtin_clzll(x);
}

bool is_pow2(i64 x) {
    ASSERT(x > 0);
    return (x&(x-1)) == 0;
}

i64 pow2_ceil(i64 x) {
    ASSERT(x > 0);
    return 1LL << (64-CLZ(x-1));
}

void solve() {
    i64 N = RD();

    set<i64,greater<>> s;
    REP(_, N) {
        s.emplace(RD());
    }
