    i64 ans = 0;
    while(SIZE(s) >= 2) {
        i64 a = *begin(s);
        i64 b = is_pow2(a) ? 2*a-a : pow2_ceil(a)-a;
        auto it = s.find(b);
        if(it != end(s)) {
            ++ans;
            s.erase(it);
        }
        s.erase(begin(s));
        DBG(s);
    }

    PRINTLN(ans);
}

