    for(int i = 0; i < n; i++) if(!deg[i]){
        if(cnt.count(val - v[i])){
            int j = cnt[ val - v[i] ].back();
            cnt[ val - v[i] ].pop_back();
            if(cnt[ val - v[i] ].empty())
                cnt.erase(val - v[i]);
            deg[i]++, deg[j]++;
            // edge.emplace_back(j, i);
            ans++;
            // addEdge(i, j, 1, 1);
        }
        else cnt[ v[i] ].push_back(i);
    }
    return ans;
}


int clean(){
    int ans = 0;

    queue<int> q;

    for(int i = 0; i < n; i++) if(deg[i] == 1){
        q.push(i);
    }

    int u;
    while(!q.empty()){
        u = q.front(); q.pop();
        if(er[u]) continue;
        int e = g[u][0];
        g[u].clear();
        ans++;
        er[u] = er[ edge[e].to ] = 1;
        for(int e2 : g[ edge[e].to ]){
            if(er[ edge[e2].to ]) continue;
            deg[ edge[e2].to ]--;
            edge[e2^1].cap = 0;
            if(deg[ edge[e2].to ] == 1){
                q.push(edge[e2].to);
            }
        }
        g[ edge[e].to ].clear();
    }

    return ans;
}

