    for (auto iter = begin; iter != end; iter++) {
        // first: key, second: value
        ll val = iter -> first;
        if(m[val] == 0){
            continue;
        }
        ll target = getMinBi(val) *2 - val;
        if(val == target){
            int del = m[val] / 2;
            count += del;
            m[val] -= del * 2;
        }else{
            int del = min(m[val],m[target]);
            m[val] -= del;
            m[target] -= del;
            count += del;
        }
        //cout << "key = " << iter->first << "\n";
