int Gc[200005];
map<int,ll> nmp;

ll answer;

vector<ll> getPair(ll x, map<ll,ll>& cnt){
  vector<ll> ret;
  ll p = 1;
  while(p < 1e12){
    if(cnt.count(abs(p-x)) > 0) ret.push_back(abs(p-x));
    p*=2;
  }
  return ret;
}

void calc(int id){
  vector<int> order;
  order.push_back(id);
  int pos = 0;
  while(pos < order.size()){
    rep(i,G[order[pos]].size()){
      pair<int,int> tmp = G[order[pos]][i];
      if(tmp.second == -1) continue;
      order.push_back(tmp.first);
    }
    pos++;
  }
  reverse(ALLOF(order));

  //cout << nmp[id] << endl;
  //rep(i,G[id].size()){
  rep(i,order.size()){
    int iid = order[i];
    rep(j,G[iid].size()){
      pair<int,int> tmp = G[iid][j];
      if(tmp.second == -1) continue;
      //cout << " " << tmp.first << " " << tmp.second << endl;
      if(Gc[iid] > 0 && Gc[tmp.first] > 0){
        int mn = min(Gc[iid], Gc[tmp.first]);
        answer += mn;
        Gc[iid] -= mn;
        Gc[tmp.first] -= mn;
      }
    }
  }
}

ll solve(const vector<ll>& v){
  map<ll,ll> cnt;
  rep(i,v.size()){
    cnt[v[i]]++;
  }

  vector<ll> out(cnt.size(), 0);
  map<ll,int> mp;
  int no = 0;
  FOR(it,cnt){
    int id1 = no;
    mp[it->first] = id1;
    nmp[id1] = it->first;
    Gc[id1] = it->second;

    //cout << "check: " << it->first << endl;
    vector<ll> tmp = getPair(it->first, cnt);
    rep(i,tmp.size()){
      if(mp.count(tmp[i]) == 0) continue;
      int id2 = mp[tmp[i]];
      //cout << " pair: " << nmp[id1] << " " << nmp[id2] << endl;
      G[id1].push_back(make_pair(id2,-1));
      G[id2].push_back(make_pair(id1,1));
      out[id1]++;
    }
    no++;
  }

  answer = 0;
  rep(i,out.size()){
    if(out[i] != 0) continue;
    calc(i);
  }
  return answer;
}


