array<int, 2> dfs(const vector<vector<int>> &v, vector<int> &c, int i) {
  array<int, 2> r = {0, 0};
  for (auto j : v[i]) {
    if (c[j] == -1) {
      c[j] = !c[i];
      r[c[j]]++;
      auto p = dfs(v, c, j);
      r[0] += p[0];
      r[1] += p[1];
    }
  }
  return r;
}

