std::set<int> pow2;

signed main() {
	INIT;

	REP(i, 31) pow2.insert(1 << i);

	VAR(int, n);
	VEC(int, a, n);

	std::map<int, int> map;
	REP(i, n) ++map[a[i]];

	std::map<int, ll> deg;
	for (auto& p : map) {
		int t = p.first;
		for (const auto& p2 : pow2) {
			if (t >= p2) continue;
			int dif = p2 - t;
			if (t == dif) continue;
			else if (map.count(dif)) {
				deg[t] += (ll)map[t] * map[dif];
			}
		}
	}

	using P = std::pair<ll, int>;
	std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
	for (auto& p : deg) {
		pq.push(P(p.second, p.first));
	}

	int ans = 0;
	while (!pq.empty()) {
		P p = pq.top(); pq.pop();
		int t = p.second;
		if (!map.count(t)) continue;
		if (deg[t] != p.first) continue;

		for (const auto& p2 : pow2) {
			if (t >= p2) continue;
			int dif = p2 - t;

			if (t == dif) continue;
			if (!map.count(dif)) continue;
			++ans;

			for (const auto& q2 : pow2) {
				if (t >= q2) continue;
				int dif2 = q2 - t;
				if (deg.count(dif2)) {
					if ((deg[dif2] -= map[dif2]) == 0) deg.erase(dif2);
					else pq.push(P(deg[dif2], dif2));
				}
			}
			for (const auto& q2 : pow2) {
				if (dif >= q2) continue;
				int dif2 = q2 - dif;
				if (deg.count(dif2)) {
					if ((deg[dif2] -= map[dif2]) == 0) deg.erase(dif2);
					else pq.push(P(deg[dif2], dif2));
				}
			}

			if (--map[t] == 0) map.erase(t);
			if (--map[dif] == 0) map.erase(dif);
		}
	}
	for (auto& p : map) {
		if (!pow2.count(p.first)) continue;
		ans += p.second / 2;
	}

	OUT(ans)BR;
	return 0;
}

