    }

    vector<ll> targets;
    ll tmp = 2;
    while(1) {
        targets.pb(tmp);
        tmp *= 2;
        if (tmp > (1e9) * 2) break;
    }

    BipartiteMatching bm(N, N);
    REP(n, N) {
        auto a = As[n];
        for (auto t: targets) {
            auto b = t - a;
