// 2分探索でペア探し
int search_pair(ll aa, int x, int y, ll a[], int flag[]){
    //再帰の終了条件
    if(x == y){
        if(flag[x] == 1){
            return (-1);
        }else{
            if(aa == a[x]){
                return x;
            }else{
                return (-1);
            }
        }
    }else{
        if(aa == a[(x+y)/2]){
            if(flag[(x+y)/2] == 0){
                return ((x+y)/2);
            }else{
                int new_pair = (search_pair(aa, (x+y)/2+1, y, a, flag));
                if(new_pair == -1){
                    new_pair = search_pair(aa, x, (x+y)/2, a, flag);
                }
                return new_pair;
            }
        }else{
            if(aa > a[(x+y)/2]){
                return (search_pair(aa, (x+y)/2+1, y, a, flag));
            }else{
                return (search_pair(aa, x, (x+y)/2, a, flag));
            }
        }
    }
}

int main() {
    int n;
    scanf("%d",&n);

    ll a[n] = {};
    int flag[n] = {};

    rep(i,n){
        scanf("%lld",&a[i]);
    }

    sort(a, a+n);

    int count = 0;

    for(int i = n-1; i>=1; --i){
        // スキップ条件
        if(flag[i] == 1){
            continue;
        }

        // (補数) = ((2のk乗) - a[i])作成
        ll hosuu = 1;
        while(hosuu <= a[i]){
            hosuu = hosuu * 2;
        }
        hosuu = hosuu - a[i];

        //ペア探し
        int pair = search_pair(hosuu, 0, i-1, a, flag);

        //事後処理
        if(pair == -1){
            ;
        }else{
            flag[pair] = 1;
            count++;
        }
    }

    int ans = 0;
    ans = count;
    cout << ans << endl;

    return 0;
}

