#include <bits/stdc++.h>

uint64_t pow2(uint64_t x) {
  return static_cast<uint64_t>(1) << x;
}

uint64_t calc(uint64_t x) {
  uint64_t p = std::ceil(std::log2(x + 1));
  return pow2(p);
}

int main() {
  uint64_t n;
  std::cin >> n;
  std::multiset<uint64_t, std::greater<uint64_t>> a;
  for (uint64_t i = 0; i < n; i++) {
    uint64_t t;
    std::cin >> t;
    a.insert(t);
  }

  uint64_t count = 0;

  while (!a.empty()) {
    const auto b = a.begin();
    const auto val = *b;
    const auto pair = calc(val) - val;
    if (val < pair) {
      a.erase(val);
    } else if (val == pair) {
      const auto co = a.count(val);
      if (2 <= co) {
        count += co / 2;
        a.erase(val);
      } else {
        a.erase(val);
      }
    } else {
      const auto cov = a.count(val);
      const auto cop = a.count(pair);
      if (cop != 0) {
        count += std::min(cov, cop);
        a.erase(val);
        a.erase(a.find(pair), std::next(a.find(pair), std::min(cov, cop)));
      } else {
        a.erase(val);
      }
    }
  }

  std::cout << count << std::endl;
  return 0;
}

