        if (p > a[i] || m.find(p) == m.end() || m[p] >= i || v[m[p]])
            continue;
        v[m[p]] = 1;
        r++;
        if (m[p] + 1 >= n || a[m[p]+1] != a[m[p]])
            m.erase(p);
        else
            m[p]++;
    }

    printf("%d\n", r);

    return 0;
}

