  rep(i, 0, N) {
    rep(j, 1, 31) {
      int x = (1ll << j) - A[i];
      if (mp.count(x)) {
        for (int k : mp[x]) {
          if (i < k) {
            Edge e = {i + 1, k + 1};
            edges.eb(e);
          }
        }
      }
    }
  }

  auto mm = MaximumMatching(N, edges);
  cout << mm.maximum_matching() << endl;

  return 0;
}

