inline int Up(int x) {
  int r = 1;
  while (r < x) r <<= 1;
  return r;
}
int Gao2() {
  static map<int, int> mp;
  int res = 0;
  for (int i = 1; i <= n; ++i) {
    ++mp[a[i]];
  }
  map<int, int>::iterator p = mp.end();
  --p;
  while (1) {
    int x = p->first;
    int t = 0;
    if (2 * x > (1 << 30)) {
      t = Up(x + 1);
    } else {
      t = Up(2 * x);
      if (t == 2 * x) {
        res += p->second / 2;
        p->second &= 1;
      }
      t /= 2;
    }
    for (; t > x; t /= 2) {
      int y = t - x;
      if (mp.find(y) == mp.end())
        continue;
      int us = min(mp[x], mp[y]);
      res += us;
      mp[x] -= us, mp[y] -= us;
    }
    if (p == mp.begin())
      break;
    --p;
  }
  return res;
}

