ll solve(int N, vi& a) {
    if (N == 1) return 0;
    if (N == 2) return (__builtin_popcount(a[0] + a[1]) == 1);

    sort(ALL(a));
    ll msum = a[N-1] + a[N-2];

    map<int,int> st;
    rep(i,N) st[a[i]]++;
    int curr = N-1;
    int pairs = 0;
    for (ll sum=1LL<<31LL; sum >= 2LL; sum >>= 1LL) {
        if (sum > msum) continue;

        while (curr >= 0) {
            int x = a[curr];
            if (x < sum/2) break;
            --curr;
            if (st[x] == 0) continue;

            int rem = sum - x;
            if (rem == sum/2) {
                pairs += st[rem]/2;
                st[rem] %= 2;
            } else {
                int tmp = min(st[x], st[rem]);
                pairs += tmp;
                st[x] -= tmp;
                st[rem] -= tmp;
            }
        }
    }
    return pairs;
}

int main() {
    vi a;
    int N = loadvec(a);
    cout << solve(N,a) << endl;
    return 0;
}

