LL N;
vector<LL> A;

LL ans = 0;

void solve(){
	sort(A.begin(),A.end());
	map<LL,int> remain;
	for(int i=0;i<N;i++){
		remain[A[i]]++;
	}
	for(int i=N-1;i>=0;i--){
		if(remain[A[i]]==0) continue;
		remain[A[i]]--;
		LL pow2 = 1;
		while(pow2<=A[i]) pow2 <<= 1;
		LL target_num = pow2 - A[i];
		if(remain.find(target_num)!=remain.end()){
			if(remain[target_num]==0) continue;
			ans++;
			remain[target_num]--;
		}
	}
}

