	for (int i = 0; i < N; i++) {
		if (m[v[i]] == 0) continue;
		m[v[i]]--;

		int target = MSb(v[i]) - v[i];
		if (m.count(target) && m[target] != 0) {
			m[target]--;
			ans++;
		}
	}

	printf("%d\n", ans);

	return 0;
}

int MSb(int n){
	// nが0以下の時は0とする。
    if (n <= 0) return 0;

    // (n & (n - 1)) == 0 の時は、nが2の冪乗であるため、そのままnを返す。
    if ((n & (n - 1)) == 0) return n;

    // bitシフトを用いて、2の冪乗を求める。
    int ret = 1;
    while (n > 0) { ret <<= 1; n >>= 1; }
    return ret;
}

