  for (size_t i = 0; i < N; i++) {scanf("%lld", &A[i]);}
  qsort(A, N, sizeof(long long int), compare_int);
  long long int B[N];
  long long int k;

  for (size_t i = 0; i < N; i++) {
    k=2;
    while(k<=A[i]){k=k*2;}
    B[i]=k-A[i];
    //printf("%lld ", B[i]);
  }
  int ans=0;
  int check[N];
  for (size_t i = 0; i < N; i++) {check[i]=0;}
  for (size_t i = N-1; i >=1 ; i--) {
    //printf("%d ",  sarch(0,i-1,A,B[i]));
    if (sarch(0,i-1,A,B[i])>=0) {
      if(check[sarch(0,i-1,A,B[i])]==0){
        check[sarch(0,i-1,A,B[i])]=1;
        ans++;
      }
    }
  }
  printf("%d", ans);
  return 0;
}

