int main(void) {
    unsigned long int i, j, n, pair = 0;
    unsigned long int sum, t;
    int *a;
    int check[N];

    scanf("%lu", &n);

    a = (int*)malloc(n * sizeof(int));
    for (i=0; i<n; i++) {
        scanf("%d", (a+i));
    }

    for (i=0; i<n; i++) {
        if (check[i] == 1) {continue;}
        for (j=0; j<N; j++) {
            check[j] = 0;
        }
        for (j=i+1; j<n; j++) {
            if (j >= n) {break;}
            sum = a[i] + a[j];
            for (t=2; t < sum; t = t*2) {;}
            if (sum%t == 0) {
                pair++;
                if (check[j] == 1) {pair--;}
                else {check[j]=1;}
                break;
            }
        }
    }
    printf("%lu\n", pair);
