#include <stdio.h>
#include <stdlib.h>

void MergeSort(long *A,long r) {
    long *t,i=0,j=r,k=0,a;

    t=(long *)malloc((r+1)*sizeof(long));

    while(k<r+1) {
        if(A[i]<A[j]) a=i++;
        else a=j++;

        t[k]=A[a];
        k++;

        if(i==r) a=j;
        else if(j==r+1) a=i;
        else continue;

        while(k<r+1){
            t[k]=A[a];
            k++;
            a++;
        }
    }

    for(i=0;i<=r;i++) A[i]=t[i];
    free(t);
    return;
}

