void swap(int *a, int *b)
{
    int temp;

    temp = *a;
    *a = *b;
    *b = temp;
}

void qsort2_rev(int x[], int left, int right)
{
    int i, j;
    int pivot;

    i = left;
    j = right;

    pivot = x[(left + right) / 2];

    while (1) {
        while (x[i] > pivot) {i++;}
        while (pivot > x[j]) {j--;}
        if (i >= j) {break;}

        swap(&x[i], &x[j]);
        i++;
        j--;
    }

    if (left < i - 1) {qsort2_rev(x, left, i - 1);}
    if (j + 1 <  right) {qsort2_rev(x, j + 1, right);}
}

