	} else {
		return -1;
	}
}

ull f (ull x) {
	if (x & 1) return 0;
	return f(x >> 1) + 1;
}
ull g (ull x) {
	ull b = 1;
	while (b <= x) b <<= 1;

	return (b - 1) - x;
}

