int compare_int(const void *a, const void *b)
{
    return *(long long int *)a - *(long long int*)b;
}

int sarch(int n,int m,long long int*A,long long int B){
  if(m-n<=5){
    for (size_t i = n; i <= m; i++) {
      if(A[i]==B){return i;}
    }
    return -1;
  }
  int k=(int)((n+m)/2);
  if(A[k]>B){sarch(n,k,A,B);}
  if(A[k]<B){sarch(k,m,A,B);}
  if(A[k]==B){return k;}
  return 0;
}

int main(int argc, char const *argv[]) {
  int N;
  scanf("%d", &N);
  long long int A[N];
  for (size_t i = 0; i < N; i++) {scanf("%lld", &A[i]);}
  qsort(A, N, sizeof(long long int), compare_int);
  long long int B[N];
  long long int k;

  for (size_t i = 0; i < N; i++) {
    k=2;
    while(k<=A[i]){k=k*2;}
    B[i]=k-A[i];
  }
  int ans=0;
  int check[N];
  int temp;
  for (size_t i = 0; i < N; i++) {check[i]=0;}
  for (size_t i = N-1; i >=1 ; i--) {
    temp=sarch(0,i-1,A,B[i]);
    if(temp>=0 && check[temp]==0){check[temp]=1;ans++;}
  }
  printf("%d", ans);
  return 0;
}

