typedef unsigned long ul;

ul N;

int main(int argc, char const *argv[]) {
  cin >> N;
  multiset<ul> as;
  ul maxA = 0;
  for (int i = 0; i < N; ++i) {
    ul a;
    cin >> a;
    maxA = max(a, maxA);
    as.insert(a);
  }
  ul maxPT = 1;
  while (maxPT < maxA)
    maxPT <<= 1;

  ul count;
  multiset<ul> used;
  for (ul pt = maxPT; pt > 1; pt >>= 1) {
    for (auto it = as.rbegin(); it != as.rend(); it++) {
      if (*it < (pt >> 1))
        break;
      if (used.count(*it) == as.count(*it))
        continue;
      ul a0 = *it, a1 = pt - *it;
      if (a0 != a1) {
        if (as.count(a1) > used.count(a1)) {
          ++count;
          used.insert(a0);
          used.insert(a1);
        }
      } else {
        if (as.count(a1) > used.count(a1) + 1) {
          ++count;
          used.insert(a0);
          used.insert(a1);
        }
      }
    }
  }

  cout << count << endl;
  return 0;
}

