int ch_A(int n,int m,long long int*A,long long int B){
  if(m==n){
    if(A[m]==B){
      return m;
    }else{
      return -1;
    }
  }
  if (B<A[n]||A[m]<B) {
    return -1;
  }
  int k=(int)((n+m)/2);
  if(A[k]>B){
    return ch_A(n,k-1,A,B);
  }
  if(A[k]<B){
    return ch_A(k+1,m,A,B);
  }
  if(A[k]==B){
    return k;
  }
  return 0;
}

