    rep(i,0,ed_cnt[x]){
        ll to=gr[x][i*2];
        if(to==from) continue;
        if(d[to]) continue;
        if(same[to]) continue;
        dfs(x,to);
    }
    rep(i,0,ed_cnt[x]){
        ll to=gr[x][i*2];
        if(to==from) continue;
        if(d[to]) continue;
        if(same[to]) dfs(x,to);
    }
    if(from==-1){
        if(same[x]){
            ans+=cnt[x]/2;
        }
        return;
    }
    if(same[x]){
        ll p=min2(cnt[x],cnt[from]);
        cnt[from]-=p;
        cnt[x]-=p;
        ans+=p;
        ans+=cnt[x]/2;
    }else{
        ll p=min2(cnt[x],cnt[from]);
        ans+=p;
        cnt[from]-=p;
    }
}






