int sarch(int n,int m,long long int*A,long long int B){
  if(m-n<=5){
    for (size_t i = n; i <= m; i++) {
      if(A[i]==B){return i;}
    }
    return -1;
  }
  int k=(int)((n+m)/2);
  if(A[k]>B){sarch(n,k,A,B);}
  if(A[k]<B){sarch(k,m,A,B);}
  if(A[k]==B){return k;}
  return 0;
}

