void MergeSort(long *A,long p,long q,long r) {
    long *t,i=p,j=q+1,k=0,a;

    t=(long *)malloc((r-p+1)*sizeof(long));

    while(k<r-p+1) {
        if(A[i]<A[j]) a=i++;
        else a=j++;

        t[k]=A[a];
        k++;

        if(i==q+1) a=j;
        else if(j==r+1) a=i;
        else continue;

        while(k<r-p+1) {
