#include <stdio.h>

void merge_sort(int x[], int n)
{
	static int y[200001] = {};
	if (n <= 1) return;
	merge_sort(&(x[0]), n/2);
	merge_sort(&(x[n/2]), (n+1)/2);

	int i, p, q;
	for (i = 0, p = 0, q = n/2; i < n; i++) {
		if (p >= n/2) y[i] = x[q++];
		else if (q >= n) y[i] = x[p++];
		else y[i] = (x[p] < x[q])? x[p++]: x[q++];
	}
	for (i = 0; i < n; i++) x[i] = y[i];
}

int main()
{	
	int i, N, A[200001];
	scanf("%d", &N);
	for (i = 0; i < N; i++) scanf("%d", &(A[i]));
	merge_sort(A, N);

	int j, k, count[200001] = {0};
	for (i = 0, k = 0; i < N; i++) {
		for (j = i + 1; j < N && A[j] == A[i]; j++);
		count[k] = j - i;
		A[k++] = A[i];
		i = j - 1;
	}
	N = k;

	int l, r, ans = 0, bit[31], tmp;
	for (i = 1, bit[0] = 1; i <= 30; i++) bit[i] = bit[i-1] * 2;
	for (i = N - 1, k = 30; i >= 0; i--) {
		for (; bit[k-1] > A[i]; k--);
		tmp = bit[k] - A[i];
		if (A[0] > tmp || A[i] < tmp) continue;
		l = 0;
		r = i;
		while (l < r) {
			if (A[(l+r)/2] < tmp) l = (l + r) / 2 + 1;
			else r = (l + r) / 2;
		}
		if (A[l] == tmp && count[l] > 0) {
			if (l < i) {
				tmp = (count[i] < count[l])? count[i]: count[l];
				count[l] -= tmp;
				ans += tmp;
			} else ans += count[i] / 2;
		}
	}

	printf("%d\n", ans);
	fflush(stdout);
	return 0;
}

