	pair *B = (pair *)malloc(sizeof(pair) * N);
	for(i = 1, j = 0, B[0].val = A[0], B[0].num = 1; i < N; i++){
		if(A[i] == A[i - 1]){
			B[j].num++;
		}
		else{
			j++;
			B[j].val = A[i];
			B[j].num = 1;
		}
	}
	N = j + 1;
	int l, h, r, k, minnum;
	for(i = N - 1; i >= 0; i--){
		if(B[i].num > 0){
			k = next_pow(B[i].val);
			l = -1;
			r = i + 1;
			while(r - l > 1){
				h = (l + r) / 2;
				if(B[h].val < k - B[i].val){
					l = h;
				}
				else{
					r = h;
				}
			}
			if(B[r].val + B[i].val == k){
				if(r == i){
					ans += B[i].num / 2;
					B[i].num %= 2;
				}
				else{
					minnum = min(B[r].num, B[i].num);
					ans += minnum;
					B[r].num -= minnum;
					B[i].num -= minnum;
				}
			}
		}
	}
	printf("%lld\n", ans);
	return 0;
}

