#define IS_SQUARE(i) (((i) & ((i) - 1)) == 0)

int bitscan_sqrt(int value) {
    int mask = 0x7FFFFFFF;

    while(mask) {
        if (value != (value & mask)) {
            return mask + 1;
        }
        mask = mask>>1;
    }

    return 0;
}

int qsort_compare_int(const void *a, const void *b)
{
    // 降順ソート
    return *(int*) b - *(int*) a;
}

int main(int argc, char *argv[])
{
    int n, i, j;
    int a[200000];
    int x, y;
    int count;
    int min_sq;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    qsort(a, n, sizeof(int), qsort_compare_int); // 降順ソート

    count = 0;
    for (i = 0; i < n - 1; i++) {
        x = a[i];
        if (x == 0) {continue;}
        min_sq = bitscan_sqrt(x)<<1;
        for (j = i + 1; j < n; j++) {
            y = a[j];
            if (y == 0) {continue;}
            if (min_sq - x > y) {break;}
            if (IS_SQUARE(x + y)) {
                count++;
                a[j] = 0;
                break;
            }
        }
    }

    printf("%d\n", count);

    return 0;
}

