inline fun <T> List<T>.fastIndexOfFirst(predicate: (T) -> Boolean): Int {
    var left = 0
    var right = size - 1
    if(predicate(this[left])){
        return left
    }
    var allFalse = true
    while (left < right) {
        val index = ((left + right) / 2)
        if (predicate(this[index])) {
            right = index
            allFalse = false
        } else {
            left = index + 1
        }
    }
    return when {
        predicate(this[left]) -> left
        allFalse -> return -1
        else -> left - 1
    }
}

