import java.io.*;
import java.util.*;

class Main{

    void solve(){
        int N = ni();
        long[] a = new long[N];
        boolean[] flag = new boolean[N];
        long[] beki = new long[31];
        for(int i = 0; i < N; i++){
            a[i] = ni();
        }
        sort(a);
        beki[0] = 2;
        for(int i = 1; i < 31; i++){
            beki[i] = beki[i - 1] * 2;
        }

        long ans = 0;
        for(int i = N - 1; i >= 0; i--){
            if(flag[i]) continue;
            for(int j = 30; j >=0; j--){
                if(beki[j] <= a[i]) continue;
                long num = beki[j] - a[i];  // お目当ての数字

                int ng = -1;
                int ok = N;
                while(Math.abs(ok - ng) > 1){
                    int mid = (ok + ng) / 2;
                    if(a[mid] >= num){
                        ok = mid;
                    } else {
                        ng = mid;
                    }
                }
                if(ok < 0 || ok >= N) continue;
                while(flag[ok] || ok == i){
                    ok++;
                    if(ok >= N) break;
                }
                if(ok < 0 || ok >= N || a[ok] != num) continue;
                ans++;
                flag[i] = true;
                flag[ok] = true;
                break;
            }
        }

        out.println(ans);

