	static void quick_sort(int[][] d, int left, int right) {
		if (left>=right) {
			return;
		}
		int p = d[(left+right)/2][0];
		int l = left, r = right, tmp,tmp1,tmp2;
		while(l<=r) {
			while(d[l][0] < p) { l++; }
			while(d[r][0] > p) { r--; }
			if (l<=r) {
				tmp = d[l][0]; d[l][0] = d[r][0]; d[r][0] = tmp;
				tmp1=d[l][1]; tmp2=d[r][1]; d[l][1]=tmp2; d[r][1]=tmp1;
				l++; r--;
			}
		}
		quick_sort(d, left, r);
		quick_sort(d, l, right);
	}
	static int bS(int n, int[][] ary){
		int low = 0;
		int high = ary.length - 1;
		while (low <= high) {
			int mid = (low + high) / 2;
			if (n == ary[mid][0])
				return mid;
			else if (n > ary[mid][0])
				low = mid + 1;
			else
				high = mid - 1;
		}
		return -1;
	}
}



