	public static void main(String[] args){
		//String tmp = getStr();
		//int tmp = getInt();
		//Long tmp = getLong();
      int N = getInt();
      int output = 0;
      PriorityQueue<Long> pq = new PriorityQueue<Long>(Comparator.reverseOrder());
      while(isNext()){
        pq.add(getLong());
      }
      while(pq.size() != 0){
        Long pqMax = pq.poll();
        double t = Math.log(pqMax) / Math.log(2);
        int tmpT = (int)t;
        if(!String.valueOf(t).toString().equals(".")){
          tmpT++;
        }
        if(t != 0){
          Long reqInt = (int)Math.pow(2,tmpT) - pqMax;
          if(pq.contains(reqInt)){
            output++;
            pq.remove(reqInt);
          }
        }
      }
      myout(output);
	}
}

