		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int n = in.nextInt();
			long[] a = in.nextLongArray(n);
			Arrays.sort(a);

			List<Long> list = new ArrayList<>();
			TreeMap<Long, Integer> map = new TreeMap<>();
			for (int i = 0; i < n; i++) {
				map.merge(a[i], 1, Integer::sum);
			}

			for (long i = 1; i <= 2 * 1e9; i *= 2) {
				list.add(i);
			}

