			map.put(A[i],map.get(A[i])-1);
			//一番左のbitを１にしたのを２倍
			long k2 = 2*Long.highestOneBit(A[i]);
			long diff = k2-A[i];
			if(map.containsKey(diff) && map.get(diff)>0) {
				map.put(diff,map.get(diff)-1);
				ret++;
			}
		}
