	static void solve()
	{
		int n = ni();
		int[] a = na(n);
		Arrays.sort(a);
		LST lst = new LST(n+3);
		lst.setRange(n);
		int ans = 0;
		for(int i = n-1;i >= 0;i--){
			if(!lst.get(i))continue;
			lst.unset(i);
			int h = Integer.highestOneBit(a[i])*2;
			int v = h-a[i];
			int lb = lst.next(lowerBound(a, v));
