                ax.remove(cur);
            }else{
                ax.put(cur,ax.get(cur)-1);
            }

            int pos = 1;
            while (pos <= cur) pos*=2;
            int need = pos-cur;
            Integer got = ax.get(need);
            if(got == null){
                continue;
            }
            result++;
            if(got == 1){
                ax.remove(need);
            }else{
                ax.put(need,got-1);
            }
       }

