		if (a[j] < 0) continue;
		if (a[i]+a[j] == p) {
		    a[j] = -1;
		    pair++;
		    break;
		}
	    }
	}
	System.out.println(pair);
    }

    private double log2(double x) {
	return Math.log(x) / Math.log(2);
    }
