                long num = beki[j] - a[i];  // お目当ての数字

                int ng = -1;
                int ok = N;
                while(Math.abs(ok - ng) > 1){
                    int mid = (ok + ng) / 2;
                    if(a[mid] >= num){
                        ok = mid;
                    } else {
                        ng = mid;
                    }
                }
                if(ok < 0 || ok >= N) continue;
                while(flag[ok] || ok == i){
                    ok++;
                    if(ok >= N) break;
                }
                if(ok < 0 || ok >= N || a[ok] != num) continue;
                ans++;
                flag[i] = true;
                flag[ok] = true;
                break;
            }
        }

        out.println(ans);

        out.flush();
    } 


