	private TreeSet<Integer> createExp2Set() {
		TreeSet<Integer> ret = new TreeSet<>();
		int max=Integer.MAX_VALUE/2;
		for (int i=1; i<max; i*=2) {
			ret.add(i);
		}
		return ret;
	}

	private int getExp2Complement(TreeSet<Integer> setExp2, int a) {
		return setExp2.higher(a);
	}

