	private TreeMap<Integer,Integer> createNumberCountMap() {
		TreeMap<Integer,Integer> ret = new TreeMap<>();
		for (int a : A) {
			if (ret.containsKey(a)) {
				ret.put(a,ret.get(a)+1);
			} else {
				ret.put(a,1);
			}
