                    col[v] = -col[u];
                    if (col[u] == 1) {
                        g.addEdge(u, v, xnum);
                    } else {
                        g.addEdge(v, u, ynum);
                    }
                }
            }
            if (col[u] == 1) {
                g.addEdge(2 * m, u, xnum);
            } else {
                g.addEdge(u, 2 * m + 1, xnum);
            }
        }
        long ans = MaximumFlow.dinic(2 * m, 2 * m + 1, g);
        for (int i = 0; i < m; i++) {
            long x = sorted[i];
            if ((x & -x) != x) {
                continue;
            }
            for (Edge e : g.getEdges(i)) {
                CapacityEdge ce = (CapacityEdge) e;
                if (ce.to == 2 * m || ce.to == 2 * m + 1) {
                    ans += (cnt[i] - ce.cap) / 2;
                }
            }
        }
        out.append(ans);
    }
}



