import java.util.Arrays;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		new Main().execute();
	}

	private void execute() {
		Scanner sc = new Scanner(System.in);
		final int N = sc.nextInt();
		int[] ball = new int[N];
		for (int i = 0; i < N; i++) {
			ball[i] = sc.nextInt();
		}
		Arrays.sort(ball);

		HashMap<Integer, LinkedList<Integer>> index = new HashMap<>();
		for (int i = 0; i < N; i++) {
			if (!index.containsKey(ball[i])) {
				index.put(ball[i], new LinkedList<Integer>());
			}
			index.get(ball[i]).add(i);
		}
		boolean[] used = new boolean[N];

		int p = 1;
		while (p <= ball[N - 1]) {
			p *= 2;
		}

		int i = N - 1;
		int pairs = 0;
		while (i >= 0 && p > 1) {
			while (i >= 0 && ball[i] >= (p / 2)) {
				int diff = p - ball[i];
				if (used[i] == false && index.containsKey(diff)) {
					LinkedList<Integer> l = index.get(diff);
					used[i] = true;
					if (l.peekLast() == i) {
						l.removeLast();
					}
					if (l.size() > 0) {
						used[l.removeLast()] = true;
						pairs++;
						if (l.isEmpty()) {
							index.remove(diff);
						}
					}
				}
				i--;
			}
			p = p / 2;
		}
		System.out.println(pairs);
		sc.close();
	}

}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

  public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);

    int N = Integer.parseInt(sc.next());
    int A[] = new int[N];
    for (int i = 0; i < N; i++) {
      A[i] = Integer.parseInt(sc.next());
    }
    Arrays.sort(A);

    int tMax = 31;
    int pow2[] = new int[tMax];
    pow2[0] = 1;
    for (int i = 1; i < tMax; i++) {
      pow2[i] = pow2[i - 1] * 2;
    }

    int order[] = new int[tMax];
    order[0] = 0;
    int ind = 0;
    for (int t = 0; t < tMax - 1; t++) {
      while (ind < N && pow2[t] >= A[ind]) {
        ind++;
      }
      order[t] = ind;
    }

    int ans = 0;
    int t = tMax - 1;
    for (int i = N - 1; i >= 0; i--) {
      if (A[i] < 0) {
        continue;
      }
      while (pow2[t - 1] > A[i]) {
        t--;
      }

      int sum = pow2[t];

      int sub = sum - A[i];
      int search;
      for (search = 0; search < tMax; search++) {
        if (sub < pow2[search]) {
          break;
        }
      }
      search--;
      int max = order[search];
      search = Math.max(search - 1, 0);
      int min = order[search];
      for (int j = max; j >= min; j--) {
        if (A[i] + A[j] == sum) {
          ans++;
          A[j] = -1000000000;
          break;
        } else if (A[i] + A[j] < sum) {
          break;
        }
      }
    }

    System.out.println(ans);
  }
}

