public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long mod = 1000000007;
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final int[] da = {-1, 0, 1, 0, -1, 1, 1, -1, -1};

    void solve() {
        int n = in.nextInt();
        TreeMap<Integer, Integer> map = new TreeMap<>(Comparator.reverseOrder());
        for (int i = 0; i < n; i++) {
            int a = in.nextInt();
            map.merge(a, 1, Integer::sum);
        }
        int ans = 0;
        while (!map.isEmpty()) {
            Map.Entry<Integer, Integer> entry = map.firstEntry();
            int a = entry.getKey();
            int b = Integer.highestOneBit(a) * 2 - a;
            if (a == b) {
                ans += map.get(a) / 2;
                if (map.get(a) % 2 == 1) {
                    map.put(a, 1);
                } else {
                    map.remove(a);
                    continue;
                }
            }
            if (map.containsKey(b)) {
                if (map.get(a) >= map.get(b)) {
                    ans += map.get(b);
                    map.remove(b);
                } else {
                    map.put(b, map.get(b) - map.get(a));
                }
            }
            map.remove(a);
        }
        out.println(ans);
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

