    public static boolean isPower2(int number) {
        int tmpNumber = number;
        while (true) {
            if (tmpNumber == 1 || tmpNumber == 2) {
                return true;
            }

            if (tmpNumber % 2 != 0) {
                return false;
            }

            tmpNumber = tmpNumber / 2;
        }
    }
