class Main{
	public static void main(String[] args) {
		SC sc=new SC(System.in);
		int N=sc.nextInt();
		long[] ary=new long[N];
		long[] ary2=new long[N];
		for(int i=0; i<N; i++) {
			ary[i]=sc.nextLong()*2;
		}
		Arrays.sort(ary);
		for(int i=0; i<N; i++) {
			ary2[i]=ary[i];
		}
		int kosu=0;
		for(int i=N-1; i>=0; i--) {
			//String ab="";
			if(ary[i]%2!=1) {
				long sp=solve_pair(ary[i]);
				int a=lowerBound(ary2,sp);
				//System.out.println(a+" "+solve_pair(ary[i]));
				if(a==-1) {
					//存在しないなら何もしない
					ary[i]--;
				}
				else if(a>=0 && ary2[a]==sp && i>a) {
					kosu++;
					ary2[a]--;
					ary[i]--;
				}
				else {
					//足して2ベキにならないなら何もしない
					ary[i]--;
				}
			}
			else {
				//そもそも使われていたら使わない
			}
			/*for(int j=0; j<N; j++) {
				ab=ab+" "+ary[j];
			}
			System.out.println(ab);*/
		}
		System.out.println(kosu);
	}
	static class SC {
		private BufferedReader reader = null;
		private StringTokenizer tokenizer = null;
		public SC(InputStream in) {
			reader = new BufferedReader(new InputStreamReader(in));
		}
		public String next() {
			if (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new UncheckedIOException(e);
				}
			}
			return tokenizer.nextToken();
		}
		public int nextInt() {
			return Integer.parseInt(next());
		}
		public long nextLong() {
			return Long.parseLong(next());
		}
	}
	public static final int lowerBound(final long[] arr, final long value) {
		int low = 0;
		int high = arr.length;
		int mid;
		while (low < high) {
			mid = ((high - low) >>> 1) + low;    //(low + high) / 2 (オーバーフロー対策)
			if (arr[mid] < value) {
				low = mid + 1;
			} else {
				high = mid;
			}
		}
		if(low<arr.length) {
			return low;
		}
		else {
			return -1;
		}
	}
	static long solve_pair(long a) {
		int k=0;
		long b=a;
		while(b>0) {
			k++;
			b/=2;
		}
		int aaa=1;
		for(int i=0; i<k; i++) {
			aaa*=2;
		}
		//System.out.println("ret "+(aaa-a));
		return (aaa-a);
	}
}

