			m.put(i, m.get(i) - 1);
			int count=0;
			int tmp=0;
			for (int p : pow) {
				int j = p - i;
				if (m.containsKey(j) && m.get(j) != 0) {
					tmp=j;
					count++;
				}
			}
			if (count==1){
				m.put(tmp, m.get(tmp) - 1);
				res++;
			}
			else{
				m.put(i, m.get(i) + 1);
			}
		}
		System.out.println(res);

	}

	private static int[] nextArr(int k) {
		// TODO Auto-generated method stub
		int[] res = new int[k];
		for (int i = 0; i < k; i++) {

			res[i] = sc.nextInt();
		}
		return res;
	}

}

