    private void solve() {
	set();
	int pair = 0;
	double loge2 = Math.log(2);
	for (int i=0;i<n;i++) {
	    if (a[i] < 0) continue;
	    int t = (int)(Math.log(a[i])/loge2) + 1;
	    long p = (1 << t) - a[i];
	    for (int j=i+1;j<n;j++) {
		if (a[j] < 0) continue;
		if (a[j] == p) {
		    a[j] = -1;
		    pair++;
		    break;
		}
	    }
	}
	System.out.println(pair);
    }
