public class Main {

	static int n, a[];
	static boolean known[];

	public static long solve() {
		long ans = 0;

		for(int i = n - 1; i >= 0; --i) {

			if(known[i])continue;
			int key = (int)(Math.log(a[i]) / Math.log(2)) + 1;
			key = (int)Math.pow(2,  key) - a[i];

			known[i] = true;

			int tmp = Arrays.binarySearch(a, key);
			if(tmp >= 0 && tmp != i && known[tmp] != true && a[i] != a[tmp]) {
				ans++;
				known[tmp] = true;
			}
		}

		return ans;

	}

