        for (int i = n - 1; i >= 0; i--) {
            long req = 0;
            if (a[i] == 0) {
                continue;
            }
            for (int j = 0; j < 33; j++) {
                if (Math.pow(2, j) > a[i]) {
                    req = (long)Math.pow(2, j) - a[i];
