import java.util.Arrays;
import java.util.Scanner;

public class Main {

  public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);

    int N = Integer.parseInt(sc.next());
    int A[] = new int[N];
    for (int i = 0; i < N; i++) {
      A[i] = Integer.parseInt(sc.next());
    }
    Arrays.sort(A);

    int tMax = 31;
    int pow2[] = new int[tMax];
    pow2[0] = 1;
    for (int i = 1; i < tMax; i++) {
      pow2[i] = pow2[i - 1] * 2;
    }

    int order[] = new int[tMax];
    order[0] = 0;
    int ind = 0;
    for (int t = 0; t < tMax; t++) {
      while (ind < N && pow2[t] >= A[ind]) {
        ind++;
      }
      order[t] = Math.max(ind - 1, 0);
    }

//    System.out.println(Arrays.toString(A));
//    System.out.println(Arrays.toString(pow2));
//    System.out.println(Arrays.toString(order));

    int ans = 0;
    int t = tMax - 1;
    for (int i = N - 1; i >= 0; i--) {
      if (A[i] < 0) {
        continue;
      }
      while (pow2[t - 1] > A[i]) {
        t--;
      }
      int sum = pow2[t];

      int sub = sum - A[i];
      int search;
      for (search = 0; search < tMax; search++) {
        if (sub < pow2[search]) {
          break;
        }
      }
      search = Math.max(search, 0);
      int max = order[search];
      search = Math.max(search - 1, 0);
      int min = order[search];
      //System.out.println(A[i] + " , " + sub + " , " + max + " , " + min);
      for (int j = max; j >= min; j--) {
        if (A[j] < 0 || i == j) {
          continue;
        }
        if (A[i] + A[j] == sum) {
          ans++;
          //System.out.println(A[i] + ", " + A[j]);
          A[j] = -1000000000;
          break;
        } else if (A[i] + A[j] < sum) {
          break;
        }
      }
    }

    System.out.println(ans);
  }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    List<Integer> list = new ArrayList<>();
    for (int i = 0; i < N; i++) list.add(scanner.nextInt());

    Collections.sort(list);
    int cnt = 0;
    while (!list.isEmpty()) {
      int a = list.remove(list.size() - 1);
      int b = (Integer.highestOneBit(a) << 1) - a;
      int j = upperBound(list, -1, list.size(), b);
      if (j >= 0 && list.get(j) == b) {
        list.remove(j);
        cnt++;
      }
    }
    System.out.println(cnt);
  }

  public static int upperBound(List<Integer> a, int left, int right, int k) {
    while (right - left > 1) {
      int mid = (left + right) / 2;
      if (a.get(mid) <= k) {
        left = mid;
      } else {
        right = mid;
      }
    }
    return left;
  }
}

import java.io.*;
import java.util.*;

public class Main {
    FastScanner in;
    PrintWriter out;

    void solve() {
        int n = in.nextInt();
        TreeMap<Integer, Integer> count = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            int x = in.nextInt();
            count.put(x, count.getOrDefault(x, 0) + 1);
        }
        int res = 0;
        while (!count.isEmpty()) {
            Map.Entry<Integer, Integer> entry = count.pollLastEntry();
            if (entry.getValue() != 1) {
                count.put(entry.getKey(), entry.getValue() - 1);
            }
            int pw2 = 1;
            while (pw2 <= entry.getKey()) {
                pw2 *= 2;
            }
            int need = pw2 - entry.getKey();
            Integer got = count.get(need);
            if (got != null) {
                res++;
                if (got.equals(1)) {
                    count.remove(need);
                } else {
                    count.put(need, got - 1);
                }
            }
        }
        out.println(res);
    }

    void run() {
        try {
            in = new FastScanner(new File("Main.in"));
            out = new PrintWriter(new File("Main.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {

        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new Main().runIO();
    }
}

import java.util.*;
import java.util.Map.Entry;

public class Main {
	static Scanner sc = new Scanner(System.in);

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		long[] pow = new long[32];
		for (int i = 0; i < pow.length; i++) {
			pow[i] = (int) Math.pow(2, i + 1);
		}

		int k = sc.nextInt();
		int[] arr = nextArr(k);
		int res = 0;
		Map<Integer, Integer> m = new HashMap();
		for (int i : arr) {
			m.put(i, 1 + m.getOrDefault(i, 0));
		}

		for (int i : arr) {
			if (m.get(i) == 0)
				continue;
			m.put(i, m.get(i) - 1);
			int count=0;
			int tmp=0;
			for (long p : pow) {
				int j = (int) (p - i);
				if (m.containsKey(j) && m.get(j) != 0) {
					tmp=j;
					count++;
				}
			}
			if (count==1){
				m.put(tmp, m.get(tmp) - 1);
				res++;
			}
			else{
				m.put(i, m.get(i) + 1);
			}
		}
		System.out.println(res);

	}

	private static int[] nextArr(int k) {
		// TODO Auto-generated method stub
		int[] res = new int[k];
		for (int i = 0; i < k; i++) {

			res[i] = sc.nextInt();
		}
		return res;
	}

}

import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static int solve() {
        Arrays.sort(A);

        int ans = 0;
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int i = 0; i < N; i++) {
            if( cnt.containsKey(A[i]) ) {
                cnt.put(A[i], cnt.get(A[i]) + 1);
            } else {
                cnt.put(A[i], 1);
            }
        }

        int[] beki = new int[31];
        beki[0] = 1;
        for (int i = 1; i < 31; i++) {
            int n = (int)Math.pow(2, i);
            beki[i] = n;
        }

        lo: for (int i = N-1; i >= 0; i--) {
            int x = A[i];

            for (int b : beki) {
                int y = b - x;
                if( y > 0 && cnt.containsKey(y)) {
                    if( x == y ) {
                        int u = cnt.get(x);
                        if( u >= 2 ) {
                            cnt.put(x, u-2);
                            ans ++;
                            continue lo;
                        }

                    } else {
                        int u = cnt.get(x);
                        int v = cnt.get(y);
                        if( u > 0 && v > 0 ) {
                            cnt.put(x, u-1);
                            cnt.put(y, v-1);
                            ans ++;
                            continue lo;
                        }
                    }
                }
            }
        }

        return ans;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
