 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        B solver = new B();
        solver.solve(1, in, out);
        out.close();
    }

    static class B {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.ni();
            int[] a = in.na(n);
            TreeMap<Integer, LinkedList<Integer>> map = new TreeMap<>();
            for (int i = 0; i < n; i++) {
                LinkedList<Integer> update = map.computeIfAbsent(a[i], k -> new LinkedList<>());
                update.add(i);
            }
            int ans = 0;
            for (int j = 30; j > 0; j--) {
                int pow = 1 << j;
//            System.out.println("pow = " + pow);
                for (int i = 0; i < n; i++) {
                    LinkedList<Integer> cur = map.get(a[i]);
                    if (cur.size() == 0)
                        continue;
                    LinkedList<Integer> pairs = map.get(pow - a[i]);
                    if (pairs != null && pairs.size() > 0) {
                        if (pow - a[i] == a[i] && pairs.size() == 1)
                            continue;
                        pairs.poll();
                        cur.poll();
                        ans++;
                    }

                }
            }
            out.println(ans);
        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
