		B_PowersOfTwo solver = new B_PowersOfTwo();
		solver.solve(1, in, out);
		out.close();
	}

	static class B_PowersOfTwo {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int[] a = new int[n];
			for (int i = 0; i < n; i++) {
				a[i] = in.nextInt();
			}
			Arrays.sort(a);
			Map<Integer, Integer> m = new HashMap<>();
			for (int x : a) {
				addOne(m, x);
			}
			int ans = 0;
			for (int i = n - 1; i >= 0; i--) {
				int x = a[i];
				if (!m.containsKey(x)) {
					continue;
				}
				removeOne(m, x);
				for (int bit = 30; bit >= 0; bit--) {
					int y = (1 << bit) - x;
					if (m.containsKey(y)) {
						removeOne(m, y);
						++ans;
						break;
					}
				}
			}
			out.println(ans);
		}

		private void addOne(Map<Integer, Integer> m, int x) {
			int v = 0;
			if (m.containsKey(x)) {
				v = m.get(x);
			}
			m.put(x, v + 1);
		}

		private void removeOne(Map<Integer, Integer> m, int x) {
			int v = m.get(x);
			if (v == 1) {
				m.remove(x);
			} else {
				m.put(x, v - 1);
			}
		}

	}

