            }
            set.remove(value);

            while (pow >> 1 > value) {
                pow = pow >> 1;
            }

            final int index = Collections.binarySearch(list, pow - value);
            if (index < 0) {
                continue;
            }
            final int sbj = list.get(index);
            if (set.contains(sbj)) {
                count++;
                set.remove(sbj);
            }
        }
        System.out.println(count);
    }
}

