/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		B_PowersOfTwo solver = new B_PowersOfTwo();
		solver.solve(1, in, out);
		out.close();
	}

	static class B_PowersOfTwo {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int[] a = new int[n];
			for (int i = 0; i < n; i++) {
				a[i] = in.nextInt();
			}
			Arrays.sort(a);
			Map<Integer, Integer> m = new HashMap<>();
			for (int x : a) {
				addOne(m, x);
			}
			int ans = 0;
			for (int i = n - 1; i >= 0; i--) {
				int x = a[i];
				if (!m.containsKey(x)) {
					continue;
				}
				for (int bit = 31; bit >= 0; bit--) {
					int y = x - (1 << bit);
					if (y < 0) {
						continue;
					}
					if (m.containsKey(y)) {
						removeOne(m, x);
						removeOne(m, y);
						++ans;
					}
					break;
				}
			}
			out.println(ans);
		}

		private void addOne(Map<Integer, Integer> m, int x) {
			int v = 0;
			if (m.containsKey(x)) {
				v = m.get(x);
			}
			m.put(x, v + 1);
		}

		private void removeOne(Map<Integer, Integer> m, int x) {
			int v = m.get(x);
			if (v == 1) {
				m.remove(x);
			} else {
				m.put(x, v - 1);
			}
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.stream.Collectors;

public class Main {

    private int n;
    private List<Long> a;

    public static void main(String[] args) {
	Main m = new Main();
	m.solve();
    }

    private void set() {
	try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
	    n = Integer.parseInt(br.readLine());
	    a = Arrays.stream(br.readLine().split(" ")).map(Long::valueOf)
		.sorted().collect(Collectors.toList());
	    Collections.reverse(a);
	} catch(IOException e) {
	    e.printStackTrace();
	}
    }

    private void solve() {
	set();
	int pair = 0;
	double loge2 = Math.log(2);
	while (!a.isEmpty()) {
	    Iterator<Long> it = a.iterator();
	    long ai = it.next();
	    it.remove();
	    int t = (int)(Math.log(ai)/loge2) + 1;
	    long p = (1 << t) - ai;
	    while (it.hasNext()) {
		long aj = it.next();
		if (aj == p) {
		    it.remove();
		    pair++;
		    break;
		}
	    }
	}
	System.out.println(pair);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();
        ArrayList<Integer> a = new ArrayList<Integer>();
        for(int i=0; i<n; i++){
            a.add(sc.nextInt());
        }

        int npow = 31;
        long[] pow2 = new long[npow];
        for(int i=0; i<pow2.length; i++){
            pow2[i] = (long)Math.pow(2, i+1);
        }

        Collections.sort(a);

        int ans = 0;
        out: for(int i=a.size()-1; i>0; i--){
            int cur = a.get(i);
            int cur2 = a.get(i-1);
            if(cur == cur2){
                int curx2 = cur*2;
                for(int j=0; j<npow; j++){
                    if(curx2 == pow2[j]){
                        a.remove(i);
                        a.remove(i-1);
                        ans++;
                        i--;
                        continue out;
                    }
                }
            }
            for(int j=0; j<npow; j++){
                if(cur >= pow2[j]) continue;
                int pos = Collections.binarySearch(a, (int)pow2[j]-cur, (ma, mb) -> Integer.compare(ma, mb));
                if(pos >= 0 && pos < i){
                    a.remove(i);
                    a.remove(pos);
                    i--;
                    ans++;
                    break;
                }
                a.remove(i);
                break;
            }
        }

        System.out.println(ans);
    }
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
