import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.TreeMap;

public class Main {

    private int n;
    private TreeMap<Integer,Integer> a;

    public static void main(String[] args) {
	Main m = new Main();
	m.solve();
    }

    private void set() {
	try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
	    n = Integer.parseInt(br.readLine());
	    a = new TreeMap<>();
	    for (String str : br.readLine().split(" ")) {
		int ai = Integer.parseInt(str);
		int num = a.getOrDefault(ai,0) + 1;
		a.put(ai,num);
	    }
	} catch(IOException e) {
	    e.printStackTrace();
	}
    }

    private void solve() {
	set();
	int pair = 0;
	while (!a.isEmpty()) {
	    int ai = a.lastKey();
	    int complement = 2*Integer.highestOneBit(ai) - ai;
	    if (ai == complement) {
		int num = a.get(ai);
		pair += num/2;
		a.remove(ai);
		continue;
	    }
	    if (a.containsKey(complement)) {
		int numA = a.get(ai);
		int numC = a.get(complement);
		if (numA < numC) {
		    pair += numA;
		    a.remove(ai);
		    a.put(complement,numC-numA);
		} else {
		    pair += numC;
		    a.remove(ai);
		    a.remove(complement);
		}
		continue;
	    }
	    a.remove(ai);
	}
	System.out.println(pair);
    }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		new Main().execute();
	}

	private void execute() {
		Scanner sc = new Scanner(System.in);
		final int N = sc.nextInt();
		int[] ball = new int[N];
		for (int i = 0; i < N; i++) {
			ball[i] = sc.nextInt();
		}
		Arrays.sort(ball);

		HashMap<Integer, Integer> index = new HashMap<>();
		for (int i = 0; i < N; i++) {
			index.put(ball[i], i);
		}
		boolean[] used = new boolean[N];

		int p = 1;
		while (p < ball[N - 1]) {
			p *= 2;
		}

		int i = N - 1;
		int pairs = 0;
		while (i >= 0 && p > 1) {
			while (i>=0 && ball[i] > (p / 2)) {
				int diff = p - ball[i];
				if (used[i] == false && index.containsKey(diff) && index.get(diff) != i) {
					used[i] = true;
					used[index.get(diff)] = true;
					index.remove(diff);
					pairs++;
				}
				i--;
			}
			p = p / 2;
		}
		System.out.println(pairs);
		sc.close();
	}

}

