            ArrayList<Integer> a = new ArrayList<>();
            HashSet<Integer> set = new HashSet<>();

            for (int i = 0; i < n; i++) {
                int cn = in.nextInt();
                a.add(cn);
                set.add(cn);
            }

            a.sort(Comparator.reverseOrder());

            int com = Integer.MAX_VALUE;

            int ans = 0;
            for (int i = 0; i < n - 1; i++) {
                int cn = a.get(i);
