		for(int i=N-1; i>=0; i--) {
			//String ab="";
			if(ary[i]%2!=1) {
				long sp=solve_pair(ary[i]);
				int a=lowerBound(ary2,sp);
				//System.out.println(a+" "+solve_pair(ary[i]));
				if(a==-1) {
					//存在しないなら何もしない
				}
				else if(a>=0 && ary2[a]==sp && ary[a]%2==0 && ary2[a]%2==0 &&ary[i]%2==0 && ary2[i]%2==0 && a<i) {
