                    LinkedList<Integer> cur = map.get(a[i]);
                    if (cur.size() == 0)
                        continue;
                    LinkedList<Integer> pairs = map.get(pow - a[i]);
                    if (pairs != null && pairs.size() > 0) {
                        if (pow - a[i] == a[i] && pairs.size() == 1)
                            continue;
                        pairs.poll();
                        cur.poll();
                        ans++;
                    }

                }
            }
            out.println(ans);
        }

