            a[i] = ni();
        }
        Arrays.sort(a);
        int ans = 0;
        boolean[] used = new boolean[n];
        for(int i = 30; i >= 0; i--){
            long[] tmp = new long[n];
            long res = (long)Math.pow(2,i);
            for(int j = 0; j < n; j++){
                tmp[j] = (long)a[j] - res;
            }
            int p = n-1;
            for(int j = 0; j < n; j++){
                if(used[j]) continue;
                if(tmp[j]>0) break;
