			for(int j = i+1; j<li.size(); j++) {
				long v = li.get(i) + li.get(j);
				if((v & (v-1)) == 0) {
					long m = 1 + getMax(sublist(i,j,li));
					System.out.println(sublist(i,j,li));
					max = Math.max(max, m);
				}
			}
			c = Math.max(max, c);
		}
		return c;

	}

	public static List<Long> sublist(int i, int j, List<Long> l){
