		int kosu=0;
		for(int i=N-1; i>=0; i--) {
			if(ary[i]%2!=1) {
				int a=lowerBound(ary,solve_pair(ary[i]));
				//System.out.println(a+" "+solve_pair(ary[i]));
				if(a==-1) {
					//
				}
				else if(a>=0 && ary[a]==solve_pair(ary[i]) && i!=a) {
					kosu++;
					ary[a]--;
					ary[i]--;
				}
				else {
					ary[i]--;
				}
			}
			else {
				//
			}
		}
		System.out.println(kosu);
	}
	static class SC {
		private BufferedReader reader = null;
		private StringTokenizer tokenizer = null;
		public SC(InputStream in) {
			reader = new BufferedReader(new InputStreamReader(in));
		}
		public String next() {
			if (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new UncheckedIOException(e);
				}
			}
			return tokenizer.nextToken();
		}
		public int nextInt() {
			return Integer.parseInt(next());
		}
		public long nextLong() {
			return Long.parseLong(next());
		}
	}
	public static final int lowerBound(final long[] arr, final long value) {
		int low = 0;
		int high = arr.length;
		int mid;
		while (low < high) {
			mid = ((high - low) >>> 1) + low;    //(low + high) / 2 (オーバーフロー対策)
			if (arr[mid] < value) {
				low = mid + 1;
			} else {
				high = mid;
			}
		}
		if(low<arr.length) {
			return low;
		}
		else {
			return -1;
		}
	}
	static long solve_pair(long a) {
		int k=0;
		long b=a;
		while(b>0) {
			k++;
			b/=2;
		}
		int aaa=1;
		for(int i=0; i<k; i++) {
			aaa*=2;
		}
		return (aaa-a);
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Map;
import java.util.TreeMap;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		String[] sa = br.readLine().split(" ");
		TreeMap<Integer, Integer> map = new TreeMap<>();
		for (int i = 0; i < n; i++) {
			int a = Integer.parseInt(sa[i]);
			addCntMap(map, a);
		}
		br.close();

		int ans = 0;
		Integer[] arr = map.keySet().toArray(new Integer[0]);
		int t = 30;
		for (int r = arr.length - 1; r >= 0; r--) {
			if (!map.containsKey(arr[r])) {
				continue;
			}
			for ( ; t >= 0; t--) {
				if (arr[r] >= (1 << t)) {
					t++;
					break;
				}
			}
			int x = (1 << t) - arr[r];
			if (map.containsKey(x)) {
				delCntMap(map, arr[r]);
				delCntMap(map, x);
				ans++;
			}
		}
		System.out.println(ans);
	}

	static void addCntMap(Map<Integer, Integer> map, Integer key) {
		if (map.containsKey(key)) {
			map.put(key, map.get(key) + 1);
		} else {
			map.put(key, 1);
		}
	}

	static void delCntMap(Map<Integer, Integer> map, Integer key) {
		if (key != null && map.containsKey(key)) {
			int val = map.get(key);
			if (val == 1) {
				map.remove(key);
			} else {
				map.put(key, val - 1);
			}
		}
	}
}

