public class Main {
    static int left(int x) {
        int i = 1;
        while(i <= x) {
            i <<= 1;
        }
        return i - x;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n + 11];
        int[] used = new int[n + 11];
        Map<Integer, Integer> cnt = new HashMap<Integer, Integer>();
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            used[i] = 0;
            if (cnt.containsKey(a[i])) {
                cnt.put(a[i], cnt.get(a[i]) + 1);
            } else {
                cnt.put(a[i], 1);
            }
        }
        Arrays.sort(a, 0, n);
        int ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int x = a[i];
            if (cnt.get(x) == 0) {
                continue;
            }
            cnt.put(x, cnt.get(x) - 1);
            int match = left(x);
            // System.out.println(x);
            // System.out.println(match);
            if (cnt.containsKey(match) && cnt.get(match) > 0) {
                ans += 1;
                cnt.put(match, cnt.get(match) - 1);
            }
        }
        System.out.println(ans);
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int[] a = new int[N];
    for (int i = 0; i < N; i++) a[i] = scanner.nextInt();

    Arrays.sort(a);
    boolean[] used = new boolean[N];
    int cnt = 0;
    for (int i = N - 1; i >= 0; i--) {
      if (used[i]) continue;
      int b = (Integer.highestOneBit(a[i]) << 1) - a[i];
      int j = upperBound(a, -1, i, b);
      if (j >= 0 && a[j] == b) {
        cnt++;
        used[j] = true;
      }
    }
    System.out.println(cnt);
  }

  public static int upperBound(int[] a, int left, int right, int k) {
    while (right - left > 1) {
      int mid = (left + right) / 2;
      if (a[mid] <= k) {
        left = mid;
      } else {
        right = mid;
      }
    }
    return left;
  }
}

