public class Main {
  private static int solve(int n, int[] as) {
    TreeMap<Integer, Integer> aMap = new TreeMap<>();
    for (int a : as) {
      aMap.put(a, aMap.getOrDefault(a, 0) + 1);
    }

    int countPair = 0;
    List<Integer> descendingKeyList = new ArrayList<>();
    for (int key : aMap.descendingKeySet()) {
      descendingKeyList.add(key);
    }
    for (int a : descendingKeyList) {
      int aCount = aMap.get(a);
      int aCeil = 1;
      while (a >= aCeil) {
        aCeil *= 2;
      }
      int b = aCeil - a;
      if (b != a) {
        int bCount = aMap.getOrDefault(b, 0);
        if (bCount > 0) {
          int pair = Math.min(aCount, bCount);
          aMap.put(a, aCount - pair);
          aMap.put(b, bCount - pair);
          countPair += pair;
        }
      } else {
        int pair = (aCount / 2);
        if (pair > 0) {
          aMap.put(a, aCount - 2 * pair);
          countPair += pair;
        }
      }
    }
    return countPair;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[] as = reader.nextIntArray(n);
    out.println(solve(n, as));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

