        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.ni();
            int[] a = in.na(n);
            HashMap<Integer, LinkedList<Integer>> map = new HashMap<>(n);
            for (int i = 0; i < n; i++) {
                LinkedList<Integer> update = map.computeIfAbsent(a[i], k -> new LinkedList<>());
