        }
        Arrays.sort(array);
        long max = array[N - 1] + array[N - 2];
        Set<Long> set = new HashSet<>();

        int t =  - 1;
        while (Math.pow(2, t + 1) < max) {
            t++;
            set.add((long)Math.pow(2, t));
        }

        int ans = 0;
        outside: for (int i = 0; i < N - 1; i++) {
            if (array2[i]) {
                continue outside;
            }
            long a = array[i];
            inside: for (int j = i + 1; j < N; j++) {
                if (array2[j]) {
                    continue inside;
                }
                long b = array[j];
                if (set.contains(a + b)) {
                    out.println(a + "," + b);
                    ans++;
                    array2[i] = true;
                    array2[j] = true;
                    continue outside;
                }
            }
        }
        out.println(ans);
        out.close();
