import java.io.PrintWriter;
import java.util.Scanner;
import java.util.Collections;
import java.util.ArrayList;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        AGC029_B solver = new AGC029_B();
        solver.solve(1, in, out);
        out.close();
    }

    static class AGC029_B {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            ArrayList<Long> balls = new ArrayList<Long>();

            for (int i = 0; i < n; i++) {
                balls.add(in.nextLong());
            }

            Collections.sort(balls);

            long tmp;
            long sub;
            long ans = 0;
            for (int i = balls.size() - 1; i > 0; i--) {
                tmp = balls.get(i);
                long binary = (long) Math.floor(Math.log(tmp * 2) / Math.log(2));
                binary = (long) Math.pow(2, binary);
                sub = binary - tmp;
                if (balls.contains(sub)) {
                    long index = balls.indexOf(sub);
                    if (index != i) {
                        ans++;
                        balls.set((int) index, Long.MAX_VALUE);
                        balls.set((int) i, Long.MAX_VALUE);
                    }
                }
            }

            out.print(ans);


        }

    }
}

import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long ans = 0;
        PriorityQueue<Long> queue = new PriorityQueue<>(Comparator.reverseOrder());
        for (int i = 0; i < n; i++) queue.add(sc.nextLong());

        while (!queue.isEmpty()) {
            long l = queue.poll();
            Long removeV = null;
            for (long o : queue) {
                long x = l + o;
                if((x & (x-1))==0) {//べき乗なら
                    removeV = o;
                    ans++;
                    break;
                }
            }
            if(removeV!=null) queue.remove(removeV);
        }
        System.out.println(ans);
    }
}

import java.util.*;
public class Main {


	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		ArrayList<Integer> A = new ArrayList<Integer>();
		for(int i=0;i<N;i++) {
			A.add(sc.nextInt());
		}
		A.sort(Collections.reverseOrder());
		int ret = 0;
		while(!A.isEmpty()) {
			int Aj = findaj(A.get(0));
			//System.out.println(Aj);
			int indAj = Collections.binarySearch(A, Aj,Collections.reverseOrder());
			//System.out.println(indAj);
			if (indAj > 0) {//0だとAiになってしまう
				ret++;
				A.remove(indAj); //０はあとで削除　ずれる
				A.remove(0);
			}
			else A.remove(0);
		}
		System.out.println(ret);
	}

	//Ai+Aj=2^kとなるAjを返す
	public static int findaj(int a) {
		return findmink(a)-a;
	}

	// aよりも大きい最小の2^kを返す
	public static int findmink(int a) {
		int k = 0;
		int mul = 1;
		while(mul <= a) {
			k++;
			mul *= 2;
		}
		return mul;
	}
}

