/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		B_PowersOfTwo solver = new B_PowersOfTwo();
		solver.solve(1, in, out);
		out.close();
	}

	static class B_PowersOfTwo {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int[] a = new int[n];
			for (int i = 0; i < n; i++) {
				a[i] = in.nextInt();
			}
			Map<Integer, Integer> m = new HashMap<>();
			for (int x : a) {
				addOne(m, x);
			}
			int ans = 0;
			for (int allowP2 = 0; allowP2 < 2; allowP2++) {
				for (int x : a) {
					if ((x & (x - 1)) == 0 && allowP2 == 0) {
						continue;
					}
					if (!m.containsKey(x)) {
						continue;
					}
					int y = -1;
//				for (int bit = 0; bit < 31; bit++) {
					for (int bit = 30; bit >= 0; bit--) {
						int z = (1 << bit) - x;
						if ((z & (z - 1)) == 0 && allowP2 == 0) {
							continue;
						}
						if (m.containsKey(z) && (x != z || m.get(z) > 1)) {
							y = z;
							break;
						}
					}
					if (y >= 0) {
						removeOne(m, x);
						removeOne(m, y);
						++ans;
					}
				}
			}
			out.println(ans);
		}

		private void addOne(Map<Integer, Integer> m, int x) {
			int v = 0;
			if (m.containsKey(x)) {
				v = m.get(x);
			}
			m.put(x, v + 1);
		}

		private void removeOne(Map<Integer, Integer> m, int x) {
			int v = m.get(x);
			if (v == 1) {
				m.remove(x);
			} else {
				m.put(x, v - 1);
			}
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.util.*;
class Main
{
    public static void main (String[] args)
    {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] a = new long[n];
        boolean[] bl = new boolean[n];
        for(int i = 0; i < n; i++){
            a[i] = sc.nextLong();
            bl[i] = true;
        }
        Arrays.sort(a);
        int ans = 0;
        for(int i = n - 1; i >= 0; i--){
            if(bl[i] == true){
                for(int k = 31; k >= 1; k--){
                    long x = (long) Math.pow(2, k);
                    int j = Arrays.binarySearch(a, x - a[i]);
                    if(j >= 0){
                        if(bl[j] == true && j != i){
                            bl[j] = false;
                            bl[i] = false;
                            ans++;
                        }
                    }
                }
            }
        }
        System.out.println(ans);
    }
}

import java.util.*;
import java.util.Map.Entry;

public class Main {
	static Scanner sc = new Scanner(System.in);

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int[] pow = new int[30];
		for (int i = 0; i < pow.length; i++) {
			pow[i] = (int) Math.pow(2, i + 1);
		}

		int k = sc.nextInt();
		int[] arr = nextArr(k);
		int res = 0;
		Map<Integer, Integer> m = new HashMap();
		for (int i : arr) {
			m.put(i, 1 + m.getOrDefault(i, 0));
		}

		for (int i : arr) {
			if (m.get(i) == 0)
				continue;
			m.put(i, m.get(i) - 1);

			for (int pp = pow.length - 1; pp >= 0; pp--) {
				int p = pow[pp];
				int j = p - i;
				if (m.containsKey(j) && m.get(j) != 0) {
					m.put(j, m.get(j) - 1);
					res++;
					break;
				}
			}
		}
		System.out.println(res);

	}

	private static int[] nextArr(int k) {
		// TODO Auto-generated method stub
		int[] res = new int[k];
		for (int i = 0; i < k; i++) {

			res[i] = sc.nextInt();
		}
		return res;
	}

}

import java.io.IOException;
