    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            IntList list = new IntArrayList(n);
            for (int i = 0; i < n; i++) {
                list.add(in.nextInt());
            }
            list.sort(IntComparator.REVERSE);

            Counter<Integer> counter = new Counter<>();
            for (int x : list) {
                counter.add(x);
            }

            int ans = 0;
            for (int x : list) {
                if (counter.get(x) == 0) continue;

                int another = (((Integer.highestOneBit(x) << 1) - 1) ^ x) + 1;
                if (counter.get(another) > 0 && (x != another || counter.get(another) >= 2)) {
                    ans++;
                    counter.add(x, -1);
                    counter.add(another, -1);
                }
            }

            out.println(ans);
        }

