                    if (d.ContainsKey(w) && d[w] > 0) { count++; d[w]--;  }
                }
            }
        return count;
    }
    static long getB(long a)
    {
        var t1 = (int)(1 + Log10(a) / Log10(2));
        var w = (long)Pow(2, t1);
        if (w >= a + 1 && w <= 2 * a) return w;
        else return (long)Pow(2, t1 +1);
    }
}

