namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            new Program().Solve(new ConsoleInput(Console.In, ' '));
#if DEBUG
            ReadLine();
#endif
        }

        void Solve(ConsoleInput cin)
        {
            List<long> pow_2 = new List<long>();
            for (int i = 1; true; i++)
            {
                long tmp = (long)Math.Pow(2, i);
                if (tmp <= 2000000000)
                {
                    pow_2.Add(tmp);
                }
                else
                {
                    break;
                }
            }


            long n = cin.ReadLong;
            long[] a = cin.ReadLongArray(n);


            Dictionary<long, List<long>> dic = new Dictionary<long, List<long>>();

            for (int i = 0; i < n; i++)
            {
                List<long> tmp = new List<long>();
                for (int j = 0; j < n; j++)
                {
                    if (i == j)
                    {
                        continue;
                    }

                    if (pow_2.Contains(a[i] + a[j]))
                    {
                        tmp.Add(j);
                    }

                }
                if (tmp.Count() > 0)
                {
                    dic.Add(i, tmp);
                }
            }

            List<long> order = dic.ToList().OrderBy(x => x.Value.Count()).Select(x => x.Key).ToList<long>();


            int result = 0;

            foreach (long i in order)
            {
                if (dic[i].Count() == 0)
                {
                    continue;
                }

                long p = dic[i][0];

                dic[i].Remove(p);


                foreach (KeyValuePair<long, List<long>> pair in dic)
                {
                    pair.Value.Remove(i);
                    pair.Value.Remove(p);
                }

                result++;
            }
            Console.WriteLine(result);
        }

        class ConsoleInput
        {
            private readonly System.IO.TextReader _stream;
            private char _separator = ' ';
            private Queue<string> inputStream;

            public ConsoleInput(System.IO.TextReader stream, char separator = ' ')
            {
                this._separator = separator;
                this._stream = stream;
                inputStream = new Queue<string>();
            }

            public string Read
            {
                get
                {
                    if (inputStream.Count != 0) return inputStream.Dequeue();
                    string[] tmp = _stream.ReadLine().Split(_separator);
                    for (int i = 0; i < tmp.Length; ++i)
                        inputStream.Enqueue(tmp[i]);
                    return inputStream.Dequeue();
                }
            }

            public string ReadLine { get { return _stream.ReadLine(); } }
            public int ReadInt { get { return int.Parse(Read); } }
            public long ReadLong { get { return long.Parse(Read); } }
            public double ReadDouble { get { return double.Parse(Read); } }
            public string[] ReadStrArray(long N) { var ret = new string[N]; for (long i = 0; i < N; ++i) ret[i] = Read; return ret; }
            public int[] ReadIntArray(long N) { var ret = new int[N]; for (long i = 0; i < N; ++i) ret[i] = ReadInt; return ret; }
            public long[] ReadLongArray(long N) { var ret = new long[N]; for (long i = 0; i < N; ++i) ret[i] = ReadLong; return ret; }
        }
    }
}

using System;

public class AtCoder
{
    public static void Main()
    {
        int n;
        n = int.Parse(Console.ReadLine().Trim());
        string[] s;
        s = Console.ReadLine().Trim().Split(' ');
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
        {
            a[i] = int.Parse(s[i]);
        }
        Array.Sort(a);
        int[] b = new int[n];
        int x = 1;
        int ans = 0;
        bool fsuc = true;
        BinarySearch f = new BinarySearch(a);
        for(int i = n - 1; i > -1; i--)
        {
            if (b[i] == 1) continue;
            while (x <= a[i])
            {
                x *= 2;
            }
            x = x - a[i];
            for(int j = f.UpperBound(x)-1; j > -1; j--)
            {                
                if (a[j] == x)
                {
                    if(b[j] == 0)
                    {
                        if (i != j)
                        {
                            b[i] = 1;
                            b[j] = 1;
                            ans++;
                            while (fsuc)
                            {
                                if (i > 0 && j > 0)
                                {
                                    if ((a[i - 1] == a[i]) && (a[j - 1] == x)
                                        && (b[j-1] == 0))
                                    {                                        
                                        i--;
                                        j--;
                                        b[i] = 1;
                                        b[j] = 1;
                                        ans++;
                                    }
                                    else fsuc = false;
                                }
                                else fsuc = false;
                            }
                            fsuc = true;
                            break;
                        }                       
                    }
                }
                if (a[j] < x) j = -1;
            }
            x = 1;
        }
        Console.WriteLine(ans);
    }
}

public class BinarySearch
{

    int[] a;
    public BinarySearch(int[] arr)
    {
        a = arr;
    }

    public int LowerBound(int x)
    {
        int l = -1;
        int r = a.Length;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (a[m] >= x) r = m;
            else l = m;
        }
        return r;
    }

    public int UpperBound(int x)
    {
        int l = -1;
        int r = a.Length;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (a[m] > x) r = m;
            else l = m;
        }
        return r;
    }
}

