class Program
{
    static int n;
    static Dictionary<int, int> dict;
    static int [] a;
    static bool[] used;

    public static void Main()
    {
	n = int.Parse(ReadLine());
	a = ReadIntArray();
	dict = new Dictionary<int,int>();
	for (int i = 0; i < n; i++) dict.Add(a[i], i);
	used = new bool[n];
	WriteLine(search(0, 0));
    }

    static int search(int i, int ct)
    {
	if (i == n-1){ return ct; }
	if (used[i]){ return search(i+1, ct); }

	int x = a[i];

	int m = ct;
	for (int j = 2; j < 31; j++)
	{
	    int p2 = (1 << j);
	    int y = p2 - x;
	    if (dict.ContainsKey(y))
	    {
		int yi = dict[y];
		if (yi != i && !used[yi]){
		    used[i] = used[yi] = true;
		    int nct = search(i+1, ct+1);
		    m = Math.Max(m, nct);
		    used[i] = used[yi] = false;
		}
	    }
	}
	return m;
    }
}

