using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		Array.Sort(nums);
		long[] answers = new long[n];
		long myNum = 0;
		long partnerNum = n-1;
		long aimNum = 2;//和として作る数
		long answer = 0;
		List<long> numList = new List<long>();
		List<long> numCountList = new List<long>();
		long numCountMemo = 1;

		numList.Add(nums[0]);
		for(int i = 1; i < n; i++)
		{
			if(nums[i] != nums[i-1])
			{
				numList.Add(nums[i]);
				numCountList.Add(numCountMemo);
				numCountMemo = 1;
				if(i == n-1) numCountList.Add(1);
			}else
			{
				numCountMemo++;
				if(i == n-1) numCountList.Add(numCountMemo);
			}
		}

		long nn = numList.Count();
		long[] answersSub = new long[nn];

		while(true)//全ての2のべき乗を試す
		{
			if(aimNum > 999999999999) break;//作れない数になった
			myNum = 0;
			partnerNum = nn-1;

			while(true)//全ての組み合わせを試す
			{
				if(numList[(int)myNum] + numList[(int)partnerNum] == aimNum)
				{
					answersSub[(int)myNum] += numCountList[(int)partnerNum];
					answersSub[(int)partnerNum] += numCountList[(int)myNum];
					//Console.WriteLine(numCountList[(int)myNum]+"a");
				}
				if(myNum == nn-1 || partnerNum == 0) break;

				if(numList[(int)myNum] + numList[(int)partnerNum-1] >= aimNum) partnerNum--;
				else myNum++;

				if(myNum == partnerNum)
				{
					if(numList[(int)myNum]*2 == aimNum)
					{
						answersSub[(int)myNum] += numCountList[(int)myNum]-1;
					}
					break;
				}
			}

			aimNum *= 2;
		}

		int memo = 0;
		for(int i = 0; i < n; i++)
		{
			answers[i] = answersSub[memo];
			numCountList[memo]--;
			if(numCountList[memo] == 0) memo++;
		}

		//解答を減らす
		for(int i = 0; i < n; i++)
		{
			answer += answers[i];
			//Console.WriteLine(answers[i]);
		}
		answer /= 2;
		Array.Sort(answers);
		Array.Reverse(answers);
		long answerMinusMemo = 0;
		for(int i = 0; i < n; i++)
		{
			//Console.WriteLine(answer);
			if(answers[i] > 1)
			{
				if(answerMinusMemo == 0)
				{
					answer -= answers[i]-1;
					answerMinusMemo = answers[i]-1;
				}else
				{
					if(answerMinusMemo >= answers[i]-1) answerMinusMemo -= (answers[i]-1);
					else
					{
						answers[i] -= answerMinusMemo;
						answer -= answers[i]-1;
						answerMinusMemo = answers[i]-1;
					}
				}
			}
		}

		Console.WriteLine(answer);
	}
}

