            for(var e = 30; e > 0; e--)
            {
                int s = 1 << e;
                for(var i = 0; i < N; i++)
                {
                    if (i >= A.Count())  { break; }
                    if (A[i] >= (1 << (e - 1)))
                    {
                        int r = LowerBound(A, s - A[i]);
                        if (r == -1 || r == A.Count()) { continue; }
                        /*Console.Write($"{i},{A[i]} {r},{A[r]}");
                        Console.WriteLine();*/

                        if (A[r] != s - A[i] || r == i) { continue; }

                        ans++;
                        A.RemoveAt(r);
                    }
                    else
                    {
                        break;
                    }

                }
            }

            Console.WriteLine(ans);



            //Console.Out.Flush();
        }
        static public int LowerBound(List<long>list, long s)
        {
            int l = -1;
            int r = list.Count();

            while (r - l > 1)
            {
                int c = (l + r) / 2;
                if (list[c] > s) 
                {
                    l = c;
                }
                else 
                {
                    r = c;
                }
            }

            return r;
        }



    }
