    class Program
    {
        static void Main()
        {
            int length = int.Parse(Console.ReadLine());
            string[] Input = Console.ReadLine().Split(' ');
            int j = 0, k = 0;
            int count = 0;
            for (int i = 0; i < length; i++)
            {
                if (int.Parse(Input[i]) % 2 == 0) j++;
                else k++;
            }
            int[] a = new int[j];
            int[] b = new int[k];
            j = 0;
            k = 0;
            for (int i = 0; i < length; i++)
            {
                if (int.Parse(Input[i]) % 2 == 0)
                {
                    a[j] = int.Parse(Input[i]);
                    j++;
                }
                else
                {
                    b[k] = int.Parse(Input[i]);
                    k++;
                }
            }

            for (int i = 0; i < j; i++)
            {
                for (int l = 0; l < j; l++)
                {
                    if (a[i] == -1 || a[l] == -1 || i == l) continue;
                    int c = a[i] + a[l];
                    for (; ; )
                    {
                        if (c % 2 == 1) break;
                        else if (c == 2)
                        {
                            count++;
                            a[i] = -1;
                            a[l] = -1;
                            break;
                        }
                        c /= 2;
                    }
                }
            }
            for (int i = 0; i < k; i++)
            {
                for (int l = 0; l < k; l++)
                {
                    if (b[i] == -1 || b[l] == -1 || i == l) continue;
                    int c = b[i] + b[l];
                    for (; ; )
                    {
                        if (c % 2 == 1) break;
                        else if (c == 2)
                        {
                            count++;
                            b[i] = -1;
                            b[l] = -1;
                            break;
                        }
                        c /= 2;
                    }
                }
            }
