    }
    static int getB(long a)
    {
        var t1 = (int)(1 + Log10(a) / Log10(2));
        var t2 = (int)(Log10(a + 1) / Log10(2));
        var w = (long)Pow(2, t1);
        if (w >= a + 1 && w <= 2 * a) return t1;
        else return t1 + 1;
    }
}

