class c
{
    static void Main()
    {
        Console.ReadLine();
        var x = Array.ConvertAll(Console.ReadLine().Split(), long.Parse).ToList();
        var a = new List<long>();
        var b = new List<long>();
        for(int i = 0; i < x.Count();i++)
        {
            if (x[i] % 2 == 0) a.Add(x[i]);
            else b.Add(x[i]);
        }
        a = a.OrderBy(f => f).ToList();
        b = b.OrderBy(f => f).ToList();
        var list = new List<long>();
        for (int i = 0; i <= 31; i++) list.Add((long)Math.Pow(2, i));
        long ans = 0;
        while (a.Any())
        {
            long num = a[0];
            a.RemoveAt(0);
            for (int i = 0; i < list.Count(); i++)
            {
                int add = BS(a, list[i] - num);
                if (add != -1)
                {
                    ans++;
                    a.RemoveAt(add);
                }
            }
        }
        while (b.Any())
        {
            long num = b[0];
            b.RemoveAt(0);
            for (int i = 0; i < list.Count(); i++)
            {
                int add = BS(b, list[i] - num);
                if (add != -1)
                {
                    ans++;
                    b.RemoveAt(add);
                }
            }
        }
        Console.WriteLine(ans);
    }
    public static int BS(List<long> a, long n)
    {
        int min = 0;
        int max = a.Count() - 1;
        while (true)
        {
            if (max < min) return -1;
            int mid = min + (max - min) / 2;
            switch (n.CompareTo(a[mid]))
            {
                case -1:
                    max = mid - 1;
                    break;
                case 1:
                    min = mid + 1;
                    break;
                case 0:
                    return mid;
            }
        }
    }
}

