using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		int N = int.Parse(Console.ReadLine());
		string[] str = Console.ReadLine().Split();
		int[] A = new int[N];
		var dic = new Dictionary<int,int>();
		int ans = 0;
		for(var i=0;i<N;i++){
			A[i] = int.Parse(str[i]);
			if(dic.ContainsKey(A[i])){
				dic[A[i]] += 1;
			} else {
				dic[A[i]] = 1;
			}
		}
		for(var i=0;i<N;i++){
			for(var j=1;j<=32;j++){
				int a = (int)Math.Pow(2,j);
				if(dic.ContainsKey(a-A[i])){
					if(a==A[i]){
						if(dic[A[i]] >= 2){
							ans += 1;
							dic[A[i]] -= 2;
						}
					} else {
						ans += 1;
						dic[A[i]] -= 1;
						dic[a-A[i]] -= 1;
					}
					break;
				}
			}
		}
		Console.WriteLine(ans/2);
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AGC029B
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());
            var A = Console.ReadLine().Split().Select(int.Parse).ToList();

            A = A.OrderBy(x => x).ToList();

            int[] twoPow = new int[29];
            twoPow[0] = 2;
            for (int i = 1; i < 29; i++) twoPow[i] = twoPow[i - 1] * 2;

            long count = 0;
            while (A.Count > 0)
            {
                int last = A.Last();

                int twoMax = 0;
                for (int i = 0; i < 29; i++)
                {
                    if (twoPow[i] > last)
                    {
                        twoMax = twoPow[i];
                        break;
                    }
                }

                //int index = A.FindIndex(x => x == twoMax - last);
                int index = A.BinarySearch(twoMax - last);
                if (index != -1 && index != A.Count - 1)
                {
                    count++;
                    A.RemoveAt(index);
                    A.RemoveAt(A.Count - 1);
                }
                else
                {
                    A.RemoveAt(A.Count - 1);
                }
            }

            Console.WriteLine(count);
            Console.ReadKey();
        }
    }
}

