        var list = new List<long>();
        for (int i = 0; i <= 31; i++) list.Add((long)Math.Pow(2, i));
        long ans = 0;
        while (a.Any())
        {
            long num = a[0];
            a.RemoveAt(0);
            for (int i = 0; i < list.Count(); i++)
            {
                int add = BS(a, list[i] - num);
