namespace Training20200620.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/agc029/tasks/agc029_b
    /// </summary>
    public class QuestionB : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var n = inputStream.ReadInt();
            var a = inputStream.ReadIntArray();
            Array.Sort(a, (a, b) => -a.CompareTo(b));

            var counter = new Counter<int>();
            foreach (var ai in a)
            {
                counter[ai]++;
            }

            long pairs = 0;
            foreach (var (value, count) in counter.OrderByDescending(p => p.key))
            {
                var other = GetOther(value);
                if (value != other)
                {
                    pairs += Math.Min(count, counter[other]);
                }
                else
                {
                    pairs += count / 2;
                }
            }

            yield return pairs;
        }

        int GetOther(int n)
        {
            var count = 0;
            var i = n;
            while (i > 0)
            {
                i >>= 1;
                count++;
            }
            return (1 << (count + 1)) - n;
        }
    }
}

