public class BinarySearch
{

    int[] a;
    public BinarySearch(int[] arr)
    {
        a = arr;
    }

    public int LowerBound(int x)
    {
        int l = -1;
        int r = a.Length;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (a[m] >= x) r = m;
            else l = m;
        }
        return r;
    }

    public int UpperBound(int x)
    {
        int l = -1;
        int r = a.Length;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (a[m] > x) r = m;
            else l = m;
        }
        return r;
    }
}

