    static void Solve()
    {
        var num = Input.num;
        var ar = Input.ar;
        Array.Sort(ar);var uf = new UnionFind(num);
        for (var i = 1; i <= 30; i++)
        {
            var mask = 1 << i;
            var min = 0;
            var same = -1;
            var dic = new Dictionary<int, List<int>>();
            for (var j = 0; j < num; j++)
                if (ar[j] < mask)
                    min = j + 1;
                else if (ar[j] == mask)
                {
                    if (same != -1) uf.Union(same, j);
                    same = j;
                }
                else
                {
                    var t = ar[j] % mask;
                    if (dic.ContainsKey(t))
                        dic[t].Add(j);
                    else dic[t] = new List<int> { j };
                }
            for (var v = 0; v < min; v++)
            {
                if (!dic.ContainsKey(mask - ar[v]))
                    continue;
                foreach (var val in dic[mask - ar[v]])
                    uf.Union(v, val);
            }
        }
        WriteLine(Enumerable.Range(0, num).Max(v => uf.Size(v) / 2));
    }
}

