    class Greator : IComparer<int>
    {
        public int Compare(int x, int y) => y - x;
    }

    static void Main(string[] args)
    {
        label:
        int n = Parse(ReadLine());
        var list = new SortedList<int, int>(n, new Greator());
        int beki = 2;
        foreach (var a in ReadLine().Split())
        {
            int tmp = Parse(a);
            if (list.ContainsKey(tmp)) list[tmp]++;
            else list[tmp] = 1;
            while (beki <= tmp) beki = beki << 1;
        }
        int result = 0;
        foreach (var key in list.Keys.ToArray())
        {
            while ((beki >> 1) > key) beki = beki << 1;
            int other = beki - key;
            while (0 < list[key])
            {
              int tmp;
                if (list.TryGetValue(other, out  tmp) && 0 < tmp)
                {
                    if (other == key && tmp == 1) break;
                    ++result;
                    --list[key];
                    --list[other];
                }
                else
                {
                    break;
                }
            }
        }
        WriteLine(result);
    }
}

