        for (int i = 0; i < n; i++)
            if (d.ContainsKey(a[i])) d[a[i]]++;
            else d[a[i]] = 1;
        var ans = getAns(d, a, b);
        Console.WriteLine(ans);
    }
    static int getAns(Dictionary<long, int> d, int[] a, long[] b)
    {
        var count = 0;
        foreach (var x in a)
            if (d[x] > 0)
            {
                var t = b[getB(x)];
                var w = t - x;
                if (x == w)
                {
                    if (d.ContainsKey(w) && d[w] > 1) { count++; d[w] -= 2; }
                }
                else
                {
                    if (d.ContainsKey(w) && d[w] > 0) { count++; d[w]--; }
                }
            }
        return count;
    }
    static int getB(long a) => (int)(1 + Log10(a) / Log10(2));
}

