                {
                    ans++;
                    x.RemoveAt(add);
                    break;
                }
            }
        }
        Console.WriteLine(ans);
    }

    public static int BS(List<long> a, long n)
    {
        int min = 0;
        int max = a.Count() - 1;
        while (true)
        {
            if (max < min) return -1;
            int mid = min + (max - min) / 2;
            switch (n.CompareTo(a[mid]))
            {
                case -1:
                    max = mid - 1;
                    break;
                case 1:
                    min = mid + 1;
                    break;
                case 0:
                    return mid;
            }
        }
    }
}

