		public void Solve(ConsoleInput cin) {
			var N = cin.ReadInt;
			var A = cin.ReadIntArray(N);
			var C = new Dictionary<int, int>();
			for(int i = 0; i<N; i++) {
				if(C.ContainsKey(A[i]))
					C[A[i]]++;
				else C.Add(A[i], 1);
			}
			A.MergeSort(true);
			var res = 0;
			foreach(var a in A) {
				if(C[a]<=0) continue;
				C[a]--;
				var target = 1;
				while(target<=a) target<<=1;
				var partner = target-a;
				if(!C.ContainsKey(partner)||C[partner]<=0) continue;
				C[partner]--;
				res++;
			}
			Console.WriteLine(res);
		}
