        Array.Sort(num);
        Array.Reverse(num);

        Dictionary<long, int> dic = new Dictionary<long, int>();
        foreach (var item in num)
        {
            if (!dic.ContainsKey(item)) dic[item] = 0;
            dic[item]++;
        }

        int ans = 0;

        foreach (var A in num)
        {
            if (dic[A] == 0) continue;
            dic[A]--;
            long T = 1;
            while (T <= A) T *= 2;

            long B = T - A;

            if(dic.ContainsKey(B) && dic[B] >= 1)
            {
                dic[B]--;
                ans++;
            }
        }

        Console.WriteLine(ans);
    }

