class MyUtil
{
    public static int[] ReadIntArray()
    {
        return ReadLine().Split().Select(x => int.Parse(x)).ToArray();
    }
}

class Program
{
    public static void Main()
    {
        int n = int.Parse(ReadLine());
        int[] a = ReadIntArray();
        Array.Sort(a);
        bool[] used = new bool[n];

        int ans = 0;
        for (int i = n-1; i > 0; i--)
        {
            if (used[i]) continue;
            int x = a[i];
            for (int j = 2; j <= 31; j++)
            {
                int p2 = (1 << j);
                int y = p2 - x;
                int idx = Array.BinarySearch(a, y);

                if (idx >= 0 && idx < i)
                {
                    ans++;
                    used[i] = used[idx] = true;
                    break;
                }
            }
        }

        WriteLine(ans);
    }
}

using System;

public class AtCoder
{
    public static void Main()
    {
        int n;
        n = int.Parse(Console.ReadLine().Trim());
        string[] s;
        s = Console.ReadLine().Trim().Split(' ');
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
        {
            a[i] = int.Parse(s[i]);
        }
        Array.Sort(a);
        int[] b = new int[n];
        int x = 1;
        int ans = 0;
        BinarySearch f = new BinarySearch(a);
        for(int i = n - 1; i > -1; i--)
        {
            if (b[i] == 1) continue;
            while (x <= a[i])
            {
                x *= 2;
            }
            x = x - a[i];
            for(int j = f.UpperBound(x)-1; j > -1; j--)
            {                
                if (a[j] == x)
                {
                    if(b[j] == 0)
                    {
                        if (i != j)
                        {
                            b[i] = 1;
                            b[j] = 1;
                            ans++;
                            break;
                        }                       
                    }
                }
                if (a[j] < x) j = -1;
            }
            x = 1;
        }
        Console.WriteLine(ans);
    }
}

public class BinarySearch
{

    int[] a;
    public BinarySearch(int[] arr)
    {
        a = arr;
    }

    public int LowerBound(int x)
    {
        int l = -1;
        int r = a.Length;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (a[m] >= x) r = m;
            else l = m;
        }
        return r;
    }

    public int UpperBound(int x)
    {
        int l = -1;
        int r = a.Length;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (a[m] > x) r = m;
            else l = m;
        }
        return r;
    }
}

