public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int[] A = GetInts(N);

		var dict = new Dictionary<int, int>();
		var set = new SortedSet<int>();
		for(int i = 0; i < N; i++)
		{
			int current = 0;
			dict.TryGetValue(A[i], out current);
			dict[A[i]] = current + 1;
			set.Add(A[i]);
		}

		int ans = 0;
		int rest = N;
		while(set.Count > 0)
		{
			int max = set.Max;
			dict[max]--;
			if(dict[max] == 0)
				set.Remove(max);

			int k = 0;
			int tmp = max;
			while(tmp > 0)
			{
				k++;
				tmp >>= 1;
			}

			int pair = (1 << k) - max;
			if(!set.Contains(pair))
				continue;

			int current = dict[pair];
			dict[pair] = current - 1;			
			ans++;
			if(current == 1)
				set.Remove(pair);
		}

		Console.WriteLine(ans);
	}
}


