    class Solver
    {
        public Solver()
        {
            Input input = new Input();
            input.Long(out N);
            input.Long(out A);
        }

        private long N;
        private long[] A;

        public void Solve()
        {
            Array.Sort(A);
            Array.Reverse(A);

            // Ai, count
            Dictionary<long, int> rest = new Dictionary<long, int>();
            for (long i = 0; i < N; i++)
            {
                if (!rest.ContainsKey(A[i])) rest.Add(A[i], 0);
                rest[A[i]]++;
            }

            var max = A.Max();
            long pow = 2;
            while (pow < max * 2)
            {
                pow *= 2;
            }

            long ans = 0;
            for (long i = 0; i < N; i++)
            {
                var cur = A[i];
                if (rest[cur] <= 0) continue;

                while (pow > A[i] * 2) pow /= 2;
                var target = pow - cur;

                if (cur == target)
                {
                    if (rest[target] > 1)
                    {
                        ans++;
                        rest[cur]--;
                        rest[target]--;
                    }
                }
                else
                {
                    if (rest.ContainsKey(target) && rest[target] > 0)
                    {
                        ans++;
                        rest[cur]--;
                        rest[target]--;
                    }
                }
            }

            Console.WriteLine(ans);
        }
    }
