        public class Calc {
	        public void Solve() {
	            var N = NextInt();
	            var A = NextLongList().OrderByDescending(x => x).ToArray();
	            var map = A.CountUp();

	            Func<long, long> next2PowFunc = (x) => {
	                var rt = 1L;
	                var idx = 1;
	                while (rt <= x) rt = (long) Pow(2, idx++);
	                return rt;
	            };

	            var sum = 0L;
	            foreach (var item in A) {
	                if (map[item] == 0) continue;

	                var next = next2PowFunc(item);
                    if(next-item == item && map[item]<2) continue;
	                if (item >= next || next >= 2 * item || map[next - item] == 0) continue;
	                map[next - item]--;
	                map[item]--;
	                sum++;

	            }

                sum.WL();
	        }

		}
    }

