    public static void Main()
    {
        int n = int.Parse(ReadLine());
        int[] a = ReadIntArray();
        Array.Sort(a);
        Dictionary<int,int> d = new Dictionary<int,int>();
        for (int i = 0; i < n; i++)
        {
            int x = a[i];
            if (d.ContainsKey(x)) d[x]++;
            else d[x] = 1;
        }

        int ans = 0;
        for (int i = n-1; i > 0; i--)
        {
            int x = a[i];
            if (d[x] == 0) continue;
            for (int j = 1; j < 31; j++)
            {
                int p2 = (1 << j);
                int y = p2 - x;
                int idx = Array.BinarySearch(a, y);

                if (idx >= 0 && idx < i)
                {
                    if ((x != y && d[y] > 0) || d[y] >= 2)
                    {
                        ans++;
                        d[x]--; d[y]--;
                        break;
                    }
                }
            }
        }

