            index = line.Length;
            return line;
        }

        public int[] IntArray()
        {
            var array = Array();
            var result = new int[array.Length];
            for (int i = 0; i < array.Length; i++)
            {
                result[i] = int.Parse(array[i]);
            }

            return result;
        }

        public long[] LongArray()
        {
            var array = Array();
            var result = new long[array.Length];
            for (int i = 0; i < array.Length; i++)
            {
                result[i] = long.Parse(array[i]);
            }

            return result;
        }
    }

    class Program
    {
        private int N;
        private int[] A;
        void Scan()
        {
            var sc = new Scanner();
            N = sc.NextInt();
            A = sc.IntArray();
        }

        public void Solve()
        {
            Scan();
            var set = new Set<int>();
            foreach (var i in A)
            {
                set.Insert(i);
            }
            Array.Sort(A, (a, b) => -a.CompareTo(b));
            int[] target = new int[N];
            int n = 1;

            for (int i = N - 1; i >= 0; i--)
            {

                if (n <= A[i])
                {
                    while (n <= A[i])
                    {
                        n *= 2;
                    }
                }

                target[i] = n;
            }

            int cnt = 0;
            for (int i = 0; i < N; i++)
            {
                var nA = set.LowerBound(A[i]);
                if (nA == null || nA.Val != A[i]) continue;
                set.Erase(A[i]);
                int t = target[i] - A[i];
                var tA = set.LowerBound(t);
                if (tA == null || tA.Val != t) continue;
                cnt++;
                set.Erase(t);

            }
            Console.WriteLine(cnt);
        }

        static void Main() => new Program().Solve();
    }


