class Set<T>
{
    private Node Root;
    public int Count { get; private set; } = 0;
    private readonly Comparison<T> Compare;
    public Set() : this(Comparer<T>.Default) { }
    public Set(IComparer<T> comparer) : this(comparer.Compare) { }
    public Set(Comparison<T> comparison)
    {
        Compare = comparison;
    }
    public class Node
    {
        public T Val;
        public Node Parent, High, Low;
        public Node(T val, Node parent)
        {
            Val = val;
            Parent = parent;
        }
    }
    /// <summary>
    /// 要素の追加
    /// </summary>
    /// <param name="item">追加する要素</param>
    /// <returns></returns>
    public void Insert(T item)
    {
        if (Root == null)
        {
            Root = new Node(item, null);
            return;
        }
        Node node = Root;
        Node parent = null;
        bool high = false;
        while (node != null)
        {
            parent = node;
            if (Compare(item, node.Val) > 0)
            {
                node = node.High;
                high = true;
            }
            else
            {
                node = node.Low;
                high = false;
            }
        }
        node = new Node(item, parent);
        if (high)
        {
            parent.High = node;
        }
        else
        {
            parent.Low = node;
        }
    }
    /// <summary>
    /// 要素の削除
    /// </summary>
    /// <param name="item"></param>
    public void Erase(T item)
    {
        Node node = LowerBound(item);
        if (node == null) return;
        if (Compare(node.Val, item) == 0)
        {
            Erase(node);
        }
    }
    /// <summary>
    /// 要素の削除
    /// </summary>
    /// <param name="node"></param>
    public void Erase(Node node)
    {
        bool hasLow = node.Low != null;
        bool hasHigh = node.High != null;
        Node connect = null;
        if (hasHigh)
        {
            if (hasLow)
            {
                Node p = node;
                Node n = node.Low;
                while (n != null)
                {
                    p = n;
                    n = n.High;
                }
                node.Val = p.Val;
                Erase(p);
                return;
            }
            else
            {
                connect = node.High;
            }
        }
        else
        {
            if (hasLow)
            {
                connect = node.Low;
            }
            else
            {
                connect = null;
            }
        }
        var parent = node.Parent;
        if (connect != null)
        {
            connect.Parent = parent;
        }
        if (parent == null)
        {
            Root = connect;
        }
        else
        {
            if (Compare(node.Val, parent.Val) > 0)
            {
                parent.High = connect;
            }
            else
            {
                parent.Low = connect;
            }
        }
    }
    /// <summary>
    /// item以上の要素の検索
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public Node LowerBound(T item)
    {
        Node node = Root;
        Node parent = null;
        Node result = null;
        while (node != null)
        {
            parent = node;
            if (Compare(node.Val, item) >= 0)
            {
                if (result == null || Compare(result.Val, node.Val) > 0)
                {
                    result = node;
                }
                node = node.Low;
            }
            else
            {
                node = node.High;
            }
        }
        return result;
    }
    /// <summary>
    /// itemより大きい要素の検索
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public Node UpperBound(T item)
    {
        Node node = Root;
        Node parent = null;
        Node result = null;
        while (node != null)
        {
            parent = node;
            if (Compare(node.Val, item) > 0)
            {
                if (result == null || Compare(result.Val, node.Val) > 0)
                {
                    result = node;
                }
                node = node.Low;
            }
            else
            {
                node = node.High;
            }
        }
        return result;
    }
}

using System;
