using System.Linq;
using System.Web;

namespace Competitive
{
    internal class Solution
    {
        public int N;
        public long[] A;
        public bool[] U;
        public long MOD = 1000000007;

        public void Run()
        {
            N = Input.ReadInt();
            A = Input.ReadLongArray();
            Array.Sort(A);

            U = new bool[N];
            for (int i = 0; i < N; i++)
            {
                U[i] = false;
            }

            int r = 0;
            for (int b = 40; b >= 0; b--)
            {
                long x = 1L << b;
                int j = 0;
                for (int i = N - 1; i >= 0; i--)
                {
                    if (U[i]) continue;
                    while (j < N)
                    {
                        if (!U[j] && i != j && A[i] + A[j] == x)
                        {
                            U[i] = true;
                            U[j] = true;
                            r++;
                            j++;
                            break;
                        }
                        else if (A[i] + A[j] > x)
                        {
                            break;
                        }
                        else
                        {
                            j++;
                        }
                    }
                }
            }

            Console.WriteLine(r);
