        public class Calc {
	        public void Solve() {
	            var N = NextInt();
	            var A = NextLongList();

	            var map = A.CountUp();
	            var aMax = A.OrderByDescending(x => x).Take(2).Sum();
	            var max = 1L;
	            var idx = 0;
	            while (max < aMax) max = (long) Pow(2, idx++);

	            var pairMap = new Map<long, List<long>>();
	            foreach (var first in A.Distinct()) {
                    pairMap[first]=new Ll();
	                foreach (var second in Enumerable.Range(0, idx + 1).Select(x => (long)Pow(2, x))) {
                        if(map[second-first]!=0) pairMap[first].Add(second-first);
	                }
	            }

	            foreach (var l in A.Distinct()) {
	                pairMap[l] = pairMap[l].OrderBy(x => pairMap[x].Count).ToList();
	            }

	            var sum = 0L;
	            foreach (var item in A.Distinct()) {
	                var pairCount = Min(pairMap[item].Select(x => map[x]).Sum(), map[item]);
	                map[item]--;
	                foreach (var l in pairMap[item]) {
	                    var next = Min(pairCount, map[l]);
	                    pairCount -= next;
	                    map[l] -= next;
	                    sum += next;
                        if(pairCount==0) break;
	                }
	            }

                sum.WL();
	        }

		}
        public class MaxFlow
        {
            private class Edge
            {
                public int To, Reverse, Capacity;
            }

            private int V { get; set; }
            private List<Edge>[] graph { get; set; }
            private int[] leveList, itr;
            public MaxFlow(int v)
            {
                V = v;
                graph = Enumerable.Repeat(1, V).Select(x => new List<Edge>()).ToArray();
            }

            public void Add(int from, int to, int capa, bool dir = true)
            {
                graph[from].Add(new Edge { Capacity = capa, Reverse = graph[to].Count, To = to });
                graph[to].Add(new Edge { To = from, Capacity = dir ? 0 : capa, Reverse = graph[from].Count - 1 });
            }

            private void Bfs(int s)
            {
                leveList = Enumerable.Repeat(-1, V).ToArray();
                var queue = new Queue<int>();
                leveList[s] = 0;
                queue.Enqueue(s);
                while (queue.Any())
                {
                    var src = queue.Dequeue();
                    foreach (var edge in graph[src])
                    {
                        if (edge.Capacity <= 0 || leveList[edge.To] >= 0) continue;
                        leveList[edge.To] = leveList[src] + 1;
                        queue.Enqueue(edge.To);
                    }
                }
            }

            private int Dfs(int v, int t, int f)
            {
                if (v == t) return f;
                for (; itr[v] < graph[v].Count; itr[v]++)
                {
                    var edge = graph[v][itr[v]];
                    if (edge.Capacity <= 0 || leveList[v] >= leveList[edge.To]) continue;
                    var d = Dfs(edge.To, t, Min(f, edge.Capacity));
                    if (d <= 0) continue;
                    edge.Capacity -= d;
                    graph[edge.To][edge.Reverse].Capacity += d;
                    return d;
                }

                return 0;
            }

            public int Run(int s, int t)
            {
                int rt = 0;
                Bfs(s);
                while (leveList[t] >= 0)
                {
                    itr = new int[V];
                    int f;
                    while ((f = Dfs(s, t, int.MaxValue)) > 0) rt += f;
                    Bfs(s);
                }

                return rt;
            }
        }

    }

