using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AGC029B
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());
            var A = Console.ReadLine().Split().Select(int.Parse).ToList();

            A = A.OrderBy(x => x).ToList();

            var dic = new Dictionary<int, int>();
            for (int i = 0; i < N; i++)
            {
                if (dic.ContainsKey(A[i])) dic[A[i]]++;
                else dic[A[i]] = 1;
            }

            int[] twoPow = new int[32];
            for (int i = 0; i < 31; i++) twoPow[i] = 1 << i;

            int count = 0;
            for (int j = N - 1; j > 0; j--)
            {
                int last = A[j];

                int pair = -1;
                for (int i = 0; i < 31; i++)
                {
                    if (twoPow[i] > last)
                    {
                        pair = twoPow[i] - last;
                        break;
                    }
                }

                if (!dic.ContainsKey(pair)) continue;

                if (dic[pair] > 0 && dic[last] > 0)
                {
                    if (pair != last)
                    {
                        count++;
                        dic[last]--;
                        dic[pair]--;
                    }
                    else
                    {
                        if (dic[last] >= 2)
                        {
                            count++;
                            dic[last] -= 2;
                        }
                    }
                }
            }

            Console.WriteLine(count);
            Console.ReadKey();
        }
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		Array.Sort(nums);
		long[] answers = new long[n];
		long myNum = 0;
		long partnerNum = n-1;
		long aimNum = 2;//和として作る数
		long answer = 0;

		while(true)//全ての2のべき乗を試す
		{
			if(n == 1) break;
			if(aimNum > nums[n-1] + nums[n-2]) break;//作れない数になった
			myNum = 0;
			partnerNum = n-1;

			while(true)//全ての組み合わせを試す
			{
      if(nums[myNum] == nums[partnerNum] && nums[myNum] + nums[partnerNum] == aimNum)//同じ数で和となる
      {
        for(int i = (int)myNum; i <= (int)partnerNum; i++)
        {
          answers[i] = partnerNum - myNum;
        }
        break;
      }

				if(nums[myNum] + nums[partnerNum] == aimNum)
				{
					answers[myNum]++;
					answers[partnerNum]++;
				}
				if(myNum == n-1 || partnerNum == 0) break;

				if(nums[myNum] + nums[partnerNum-1] >= aimNum) partnerNum--;
				else
        {
          while(true)
          {
            myNum++;
            if(nums[myNum] != nums[myNum-1]) break;
            else
            {
              answers[myNum] = answers[myNum-1];
              answers[partnerNum] += answers[myNum-1];
            }
          }
        }

        if(myNum == partnerNum) break;

			}

			aimNum *= 2;
		}

    //解答を減らす
    for(int i = 0; i < n; i++)
    {
      answer += answers[i];
    }
    answer /= 2;
    //Console.WriteLine(answer);
		Array.Sort(answers);
		Array.Reverse(answers);
		long answerMinusMemo = 0;
		for(int i = 0; i < n-1; i++)
		{
			if(answers[i] > 1)
			{
				if(answerMinusMemo == 0)
				{
					answer -= answers[i]-1;
					answerMinusMemo = answers[i]-1;
				}else
				{
					if(answerMinusMemo >= answers[i]-1) answerMinusMemo -= (answers[i]-1);
					else
					{
						answers[i] -= answerMinusMemo;
						answer -= answers[i]-1;
						answerMinusMemo = answers[i]-1;
					}
				}
			}
		}

		Console.WriteLine(answer);
	}
