    static class Program {

        static void Main() {
            var n = ReadInt();
            var a = ReadLong(n);

            Calc(a).WriteLine();
        }

        static int Calc(IEnumerable<long> a) {
            var hSet = new SortedMultiSet<long>(a.Select(x => -x));
            var count = 0;

            while (hSet.Count > 0) {
                var max = -hSet.First();
                hSet.Remove(-max);
                var target = (int) Pow(2, Ceiling(Log(max, 2) + 0.001)) - max;
                if (hSet.Contains(-target)) {
                    hSet.Remove(-target);
                    count++;
                };
            }
            return count;
        }
    }
}
