	static string[] strAry(String str) {
		string[] re = new string[str.Length];
		for ( int i = 0; i < str.Length; i++ ) { re[i] = str[i].ToString(); }
		return re;
	}

	static public int Binary_SearchX(int x) {
		int Lower = 0;
		int Upper = va.Count - 1;
		while ( Lower <= Upper ) {
			int Center = ( Lower + Upper ) >> 1;
			if ( x > va[(int)Center] ) {
				Lower = Center + 1;
			} else if ( x < va[(int)Center] ) {
				Upper = Center - 1;
			} else {
				return (int)Center;
			}
		}
		return -1;
	}
}

using System;

public class AtCoder
{
    public static void Main()
    {
        int n;
        n = int.Parse(Console.ReadLine().Trim());
        string[] s;
        s = Console.ReadLine().Trim().Split(' ');
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
        {
            a[i] = int.Parse(s[i]);
        }
        Array.Sort(a);
        int[] b = new int[n];
        int x = 1;
        int ans = 0;
        BinarySearch f = new BinarySearch(a);
        for(int i = n - 1; i > -1; i--)
        {
            if (b[i] == 1) continue;
            while (x <= a[i])
            {
                x *= 2;
            }
            x = x - a[i];
            for(int j = f.UpperBound(x); j > -1; j--)
            {                
                if (a[j] == x)
                {
                    if(b[j] == 0)
                    {
                        if (i != j)
                        {
                            b[i] = 1;
                            b[j] = 1;
                            ans++;
                            break;
                        }                       
                    }
                }
                if (a[j] < x) j = -1;
            }
            x = 1;
        }
        Console.WriteLine(ans);
    }
}

public class BinarySearch
{

    int[] a;
    public BinarySearch(int[] arr)
    {
        a = arr;
    }

    public int LowerBound(int x)
    {
        int l = -1;
        int r = a.Length;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (a[m] >= x) r = m;
            else l = m;
        }
        return r;
    }

    public int UpperBound(int x)
    {
        int l = -1;
        int r = a.Length;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (a[m] > x) r = m;
            else l = m;
        }
        return r;
    }
}

