public class Hello
{
    public static void Main()
    {
        var b = new long[32];
        b[0] = 1;
        for (int i = 1; i <= 31; i++) b[i] = b[i - 1] * 2;
        var n = int.Parse(Console.ReadLine().Trim());
        string[] line = Console.ReadLine().Trim().Split(' ');
        var a = Array.ConvertAll(line, int.Parse);
        Array.Sort(a);
        Array.Reverse(a);
        var d = new Dictionary<long, int>();
        for (int i = 0; i < n; i++)
            if (d.ContainsKey(a[i])) d[a[i]]++;
            else d[a[i]] = 1;
        var ans = getAns(d, a, b);
        Console.WriteLine(ans);
    }
    static int getAns(Dictionary<long, int> d, int[] a, long[] b)
    {
        var count = 0;
        foreach (var x in a)
            if (d[x] > 0)
            {
                var t = b[getB(x)];
                var w = t - x;
                if (x == w)
                {
                    if (d.ContainsKey(w) && d[w] > 1) { count++; d[w] -= 2; }
                }
                else
                {
                    if (d.ContainsKey(w) && d[w] > 0) { count++; d[w]--; }
                }
            }
        return count;
    }
    static int getB(long a) => (int)(Log10(2 * a) / Log10(2));
}

