        }
        numbers.Sort();
        int count = 0;
        for(int i = 0; i < numbers.Count; i++)
        {
            for(int j = numbers.Count - 1; j > i; j--)
            {
                if (IsPower2(numbers[i] + numbers[j]))
                {
