                    numbers.RemoveAt(i);
                    count++;
                    i--;
                    break;
                }
            }
        }
        Console.WriteLine(count);
    }

    static bool IsPower2(int number)
    {
        if (number % 2 == 1) return false;
        if (number == 2) return true;
        return IsPower2(number / 2);
    }
