namespace AGC029B
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());
            var A = Console.ReadLine().Split().Select(int.Parse).ToList();

            A = A.OrderBy(x => x).ToList();

            var dic = new Dictionary<int, int>();
            for (int i = 0; i < N; i++)
            {
                if (dic.ContainsKey(A[i])) A[i]++;
                else dic[A[i]] = 1;
            }

            int[] twoPow = new int[29];
            for (int i = 1; i < 29; i++) twoPow[i] = 1 << i;

            int count = 0;
            for (int j = N - 1; j > 1; j--)
            {
                int last = A[j];

                int pair = -1;
                for (int i = 0; i < 29; i++)
                {
                    if (twoPow[i] > last)
                    {
                        pair = twoPow[i] - last;
                        break;
                    }
                }

                if (!dic.ContainsKey(pair)) continue;

                if (dic[pair] > 0 && dic[last] > 0)
                {
                    if (pair != last)
                    {
                        count++;
                        dic[last]--;
                        dic[pair]--;
                    }
                    else
                    {
                        if (dic[pair] >= 2)
                        {
                            count++;
                            dic[last] -= 2;
                        }
                    }
                }
            }

            Console.WriteLine(count);
            Console.ReadKey();
        }
    }
