class Program
{
    public static void Main()
    {
        int n = int.Parse(ReadLine());
        int[] a = ReadIntArray();
        Array.Sort(a);
        bool[] used = new bool[n];

        int ans = 0;
        for (int i = n-1; i > 0; i--)
        {
            if (used[i]) continue;
            int x = a[i];
            for (int j = 2; j < 31; j++)
            {
                int p2 = (1 << j);
                int y = p2 - x;
                int idx = Array.BinarySearch(a, y);
                while (a[idx] == a[idx+1]) idx++;

                if (idx >= 0 && idx < i)
                {
                    ans++;
                    used[i] = used[idx] = true;
                    break;
                }
            }
        }

        WriteLine(ans);
    }
}

