namespace AtCoder {
    using VI = VectorInt2;

    static class Program {
        static Random Rand = new Random();

        static List<long> Powers = new List<long>();

        static void Initialize() {
            const long LargeEnough = int.MaxValue * 2L;
            var i = 2L;
            while (i < LargeEnough) {
                Powers.Add(i);
                i *= 2;
            }
        }

        static void Main() {
            Initialize();
            var n = ReadInt();
            var a = ReadLong(n);

            1. Times(() => Calc(a)).Max().WriteLine();
        }

        static int Calc(IEnumerable<long> a) {
            var hSet = new Multiset<long>(a);
            var count = 0;

            while (hSet.Count > 0) {
                var n = hSet.First();
                hSet.Remove(n);
                var candidates = Powers.Select(x => x - n).Where(x => hSet.Contains(x)).ToList();
                if (candidates.isEmpty()) continue;

                var canlength = candidates.Count;
                var chosen = candidates[Rand.Next(canlength)];
                hSet.Remove(chosen);
                count++;

            }
            return count;
        }
    }
}
