    public class Multiset<T> : ICollection<T> {
        // TODO: 順番がグチャグチャなので整理する
        Dictionary<T, int> occurrence;

        public Multiset(Multiset<T> source) : this(source.occurrence) {}
        public Multiset(Dictionary<T, int> source) {
            occurrence = new Dictionary<T, int>(source);
            Validate();
        }

        public Multiset() {
            occurrence = new Dictionary<T, int>();
        }
        public Multiset(IEnumerable<T> source) {
            occurrence = new Dictionary<T, int>();
            AddRange(source);
        }

        public Dictionary<T, int> Dict => occurrence;

        public void Add(T data) {
            if (!occurrence.ContainsKey(data)) {
                occurrence[data] = 1;
                return;
            }
            occurrence[data]++;
        }

        public void Clear() => occurrence.Clear();

        public void Add(T key, int value) {
            return;
            if (value <= 0) throw new ArgumentException();
            if (!occurrence.ContainsKey(key)) {
                occurrence[key] = value;
                return;
            }
            //            occurrence[key] += value;
        }

        public void Add(KeyValuePair<T, int> pair) => Add(pair.Key, pair.Value);

        public void AddRange(IEnumerable<T> source) =>
        source.ToList().ForEach(Add);

        public bool Remove(T data) {
            if (!occurrence.ContainsKey(data)) return false;
            occurrence[data]--;
            if (occurrence[data] == 0) occurrence.Remove(data);
            return true;
        }

        // IDictionary
        public int this [T key] {
            get { return occurrence.ContainsKey(key) ? occurrence[key] : 0; }
            set {
                if (value <= 0) throw new ArgumentException();
                occurrence[key] = value;
            }
        }

        public ICollection<T> Keys => occurrence.Keys;
        public ICollection<int> Values => occurrence.Values;

        public bool ContainsKey(T key) => occurrence.ContainsKey(key);
        public bool Contains(T key) => ContainsKey(key);
        public bool TryGetValue(T key, out int value) {
            value = this [key];
            return true;
        }
        // /IDictionary

        public int Count => occurrence.Values.Sum();
        public bool IsReadOnly => false;
        public void CopyTo(T[] array, int index) {
            foreach (var pair in occurrence) {
                for (int i = 0; i < pair.Value; i++) {
                    array[index] = pair.Key;
                    index++;
                }
            }
        }

        public IEnumerator<T> GetEnumerator() {
            foreach (var pair in occurrence)
                for (int i = 0; i < pair.Value; i++) yield return pair.Key;

        }

        IEnumerator IEnumerable.GetEnumerator() => this.GetEnumerator();

        public void Validate() {
            if (occurrence.Values.Any(x => x <= 0)) throw new ArgumentException();
        }
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		Array.Sort(nums);
		long[] answers = new long[n];
		long myNum = 0;
		long partnerNum = n-1;
		long aimNum = 1;//和として作る数
		long answer = 0;
		List<long> numList = new List<long>();
		List<long> numCountList = new List<long>();
		long numCountMemo = 1;

		numList.Add(nums[0]);
		for(int i = 1; i < n; i++)
		{
			if(nums[i] != nums[i-1])
			{
				numList.Add(nums[i]);
				numCountList.Add(numCountMemo);
				numCountMemo = 1;
				if(i == n-1) numCountList.Add(1);
			}else
			{
				numCountMemo++;
				if(i == n-1) numCountList.Add(numCountMemo);
			}
		}

		long nn = numList.Count();
		long[] answersSub = new long[nn];

		while(true)//全ての2のべき乗を試す
		{
			aimNum *= 2;
			if(aimNum > 999999999999) break;//作れない数になった

			if(nn == 1)
			{
				if(numList[(int)myNum] * 2 == aimNum)
				{
					answersSub[0] = numCountList[0]-1; 
				}
				continue;
			}

			myNum = 0;
			partnerNum = nn-1;

			while(true)//全ての組み合わせを試す
			{
				if(numList[(int)myNum] + numList[(int)partnerNum] == aimNum)
				{
					answersSub[(int)myNum] += numCountList[(int)partnerNum];
					answersSub[(int)partnerNum] += numCountList[(int)myNum];
				}
				if(myNum == partnerNum)
				{
					if(numList[(int)myNum] * 2 == aimNum)
					{
						answersSub[(int)myNum] = numCountList[(int)myNum]-1; 
					}
					break;
				}

				if(numList[(int)myNum] + numList[(int)partnerNum-1] >= aimNum) partnerNum--;
				else myNum++;

			}

		}

		int memo = 0;
		for(int i = 0; i < n; i++)
		{
			answers[i] = answersSub[memo];
			numCountList[memo]--;
			if(numCountList[memo] == 0) memo++;
		}

		//解答を減らす
		for(int i = 0; i < n; i++)
		{
			answer += answers[i];
			//Console.WriteLine(answers[i]);
		}
		answer /= 2;
		Array.Sort(answers);
		Array.Reverse(answers);
		long answerMinusMemo = 0;
		for(int i = 0; i < n; i++)
		{
			if(answers[i] > 1)
			{
				if(answerMinusMemo == 0)
				{
					answer -= answers[i]-1;
					answerMinusMemo = answers[i]-1;
				}else
				{
					if(answerMinusMemo >= answers[i]-1) answerMinusMemo -= (answers[i]-1);
					else
					{
						answers[i] -= answerMinusMemo;
						answer -= answers[i]-1;
						answerMinusMemo = answers[i]-1;
					}
				}
			}
		}
		answer += answerMinusMemo/2;
		Console.WriteLine(answer);
	}
}

using System;
using System.Linq;
using System.Collections.Generic;
class c
{
    static void Main()
    {
        Console.ReadLine();
        var a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse).ToList();
        a = a.OrderBy(f => f).ToList();
        var list = new List<long>();
        for (int i = 0; i < 31; i++) list.Add((long)Math.Pow(2,i));
        long ans = 0;
        while (a.Any())
        {
            int num = a[0];
            a.RemoveAt(0);
            for (int i = 0; i < list.Count(); i++)
            {
                int add = BS(a, (int)(list[i] - num));
                if (add != -1)
                {
                    ans++;
                    a.RemoveAt(add);
                }
            }
        }
        Console.WriteLine(ans);
    }
    public static int BS(List<int> a,int n)
    {
        int min = 0;
        int max = a.Count() - 1;
        while(true)
        {
            if (max < min) return -1;
            int mid = min + (max - min) / 2;
            switch(n.CompareTo(a[mid]))
            {
                case -1:
                    max = mid - 1;
                    break;
                case 1:
                    min = mid + 1;
                    break;
                case 0:
                    return mid;
            }
        }
    }
}

