            if (a == 0 || b == 0) return Max(a, b);
            return a % b == 0 ? b : Gcd(b, a % b);
        }
        static public long LPow(int a, int b) => (long)Pow(a, b);
        static public bool Bit(long x, int dig) => ((1L << dig) & x) != 0;
        static public int Sig(long a) => a == 0 ? 0 : (int)(a / Abs(a));
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		Array.Sort(nums);
		long[] answers = new long[n];
		long myNum = 0;
		long partnerNum = n-1;
		long aimNum = 2;//和として作る数
		long answer = 0;

		while(true)//全ての2のべき乗を試す
		{
			if(n == 1) break;
			if(aimNum > nums[n-1] + nums[n-2]) break;//作れない数になった
			myNum = 0;
			partnerNum = n-1;

			while(true)//全ての組み合わせを試す
			{
				if(nums[myNum] + nums[partnerNum] == aimNum)
				{
					answer++;
					answers[myNum]++;
					answers[partnerNum]++;
				}
				if(myNum == n-1 || partnerNum == 0) break;

				if(nums[myNum] + nums[partnerNum-1] >= aimNum) partnerNum--;
				else myNum++;

				if(myNum == partnerNum) break;
			}

			aimNum *= 2;
		}

		Array.Sort(answers);
		Array.Reverse(answers);
		long answerMinusMemo = 0;
		for(int i = 0; i < n-1; i++)
		{
			if(answers[i] > 1)
			{
				if(answerMinusMemo == 0)
				{
					answer -= answers[i]-1;
					answerMinusMemo = answers[i]-1;
				}else
				{
					if(answerMinusMemo >= answers[i]-1) answerMinusMemo -= (answers[i]-1);
					else
					{
						answers[i] -= answerMinusMemo;
						answer -= answers[i]-1;
						answerMinusMemo = answers[i]-1;
					}
				}
			}
		}

		Console.WriteLine(answer);
	}
}

