            var low = 0;
            var high = arr.Length - 1;

            while (low + 1 < high)
            {
                var mid = (low + high) / 2;
                if (arr[mid] >= val) high = mid;
                else low = mid;
            }

            return high;
        }

        static int UpperBound(long[] arr, int val)
        {
            val++;
            if (arr[0] >= val) return 0;
