        for (int i = 0; i < n; i++)
            if (d.ContainsKey(a[i])) d[a[i]]++;
            else d[a[i]] = 1;
        var ans = getAns(d, a, b);
        Console.WriteLine(ans);
    }
    static int getAns(Dictionary<long, int> d, int[] a, long[] b)
    {
        var count = 0;
        foreach (var x in a)
            if (d[x] > 0)
            {
                var t = b[getB(x, b)];
                var w = t - x;
                if (x == w)
                {
                    if (d[w] > 1) { count++; d[w] -= 2; }
                }
                else
                {
                    if (d.ContainsKey(w) && d[w] > 0) { count++; d[w]--; }
                }
            }
        return count;
    }
    static int getB(long a, long[] b)
    {
        var t1 = (int)(1 + Log10(a) / Log10(2));
        var t2 = (int)(Log10(a + 1) / Log10(2));
        if (b[t1] >= a + 1 && b[t1] <= 2 * a) return t1;
        else return t1 + 1;
    }
}

