namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			int n = int.Parse(Console.ReadLine());
			var a = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();

			Array.Sort(a);
			long max = a.Max();
			var done = new bool[n];

			long target = 1;
			while (target < max) {
				target *= 2;
			}

			int ans = 0;
			while (target > 0) {
				var dic = new Dictionary<long, Queue<int>>();
				for (int i = 0; i < n; i++) {
					if (a[i] > target * 2) {
						break;
					}

					if (done[i]) {
						continue;
					}

					if (a[i] == target) {
						if (dic.ContainsKey(0) && dic[0].Count > 0) {
							ans++;
							int c = dic[0].Dequeue();
							done[c] = true;
							done[i] = true;
						} else {
							if (dic.ContainsKey(0) == false) {
								dic[0] = new Queue<int>();
							}

							dic[0].Enqueue(i);
						}
					} else if (a[i] < target) {
						long num = target - a[i];
						if (dic.ContainsKey(num) == false) {
							dic[num] = new Queue<int>();
						}

						dic[num].Enqueue(i);
					} else {
						long num = a[i] - target;
						if (dic.ContainsKey(num) && dic[num].Count > 0) {
							ans++;
							int c = dic[num].Dequeue();
							done[c] = true;
							done[i] = true;
						}
					}
				}

				target /= 2;
			}

			Console.WriteLine(ans);
		}
	}
}

