        //valid(n,a) && valid(n,b)でa>bであればbにまだ何かが存在しているかも
        int res = 0;
        Dictionary<uint, List<int>> dict = a.Distinct().ToDictionary(x => x, _ => new List<int>());
        for (int i = 0; i < a.Length; i++)
        {
            dict[a[i]].Add(i);

