            if (dict.ContainsKey(j - item))
            {
                var value = dict[j - item];
                for (int k = 0; k < value.Count; k++)
                {
                    if (used[value[k]] || value[k] == i) continue;
                    used[i] = true;
                    used[value[k]] = true;
                    res++;
                    goto end;
                }
            }

