//解説動画を見て解きなおす
//大きい順にソートして、大きい数と2^tを作る数がないか調べる
//あったら、それをpairsに追加して、大きい数とその数を消す。
//空になるまで続ける。
func main() {

	var N int
	fmt.Scanf("%d", &N)
	nums := scanNums(N)

	//大きい順に並べる
	sort.Sort(sort.Reverse(sort.IntSlice(nums)))

	numMap := make(map[int]bool)
	for _, num := range nums {
		numMap[num] = true
	}
	pairCount := 0
	for len(nums) > 1 {
		debug("nums = %v\n", nums)
		num0 := nums[0]
		pow2 := ceilPow2(num0)
		num1 := pow2 - num0
		debug("nums0=%d pow2=%d num1=%d\n", num0, pow2, num1)
		if numMap[num1] {
			foundNumIdx := -1
			for j := 1; j < len(nums); j++ {
				if nums[j] == num1 {
					foundNumIdx = j
					break
				}
				if nums[j] < num1 {
					break
				}
			}

			nums = append(nums[1:foundNumIdx], nums[foundNumIdx+1:]...)
			pairCount++
		} else {
			nums = nums[1:]
		}
	}

	fmt.Printf("%d\n", pairCount)
}

/**
 * 引数で与えられた数以上の2の累乗数を求める
 */
func ceilPow2(n int) int {
	t := math.Log2(float64(n))
	pow2 := 1 << uint64(t)
	if n == pow2 {
		return n
	} else {
		return pow2 << 1
	}
}

/**
 * １行に空白区切りで数字を読み込み
 */
func scanNums(len int) (nums []int) {
	nums = make([]int, len)
	for i := 0; i < len; i++ {
		fmt.Scan(&nums[i])
	}
	return
}

