		values[i], _ = strconv.Atoi(str)
	}

	sort.Sort(sort.IntSlice(values))

	count := 0
	for len(values) > 0 {
		v := values[len(values)-1]
		values = values[:len(values)-1]
		if len(values) == 0 {
			break
		}

		target := find(v)
		if target == -1 {
			continue
		}
		i := sort.SearchInts(values, target)
