						isChanged = true
						opponents[p.fst] = struct{}{}

						count++
						isChanged = true
					}
				}

				for p := range pairs {
					if _, b := opponents[p.fst]; b {
						delete(pairs, p)
					}
					if _, b := opponents[p.snd]; b {
						delete(pairs, p)
					}
