const INFINITY = math.MaxInt64/2 - 1

func exec(stdin *Stdin, stdout *Stdout) {
	n := stdin.ReadInt()
	a := stdin.ReadIntSlice(n)
	sort.Ints(a)
	ReverseSlice(a)

	d := map[int]int{}
	for _, k := range a {
		if v, ok := d[k]; ok {
			d[k] = v + 1
		} else {
			d[k] = 1
		}
	}

	tgts := []int{1}
	tgt := 2
	for tgts[len(tgts)-1] < a[len(a)-1]*2 {
		tgts = append(tgts, tgt)
		tgt *= 2
	}
	ReverseSlice(tgts)

	ans := 0
	for _, v := range a {
		if d[v] == 0 {
			continue
		}

		for _, tgt := range tgts {
			w := tgt - v
			if v == w {
				if d[v] > 1 {
					ans++
					d[v] -= 2
					break
				}
			} else {
				if d[w] > 0 {
					ans++
					d[v]--
					d[w]--
					break
				}
			}
		}
	}
	stdout.Println(ans)
}

func main() {
	stdout := NewStdout()
	defer stdout.Flush()
	exec(NewStdin(bufio.ScanWords), stdout)
}

