var pows = []int{1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536, 131072, 262144, 524288, 1048576, 2097152, 4194304, 8388608, 16777216, 33554432, 67108864, 134217728, 268435456, 536870912, 1073741824}

func main() {
	var n int
	fmt.Scan(&n)

	values := make([]int, n)
	dic := make(map[int]int)
	for i := 0; i < n; i++ {
		var str string
		fmt.Scan(&str)

		v, _ := strconv.Atoi(str)
		dic[v] = dic[v] + 1

		values[i] = v
	}
	sort.Sort(sort.Reverse(sort.IntSlice(values)))

	count := 0
	for _, v := range values {
		rest, _ := dic[v]
		target := find(v)
		if v == target {
			dic[target] = dic[target] - (rest/2)*2
			count = count + rest/2
			continue
		}
		t, _ := dic[target]
		if t > 0 {
			dic[target] = dic[target] - min(t, rest)
			dic[v] = dic[v] - min(t, rest)
			count = count + min(t, rest)
		}
	}
	fmt.Println(count)
