func exec(stdin *Stdin, stdout *Stdout) {
	n := stdin.ReadInt()
	a := stdin.ReadIntSlice(n)
	sort.Ints(a)

	d := NewSet()
	for _, v := range a {
		d.Add(v)
	}

	tgts := []int{1}
	tgt := 2
	for tgts[len(tgts)-1] < a[len(a)-1]*2 {
		tgts = append(tgts, tgt)
		tgt *= 2
	}
	ReverseSlice(tgts)

	ans := 0
	for _, v := range a {
		if !d.Contains(v) {
			continue
		}

		for _, tgt := range tgts {
			w := tgt - v
			if w == v || !d.Contains(w) {
				continue
			}
			ans++
			d.Remove(v)
			d.Remove(w)
			break
		}
	}
	stdout.Println(ans)
