//大きい順にソートして、大きい数と2^tを作る数がないか調べる
//あったら、それをpairsに追加して、大きい数とその数を消す。
//空になるまで続ける。
func main() {

	var N int
	fmt.Scanf("%d", &N)
	nums := scanNums(N)

	//大きい順に並べる
	sort.Sort(sort.Reverse(sort.IntSlice(nums)))

	pairCount := 0
	for len(nums) > 1 {
		//debug("nums = %v\n", nums)
		num0 := nums[0]
		pow2 := floorPow2(num0)
		num1 := num0 - pow2
		foundNumIdx := -1
		for j := 1; j < len(nums); j++ {
			if nums[j] == num1 {
				foundNumIdx = j
				break
			}
			if nums[j] < num1 {
				break
			}
		}
		if foundNumIdx >= 0 {
			nums = append(nums[1:foundNumIdx], nums[foundNumIdx+1:]...)
			pairCount++
		} else {
			nums = nums[1:]
		}
	}

	fmt.Printf("%d\n", pairCount)
}

/**
 * 引数で与えられた数以下の2の累乗数を求める
 */
func floorPow2(n int) int {
	t := math.Log2(float64(n))
	return (1 << uint64(t))
}

/**
 * １行に空白区切りで数字を読み込み
 */
func scanNums(len int) (nums []int) {
	nums = make([]int, len)
	for i := 0; i < len; i++ {
		fmt.Scan(&nums[i])
	}
	return
}

