func exec(stdin *Stdin, stdout *Stdout) {
	n := stdin.ReadInt()
	a := stdin.ReadIntSlice(n)
	sort.Ints(a)
	ReverseSlice(a)

	d := map[int]int{}
	for _, k := range a {
		if v, ok := d[k]; ok {
			d[k] = v + 1
		} else {
