	b := make([]int, 50)
	for i := 0; i < 50; i++ {
		b[i] = Pow(2, i)
	}

	ans := 0
	for _, x := range a {
		if d[x] == 0 {
			continue
		}

		i := sort.SearchInts(b, x)
		if x == b[i] {
			i++
		}
		y := b[i] - x

		if x == y {
			if d[x] > 1 {
				d[x] -= 2
				ans++
			}
		} else {
			if d[y] > 0 {
				d[x]--
				d[y]--
				ans++
			}
		}
	}

	stdout.Println(ans)
