//空になるまで続ける。
func main() {

	var N int
	fmt.Scanf("%d", &N)
	nums := scanNums(N)

	//大きい順に並べる
	sort.Sort(sort.Reverse(sort.IntSlice(nums)))

	maxIndex := 0
	//値からスライスのindexへアクセスするためのmap
	numIndex := make(map[int]int)
	for idx, num := range nums {
		numIndex[num] = idx
	}

	pairCount := 0
	for maxIndex < len(nums) {
		debug("nums = %v\n", nums)
		num0 := nums[maxIndex]
		if num0 < 0 { //すでにペアになって印がついている
			maxIndex++
			continue
		}
		pow2 := ceilPow2(num0)
		num1 := pow2 - num0
		debug("nums0=%d pow2=%d num1=%d\n", num0, pow2, num1)
		if numIndex, ok := numIndex[num1]; ok {
			if nums[numIndex] > 0 {
				pairCount++
				nums[numIndex] = -1 //一度ペアになったら印をつける
			}
		}
		nums[maxIndex] = -1//念のためmaxIndexのところに-1を付けておく
		maxIndex++
	}

	fmt.Printf("%d\n", pairCount)
}

/**
 * 引数で与えられた数以上の2の累乗数を求める
 */
func ceilPow2(n int) int {
	t := math.Log2(float64(n))
	pow2 := 1 << uint64(t)
	if n == pow2 {
		return n
	} else {
		return pow2 << 1
	}
}

/**
 * １行に空白区切りで数字を読み込み
 */
func scanNums(len int) (nums []int) {
	nums = make([]int, len)
	for i := 0; i < len; i++ {
		fmt.Scan(&nums[i])
	}
	return
}

