	c := make(map[int]int)
	for i := 0; i < N; i++ {
		c[As[i]]++
	}
	pairMax := As[N-1] + As[N-2]
	bs := []int{}
	for b := 2; b < pairMax; b *= 2 {
		bs = append(bs, b)
	}

	ans := 0
	for i := 0; i < N; i++ {
		if c[As[i]] == 0 {
			continue
		}
		for _, b := range bs {
			opp := b - As[i]
			if opp < 1 {
				continue
			}
