				continue
			}
			if opp == As[i] {
				if c[opp] >= 2 {
					c[opp] -= 2
					ans++
					continue
				}
			} else {
				if c[opp] >= 1 {
					c[As[i]]--
					c[opp]--
					ans++
					continue
				}
			}
		}
	}

	fmt.Println(ans)
