func isPower(n int) bool {
	if n == 1 {
		return false
	}

	for (n % 2) == 0 {
		n = n / 2
	}
	return n == 1
}

func main() {
	var n int
	fmt.Scan(&n)

	values := make([]int, n)

	for i := 0; i < n; i++ {
		var str string
		fmt.Scan(&str)
		n, _ := strconv.Atoi(str)
		values[i] = n
	}

	type pair struct {
		fst int
		snd int
	}

	pairs := make(map[pair]struct{})
	for i := 0; i < n; i++ {
		a := values[i]
		for j := i + 1; j < n; j++ {
			b := values[j]
			if isPower(a + b) {
				pairs[pair{a, b}] = struct{}{}
			}
		}
	}

	node2count := make(map[int]int)
	for v := range pairs {
		node2count[v.fst]++
		node2count[v.snd]++
	}

	count := 0
	isChanged := true
	for isChanged {
		isChanged = false

		min := math.MaxInt64
		for _, v := range node2count {
			if v < min {
				min = v
			}
		}
		for node, v := range node2count {
			if v == min {
				opponents := make(map[int]struct{})
				for p := range pairs {
					if p.fst == node {
						delete(pairs, p)
						opponents[p.snd] = struct{}{}

						count++
						isChanged = true
					}
					if p.snd == node {
						delete(pairs, p)
						isChanged = true
						opponents[p.fst] = struct{}{}

						count++
						isChanged = true
					}
				}

				for p := range pairs {
					if _, b := opponents[p.fst]; b {
						delete(pairs, p)
					}
					if _, b := opponents[p.snd]; b {
						delete(pairs, p)
					}
				}
			}
		}
	}

	/*
		fmt.Println("--------")
		for k, v := range pairs {
			fmt.Println(k, v)
		}
	*/

	fmt.Println(count)
}

