package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc.Split(bufio.ScanWords)

	n := nextInt()

	cm := make(map[int]int)
	as := make([]int, n)
	for i := 0; i < n; i++ {
		as[i] = nextInt()
		cm[as[i]]++
	}
	sort.Ints(as)

	ans := 0
	for i := 0; i < n; i++ {
		a := as[n-i-1]
		a2 := 2
		for a2 < a {
			a2 *= 2
		}
		b := a2 - a
		if (b != a2 && cm[b] >= 1) || (b == a2 && cm[b] >= 2) {
			cm[b]--
			ans++
		}
	}
	fmt.Println(ans)
}

var sc = bufio.NewScanner(os.Stdin)

