use Data::Dumper;

my @INPUT;
while (<>) {
    chomp;
    push @INPUT, $_;
}

my $N = shift @INPUT;
my @A = split " ", shift @INPUT;
my %A;
for (my $i = 0; $i <= $#A; $i++) {
    $A{$A[$i]} = $i;
}

my @twot;
for (my $i = 0; 2 ** $i < 10 ** 9; $i++) {
    push @twot, 2 ** $i;
}

my $ans = 0;
my $min = 1;
while ($min < 3) {
    my $found = hoge($min);
    if ($found == 1) {
        $min = 1;
    } elsif ($found == 100000) {
        last;
    } else {
        $min += $found;
    }
}

sub hoge {
    my $min = shift;
    #say "min: $min";
    my $min_cnt = 100000;
    for (my $i = 0; $i < @A; $i++) {
        my $a = $A[$i];
        #say "i: $a";
        if ($a == 0) {
            next;
        }
        my $cnt = 0;
        my $pair;
        for my $twot (reverse @twot) {
            my $pair_v = $twot - $a;
            if ($pair_v <= 0) {
                last;
            }
            if (defined $A{$pair_v} && $A{$pair_v} != $i) {
                $pair = $A{$pair_v};
                $cnt++;
            }
        }
        if ($cnt && $min_cnt > $cnt) {
            $min_cnt = $cnt;
        }
        #say "cnt: $cnt";
        if ($cnt == $min) {
            $ans++;
            #say "$A[$i] + $A[$pair]";
            delete $A{$A[$pair]};
            $A[$i] = 0;
            $A[$pair] = 0;
            return 1;
        }
    }
    return $min_cnt;
}
say $ans;


__END__

my %pairs;
my $cnt = 0;
for (my $i = 0; $i < @A; $i++) {
    my $a = $A[$i];
    for my $twot (reverse @twot) {
        my $pair = $twot - $a;
        if ($pair <= 0) {
            last;
        }
        if (defined $A{$pair} && $A{$pair} != $i) {
            push @{$pairs{$i}}, $A{$pair};
            $cnt++;
        }
    }
}
print Dumper \%pairs;

my %num_of_pair;
for (my $i = 0; $i < @A; $i++) {
    next unless defined $pairs{$i};
    $num_of_pair{$i} = scalar @{$pairs{$i}};
}

