use v5.18;
use warnings;
sub read_line { chomp(my $s = <>); $s }
sub splited_read_line { split / /, read_line }

my $n = read_line;
my @balls = splited_read_line;
say solve(\@balls);

sub solve {
  my $balls = shift;
  my @sorted_balls = sort { $b <=> $a } @$balls;

  my $count = 0;
  for (
    my $ball = $sorted_balls[my $i = $#sorted_balls];
    $i >= 0;
    $ball = $sorted_balls[--$i]
  ) {
    next unless defined $ball;
    for (
      my $compare_ball = $sorted_balls[my $j = $i - 1];
      $j >= 0;
      $compare_ball = $sorted_balls[--$j]
    ) {
      next unless defined $compare_ball;
      my $sum = $compare_ball + $ball;
      if ( ( log($sum) / log(2) ) =~ /^[0-9]+$/ ) {
        $count++;
      }
      $sorted_balls[$j] = undef;
    }
    $sorted_balls[$i] = undef;
  }
  $count;
}

