sub solve {
  my $balls = shift;
  my @sorted_balls = sort { $b <=> $a } @$balls;

  my $count = 0;
  for (
    my $ball = $sorted_balls[my $i = 0];
    $i < $#sorted_balls;
    $ball = $sorted_balls[++$i]
  ) {
    next unless defined $ball;
    for (
      my $compare_ball = $sorted_balls[my $j = $i + 1];
      $j < @sorted_balls;
      $compare_ball = $sorted_balls[++$j]
    ) {
      next unless defined $compare_ball;
      my $sum = $compare_ball + $ball;
      if ( ( log($sum) / log(2) ) =~ /^[0-9]+$/ ) {
        $count++;
        $sorted_balls[$j] = undef;
        last;
      }
    }
