long msb(long bits) {
  bits = bits&0xffffffff00000000L ? bits&0xffffffff00000000L : bits;
  bits = bits&0xffff0000ffff0000L ? bits&0xffff0000ffff0000L : bits;
  bits = bits&0xff00ff00ff00ff00L ? bits&0xff00ff00ff00ff00L : bits;
  bits = bits&0xf0f0f0f0f0f0f0f0L ? bits&0xf0f0f0f0f0f0f0f0L : bits;
  bits = bits&0xccccccccccccccccL ? bits&0xccccccccccccccccL : bits;
  bits = bits&0xaaaaaaaaaaaaaaaaL ? bits&0xaaaaaaaaaaaaaaaaL : bits;
  return bits;
}

