bool isPowerOfTwo(long n) {
    return (n & (n - 1)) == 0;
}

int calc(int[] a) {
    long[] pows;
    for (int i = 1; i <= 30; i++) pows ~= 2 ^^ i;

    int[long] d;
    foreach (x; a) d[x]++;

    auto ks = d.keys.array;
    ks.sort();

    long[] keys, vals;
    foreach (k; ks) {
        keys ~= k;
        vals ~= d[k];
    }

    long[][] pairs;
    int ans = 0;
    int[long] refs;
    for (int i = 0; i < keys.length; i++) {
        long k = keys[i];
        foreach (pow; pows) {
            if (k < pow) {
                long x = pow - k;
                if (x > k && x in d) {
                    pairs ~= [k, x];
                    refs[k]++;
                    refs[x]++;
                }
            }
        }
    }

    bool updated = true;
    while (updated) {
        updated = false;
        for (int i = 0; i < pairs.length; i++) {
            long x = pairs[i][0];
            long y = pairs[i][1];
            if (refs[x] == 1 || refs[y] == 1) {
                int p = min(d[x], d[y]);
                ans += p;
                d[x] -= p;
                d[y] -= p;
                updated = true;
                refs[x]--;
                refs[y]--;
            }
        }
    }

    for (int i = 0; i < pairs.length; i++) {
        long x = pairs[i][0];
        long y = pairs[i][1];
        if (refs[x] > 1 || refs[y] > 1) {
            int p = min(d[x], d[y]);
            ans += p;
            d[x] -= p;
            d[y] -= p;
        }
    }

    foreach (k, v; d) {
        if (isPowerOfTwo(k + k)) {
            ans += v / 2;
        }
    }


    return ans;
}

void main() {
    readint;
    auto a = readints;
    writeln(calc(a));
}

