auto solve( long[] as )
{
	// 2^^n-1 <= a < a+b == 2^^n <= 2a < 2^^n+1 なので、
	// a = max(as) のときの b は一意に決まるから、大きい順で貪欲にペアを作ればいい
	auto ans = 0L;
	auto rbt = redBlackTree!true( as );
	while( !rbt.empty )
	{
		auto a = rbt.back;
		rbt.removeBack;
		auto b = ( 2L << a.bsr ) - a;
		if( rbt.removeKey( b ) ) ans++;		// a に対応する b が見つかればペアにする
	}
	return ans;
}

