    foreach(a;A){
        if(a !in m) m[a]=0;
        ++m[a];
    }
    int c=0;
    foreach_reverse(a;A) if(m[a]>0){
        auto t=a+1;
        if((t&t-1)!=0) t=1<<bsr(t)+1;
        t-=a;
