from collections import defaultdict, Counter


class UnionFind(object):
    def __init__(self, N):
        self._parent = list(range(N))
        self.__rank = [0] * N


    def root(self, x):
        if self._parent[x] == x:
            return x
        else:
            # root abbreviation
            self._parent[x] = self.root(self._parent[x])
            return self._parent[x]


    def same(self, x, y):
        return self.root(x) == self.root(y)


    def unite(self, x, y):
        x = self.root(x)
        y = self.root(y)
        if (x == y):
            return
        rank_x = self.__rank[x]
        rank_y = self.__rank[y]
        if rank_x < rank_y:
            self._parent[x] = y
        else:
            self._parent[y] = x
            if rank_x == rank_y:
                self.__rank[x] += 1
        return


