def pair(n, a, b, _i, ans):
    list_ans = []
    for i in range(_i, n-1):
        if b[i] == False:
            continue
        for j in range(i+1, n):
            if b[j] == False:
                continue
            if powers_of_2(a[i]+a[j]):
                b[j] = False
                list_ans.append(pair(n, a, b, i+1, ans+1))
                b[j] = True
    return max(list_ans) if list_ans != [] else ans

