import bisect

def f(a,k):
  if len(a) <= 1:
    return k
  m = a.pop(-1)
  v = 1
  while v <= m:
    v *= 2
  r = v-m
  i = bisect.bisect_left(a,r)
  if i < len(a) and a[i] == r:
    k += 1
    a.pop(i)
    return f(a,k)
  else:
    return f(a,k)

