def bins(a, x):
    left = 0
    right = len(a) - 1
    res = -1e10
    while left <= right:
        mid = (left + right) // 2
        if a[mid] == x:
            res = mid
            break
        elif a[mid] > x:
            right = mid - 1
        else:
            left = mid + 1
    return res

