def slv(N, A):
    bp = list(reversed([2**i for i in range(2, 40)]))
    C = Counter(A)
    ans = 0
    A.sort(reverse=True)
    for k in A:
        if C[k] == 0:
            continue
        for b in bp:
            r = b-k
            if r == k:
                if C[k] >= 2:
                    ans += 1
                    C[k] -= 2
                    break
            elif C[r] > 0 and C[k] > 0:
                ans += 1
                C[r] -= 1
                C[k] -= 1
                break

    return ans


