def solve(count):
    sk = sorted(count.keys())
    rd = {a: i for i, a in enumerate(sk)}
    lc = len(count)
    ma = max(count)

    mf = Dinic(2 * lc + 2)
    s, g = 0, 2 * lc + 1

    for i, a in enumerate(sk):
        cnt = count[a]
        li = i + 1
        k = 2
        b = k - a
        flag = False
        while b <= ma:
            if b > 0 and b in count:
                if a != b or cnt > 1:
                    mf.add_link(li, lc + rd[b] + 1, cnt)
                    flag = True
            k <<= 1
            b = k - a
        if flag:
            mf.add_link(s, li, cnt)
            mf.add_link(lc + li, g, cnt)

    # print(*mf.links, sep='\n')
    return mf.max_flow(s, g) // 2


