import sys

def getComplement(val):
	target = 1
	while target <= val:
		target <<= 1
	return target - val

def lowerBound(c, values, left, right):
	if left+1 > right:
		return None
	if left+1 == right:
		return left
	middle = (left + right) // 2
	if c > values[middle]:
		return lowerBound(c, values, left, middle)
	else: # c <= values[middle]
		return lowerBound(c, values, middle, right)

def maximumPairCount(values):
	n = len(values)
	values.sort(reverse=True)
	count = 0
	used = [False] * n
	for i in range(n):
		if used[i]:
			continue
		c = getComplement(values[i])
		cur = lowerBound(c, values, i+1, n)
		if cur is None or values[cur] != c:
			continue
		used[cur] = True
		count += 1
	return count

