def nibun(x, *args):
  l = len(args)
  if l == 0:
    return -float('inf')
  else:
    u = l // 2
    v = args[l // 2]
  for i in range(n):
    if v != -1:
      if v == x:
        return l // 2
      elif v < x:
        b = args[:l //2]
        return nibun(x, *b)
      else:
        b = args[l // 2+1:]
        return u + 1 + nibun(x, *b)
    else:
      u += 1
      u %= l
      v = args[u]
  return -1

