    bp = list(reversed([2**i for i in range(2, 40)]))
    C = Counter(A)
    K = list(C.keys())
    K.sort(reverse=True)
    ans = 0
    for k in K:
        for b in bp:
            r = b-k
            if r == k:
                if C[k] >= 2:
                    ans += 1
                    C[r] -= 1
                    C[k] -= 1
                    break
            elif C[r] > 0 and C[k] > 0:
                ans += 1
                C[r] -= 1
                C[k] -= 1
                break

    return ans


