def bisect_left(a,x):
    s = 0
    t = n-1
    while t-s >= 2:
        m = (s+t)//2
        if a[m] < x:
            s = m
        else:
            t = m
    return s

def bisect_right(a,x):
    s = 0
    t = n-1
    while t-s >= 2:
        m = (s+t)//2
        if a[m] <= x:
            s = m
        else:
            t = m
    return t



