def is_exist_b(search_list, target):
    low = 0
    high = len(search_list)
    if high == 0:
        return False
    index = (low + high) // 2
    while low <= high:
        if target == search_list[index]:
            break
        elif i > search_list[index]:
            low = index + 1
        elif i < search_list[index]:
            high = index - 1
        index = (low + high) // 2
    if target == search_list[index]:
        return True
    else:
        return False


def make_list(base, ceil):
    limit = ceil + base
    max_t = int(math.log2(limit))
    result = []
    for t in range(1, max_t + 2):
        can = 2**t - base
        if 0 < can <= ceil:
            result.append(can)
    return result


