def isFinished(S):
    for i in range(len(S) - 1):
        if S[i] == 'B' and S[i+1] == 'W':
            return True
    return False

def solve(S):
    count = 0
    while isFinished(S):
        black_pos = -1
        for i in range(len(S)):
            if S[i] == 'B':
                black_pos = i
            elif S[i] == 'W' and black_pos != -1:
                count += i - black_pos
                S[black_pos] = 'W'
                S[i] = 'B'
                black_pos = -1
    return count

