def two_power(m):
  if m < 2:
    return 0
  else:
    return two_power(m//2) + 1

def nibun(x, *args):
  l = len(args)
  if l == 0:
    return -float('inf')
  elif args[l // 2] == x:
    return l // 2
  elif args[l // 2] < x:
    b = args[:l //2]
    return nibun(x, *b)
  else:
    b = args[l // 2+1:]
    return l // 2 + 1 + nibun(x, *b)

