from collections import Counter

def ans_solve(N, As):
    C = Counter(As)
    ans = 0
    while len(C):
        d = max(C.keys())
        n = (2 ** d.bit_length()) - d
        if d != n:
            dc = C[d]
            dn = C[n] if n in C else 1
            mn = min(dc, dn)
            C[d] -= mn
            if n in C:
                C[n] -= mn
                ans += mn
        else:
            if C[d] >= 2:
                ans += C[d]//2
                C[d] -= 2 * C[d]//2
            elif C[d] >= 1:
                C[d] -= 1

        if C[d] == 0:
            del C[d]
        if n in C and C[n] == 0:
            del C[n]
    return ans


