    a.sort();
    for i in 0..n {
        a[i] *= 2;
    }
    let mut ans = 0;
    for i in (0..n).rev() {
        if a[i] % 2 == 1 {
            continue;
        }
        let mut two = 1;
        while two <= a[i] {
            two *= 2;
        }
        let opp = two - a[i];
        let idx = a[..i].upper_bound(&opp);
        if idx > 0 && a[idx - 1] == opp {
            a[idx - 1] += 1;
            a[i] += 1;
            ans += 1;
        }
    }
    puts!("{}\n", ans);
}

