fn binary_search_left<T: Ord>(v: &Vec<T>, x: T) -> usize {
    let mut l: isize = -1;
    let mut r: isize = v.len() as isize;
    while r - l > 1 {
        let m = (r + l) / 2;
        if v[m as usize] < x {
            l = m;
        } else {
            r = m;
        }
    }
    r as usize
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n = parse!(it);
    let mut a: Vec<usize> = parse!(it, n);
    let mut used = vec![false; n];
    a.sort();
    let mut ret = 0;
    for i in 0..n {
        let ai = a[n - i - 1];
        let mut k = 1;
        while ai > k {
            k <<= 1;
        }
        let bi = if k == ai { ai } else { k - ai };
        let al = &a[..n - i - 1];
        match al.binary_search(&bi) {
            Ok(j) => {
                let mut j = j;
                while used[j] {
                    j += 1;
                    if j == al.len() {
                        break;
                    }
                }
                if j == al.len() || al[j] != bi {
                    continue;
                }
                used[n - i - 1] = true;
                used[j] = true;
                ret += 1;
            }
            _ => (),
        }
    }
    println!("{}", ret);
}

