#[fastout]
fn main() {
    input! {
        n: usize,
        mut a: [usize; n],
    }
    a.sort();
    let mut nokori_kosuu: BTreeMap<usize, usize> = BTreeMap::new();
    for &ai in &a {
        if let Some(e) = nokori_kosuu.get_mut(&ai) {
            *e += 1;
        } else {
            nokori_kosuu.insert(ai, 1);
        }
    }
    let mut num_pairs = 0;
    for i in (0..n).rev() {
        let ai = a[i];
        if *nokori_kosuu.get(&ai).unwrap() == 0 {
            continue;
        }
        *nokori_kosuu.get_mut(&ai).unwrap() -= 1;
        let mut nibeki = 1;
        while nibeki <= ai {
            nibeki *= 2;
        }
        let aikata = nibeki - ai;
        if let Some(&c) = nokori_kosuu.get(&aikata) {
            if c != 0 {
                num_pairs += 1;
                *nokori_kosuu.get_mut(&aikata).unwrap() -= 1;
            }
        }
    }
    println!("{}", num_pairs);
}

