    for i in 1..33 {
        let mut map: HashMap<usize, Vec<usize>> = HashMap::new();
        let p = 2usize.pow(i);
        for j in 0..n {
            let a = aa[j];
            if a >= p {
                continue;
            }
            let r = a%p;
            let e = map.entry(r).or_insert(vec![]);
            e.push(j);
        }
        pp.push(map);
    }

    let mut pairs = vec![(0, 0); n];
    {
        for i in 0..n {
            pairs[i].0 = i;
    }
    }

    for i in 0..n {
        let a = aa[i];
        for j in 1..33 {
            let p = 2usize.pow(j as u32);
            if a >= p {
                continue;
            }
            let r = p - a%p;
            let map = &pp[j-1];
            if let Some(vs) = map.get(&r) {
                pairs[i].1 += vs.len();
                if r == a%p {
                    pairs[i].1 -= 1;
                }
            }
        }
    }

    let mut used = vec![false; n];
    pairs.sort_by_key(|v| v.1);

    let mut ans = 0;
    for i in 0..n {
        let pair = &pairs[i];
