            let mut map = &mut pp[j-1];
            if map.contains_key(&r) {
                let e = map.entry(r).or_insert(vec![]);
                while e.len() > 0 {
                    if let Some(v2) = e.pop() {
                        if used[v2] {
                            continue;
                        }
                        if v2 == v1 {
                            continue;
                        }

                        used[v1] = true;
                        used[v2] = true;
                        ans += 1;
                        break;
                    }
                }
            }
            if used[v1] {
                break;
            }
        }
    }
    println!("{}", ans);
}

