    }
    let mut ret = 0;
    for &a in a.iter().rev() {
        if counts[&a] == 0 {
            continue;
        }
        *counts.entry(a).or_insert(0) -= 1;
        let mut k = 1;
        while a > k {
            k <<= 1;
        }
        let b = if k == a { a } else { k - a };
        let mut e = counts.entry(b).or_insert(0);
        if *e > 0 {
            *e -= 1;
            ret += 1;
        }
    }
    println!("{}", ret);
