        let a = aa[i];
        let e = map.entry(a).or_insert(vec![]);
        e.push(i);
    }

    for r in (0..n).rev() {
        if used[r] {
            continue;
        }

        let a = aa[r];
        for x in 0..32 {
            let p = 2usize << x;
            if p < a {
                continue;
            }
            let t = p - a;
            if let Some(vs) = map.get_mut(&t) {
                while let Some(v) = vs.pop() {
                    if v != r && !used[v] {
                        used[v] = true;
                        used[r] = true;
                        ans += 1;
                        break;
                    }
                }
            }
            if used[r] {
                break;
            }
        }
    }
    println!("{}", ans);
}

