fn main() {
    input!{
        n: usize,
        arr: [u32; n],
    }

    let mut map = HashMap::new();
    for a in arr {
        let r = map.entry(a).or_insert(0);
        *r += 1;
    }

    let mut result = 0;

    while !map.is_empty() {
        let init = {
            let (init, _) = map.iter().next().unwrap();
            *init
        };
        remove(&mut map, init);

        let (left, right) = rec(&mut map, init);

        result += ::std::cmp::min(left, right);
    }

    println!("{}", result);
}

fn rec(map: &mut HashMap<u32, u32>, init: u32) -> (u32, u32) {
    let mut left = 1;
    let mut right = 0;
    for d in diffs(init) {
        if remove(map, d) {
            let (ls, rs) = rec(map, d);
            left += rs;
            right += ls;
        }
    }
    (left, right)
}
fn diffs(val: u32) -> Vec<u32> {
    let mut result = Vec::with_capacity(30);
    let mut tar = 2;
    while tar <= 2 * 1000000000 {
        if tar <= val {
            tar *= 2;
            continue;
        }
        let d = tar - val;
        result.push(d);
        tar *= 2;
    }
    result
}

fn remove(map: &mut HashMap<u32, u32>, key: u32) -> bool {
    let v = {
        let v = map.get(&key);
        if v.is_none() {
            return false;
        }
        *v.unwrap()
    };
    if v > 1 {
        map.insert(key, v - 1);
    } else {
        map.remove(&key);
    }
    return true;
}

