ll next_power(ll x) {
  ll pow = 1;
  while (pow <= x) {
    pow *= 2;
  }
  return pow;
}

int main() {
  ios::sync_with_stdio(false);
  int n;
  cin >> n;
  multiset<ll, greater<ll>> balls;
  REP(i,0,n) {
    ll a;
    cin >> a;
    balls.emplace(a);
  }
  ll ans = 0;
  while (! balls.empty()) {
    auto max_it = balls.begin();
    ll max_b = *max_it;
    balls.erase(max_it);
    ll sum = next_power(max_b);
    auto opponent = balls.find(sum - max_b);
    if (opponent != balls.end()) {
      ans++;
      balls.erase(opponent);
    }
  }
  cout << ans << endl;

  return 0;
}

