trait Bisect<T> {
    fn lower_bound(&self, val: &T) -> usize;
    fn upper_bound(&self, val: &T) -> usize;
}

impl<T: Ord> Bisect<T> for [T] {
    fn lower_bound(&self, val: &T) -> usize {
        let mut pass = self.len() + 1;
        let mut fail = 0;
        while pass - fail > 1 {
            let mid = (pass + fail) / 2;
            if &self[mid - 1] >= val {
                pass = mid;
            } else {
                fail = mid;
            }
        }
        pass - 1
    }
    fn upper_bound(&self, val: &T) -> usize {
        let mut pass = self.len() + 1;
        let mut fail = 0;
        while pass - fail > 1 {
            let mid = (pass + fail) / 2;
            if &self[mid - 1] > val {
                pass = mid;
            } else {
                fail = mid;
            }
        }
        pass - 1
    }
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [i64; n],
    }
    let mut a = a;
    a.sort();
    for i in 0..n {
        a[i] *= 2;
    }
    let mut ans = 0;
    for i in (0..n).rev() {
        if a[i] % 2 == 1 {
            continue;
        }
        let mut two = 1;
        while two <= a[i] {
            two *= 2;
        }
        let opp = two - a[i];
        let idx = a.upper_bound(&opp);
        if idx > 0 && idx <= i && a[idx - 1] == opp {
            a[idx - 1] += 1;
            a[i] += 1;
            ans += 1;
        }
    }
    puts!("{}\n", ans);
}

