        let p = 2usize.pow(i);
        for j in 0..n {
            let a = aa[j];
            if a >= p {
                continue;
            }
            let r = a%p;
            let e = map.entry(r).or_insert(vec![]);
            e.push(j);
        }
        pp.push(map);
    }

    let mut pairs = vec![(0, 0); n];
    {
        for i in 0..n {
            pairs[i].0 = i;
    }
    }

    for i in 0..n {
        let a = aa[i];
        for j in 1..32 {
            let p = 2usize.pow(j as u32);
            if a >= p {
                continue;
            }
            let r = p - a%p;
            let map = &pp[j-1];
            if let Some(vs) = map.get(&r) {
                pairs[i].1 += vs.len();
                if r == a%p {
                    pairs[i].1 -= 1;
                }
            }
        }
    }

    // for i in 0..31 {
    //     debug!(pp[i]);
    // }

    let mut used = vec![false; n];
    pairs.sort_by_key(|v| v.1);

    let mut ans = 0;
    for i in 0..n {
        let pair = &pairs[i];
        if pair.1 == 0 {
            continue;
        }
        let v1 = pair.0;
        if used[v1] {
            continue;
        }

        let a = aa[v1];
        for j in 1..32 {
            let p = 2usize.pow(j as u32);
            if a >= p {
                continue;
            }
            let r = p - a%p;
            let mut map = &mut pp[j-1];
            if map.contains_key(&r) {
                let e = map.entry(r).or_insert(vec![]);
                while e.len() > 0 {
                    if let Some(v2) = e.pop() {
                        if used[v2] {
                            continue;
                        }
                        if v2 == v1 {
                            continue;
                        }

                        used[v1] = true;
                        used[v2] = true;
                        ans += 1;
                        break;
                    }
                }
            }
            if used[v1] {
                break;
            }
        }
    }
    println!("{}", ans);
}

