pub trait BinarySearch<T> {
    fn lower_bound(&self, &T) -> usize;
    fn upper_bound(&self, &T) -> usize;
}
impl<T: Ord> BinarySearch<T> for [T] {
    fn lower_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();
        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less => {
                    low = mid + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
    fn upper_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();
        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less | Ordering::Equal => {
                    low = mid + 1;
                }
                Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
}

#[allow(dead_code)]
pub fn bipartite_matching(g: &[Vec<usize>]) -> usize {
    fn dfs(v: usize, g: &[Vec<usize>], mat: &mut [Option<usize>], used: &mut [bool]) -> bool {
        used[v] = true;
        for &u in &g[v] {
            if mat[u].is_none() || !used[mat[u].unwrap()] && dfs(mat[u].unwrap(), g, mat, used) {
                mat[v] = Some(u);
                mat[u] = Some(v);
                return true;
            }
        }
        false
    }
    let mut res = 0;
    let mut mat = vec![None; g.len()];
    for v in 0..g.len() {
        if mat[v].is_none() {
            let mut used = vec![false; g.len()];
            if dfs(v, g, &mut mat, &mut used) {
                res += 1;
            }
        }
    }
    res
}

fn solve() {
    let n = get!(usize);
    let mut aa = get!([u64]);

    aa.sort();
    let mut g = vec![Vec::new(); 2 * n];

    for i in 0..40 {
        let sum = 1u64 << i;

        for j in 0..n {
            if sum > aa[j] {
                let mut k = aa.lower_bound(&(sum - aa[j]));
                while k < n && aa[k] + aa[j] == sum {
                    if k != j {
                        g[j].push(n + k);
                        g[n + k].push(j);
                        g[k].push(n + j);
                        g[n + j].push(k);
                    }
                    k += 1;
                }
            }
        }
    }

    for v in &mut g {
        v.sort();
        v.dedup();
    }

    println!("{}", bipartite_matching(&g) / 2);
}

