    let mut map = std::collections::HashMap::<u64, i64>::new();
    for i in 0..n {
        let p = map.entry(a[i]).or_insert(0);
        *p += 1;
    }

    let mut ans = 0;
    for i in 0..n {
        let j = a[i].next_power_of_two();
        let p = map.entry(j - a[i]).or_insert(0);
